function generateName(){ return `${pick(FIRST_NAMES)} ${pick(LAST_NAMES)}`; }

function uid(){ return Math.random().toString(36).slice(2,10); }
function rand(min,max){ return Math.round(min + Math.random()*(max-min)); }
function randf(min,max){ return min + Math.random()*(max-min); }
function pick(arr){ return arr[Math.floor(Math.random()*arr.length)]; }
function fmt$(n){
  n = Math.round(n||0);
  const neg = n<0; n=Math.abs(n);
  let s = "$" + n.toLocaleString("en-US");
  return neg? "-"+s : s;
}
function clamp(n,a,b){ return Math.max(a,Math.min(b,n)); }
function freshName(existing){
  const used = (G && G.company && G.company.usedNames) ? G.company.usedNames : [];
  for(let i=0;i<60;i++){
    const n = generateName();
    if(!existing.some(e=>e.name===n) && !used.includes(n)){
      if(G && G.company){ if(!G.company.usedNames) G.company.usedNames=[]; G.company.usedNames.push(n); }
      return n;
    }
  }
  const n2 = generateName()+" "+rand(2,999);
  if(G && G.company){ if(!G.company.usedNames) G.company.usedNames=[]; G.company.usedNames.push(n2); }
  return n2;
}
// Single source of truth for MRR: sum of all client MRR plus any un-attributed
// "base" MRR gained from events not tied to a specific client. Recomputed
// on every topbar render and at month-end so displayed MRR never drifts
// out of sync with what clients actually contribute.
function recomputeMRR(){
  if(!G || !G.company) return;
  const clientSum = G.company.clients.reduce((s,c)=>s+(c.mrr||0),0);
  G.company.mrr = Math.round(clientSum + (G.company.baseMrr||0));
}

