const DEPT_KEYS = ["sales","marketing","product","support","finance","operations","hr"];
const HEADCOUNT_CAP = [8,20,60,250];
function headcountCap(){
  let cap = HEADCOUNT_CAP[G.company.hqStage];
  if(deptHas("operations","manager")) cap += 5;
  if(deptHas("operations","coo")) cap += 15;
  return cap;
}

function rungIndex(deptKey, rungKey){ return LADDERS[deptKey].rungs.findIndex(r=>r.key===rungKey); }
function deptEmployees(deptKey){ return G.company.employees.filter(e=>e.dept===deptKey); }
function deptHas(deptKey, rungKey){ return deptEmployees(deptKey).some(e=>e.rung===rungKey); }
function rungCount(deptKey, rungKey){ return deptEmployees(deptKey).filter(e=>e.rung===rungKey).length; }
function rungCapacity(deptKey, rungKey){
  const rungs = LADDERS[deptKey].rungs;
  const r = rungs.find(x=>x.key===rungKey);
  if(!r.under) return Infinity;
  const isTopRung = rungs[rungs.length-1].key === rungKey;
  const raw = Math.floor(rungCount(deptKey, r.under) / r.per);
  return isTopRung ? Math.min(1, raw) : raw; // at most one C-suite exec per department
}
function rungRemaining(deptKey, rungKey){
  const cap = rungCapacity(deptKey, rungKey);
  return cap===Infinity ? Infinity : Math.max(0, cap - rungCount(deptKey, rungKey));
}

