function makeCompetitors(){
  const seeds = [
    ["Northstar Systems", 22, "aggressive fundraising"],
    ["Verdant Labs", 15, "strong brand loyalty"],
    ["Kestrel & Co.", 9, "undercutting on price"],
    ["Bramble Works", 6, "niche enterprise focus"],
  ];
  return seeds.map(([name, share, note])=>({
    id: uid(), name, marketShare: share, funding: rand(500,4000)*1000,
    threat: share>18?"High":share>10?"Medium":"Low", notes: note
  }));
}

/* ---------------- Persistence ---------------- */
function saveToSlot(state, slotKey, label){
  localStorage.setItem(slotKey, JSON.stringify(state));
  let idx = JSON.parse(localStorage.getItem(LS_SLOTS_INDEX) || "[]");
  idx = idx.filter(s=>s.key!==slotKey);
  idx.push({ key:slotKey, label: label || state.meta.name, savedAt: Date.now(),
    month:state.company.month, year:state.company.year, cash:state.company.cash });
  localStorage.setItem(LS_SLOTS_INDEX, JSON.stringify(idx));
}
function listSlots(){ return JSON.parse(localStorage.getItem(LS_SLOTS_INDEX) || "[]").sort((a,b)=>b.savedAt-a.savedAt); }
function loadSlot(key){ const raw = localStorage.getItem(key); return raw? JSON.parse(raw) : null; }
function deleteSlot(key){
  localStorage.removeItem(key);
  let idx = JSON.parse(localStorage.getItem(LS_SLOTS_INDEX) || "[]");
  idx = idx.filter(s=>s.key!==key);
  localStorage.setItem(LS_SLOTS_INDEX, JSON.stringify(idx));
}

let G = null;
function normalizeGameBase(g){
  if(!g) return g;
  if(!g.assistantChat) g.assistantChat=[];
  if(!g.ui.queue) g.ui.queue=[];
  if(g.ui.openClientGroup===undefined) g.ui.openClientGroup="clientgroup_Enterprise";
  if(!g.ui.decisionFolder) g.ui.decisionFolder="founder";
  const c = g.company;
  if(!c.pricing) c.pricing = { "Enterprise":1, "Mid-Market":1, "Small":1 };
  if(!c.investCostBasis) c.investCostBasis = { savings:0, indexFund:0, growthStocks:0, bonds:0, realEstate:0, crypto:0, privateEquity:0 };
  if(c.investCostBasis.crypto===undefined) c.investCostBasis.crypto=0;
  if(c.investCostBasis.privateEquity===undefined) c.investCostBasis.privateEquity=0;
  if(c.assets.crypto===undefined) c.assets.crypto=0;
  if(c.assets.privateEquity===undefined) c.assets.privateEquity=0;
  if(!c.companyChannel) c.companyChannel = [];
  if(!c.leadershipChannel) c.leadershipChannel = [];
  if(!c.csuiteChannel) c.csuiteChannel = [];
  if(c.successScore===undefined) c.successScore = 55;
  if(c.valuation===undefined) c.valuation = c.netWorth||0;
  if(c.dateNightUsedThisMonth===undefined) c.dateNightUsedThisMonth = false;
  if(c.vacationUsedThisMonth===undefined) c.vacationUsedThisMonth = false;
  if(c.founderActionsUsed===undefined) c.founderActionsUsed = 0;
  if(c.vacationBooked===undefined) c.vacationBooked = null;
  if(c.townHallUsedThisMonth===undefined) c.townHallUsedThisMonth = false;
  if(c.emptyQueueStreak===undefined) c.emptyQueueStreak = 0;
  if(c.orders && c.orders.hr===undefined) c.orders.hr = null;
  if(!c.benefitsTier) c.benefitsTier = 0;
  if(!c.perks) c.perks = { fleet: [] };
  if(c.oneOffSpendLastMonth===undefined) c.oneOffSpendLastMonth = 0;
  if(c.product.inProgress===undefined) c.product.inProgress = null;
  if(!c.product.shipped) c.product.shipped = [];
  if(!c.badges) c.badges = [];
  if(!c.charity) c.charity = { totalContributed:0, causes:{ research:0, food:0, wells:0 }, scope:"Local" };
  if(c.charityFounded===undefined) c.charityFounded = false;
  if(c.baseMrr===undefined) c.baseMrr = 0;
  if(!c.usedNames) c.usedNames = c.employees.map(e=>e.name);
  if(c.internationalLaunched===undefined) c.internationalLaunched = false;
  if(!c.acquiredCompetitors) c.acquiredCompetitors = [];
  if(!c.pricingBoostFromFeatures) c.pricingBoostFromFeatures = 0;
  if(!c.board) c.board = [];
  if(c.founderActionsLifetime===undefined) c.founderActionsLifetime = 0;
  if(c.townHallCount===undefined) c.townHallCount = 0;
  if(c.distressMonthsLifetime===undefined) c.distressMonthsLifetime = 0;
  // migrate old ladder rung "vp" to "director" (removed rung)
  c.employees.forEach(e=>{ if(e.rung==="vp") e.rung="director"; });
  const p = g.personal;
  if(!p.assets.toys) p.assets.toys = [];
  if(!p.giftHistory) p.giftHistory = [];
  if(!p.assets.houses){
    p.assets.houses = p.assets.house ? [{ ...p.assets.house, id:uid(), primary:true, rented:false, renovations:[] }] : [];
    delete p.assets.house;
  }
  if(!p.assets.cars){
    p.assets.cars = p.assets.car ? [{ ...p.assets.car, id:uid() }] : [];
    delete p.assets.car;
  }
  if(p.kenzie===undefined) p.kenzie = 70;
  if(p.totalNetWorth===undefined) p.totalNetWorth = p.netWorth;
  if(!p.monthEvents) p.monthEvents = [];
  return g;
}

/* ---------------- Hire / fire ---------------- */
function rungSalary(deptKey, rungKey){
  const r = LADDERS[deptKey].rungs.find(x=>x.key===rungKey);
  return rand(r.salaryRange[0], r.salaryRange[1]);
}
function hire(deptKey, rungKey){
  const r = LADDERS[deptKey].rungs.find(x=>x.key===rungKey);
  const salary = rungSalary(deptKey, rungKey);
  const name = freshName(G.company.employees);
  const emp = { id:uid(), name, dept:deptKey, rung:rungKey, role:r.label, icon:r.icon,
    salary, performance:rand(60,80), morale:rand(65,85),
    hiredMonth:G.company.month, hiredYear:G.company.year };
  G.company.employees.push(emp);
  G.company.slackThreads[emp.id] = [
    { from:"them", text:`Excited to join as ${r.label}! Ready to get to work.`, m:G.company.month }
  ];
  logHistory(`Hired ${name} as ${r.label} (${fmt$(salary)}/mo).`);
  return emp;
}
function fireEmployee(id){
  const emp = G.company.employees.find(x=>x.id===id);
  if(!emp) return;
  G.company.employees = G.company.employees.filter(e=>e.id!==id);
  logHistory(`Let go of ${emp.name} (${emp.role}).`);
}
function logHistory(text){
  G.company.history.unshift({ month:G.company.month, year:G.company.year, text });
  if(G.company.history.length>200) G.company.history.pop();
}

/* ---------------- Queue system ---------------- */
// Queue items: { id, label, kind, run: fn(report[]) }
function queueAdd(item){ G.ui.queue.push(item); }
function queueRemove(qid){ G.ui.queue = G.ui.queue.filter(q=>q.id!==qid); }

/* ---------------- Client helpers ---------------- */
function clientSize(c){ return c.mrr>=2000?"Enterprise":c.mrr>=700?"Mid-Market":"Small"; }

/* ---------------- Monthly resolution ---------------- */
function ladderBoostMultiplier(deptKey){
  let m = deptHas(deptKey,"coordinator") ? 1.2 : 1.0;
  if(deptHas(deptKey,"teamlead")) m *= 1.06;
  if(deptHas(deptKey,"manager")) m *= 1.06;
  return m;
}
function passiveGrowthRate(deptKey, key){
  if(deptKey==="sales"){
    if(deptHas("sales","cro")) return 0.06;
    if(deptHas("sales","director")) return 0.03;
  }
  return 0;
}

function pricingMultiplier(segment){ return ((G.company.pricing && G.company.pricing[segment]) || 1) + (G.company.pricingBoostFromFeatures||0); }
function rollSegment(order){
  const r = Math.random();
  if(order==="enterprise") return r<0.5?"Enterprise":r<0.85?"Mid-Market":"Small";
  return r<0.55?"Small":r<0.88?"Mid-Market":"Enterprise";
}
function segmentMrrRange(segment){
  if(segment==="Enterprise") return [2000,4200];
  if(segment==="Mid-Market") return [700,1900];
  return [250,650];
}
function segmentNamePool(segment){
  if(segment==="Enterprise") return ["Titan Manufacturing","Argent Bank","Meridian Health","Vantage Logistics"].map(n=>n+" (Enterprise)");
  if(segment==="Mid-Market") return ["Harbor Analytics","Nimbus Foods","Cobalt Studio","Junction Coffee","Lark & Co"];
  return ["Acme Retail","Bluepeak Co","Fenwick Group","Willow Café","Redstone Fitness","Sable Goods","Pixel Studio"];
}
function resolveSalesReps(report){
  const reps = deptEmployees("sales").filter(e=>e.rung==="rep");
  if(reps.length===0){
    if(opsBasedIndustry()){
      report.push("No sales team on payroll — revenue this month came from walk-in and repeat customers at your locations.");
      return;
    }
    // Founder-led sales: with no reps, you sell it yourself (v10 balance)
    const solo = clamp(0.42 * (0.7 + (G.company.successScore||40)/140) * (1 + marketingBoost()*0.5), 0.05, 0.75);
    if(Math.random() < solo){
      const segment = rollSegment(G.company.orders.sales);
      const [lo,hi] = segmentMrrRange(segment);
      const mrrVal = Math.max(150, Math.round(rand(lo,hi) * 0.55 * pricingMultiplier(segment)));
      G.company.clients.push({ id:uid(), name:pick(segmentNamePool(segment)), mrr:mrrVal, health:rand(60,85), sinceMonth:G.company.month, sinceYear:G.company.year });
      G.company.mrr += mrrVal;
      report.push(`You closed a deal yourself: ${fmt$(mrrVal)} in ${mrrWord()}. Hiring reps scales this up a lot.`);
    } else {
      report.push("You worked the pipeline yourself but didn't close anyone this month. Hiring a sales rep would multiply your reach.");
    }
    return;
  }
  const boost = ladderBoostMultiplier("sales");
  const order = G.company.orders.sales;
  let chanceMod = 1, mrrMod = 1;
  if(order==="volume"){ chanceMod=1.15; mrrMod=0.75; }
  else if(order==="enterprise"){ chanceMod=0.55; mrrMod=1.15; }
  else if(order==="coach"){ reps.forEach(r=>r.performance=clamp(r.performance+8,0,100)); }
  let closed=0, closedMrr=0, pitches=0;
  reps.forEach(rep=>{
    const pitchCount = rand(2,4);
    pitches += pitchCount;
    const chance = clamp(0.40 * (rep.performance/70) * boost * chanceMod, 0.05, 0.92);
    if(Math.random() < chance){
      const segment = rollSegment(order);
      const [lo,hi] = segmentMrrRange(segment);
      const mrrVal = Math.round(rand(lo,hi) * mrrMod * pricingMultiplier(segment));
      G.company.clients.push({ id:uid(), name:pick(segmentNamePool(segment)), mrr:mrrVal, health:rand(65,85), sinceMonth:G.company.month, sinceYear:G.company.year });
      G.company.mrr += mrrVal;
      closed++; closedMrr += mrrVal;
      rep.performance = clamp(rep.performance + rand(1,4), 0, 100);
    } else {
      rep.performance = clamp(rep.performance + rand(-2,1), 0, 100);
    }
  });
  if(closed>0) report.push(`Sales team pitched ~${pitches} prospect(s) and closed ${closed} deal(s) worth ${fmt$(closedMrr)} in ${mrrWord()}.`);
  else report.push(`Sales team pitched ~${pitches} prospect(s) but had no closes this month (${reps.length} rep(s) working the pipeline).`);
}

function resolveMarketing(report){
  const specs = deptEmployees("marketing").filter(e=>e.rung==="rep");
  if(specs.length===0) { G.company.expensesBreakdown.marketing = 0; return; }
  const boost = ladderBoostMultiplier("marketing");
  const order = G.company.orders.marketing;
  let chanceMod=1, costEach=0;
  if(order==="brand"){ chanceMod=1.2; }
  else if(order==="performance"){ chanceMod=1.5; costEach=350; }
  else if(order==="content"){ chanceMod=0.85; }
  if(hasBoardSeat("growth")) chanceMod *= 1.1; // Growth Marketing Advisor board seat
  let closed=0, closedMrr=0, spend=0;
  specs.forEach(sp=>{
    spend += costEach;
    const chance = clamp(0.30 * (sp.performance/70) * boost * chanceMod, 0.03, 0.75);
    if(Math.random() < chance){
      const mrrVal = rand(150,450);
      G.company.clients.push({ id:uid(), name: pick(["Pixel Studio","Junction Coffee","Lark & Co","Sable Goods","Northwind Retail"]),
        mrr:mrrVal, health:rand(60,85), sinceMonth:G.company.month, sinceYear:G.company.year });
      G.company.mrr += mrrVal;
      closed++; closedMrr += mrrVal;
    }
  });
  // Performance-marketing ad spend is a recurring monthly cost, so it's tracked
  // in expensesBreakdown (reset fresh each month, not accumulated) and comes
  // out of cash once via the normal end-of-month net-profit roll-up — not
  // deducted a second time here, which used to double-charge the company.
  G.company.expensesBreakdown.marketing = spend;
  if(closed>0) report.push(`Marketing generated ${closed} new inbound client(s) worth ${fmt$(closedMrr)} MRR.`);
}

function resolveProduct(report){
  const engs = deptEmployees("product").filter(e=>e.rung==="rep");
  if(engs.length===0) return;
  const boost = ladderBoostMultiplier("product");
  const order = G.company.orders.product;
  let shipMod=1, healthEach=6, bugRisk=0.1;
  if(order==="fast"){ shipMod=1.4; bugRisk=0.3; }
  else if(order==="stabilize"){ shipMod=0.7; healthEach=10; bugRisk=0.02; }
  else if(order==="innovate"){ shipMod=0.9; healthEach=14; bugRisk=0.15; }
  let shipped=0;
  engs.forEach(e=>{
    const chance = clamp(0.22 * (e.performance/70) * boost * shipMod, 0.03, 0.7);
    if(Math.random() < chance){
      shipped++;
      const feat = pick(["Faster dashboard load times","Mobile-friendly redesign","Advanced reporting","Automated onboarding",
        "Integrations marketplace","Smarter notifications","Bulk export tools","Improved search","Dark mode","Custom workflows"]);
      const maturityGain = rand(2,5);
      G.company.product.features.push({ name:feat, month:G.company.month, year:G.company.year, impact:{ clientHealth:healthEach, maturity:maturityGain } });
      G.company.product.maturity = clamp(G.company.product.maturity + maturityGain, 0, 100);
    }
  });
  if(shipped>0){
    G.company.clients.forEach(c=> c.health = clamp(c.health+healthEach, 0, 100));
    report.push(`Engineering shipped ${shipped} feature(s), lifting client health company-wide.`);
  }
  if(Math.random() < bugRisk && G.company.clients.length){
    const victim = pick(G.company.clients);
    victim.health = clamp(victim.health - rand(8,18), 0, 100);
    report.push(`A bug slipped through and hit ${victim.name}'s experience.`);
  }
  resolvePlannedFeature(report);
}
const FEATURE_DEFS = [
  { key:"onboarding_wizard", name:"Guided Onboarding Wizard", reqEngineers:2, reqTeamLeads:0, months:2, impact:{clientHealth:15, maturity:8} },
  { key:"enterprise_sso", name:"Enterprise SSO & Permissions", reqEngineers:3, reqTeamLeads:1, months:3, impact:{clientHealth:20, maturity:12} },
  { key:"mobile_app", name:"Native Mobile App", reqEngineers:4, reqTeamLeads:1, months:4, impact:{clientHealth:25, maturity:18} },
  { key:"ai_assist", name:"AI-Powered Assistant", reqEngineers:3, reqTeamLeads:1, months:3, impact:{clientHealth:18, maturity:15} },
  { key:"platform_api", name:"Public Platform API", reqEngineers:2, reqTeamLeads:0, months:2, impact:{clientHealth:12, maturity:10} },
];
function meetsFeatureReqs(def){
  return rungCount("product","rep")>=def.reqEngineers && rungCount("product","teamlead")>=def.reqTeamLeads;
}
function resolvePlannedFeature(report){
  const ip = G.company.product.inProgress;
  if(!ip) return;
  const def = FEATURE_DEFS.find(f=>f.key===ip.key);
  if(!def) { G.company.product.inProgress = null; return; }
  if(!meetsFeatureReqs(def)){
    report.push(`${def.name} is stalled — team no longer meets the staffing requirement.`);
    return;
  }
  ip.monthsLeft--;
  if(ip.monthsLeft<=0){
    G.company.product.features.push({ name:def.name, month:G.company.month, year:G.company.year, impact:def.impact });
    G.company.product.shipped.push(def.key);
    G.company.product.maturity = clamp(G.company.product.maturity + def.impact.maturity, 0, 100);
    G.company.clients.forEach(c=> c.health = clamp(c.health+def.impact.clientHealth, 0, 100));
    // Pricing power ratio: bigger, longer engineering investments earn a
    // permanent boost to what you can charge across all client segments.
    // effort = engineers x months invested; ~1.5% pricing power per effort-point.
    const effort = def.reqEngineers * def.months;
    const priceBoost = Math.round(effort * 1.5) / 100;
    G.company.pricingBoostFromFeatures = Math.round(((G.company.pricingBoostFromFeatures||0) + priceBoost) * 1000) / 1000;
    report.push(`🚀 Shipped major feature: ${def.name}! Client health +${def.impact.clientHealth}, maturity +${def.impact.maturity}, pricing power +${Math.round(priceBoost*100)}% (built with ${def.reqEngineers} engineer(s) over ${def.months} month(s)).`);
    G.company.product.inProgress = null;
  } else {
    report.push(`${def.name} is in progress — ${ip.monthsLeft} month(s) left.`);
  }
}

function resolveSupport(report){
  const agents = deptEmployees("support").filter(e=>e.rung==="rep");
  const boost = ladderBoostMultiplier("support");
  const order = G.company.orders.support;
  const capacity = agents.length * 6;
  let coveredHealth = 3 * boost;
  if(order==="outreach"){ coveredHealth = 6*boost; }
  else if(order==="blitz"){
    const risky = [...G.company.clients].sort((a,b)=>a.health-b.health).slice(0,Math.max(1,agents.length*2));
    risky.forEach(c=> c.health = clamp(c.health + rand(15,25), 0, 100));
    if(risky.length) report.push(`Support ran a retention blitz on ${risky.length} at-risk client(s).`);
  }
  if(order!=="blitz" && agents.length){
    const covered = G.company.clients.slice(0, capacity);
    covered.forEach(c=> c.health = clamp(c.health + coveredHealth, 0, 100));
  }
}

function churnMultiplier(){
  let m = 1;
  if(deptHas("support","cxo")) m *= 0.45;
  else if(deptHas("support","director")) m *= 0.65;
  if(deptHas("marketing","cmo")) m *= 0.85;
  if(deptHas("product","cto")) m *= 0.6;
  const maturityBonus = 1 - (G.company.product.maturity/100)*0.3;
  m *= maturityBonus;
  return m;
}

function resolveFinance(report){
  if(deptEmployees("finance").length===0) return;
  const order = G.company.orders.finance;
  if(order==="tighten"){ G.company.expensesBreakdown.other = Math.round(G.company.expensesBreakdown.other*0.85); report.push("Finance tightened the budget — overhead trimmed further."); }
  else if(order==="invest"){ Object.keys(G.company.assets).forEach(k=>{ if(k!=="hq") G.company.assets[k]*=1.005; }); report.push("Finance pushed for better investment returns this month."); }
}
function resolveOperations(report){
  if(deptEmployees("operations").length===0) return;
  const order = G.company.orders.operations;
  if(order==="efficiency"){ G.company.expensesBreakdown.tools = Math.round(G.company.expensesBreakdown.tools*0.85); report.push("Operations ran an efficiency drive — tooling costs down."); }
  else if(order==="capacity"){ report.push("Operations focused on capacity planning ahead of growth."); }
}
function resolveHR(report){
  if(deptEmployees("hr").length===0) return;
  const order = G.company.orders.hr;
  if(deptHas("hr","coordinator")) G.company.employees.forEach(e=>{ if(tenureMonths(e)===0) e.morale = clamp(e.morale+8,0,100); });
  if(deptHas("hr","teamlead")) G.company.employees.forEach(e=> e.morale = clamp(e.morale+1,0,100));
  if(deptHas("hr","chro")) G.company.employees.forEach(e=> e.morale = clamp(e.morale+4,0,100));
  if(order==="morale"){ G.company.employees.forEach(e=> e.morale = clamp(e.morale+6,0,100)); report.push("HR ran a morale push across the whole company."); }
  else if(order==="retention"){ G.company.employees.forEach(e=>{ if(e.morale<50) e.morale = clamp(e.morale+12,0,100); }); report.push("HR focused on retaining at-risk employees."); }
}
const BENEFITS_TIERS = [
  { name:"Basic", costPerEmp:0, moraleBonus:0, desc:"No formal benefits program yet." },
  { name:"Standard Health", costPerEmp:120, moraleBonus:5, desc:"Health coverage for the whole team." },
  { name:"Health + Vision", costPerEmp:220, moraleBonus:10, desc:"Health + vision, plus a small leader-only wellness stipend." },
  { name:"Premium Package", costPerEmp:380, moraleBonus:18, desc:"Full health/vision/dental + leader-only perks (parking, travel upgrades)." },
];
function benefitsMaxTier(){ return deptHas("hr","manager") ? (deptHas("hr","chro")?3:2) : (deptHas("hr","rep")?1:0); }
function overheadMultiplier(){
  let m = 1;
  if(deptHas("finance","coordinator")) m -= 0.05;
  if(deptHas("finance","teamlead")) m -= 0.03;
  if(deptHas("finance","cfo")) m -= 0.08;
  if(deptHas("operations","coordinator")) m -= 0.05;
  if(deptHas("operations","teamlead")) m -= 0.03;
  if(deptHas("operations","coo")) m -= 0.15;
  return Math.max(0.5, m);
}
function hasBoardSeat(key){ return (G.company.board||[]).includes(key); }
function effectiveLoanRate(){
  let r = deptHas("finance","cfo") ? G.company.debt.loanRate*0.6 : G.company.debt.loanRate;
  if(hasBoardSeat("finance")) r *= 0.85;
  return r;
}
function effectiveLocRate(){
  let r = deptHas("finance","cfo") ? G.company.debt.locRate*0.6 : G.company.debt.locRate;
  if(hasBoardSeat("finance")) r *= 0.85;
  return r;
}
function investReturnBoost(){
  let b = 0;
  if(deptHas("finance","manager")) b += 0.003;
  if(deptHas("finance","cfo")) b += 0.005;
  return b;
}

