function checkBadges(report){
  const c = G.company, p = G.personal;
  BADGE_DEFS.forEach(b=>{
    if(c.badges.includes(b.key)) return;
    if(b.check(c,p)){ c.badges.push(b.key); report.push(`🏅 Milestone unlocked: ${b.name}!`); }
  });
}
