function el(html){ const d=document.createElement("div"); d.innerHTML=html.trim(); return d.firstElementChild; }

function renderOnboard(){
  const ob = document.getElementById("onboard");
  const slots = listSlots();
  ob.style.display = "flex";
  ob.innerHTML = `
    <div class="ob-card">
      <h1>🚀 Business Empire Simulator</h1>
      <p class="sub">Start a new venture, or continue a saved one.</p>
      <label>Your name</label>
      <input id="obPlayer" placeholder="e.g. Felipe" />
      <label>Company / idea name</label>
      <input id="obName" placeholder="e.g. Cobalt Analytics" />
      <label>One-line pitch</label>
      <textarea id="obIdea" placeholder="e.g. Affordable analytics dashboards for small retailers"></textarea>
      <div class="ob-actions">
        <button class="btn" id="obStart">Start New Venture</button>
        <span class="muted" style="font-size:11px;">Starting cash: $30,000</span>
      </div>
      ${slots.length? `<div class="mt14"><label>Or load a save</label>
        <div class="saveslot-list">
          ${slots.map(s=>`<div class="saveslot">
              <span>${s.label}<br><span class="meta">Y${s.year||1} M${s.month||1} · ${fmt$(s.cash)}</span></span>
              <span class="flexrow">
                <button class="btn secondary small" data-load="${s.key}">Load</button>
                <button class="btn danger small" data-del="${s.key}">&times;</button>
              </span>
            </div>`).join("")}
        </div></div>`:""}
    </div>`;
  ob.querySelector("#obStart").onclick = ()=>{
    const player = ob.querySelector("#obPlayer").value.trim() || "Founder";
    const name = ob.querySelector("#obName").value.trim() || "Untitled Venture";
    const idea = ob.querySelector("#obIdea").value.trim();
    G = normalizeGame(newGame(player, name, idea));
    ob.style.display="none";
    renderAll();
  };
  ob.querySelectorAll("[data-load]").forEach(b=> b.onclick = ()=>{
    G = normalizeGame(loadSlot(b.getAttribute("data-load")));
    ob.style.display="none";
    renderAll();
  });
  ob.querySelectorAll("[data-del]").forEach(b=> b.onclick = (e)=>{ e.stopPropagation(); deleteSlot(b.getAttribute("data-del")); renderOnboard(); });
}

