function renderTopbar(){
  recomputeMRR();
  const c = G.company;
  const expenses = Object.values(c.expensesBreakdown).reduce((a,b)=>a+b,0);
  const bar = document.createElement("div");
  bar.id="topbar";
  const debtTotal = c.debt.loanBalance + c.debt.locBalance;
  bar.innerHTML = `
    <div class="stat"><div class="label">Cash</div><div class="value ${c.cash<0?'bad':''}">${fmt$(c.cash)}</div></div>
    <div class="stat"><div class="label">MRR</div><div class="value good">${fmt$(c.mrr)}</div></div>
    <div class="stat" title="MRR plus any business-line revenue — all recurring cash generated by the company this month."><div class="label">Revenue/mo ⓘ</div><div class="value good">${fmt$(c.mrr + c.businessLines.reduce((s,l)=>s+l.monthlyRevenue,0))}</div></div>
    <div class="stat" title="Recurring costs as of your last month close (salaries, rent, tools, debt service). One-off spend like bonuses/hires/upgrades is separate and shown in the month-end summary."><div class="label">Expenses/mo ⓘ</div><div class="value bad">${fmt$(expenses)}</div></div>
    <div class="stat"><div class="label">Net Worth</div><div class="value ${c.netWorth<0?'bad':''}">${fmt$(c.netWorth)}</div></div>
    <div class="stat"><div class="label">Employees</div><div class="value">${c.employees.length}/${headcountCap()}</div></div>
    <div class="stat" title="Weighted score: 30% avg employee morale, 25% avg client health, 25% last month's profit, 20% MRR growth trend, minus a penalty for consecutive distress months."><div class="label">Success ⓘ</div><div class="value ${c.successScore>=60?'good':c.successScore<35?'bad':''}">${c.successScore}</div></div>
    ${debtTotal>0? `<div class="stat"><div class="label">Debt</div><div class="value bad">${fmt$(debtTotal)}</div></div>`:""}
    <div class="grow"></div>
    <div class="datebox">${G.meta.playerName} · ${G.meta.name}<br>Year ${c.year} · Month ${c.month}</div>
    <button class="btn" id="advanceBtn">Advance Month ▶</button>
  `;
  document.getElementById("app").querySelector("#topbar")?.remove();
  document.getElementById("app").prepend(bar);
  bar.querySelector("#advanceBtn").onclick = ()=>{ confirmAndAdvance(); };
}

