function shopCard(item, kind){
  const p = G.personal;
  const owned = kind==="house"? p.assets.houses.some(h=>h.key===item.key)
    : kind==="car"? p.assets.cars.some(c=>c.key===item.key) : false;
  const locked = item.minNetWorth>0 && p.netWorth<item.minNetWorth;
  const vacationLocked = kind==="vacation" && G.company.vacationUsedThisMonth;
  return `<div class="shop-card ${locked?'locked-overlay':''}">
    ${locked?`<div class="locked-badge">Requires ${fmt$(item.minNetWorth)} net worth</div>`:""}
    <img src="${IMG[item.img]}" />
    <div class="info">
      <div class="name">${item.name} ${owned?'<span class="pill good">Owned</span>':''}</div>
      <div class="feat">${item.feat}</div>
      <div class="price">${fmt$(item.price)}${kind==='house'?` · ~${fmt$(item.mortgage)}/mo mortgage`:''}</div>
      ${owned? "" : `<button class="btn small" ${locked||vacationLocked?'disabled':''} data-buy="${kind}:${item.key}">${kind==='vacation'?'Book Trip':'Buy'}</button>`}
    </div></div>`;
}

function renderPersonal(){
  const p = G.personal;
  if(!p.assets.houses) p.assets.houses=[];
  if(!p.assets.cars) p.assets.cars=[];
  if(p.kenzie===undefined) p.kenzie=70;
  const totalExp = Object.values(p.expenses).reduce((a,b)=>a+b,0);
  const wrap = el(`<div></div>`);
  const primaryHouse = p.assets.houses.find(h=>h.primary);
  wrap.innerHTML = `
    <div class="window-title"><h2>🏡 Personal Dashboard</h2><span class="sub">${G.meta.playerName}'s own finances</span></div>
    <div class="grid cols-3">
      <div class="card"><h3>Personal Cash</h3><div class="big">${fmt$(p.cash)}</div></div>
      <div class="card"><h3>Monthly Salary</h3><div class="big good">${fmt$(p.salaryDraw)}</div></div>
      <div class="card"><h3>Total Net Worth</h3><div class="big">${fmt$(p.totalNetWorth||p.netWorth)}</div>
        <div class="muted" style="font-size:11px;">Personal ${fmt$(p.netWorth)} + Business (your ownership) ${fmt$(G.company.valuation||0)}</div></div>
    </div>
    <div class="card mt14"><h3>💼 My Compensation</h3>
      <div class="muted mb8" style="font-size:12px;">As founder/CEO, you set your own salary and can award yourself a bonus — both come straight out of company cash.</div>
      <div class="barrow"><span class="lbl">Monthly Salary</span>
        <span class="flexrow" style="align-items:center;">
          <button class="btn secondary small" id="salaryDown">−</button>
          <b style="min-width:80px;text-align:center;display:inline-block;">${fmt$(p.salaryDraw)}</b>
          <button class="btn secondary small" id="salaryUp">+</button>
        </span>
      </div>
      <div class="muted" style="font-size:11px;">Adjusts in ${fmt$(500)} steps · capped near what the company can sustain.</div>
      <div class="mt8"><button class="btn small" id="selfBonusBtn">🎁 Give Myself a Bonus</button></div>
    </div>
    <div class="card mt14"><h3>Net Worth Breakdown</h3>
      ${(()=>{
        const houseVal = p.assets.houses.reduce((s,h)=>s+(h.price||0)*(h.valueMult||1),0);
        const carVal = p.assets.cars.reduce((s,c)=>s+(c.price||0),0);
        const toyVal = (p.assets.toys||[]).reduce((s,t)=>s+(t.price||0),0);
        const rows = [
          ["Cash on hand", p.cash],
          ["Houses", houseVal],
          ["Cars", carVal],
          ["Big Toys (yacht/island)", toyVal],
          ["Business ownership (valuation)", G.company.valuation||0],
        ];
        const total = rows.reduce((s,[,v])=>s+v,0) || 1;
        return rows.filter(([,v])=>v!==0).map(([label,v])=>`<div class="barrow"><span class="lbl">${label}</span><div class="track"><div class="fill" style="width:${clamp(100*v/total,0,100)}%;background:${v<0?'var(--bad)':'var(--good)'};"></div></div><span>${fmt$(v)}</span></div>`).join("")
          || `<div class="muted">Nothing accumulated yet — start earning and buying!</div>`;
      })()}
    </div>
    <div class="grid cols-2 mt14">
      <div class="card"><h3>Monthly Expenses (${fmt$(totalExp)})</h3>
        ${Object.entries(p.expenses).map(([k,v])=>`<div class="barrow"><span class="lbl">${k}</span><div class="track"><div class="fill" style="width:${100*v/Math.max(1,totalExp)}%;background:var(--bad);"></div></div><span>${fmt$(v)}</span></div>`).join("")}
      </div>
      <div class="card"><h3>Life</h3>
        <div class="barrow"><span class="lbl">Happiness</span><div class="track"><div class="fill" style="width:${p.happiness}%;background:var(--good);"></div></div><span>${p.happiness}</span></div>
        <div class="barrow"><span class="lbl">${spouseName()} ❤️</span><div class="track"><div class="fill" style="width:${p.kenzie}%;background:#e0679a;"></div></div><span>${p.kenzie}</span></div>
        <div class="muted mt8" style="font-size:12px;">Home: ${primaryHouse?primaryHouse.name:"Renting"} · Cars owned: ${p.assets.cars.length} · Vacations: ${p.assets.vacationHistory.length}</div>
        ${p.kenzie<30?`<div class="mt8" style="color:var(--bad);font-size:12px;">${spouseName()}'s feeling neglected — maybe plan a date night.</div>`:""}
      </div>
    </div>
    <div class="card mt14"><h3>Date Night with ${spouseName()}</h3>
      <div class="flexrow">${DATE_NIGHTS.map(d=>`<button class="btn secondary small" data-date="${d.key}" ${G.company.dateNightUsedThisMonth?'disabled':''}>${d.name} (${fmt$(d.price)})</button>`).join("")}</div>
      ${G.company.dateNightUsedThisMonth? `<div class="muted mt8" style="font-size:11.5px;">Already had a date night this month — next one resets after you advance the month.</div>`:""}
    </div>
    <div class="card mt14 muted" style="font-size:12.5px;">🛍️ Houses, cars, vacations, gifts, and big toys have moved to the <b>Market vs Owned</b> tab for a cleaner shopping view.</div>
  `;
  wrap.querySelectorAll("[data-date]").forEach(b=> b.onclick=()=>{
    if(G.company.dateNightUsedThisMonth) return;
    const d = DATE_NIGHTS.find(x=>x.key===b.getAttribute("data-date"));
    if(p.cash<d.price){ alert("Not enough personal cash."); return; }
    p.cash-=d.price; p.happiness=clamp(p.happiness+d.happiness,0,100); p.kenzie=clamp(p.kenzie+d.kenzie,0,100);
    G.company.dateNightUsedThisMonth = true;
    p.monthEvents.push(`Date night with ${spouseName()}: ${d.name} (${fmt$(d.price)})`);
    renderScreen();
  });
  const salaryCap = Math.max(3500, Math.round((G.company.mrr||0)*0.6) + 3500);
  wrap.querySelector("#salaryUp")?.addEventListener("click", ()=>{
    p.salaryDraw = Math.min(salaryCap, p.salaryDraw + 500);
    p.monthEvents.push(`Adjusted salary to ${fmt$(p.salaryDraw)}/mo`);
    renderScreen();
  });
  wrap.querySelector("#salaryDown")?.addEventListener("click", ()=>{
    p.salaryDraw = Math.max(0, p.salaryDraw - 500);
    p.monthEvents.push(`Adjusted salary to ${fmt$(p.salaryDraw)}/mo`);
    renderScreen();
  });
  wrap.querySelector("#selfBonusBtn")?.addEventListener("click", ()=>{
    const amountStr = window.prompt("How much of a bonus would you like to give yourself (paid from company cash)?", "1000");
    const amount = Number(amountStr);
    if(!amount || amount<=0) return;
    if(!affordOrAlert(amount, "your bonus")) return;
    queueAdd({ id:uid(), label:`Founder bonus to self`, cost:amount, run:(report)=>{
      if(G.company.cash<amount){ report.push(`Skipped your founder bonus — insufficient company cash.`); return; }
      G.company.cash -= amount;
      G.personal.cash += amount;
      G.personal.happiness = clamp(G.personal.happiness+8,0,100);
      G.personal.monthEvents.push(`Gave yourself a ${fmt$(amount)} bonus from company cash`);
      report.push(`You paid yourself a ${fmt$(amount)} bonus from company cash.`);
    }});
    renderScreen();
  });
  return wrap;
}

