const INDUSTRY_KEYS = ["ai_saas","retail","restaurant","robotics","finance"];
function industryOf(co){ return INDUSTRIES[(co && co.industry) || "ai_saas"] || INDUSTRIES.ai_saas; }
function industry(){ return industryOf(G && G.company); }
function applyIndustryLabels(){
  const cfg = industry();
  DEPT_KEYS.forEach(dk=>{
    LADDERS[dk].label = (cfg.deptLabels && cfg.deptLabels[dk]) || BASE_LADDERS[dk].label;
    LADDERS[dk].rungs.forEach((r,i)=>{
      const names = cfg.roles && cfg.roles[dk];
      r.label = (names && names[i]) || BASE_LADDERS[dk].rungs[i].label;
    });
  });
}
function segmentNamePool(segment){
  const cfg = industry();
  return (cfg.accounts && cfg.accounts[segment]) || INDUSTRIES.ai_saas.accounts[segment];
}

/* ---------------- Equity / cap table ---------------- */
const TOTAL_SHARES = 10000000;
function initEquity(){
  return { totalShares:TOTAL_SHARES, founder:9000000, pool:1000000, grants:[], investors:[], dividendsPaid:0 };
}
function eq(co){ co = co || G.company; if(!co.equity) co.equity = initEquity(); return co.equity; }
function founderPct(co){ co = co || G.company; return eq(co).founder / eq(co).totalShares; }
function grantedShares(co){ return eq(co).grants.reduce((s,g)=>s+g.shares,0); }
function vestedShares(g){ return Math.round(g.shares * clamp(g.vestedMonths/g.vestMonths,0,1)); }
function stakeValue(co){ return Math.round((co.valuation||0) * founderPct(co)); }
function grantEquity(empId, pct, vestMonths){
  const co = G.company, e = co.employees.find(x=>x.id===empId);
  if(!e) return "Employee not found.";
  const shares = Math.round(eq(co).totalShares * (pct/100));
  if(shares > eq(co).pool) return `Option pool only has ${(100*eq(co).pool/eq(co).totalShares).toFixed(2)}% left.`;
  eq(co).pool -= shares;
  eq(co).grants.push({ id:uid(), empId, name:e.name, role:e.role, shares, vestMonths:vestMonths||48, vestedMonths:0,
    grantedMonth:co.month, grantedYear:co.year });
  e.morale = clamp(e.morale + Math.min(25, Math.round(pct*12)), 0, 100);
  e.equityShares = (e.equityShares||0) + shares;
  logHistory(`Granted ${e.name} ${pct}% equity (${shares.toLocaleString()} shares, ${vestMonths||48}-month vest).`);
  return null;
}
function sellFounderShares(pct){
  const co = G.company;
  const shares = Math.round(eq(co).totalShares * (pct/100));
  if(shares > eq(co).founder) return "You don't own that many shares.";
  const gross = Math.round((co.valuation||0) * (pct/100) * 0.85);
  eq(co).founder -= shares;
  eq(co).investors.push({ id:uid(), name: pick(["Northbridge Capital","Summit Secondary Fund","Halcyon Partners","Grove Street Holdings"]),
    shares, boughtAtValuation: co.valuation, month:co.month, year:co.year });
  G.personal.cash += gross;
  G.personal.monthEvents.push(`Sold ${pct}% of ${co.name} for ${fmt$(gross)}`);
  logHistory(`Sold ${pct}% of ${co.name} on the secondary market for ${fmt$(gross)} (15% illiquidity discount).`);
  return null;
}
function vestingTick(co, report){
  eq(co).grants.forEach(g=>{
    if(g.vestedMonths < g.vestMonths){
      g.vestedMonths++;
      if(g.vestedMonths===g.vestMonths) report.push(`\u{1F4DC} ${g.name}'s equity grant is now fully vested.`);
    }
  });
}
function declareDividend(amount){
  const co = G.company;
  if(co.cash < amount) return "Not enough company cash.";
  co.cash -= amount;
  const mine = Math.round(amount * founderPct(co));
  G.personal.cash += mine;
  eq(co).dividendsPaid += amount;
  logHistory(`Declared a ${fmt$(amount)} dividend \u2014 your ${(founderPct(co)*100).toFixed(1)}% share was ${fmt$(mine)}.`);
  return null;
}

/* ---------------- Multi-company plumbing ---------------- */
function defineActiveAccessors(g){
  const cDesc = Object.getOwnPropertyDescriptor(g, "company");
  if(!cDesc || !cDesc.get){
    try{ delete g.company; }catch(e){}
    Object.defineProperty(g, "company", {
      get(){ return g.companies[g.activeCompanyIndex]; },
      set(v){ g.companies[g.activeCompanyIndex] = v; },
      enumerable:false, configurable:true });
  }
  const mDesc = Object.getOwnPropertyDescriptor(g, "meta");
  if(!mDesc || !mDesc.get){
    try{ delete g.meta; }catch(e){}
    Object.defineProperty(g, "meta", {
      get(){ const co = g.companies[g.activeCompanyIndex] || {};
        return { playerName: g.playerMeta.playerName, name: co.name, idea: co.idea, createdAt: g.playerMeta.createdAt }; },
      enumerable:false, configurable:true });
  }
}
function buildCompany(name, idea, industryKey, seedCash){
  const base = newGameLegacyBase(G && G.playerMeta ? G.playerMeta.playerName : "Founder", name, idea);
  const co = base.company;
  co.id = uid();
  co.name = name || "Untitled Venture";
  co.idea = idea || "";
  co.industry = industryKey || "ai_saas";
  co.cash = seedCash!=null ? seedCash : INDUSTRIES[co.industry].startCash;
  co.equity = initEquity();
  co.ceo = { type:"player" };
  co.passive = false;
  co.ops = opsInit(co.industry);
  co.opsLog = [];
  co.foundedAt = Date.now();
  co.costPolicy = { lean:false };
  return co;
}
function foundNewCompany(name, idea, industryKey, seedFromPersonal){
  const cfg = INDUSTRIES[industryKey] || INDUSTRIES.ai_saas;
  const seed = seedFromPersonal!=null ? seedFromPersonal : cfg.startCash;
  if(G.personal.cash < seed) return `You need ${fmt$(seed)} of personal cash to seed a ${cfg.label}.`;
  G.personal.cash -= seed;
  const co = buildCompany(name, idea, industryKey, seed);
  G.companies.push(co);
  G.personal.monthEvents.push(`Founded ${co.name} (${cfg.label}) with ${fmt$(seed)} of personal capital`);
  logHistory(`Founded a new company: ${co.name} (${cfg.label}), seeded with ${fmt$(seed)} of your own money.`);
  return null;
}
function switchCompany(idx){
  if(idx<0 || idx>=G.companies.length) return;
  G.activeCompanyIndex = idx;
  G.ui.activeSlackId = null;
  G.ui.openDept = null;
  applyIndustryLabels();
  renderAll();
}
function stepAwayAsCEO(){
  const co = G.company;
  const salary = rand(26000, 38000);
  co.ceo = { type:"hired", name: generateName(), salary };
  co.passive = true;
  logHistory(`Stepped away as CEO of ${co.name} \u2014 hired ${co.ceo.name} at ${fmt$(salary)}/mo. You still own ${(founderPct(co)*100).toFixed(1)}%.`);
}
function resumeAsCEO(idx){
  const co = G.companies[idx];
  co.ceo = { type:"player" };
  co.passive = false;
  logHistory(`Took back the CEO seat at ${co.name}.`);
}

/* ---------------- Industry ops: state ---------------- */
const RETAIL_STORES = [
  { key:"kiosk", name:"Mall Kiosk", cost:9000, rent:1500, baseDemand:420 },
  { key:"store", name:"Street-Front Store", cost:60000, rent:7000, baseDemand:850 },
  { key:"flagship", name:"Flagship Store", cost:250000, rent:17000, baseDemand:3400 },
];
const REST_LOCATIONS = [
  { key:"truck", name:"Food Truck", cost:28000, rent:1500, baseCovers:1150 },
  { key:"bistro", name:"Neighborhood Bistro", cost:180000, rent:6500, baseCovers:2200 },
  { key:"fine", name:"Fine Dining Room", cost:600000, rent:18000, baseCovers:3100 },
];
const ROBO_LINES = [
  { key:"cell", name:"Assembly Cell", cost:78000, rent:3000, capacity:8 },
  { key:"line", name:"Production Line", cost:500000, rent:14000, capacity:30 },
  { key:"plant", name:"Automated Plant", cost:2000000, rent:45000, capacity:120 },
];
const ROBO_MODELS = [
  { key:"palletizer", name:"Warehouse Palletizer", months:3, reqEngineers:2, unitPrice:48000, unitCost:26000 },
  { key:"cobot", name:"Collaborative Arm (Cobot)", months:4, reqEngineers:3, unitPrice:82000, unitCost:41000 },
  { key:"amr", name:"Autonomous Mobile Robot", months:5, reqEngineers:4, unitPrice:135000, unitCost:62000 },
  { key:"surgical", name:"Surgical Assist Platform", months:7, reqEngineers:6, unitPrice:410000, unitCost:180000 },
];
const PRICE_TIER_OPTS = [ {v:0.85,label:"Value"}, {v:1,label:"Standard"}, {v:1.25,label:"Premium"} ];
const UNDERWRITING = [
  { key:"tight", label:"Tight", rate:0.0075, defaults:0.002, growth:0.6 },
  { key:"balanced", label:"Balanced", rate:0.0095, defaults:0.005, growth:1.0 },
  { key:"loose", label:"Loose", rate:0.0125, defaults:0.014, growth:1.5 },
];
function opsInit(industryKey){
  if(industryKey==="retail") return { type:"retail", stores:[], priceTier:1, satisfaction:70, lastNet:0, lastGross:0 };
  if(industryKey==="restaurant") return { type:"restaurant", locations:[], priceTier:1, quality:62, inspectionFails:0, lastNet:0, lastGross:0 };
  if(industryKey==="robotics") return { type:"robotics", lines:[], released:[], rnd:null, backlog:0, delivered:0, lastNet:0, lastGross:0 };
  if(industryKey==="finance") return { type:"finance", deposits:250000, loanBook:0, underwriting:"balanced", insuranceBook:0, chargeOffs:0, lastNet:0, lastGross:0 };
  return null;
}
function opsSpend(amount, label){
  const co = G.company;
  if(co.cash < amount){ alert(`Not enough company cash for ${label} (${fmt$(amount)}). You have ${fmt$(co.cash)}.`); return false; }
  co.cash -= amount;
  logHistory(`${label} \u2014 ${fmt$(amount)} paid from company cash.`);
  return true;
}
function marketingBoost(){
  const specs = rungCount("marketing","rep");
  let b = 0.03*specs;
  if(deptHas("marketing","manager")) b += 0.05;
  if(deptHas("marketing","cmo")) b += 0.12;
  return b;
}

/* ---------------- Industry ops: monthly resolution ---------------- */
function opsResolve(co, report){
  const o = co.ops;
  if(!o) return 0;
  if(o.type==="retail") return opsResolveRetail(co, report);
  if(o.type==="restaurant") return opsResolveRestaurant(co, report);
  if(o.type==="robotics") return opsResolveRobotics(co, report);
  if(o.type==="finance") return opsResolveFinance(co, report);
  return 0;
}
function opsResolveRetail(co, report){
  const o = co.ops;
  if(o.stores.length===0){ o.lastNet=0; o.lastGross=0; return 0; }
  const assoc = rungCount("sales","rep");
  const merch = rungCount("product","rep");
  const supply = rungCount("operations","rep");
  const price = 42 * o.priceTier;
  const unitCost = 19 * (supply>0 ? 0.92 : 1);
  const elasticity = o.priceTier>1.1 ? 0.8 : o.priceTier<0.95 ? 1.18 : 1;
  let gross=0, cogs=0, rent=0, sold=0, stockouts=0;
  o.stores.forEach(s=>{
    rent += s.rent;
    const staffed = 1 + 0.045*assoc + 0.03*merch;
    const demand = Math.round(s.baseDemand * staffed * (1+marketingBoost()) * elasticity * randf(0.85,1.15) * (0.7 + o.satisfaction/200));
    const affordable = Math.floor(s.inventory / unitCost);
    const units = Math.min(demand, affordable);
    sold += units;
    s.inventory = Math.max(0, s.inventory - units*unitCost);
    gross += units*price; cogs += units*unitCost;
    if(demand > affordable) stockouts++;
  });
  if(stockouts>0){
    o.satisfaction = clamp(o.satisfaction - 4*stockouts, 0, 100);
    report.push(`\u{1F6CD}\uFE0F ${stockouts} store(s) ran out of stock \u2014 lost sales; customer satisfaction down to ${o.satisfaction}.`);
  } else {
    o.satisfaction = clamp(o.satisfaction + 2, 0, 100);
  }
  const net = Math.round(gross - cogs - rent);
  o.lastGross = Math.round(gross); o.lastNet = net;
  report.push(`\u{1F6CD}\uFE0F Stores sold ${sold.toLocaleString()} unit(s) for ${fmt$(gross)} (COGS ${fmt$(cogs)}, rent ${fmt$(rent)}) \u2192 ${fmt$(net)} store contribution.`);
  return net;
}
function opsResolveRestaurant(co, report){
  const o = co.ops;
  if(o.locations.length===0){ o.lastNet=0; o.lastGross=0; return 0; }
  const kitchen = rungCount("product","rep");
  const foh = rungCount("support","rep");
  const ticket = 31 * o.priceTier;
  const elasticity = o.priceTier>1.1 ? 0.82 : o.priceTier<0.95 ? 1.2 : 1;
  let gross=0, rent=0, covers=0;
  o.locations.forEach(l=>{
    rent += l.rent;
    const service = 1 + 0.035*foh + 0.02*kitchen;
    const c = Math.round(l.baseCovers * service * (0.65 + o.quality/150) * (1+marketingBoost()) * elasticity * randf(0.88,1.12));
    covers += c;
    gross += c*ticket;
  });
  const food = Math.round(gross * (kitchen>0 ? 0.29 : 0.34));
  const qDrift = -4 + Math.min(8, kitchen*1.2) + (deptHas("product","manager")?2:0);
  o.quality = clamp(o.quality + qDrift, 0, 100);
  let penalty = 0;
  if(o.quality < 42 && Math.random() < 0.35){
    penalty = Math.round(3500 + gross*0.05);
    o.inspectionFails = (o.inspectionFails||0)+1;
    co.successScore = clamp(co.successScore-6,0,100);
    report.push(`\u{1F6A8} Health inspection failed (quality ${Math.round(o.quality)}) \u2014 ${fmt$(penalty)} in fines and remediation. Invest in the kitchen.`);
  }
  const net = Math.round(gross - food - rent - penalty);
  o.lastGross = Math.round(gross); o.lastNet = net;
  report.push(`\u{1F37D}\uFE0F Served ${covers.toLocaleString()} covers for ${fmt$(gross)} (food cost ${fmt$(food)}, rent ${fmt$(rent)}) \u2192 ${fmt$(net)} restaurant contribution. Quality ${Math.round(o.quality)}/100.`);
  return net;
}
function opsResolveRobotics(co, report){
  const o = co.ops;
  const engineers = rungCount("product","rep");
  const techs = rungCount("operations","rep");
  if(o.rnd){
    const def = ROBO_MODELS.find(m=>m.key===o.rnd.key);
    if(engineers >= def.reqEngineers){
      o.rnd.monthsLeft--;
      if(o.rnd.monthsLeft<=0){
        o.released.push(def.key);
        co.product.maturity = clamp(co.product.maturity+12,0,100);
        report.push(`\u{1F9BE} R&D complete \u2014 the ${def.name} is released for production at ${fmt$(def.unitPrice)}/unit.`);
        o.rnd = null;
      } else report.push(`\u{1F9BE} ${def.name} R&D in progress \u2014 ${o.rnd.monthsLeft} month(s) left.`);
    } else {
      report.push(`\u{1F9BE} ${def.name} R&D stalled \u2014 needs ${def.reqEngineers} engineer(s), you have ${engineers}.`);
    }
  }
  const flagship = o.released.map(k=>ROBO_MODELS.find(m=>m.key===k)).sort((a,b)=>b.unitPrice-a.unitPrice)[0];
  if(!flagship){
    o.lastNet=0; o.lastGross=0;
    if(!o.rnd) report.push("\u{1F9BE} No robot model released yet \u2014 start an R&D project on the Industry Ops tab.");
    return 0;
  }
  const reps = rungCount("sales","rep");
  const newOrders = Math.round((reps*randf(0.8,2.2) + marketingBoost()*6) * (deptHas("sales","manager")?1.2:1));
  o.backlog += newOrders;
  const capacity = o.lines.reduce((s,l)=>s+l.capacity,0) * (1 + 0.03*techs);
  const rent = o.lines.reduce((s,l)=>s+l.rent,0);
  const produced = Math.min(Math.floor(capacity), o.backlog);
  o.backlog -= produced;
  o.delivered = (o.delivered||0) + produced;
  const gross = produced * flagship.unitPrice;
  const cogs = produced * flagship.unitCost;
  if(o.backlog > Math.max(5, capacity*2)){
    co.successScore = clamp(co.successScore-4,0,100);
    report.push(`\u{1F9BE} Backlog is ${o.backlog} unit(s) against ${Math.floor(capacity)} units/mo of capacity \u2014 customers are frustrated. Build more capacity.`);
  }
  const net = Math.round(gross - cogs - rent);
  o.lastGross = Math.round(gross); o.lastNet = net;
  report.push(`\u{1F9BE} Took ${newOrders} new order(s), shipped ${produced} ${flagship.name}(s) for ${fmt$(gross)} (build cost ${fmt$(cogs)}, plant ${fmt$(rent)}) \u2192 ${fmt$(net)} manufacturing contribution.`);
  return net;
}
function opsResolveFinance(co, report){
  const o = co.ops;
  const uw = UNDERWRITING.find(u=>u.key===o.underwriting) || UNDERWRITING[1];
  const officers = rungCount("sales","rep");
  const underwriters = rungCount("product","rep");
  const tellers = rungCount("support","rep");
  const depGrowth = o.deposits * (0.004 + marketingBoost()*0.05) + tellers*18000;
  o.deposits = Math.round(o.deposits + depGrowth);
  const maxBook = Math.round(o.deposits*0.85);
  if(officers>0 && o.loanBook < maxBook){
    const originate = Math.min(maxBook - o.loanBook, Math.round(officers*120000*uw.growth*randf(0.7,1.3)));
    o.loanBook += originate;
    if(originate>0) report.push(`\u{1F3E6} Originated ${fmt$(originate)} of new loans (${uw.label} underwriting).`);
  }
  const interest = Math.round(o.loanBook * uw.rate);
  const depositCost = Math.round(o.deposits * 0.0016);
  const defaultRate = uw.defaults * (underwriters>0 ? Math.max(0.45, 1 - 0.08*underwriters) : 1.25);
  const chargeOffs = Math.round(o.loanBook * defaultRate * randf(0.4,1.8));
  o.loanBook = Math.max(0, o.loanBook - chargeOffs);
  o.chargeOffs = (o.chargeOffs||0) + chargeOffs;
  let premiums = 0, claims = 0;
  if(o.insuranceBook>0){
    premiums = Math.round(o.insuranceBook * 0.022);
    claims = Math.round(o.insuranceBook * 0.014 * randf(0.3,2.1));
  }
  const net = interest + premiums - depositCost - chargeOffs - claims;
  o.lastGross = interest + premiums; o.lastNet = net;
  report.push(`\u{1F3E6} Spread income ${fmt$(interest)}${premiums?` + premiums ${fmt$(premiums)}`:""} minus deposit cost ${fmt$(depositCost)}, charge-offs ${fmt$(chargeOffs)}${claims?`, claims ${fmt$(claims)}`:""} \u2192 ${fmt$(net)}. Book: ${fmt$(o.loanBook)} loans on ${fmt$(o.deposits)} deposits.`);
  return Math.round(net);
}
function setOpsLine(co, net){
  co.businessLines = (co.businessLines||[]).filter(l=>l.id!=="ops_line");
  if(net!==0) co.businessLines.push({ id:"ops_line", name: industryOf(co).revenueLabel, monthlyRevenue: Math.round(net) });
}

/* ---------------- Passive companies ---------------- */
function recomputePassiveValuation(co){
  const assetTotal = Object.entries(co.assets).filter(([k])=>k!=="hq").reduce((s,[,v])=>s+(typeof v==="number"?v:0),0);
  co.netWorth = Math.round(co.cash + assetTotal - co.debt.loanBalance - co.debt.locBalance);
  const opsMult = co.ops ? Math.max(0, (co.ops.lastNet||0)*14) : 0;
  co.valuation = Math.round(Math.max(co.netWorth, co.mrr*24 + opsMult));
}
function simulatePassiveCompany(co, report){
  const salaries = co.employees.reduce((s,e)=>s+e.salary,0);
  const ceoSalary = (co.ceo && co.ceo.salary) || 0;
  const rentMap = [0,600,1800,4500];
  const opsNet = co.ops ? Math.round((co.ops.lastNet||0) * randf(0.92,1.08)) : 0;
  const revenue = Math.round(co.mrr * randf(0.98,1.04)) + opsNet;
  const expenses = (Number(salaries)||0) + (Number(ceoSalary)||0) + (rentMap[Math.max(0, Math.min(3, Number(co.hqStage)||0))] || 0) + 400;
  const profit = revenue - expenses;
  if(isFinite(profit)) co.cash = (Number(co.cash)||0) + profit;
  co.mrr = Math.round(co.mrr * randf(0.99,1.03));
  recomputePassiveValuation(co);
  co.month++;
  if(co.month>12){ co.month=1; co.year++; }
  co.financialHistory.push({ month:co.month, year:co.year, revenue, expenses, netProfit:profit, cash:co.cash, mrr:co.mrr });
  if(co.financialHistory.length>36) co.financialHistory.shift();
  if(profit>0 && co.cash > expenses*3){
    const payout = Math.round(profit*0.5);
    co.cash -= payout;
    const mine = Math.round(payout * founderPct(co));
    G.personal.cash += mine;
    eq(co).dividendsPaid += payout;
    report.push(`\u{1F4BC} ${co.name} (run by ${co.ceo.name}) netted ${fmt$(profit)} and paid you ${fmt$(mine)} in dividends.`);
  } else if(profit<0){
    report.push(`\u{1F4BC} ${co.name} ran a ${fmt$(-profit)} loss under ${co.ceo.name}. Cash on hand: ${fmt$(co.cash)}.`);
  }
}
function passiveCompaniesTick(report){
  G.companies.forEach((co,i)=>{ if(i!==G.activeCompanyIndex && co.passive) simulatePassiveCompany(co, report); });
}
function empireNetWorthTick(){
  const p = G.personal;
  const stakes = G.companies.reduce((s,co)=> s + Math.round((co.valuation||0)*founderPct(co)), 0);
  p.totalNetWorth = Math.round(p.netWorth + stakes);
}
function activeValuationWithOps(){
  const co = G.company;
  if(!co.ops) return;
  const opsMult = Math.max(0, (co.ops.lastNet||0)*14);
  co.valuation = Math.round(Math.max(co.valuation, co.netWorth, co.mrr*24 + opsMult));
}

/* ---------------- New game / normalize (v8) ---------------- */
function newGame(playerName, companyName, idea, industryKey, spouse){
  const base = newGameLegacyBase(playerName, companyName, idea);
  const g = {
    version: SCHEMA_VERSION,
    playerMeta:{ playerName: playerName||"Founder", createdAt: Date.now() },
    companies: [],
    activeCompanyIndex: 0,
    personal: base.personal,
    ui: base.ui,
    assistantChat: [],
  };
  const co = base.company;
  co.id = uid();
  co.name = companyName || "Untitled Venture";
  co.idea = idea || "";
  co.industry = industryKey || "ai_saas";
  co.cash = INDUSTRIES[co.industry].startCash;
  co.equity = initEquity();
  co.ceo = { type:"player" };
  co.passive = false;
  co.ops = opsInit(co.industry);
  co.opsLog = [];
  g.companies.push(co);
  g.personal.spouseName = (spouse && spouse.trim()) || "Spouse";
  defineActiveAccessors(g);
  return g;
}
function normalizeCompanyV8(co){
  if(!co.id) co.id = uid();
  if(!co.name) co.name = "Untitled Venture";
  if(co.idea===undefined) co.idea = "";
  if(!co.industry) co.industry = "ai_saas";
  if(!co.equity) co.equity = initEquity();
  if(co.equity.dividendsPaid===undefined) co.equity.dividendsPaid = 0;
  if(!co.equity.grants) co.equity.grants = [];
  if(!co.equity.investors) co.equity.investors = [];
  if(!co.ceo) co.ceo = { type:"player" };
  if(co.passive===undefined) co.passive = false;
  const wantType = INDUSTRIES[co.industry].opsType || null;
  if(co.ops===undefined || (co.ops ? co.ops.type : null) !== wantType) co.ops = opsInit(co.industry);
  if(!co.opsLog) co.opsLog = [];
}
function normalizeGameV11(g){
  if(!g) return g;
  if(!g.companies){
    const legacyCo = g.company;
    const legacyMeta = g.meta || {};
    g.playerMeta = { playerName: legacyMeta.playerName || "Founder", createdAt: legacyMeta.createdAt || Date.now() };
    legacyCo.name = legacyMeta.name || "Untitled Venture";
    legacyCo.idea = legacyMeta.idea || "";
    legacyCo.industry = legacyCo.industry || "ai_saas";
    g.companies = [legacyCo];
    g.activeCompanyIndex = 0;
  }
  if(!g.playerMeta) g.playerMeta = { playerName: (g.meta && g.meta.playerName) || "Founder", createdAt: Date.now() };
  if(g.activeCompanyIndex==null || g.activeCompanyIndex>=g.companies.length) g.activeCompanyIndex = 0;
  defineActiveAccessors(g);
  const prevG = G; G = g;
  const savedIdx = g.activeCompanyIndex;
  g.companies.forEach((co,i)=>{
    g.activeCompanyIndex = i;
    normalizeGameBase(g);
    normalizeCompanyV8(co);
  });
  g.activeCompanyIndex = savedIdx;
  const p = g.personal;
  if(!p.spouseName) p.spouseName = "Spouse";
  if(p.totalNetWorth===undefined) p.totalNetWorth = p.netWorth;
  g.version = SCHEMA_VERSION;
  G = prevG;
  return g;
}

/* ---------------- Month advance wrapper ---------------- */
function advanceMonthV8(){
  const pre = [];
  const co = G.company;
  if(co.ops){
    const net = opsResolve(co, pre);
    setOpsLine(co, net);
    co.opsLog.unshift({ month:co.month, year:co.year, net, gross:co.ops.lastGross });
    if(co.opsLog.length>36) co.opsLog.pop();
  }
  advanceMonthCore();
  const post = [];
  vestingTick(co, post);
  passiveCompaniesTick(post);
  activeValuationWithOps();
  empireNetWorthTick();
  const r = co.lastReport;
  if(r) r.lines = pre.concat(r.lines||[], post);
  post.forEach(l=> logHistory(l));
  saveToSlot(G, LS_AUTOSAVE, G.meta.name + " (autosave)");
}

