/* ---------------- Funding rounds & founder capital ---------------- */
const FUNDING_ROUNDS = [
  { key:"ff",     name:"Friends & Family", cash:75000,   pct:8,  minRev:0,     note:"No traction required. Cheap money, awkward Thanksgivings." },
  { key:"angel",  name:"Angel Round",      cash:400000,  pct:12, minRev:8000,  note:"Needs early revenue proof." },
  { key:"seed",   name:"Seed Round",       cash:1500000, pct:15, minRev:25000, note:"Institutional money. Real dilution." },
  { key:"a",      name:"Series A",         cash:6000000, pct:18, minRev:90000, note:"Growth capital, board pressure included." },
];
const VC_NAMES = ["Lantern Ventures","Foundry Row","Blue Harbor Capital","Meridian Growth","Tessellate Partners","Ninth Street Fund"];
function monthlyRevenue(co){
  co = co || G.company;
  const lines = (co.businessLines||[]).reduce((s,l)=>s+(l.monthlyRevenue||0),0);
  const ops = co.ops && co.ops.lastNet>0 ? co.ops.lastNet : 0;
  return (co.mrr||0) + lines + ops;
}
function raiseRound(key){
  const co = G.company;
  const r = FUNDING_ROUNDS.find(x=>x.key===key);
  if(!r) return "Unknown round.";
  co.funding = co.funding || [];
  if(co.funding.indexOf(key)>=0) return `${r.name} is already closed.`;
  const rev = monthlyRevenue(co);
  if(rev < r.minRev) return `Investors want at least ${fmt$(r.minRev)}/mo in revenue for a ${r.name}. You are at ${fmt$(Math.round(rev))}.`;
  const e = eq(co), pct = r.pct/100;
  const newShares = Math.round(e.totalShares * pct/(1-pct));
  e.totalShares += newShares;
  e.investors.push({ id:uid(), name:pick(VC_NAMES), shares:newShares, round:r.name, invested:r.cash, month:co.month, year:co.year });
  co.cash += r.cash;
  co.funding.push(key);
  logHistory(`Closed a ${r.name}: ${fmt$(r.cash)} in the bank for ${r.pct}% \u2014 you now hold ${(founderPct(co)*100).toFixed(1)}%.`);
  return null;
}
function injectPersonalCash(amount){
  amount = Math.round(amount);
  if(!amount || amount<=0) return "Enter an amount.";
  if(amount > G.personal.cash) return `You only have ${fmt$(G.personal.cash)} in personal cash.`;
  G.personal.cash -= amount;
  G.company.cash += amount;
  logHistory(`Wired ${fmt$(amount)} of personal money into ${G.company.name}.`);
  return null;
}

/* =========================================================
   v9 \u2014 Command Deck
   - Grouped dock (folders + sub-tabs)
   - F.E.L.I.P.E AI advisor with ranked, actionable suggestions
   - Collapsible Board of Directors / Benefits sections
   - Hiring affordability gate + crash guard on month close
   - Revenue-scaled financing (term loans, LOC, custom amounts)
   ========================================================= */

/* ---------------- Financing v9 ---------------- */
function debtCapacity(){
  const c = G.company;
  const rev = monthlyRevenue(c);
  const assetBase = Math.round((c.netWorth||0) * 0.25);
  return Math.max(60000, Math.round(rev * 12) + Math.max(0, assetBase));
}
function debtHeadroom(){
  const d = G.company.debt;
  return Math.max(0, debtCapacity() - d.loanBalance - d.locLimit);
}
function loanEligibleAmounts(){
  const room = Math.max(0, debtCapacity() - G.company.debt.loanBalance);
  const tiers = [25000,50000,100000,250000,500000,1000000,2500000,5000000];
  const ok = tiers.filter(a=>a<=room);
  if(!ok.length && room>=10000) ok.push(Math.round(room/1000)*1000);
  return ok.slice(-4);
}
function applyForLoan(amount){
  const d = G.company.debt;
  amount = Math.round(amount);
  if(!amount || amount<=0) return "Enter a loan amount.";
  const room = Math.max(0, debtCapacity() - d.loanBalance);
  if(amount > room){
    return `Underwriting caps you at ${fmt$(room)} more right now. Capacity scales with revenue (currently ${fmt$(Math.round(monthlyRevenue()))}/mo) and company net worth.`;
  }
  const newBalance = d.loanBalance + amount;
  d.loanBalance = newBalance;
  d.loanMonthsLeft = 24;
  d.loanMonthlyPayment = Math.round((newBalance*(1+effectiveLoanRate()*24))/24);
  G.company.cash += amount;
  logHistory(`Drew a ${fmt$(amount)} term loan (24mo @ ${(effectiveLoanRate()*100).toFixed(1)}%/mo). Total loan balance ${fmt$(newBalance)}.`);
  return null;
}
function raiseLocLimit(limit){
  const d = G.company.debt;
  limit = Math.round(limit);
  const room = Math.max(0, debtCapacity() - d.loanBalance);
  if(limit > room) return `Your credit line can't exceed ${fmt$(room)} at this revenue level.`;
  if(limit <= d.locLimit) return "That's not an increase.";
  d.locLimit = limit;
  logHistory(`Raised the line of credit limit to ${fmt$(limit)}.`);
  return null;
}
function drawLoc(amount){
  const d = G.company.debt;
  amount = Math.round(amount);
  const avail = Math.max(0, d.locLimit - d.locBalance);
  if(amount<=0) return "Enter an amount.";
  if(amount > avail) return `Only ${fmt$(avail)} is available on the line.`;
  d.locBalance += amount;
  G.company.cash += amount;
  logHistory(`Drew ${fmt$(amount)} from the line of credit.`);
  return null;
}
function suggestedLocLimit(){
  const rev = monthlyRevenue();
  return Math.min(Math.max(0, debtCapacity() - G.company.debt.loanBalance), Math.max(25000, Math.round(rev*6/5000)*5000));
}
function capitalDeskCard(){
  const c = G.company, d = c.debt;
  const cap = debtCapacity();
  const used = d.loanBalance + d.locLimit;
  const pct = Math.min(100, Math.round(100*used/Math.max(1,cap)));
  return `<div class="card mt14">
    <h3>\u{1F4B5} Capital Desk \u2014 Revenue-Based Financing</h3>
    <div class="muted mb8" style="font-size:12px;">Your borrowing capacity scales with revenue and company net worth, and loans can be stacked up to that cap. Capacity: <b>${fmt$(cap)}</b> \u00b7 committed: ${fmt$(used)} \u00b7 headroom: <b class="${debtHeadroom()>0?"good":"bad"}">${fmt$(debtHeadroom())}</b></div>
    <div class="barrow"><span class="lbl">Capacity used</span><div class="track"><div class="fill" style="width:${pct}%;background:${pct>85?"var(--bad)":"var(--accent)"};"></div></div><span>${pct}%</span></div>
    <div class="flexrow mt8">
      ${loanEligibleAmounts().map(a=>`<button class="btn secondary small" data-v9loan="${a}">Borrow ${fmt$(a)}</button>`).join("") || `<span class="muted">No additional term-loan capacity \u2014 grow revenue or repay debt.</span>`}
      <button class="btn small" id="v9CustomLoan">Custom amount\u2026</button>
    </div>
    <div class="flexrow mt8">
      <button class="btn secondary small" id="v9RaiseLoc">Set credit line to ${fmt$(suggestedLocLimit())}</button>
      <button class="btn secondary small" id="v9CustomLoc">Custom credit limit\u2026</button>
      <button class="btn secondary small" id="v9DrawLoc">Draw from line\u2026</button>
    </div>
    <div class="muted mt8" style="font-size:11.5px;">Need non-dilutive cash fast? Equity rounds and personal cash injections live in \u{1F3D7}\uFE0F My Empire.</div>
  </div>`;
}
function wireCapitalDesk(wrap){
  wrap.querySelectorAll("[data-v9loan]").forEach(b=> b.onclick=()=>{
    const err = applyForLoan(Number(b.getAttribute("data-v9loan")));
    if(err) alert(err);
    renderAll();
  });
  const cl = wrap.querySelector("#v9CustomLoan");
  if(cl) cl.onclick = ()=>{
    const room = Math.max(0, debtCapacity() - G.company.debt.loanBalance);
    const amt = Number(window.prompt(`How much do you want to borrow? Available headroom: ${fmt$(room)}`, String(Math.min(room, 250000))));
    if(!amt) return;
    const err = applyForLoan(amt); if(err) alert(err);
    renderAll();
  };
  const rl = wrap.querySelector("#v9RaiseLoc");
  if(rl) rl.onclick = ()=>{ const err = raiseLocLimit(suggestedLocLimit()); if(err) alert(err); renderAll(); };
  const cloc = wrap.querySelector("#v9CustomLoc");
  if(cloc) cloc.onclick = ()=>{
    const amt = Number(window.prompt(`Set your line of credit limit. Max allowed: ${fmt$(Math.max(0, debtCapacity()-G.company.debt.loanBalance))}`, String(suggestedLocLimit())));
    if(!amt) return;
    const err = raiseLocLimit(amt); if(err) alert(err);
    renderAll();
  };
  const dl = wrap.querySelector("#v9DrawLoc");
  if(dl) dl.onclick = ()=>{
    const avail = Math.max(0, G.company.debt.locLimit - G.company.debt.locBalance);
    if(avail<=0){ alert("No credit line available yet \u2014 set a limit first."); return; }
    const amt = Number(window.prompt(`How much do you want to draw? Available: ${fmt$(avail)}`, String(avail)));
    if(!amt) return;
    const err = drawLoc(amt); if(err) alert(err);
    renderAll();
  };
}
function renderBank(){
  const wrap = renderBankBase();
  const card = el(capitalDeskCard());
  const kids = Array.from(wrap.children).filter(n=>n.classList && n.classList.contains("card"));
  const history = kids[kids.length-1];
  if(history && history.parentNode===wrap) wrap.insertBefore(card, history); else wrap.appendChild(card);
  wireCapitalDesk(wrap);
  return wrap;
}

/* ---------------- Hiring affordability gate + crash guard ---------------- */
let __hireGate = { at:0, ok:false };
function hireGateAllows(item){
  const now = Date.now();
  if(now - __hireGate.at < 900) return __hireGate.ok;
  const salary = (item.hireDept && item.hireRung) ? rungSalary(item.hireDept, item.hireRung) : 0;
  const proj = projectShortfall();
  const after = proj.projectedCash - salary - (item.cost||0);
  if(after >= 0){ __hireGate = { at:now, ok:true }; return true; }
  const gap = -after;
  const credit = Math.max(0, G.company.debt.locLimit - G.company.debt.locBalance);
  const headroom = Math.max(0, debtCapacity() - G.company.debt.loanBalance);
  let msg = `\u26A0\uFE0F You can't cover this hire.\n\nProjected month-end cash would be ${fmt$(after)} \u2014 short by about ${fmt$(gap)} after salaries and everything already queued.\n\nAvailable credit line: ${fmt$(credit)}\nAdditional borrowing capacity: ${fmt$(headroom)}\n\n`;
  msg += (credit >= gap)
    ? "Your credit line can absorb it, but it will cost interest.\n\nQueue the hire anyway?"
    : "Recommended: open the Bank tab (Run \u2192 Bank) and take a term loan or raise your credit line first.\n\nQueue the hire anyway? Cancel to go get funding.";
  const ok = confirm(msg);
  __hireGate = { at:now, ok };
  if(!ok) G.ui.activeTab = "bank";
  return ok;
}
function queueAdd(item){
  if(!item) return;
  if(G.ui.queue.length >= 40){
    alert("That's 40 queued actions \u2014 the plan is full for this month. Advance the month or remove something first.");
    return;
  }
  if(item.hireDept && !hireGateAllows(item)) return;
  G.ui.queue.push(item);
}
function advanceMonthV9(){
  try {
    advanceMonthV8();
  } catch(err){
    console.error(err);
    alert(`Something went wrong while closing the month:\n${err && err.message ? err.message : err}\n\nThe month was rolled back to a safe state and your save is intact. Try removing the last queued action.`);
    G.ui.queue = [];
  }
}

/* ---------------- Grouped dock ---------------- */
const DOCK_GROUPS = [
  { id:"run",    icon:"\u{1F9ED}", label:"Run",     items:["decisions","bank","financials","industry"] },
  { id:"people", icon:"\u{1F9D1}\u200D\u{1F4BC}", label:"People", items:["team","hr","orgchart","slack","zoom"] },
  { id:"market", icon:"\u{1F4E6}", label:"Product", items:["product","clients","research"] },
  { id:"empire", icon:"\u{1F3D7}\uFE0F", label:"Empire", items:["empire","invest","milestones"] },
  { id:"life",   icon:"\u{1F3E1}", label:"Life",    items:["personal","market","life"] },
  { id:"jarvis", icon:"\u{1F916}", label:"F.E.L.I.P.E AI",  items:["assistant"] },
  { id:"system", icon:"\u{1F4BE}", label:"System",  items:["saves"] },
];
function dockItem(id){ return DOCK_ITEMS.find(i=>i.id===id) || { id, icon:"\u{1F4C4}", label:id }; }
function groupOfTab(tabId){ return DOCK_GROUPS.find(g=>g.items.indexOf(tabId)>=0) || DOCK_GROUPS[0]; }
function groupNeedsAttention(g){
  if(g.items.indexOf("decisions")>=0 && G.company.pendingEvent) return true;
  return false;
}
function renderDock(){
  let dock = document.getElementById("dock");
  if(!dock){
    const main = document.createElement("div");
    main.id = "main";
    main.innerHTML = `<div id="dock"></div><div id="screen"></div>`;
    document.getElementById("app").appendChild(main);
    dock = document.getElementById("dock");
  }
  const active = groupOfTab(G.ui.activeTab);
  dock.innerHTML = DOCK_GROUPS.map(g=>`
    <div>
      <div class="dock-btn ${active.id===g.id?"active":""}" data-group="${g.id}" title="${g.items.map(i=>dockItem(i).label).join(" \u00b7 ")}">${g.icon}
        <span class="dot ${groupNeedsAttention(g)?"show":""}"></span></div>
      <div class="dock-label">${g.label}</div>
    </div>`).join("");
  dock.querySelectorAll("[data-group]").forEach(b=> b.onclick = ()=>{
    const g = DOCK_GROUPS.find(x=>x.id===b.getAttribute("data-group"));
    if(!g) return;
    G.ui.lastTabByGroup = G.ui.lastTabByGroup || {};
    G.ui.activeTab = G.ui.lastTabByGroup[g.id] && g.items.indexOf(G.ui.lastTabByGroup[g.id])>=0
      ? G.ui.lastTabByGroup[g.id] : g.items[0];
    renderDock(); renderScreen();
  });
}
function subTabBar(){
  const g = groupOfTab(G.ui.activeTab);
  if(g.items.length<2) return null;
  const bar = el(`<div class="card mb8" style="padding:8px 10px;">
    <div class="flexrow" style="flex-wrap:wrap;gap:6px;">
      <span class="muted" style="font-size:11.5px;margin-right:4px;">${g.icon} ${g.label}</span>
      ${g.items.map(id=>{ const it = dockItem(id);
        return `<button class="btn ${G.ui.activeTab===id?"":"secondary"} small" data-subtab="${id}">${it.icon} ${it.label}</button>`; }).join("")}
    </div></div>`);
  bar.querySelectorAll("[data-subtab]").forEach(b=> b.onclick = ()=>{
    G.ui.activeTab = b.getAttribute("data-subtab");
    G.ui.lastTabByGroup = G.ui.lastTabByGroup || {};
    G.ui.lastTabByGroup[groupOfTab(G.ui.activeTab).id] = G.ui.activeTab;
    renderDock(); renderScreen();
  });
  return bar;
}
function renderScreenV11(){
  const screen = document.getElementById("screen");
  try {
    renderScreenBase();
  } catch(err){
    console.error(err);
    screen.innerHTML = `<div class="card"><h3 class="bad">That tab hit an error</h3><div class="muted">${(err && err.message)||err}</div><div class="muted mt8" style="font-size:11.5px;">Your save is fine \u2014 switch tabs and try again.</div></div>`;
  }
  const bar = subTabBar();
  if(bar) screen.insertBefore(bar, screen.firstChild);
  G.ui.lastTabByGroup = G.ui.lastTabByGroup || {};
  G.ui.lastTabByGroup[groupOfTab(G.ui.activeTab).id] = G.ui.activeTab;
}

/* ---------------- Collapsible sections ---------------- */
function collapseSection(wrap, label, openByDefault){
  const heads = Array.from(wrap.querySelectorAll("h3.section-divider"));
  const h = heads.find(x=>x.textContent.indexOf(label)>=0);
  if(!h) return null;
  const card = h.nextElementSibling;
  if(!card) return null;
  const det = document.createElement("details");
  det.className = "v9-collapse";
  det.style.cssText = "margin:14px 0 8px;";
  if(openByDefault) det.open = true;
  const sum = document.createElement("summary");
  sum.textContent = h.textContent;
  sum.style.cssText = "cursor:pointer;list-style:revert;font-weight:600;font-size:13px;color:var(--muted);padding:6px 0;border-top:1px solid var(--border);";
  h.replaceWith(det);
  det.appendChild(sum);
  det.appendChild(card);
  return det;
}
function renderHR(){
  const wrap = renderHRBase();
  collapseSection(wrap, "Board of Directors", false);
  collapseSection(wrap, "Benefits & Perks", false);
  return wrap;
}

/* ---------------- Jarvis advisor ---------------- */
function cashRunway(){
  const c = G.company;
  const exp = Object.values(c.expensesBreakdown||{}).reduce((a,b)=>a+(b||0),0);
  const rev = monthlyRevenue(c);
  const burn = exp - rev;
  if(burn <= 0) return Infinity;
  return Math.max(0, Math.floor(c.cash / burn));
}
function jarvisAdvice(){
  const c = G.company, p = G.personal, out = [];
  const add = (pri, icon, title, text, tab)=> out.push({ pri, icon, title, text, tab });
  const rev = monthlyRevenue(c);
  const runway = cashRunway();

  if(c.cash < 0 || (c.distressMonths||0) > 0)
    add(100, "\u{1F6A8}", "You are in financial distress", `Cash is ${fmt$(c.cash)} and you've had ${c.distressMonths} month(s) of overdrafts. Borrowing capacity right now is ${fmt$(Math.max(0, debtCapacity()-c.debt.loanBalance))}. Take a term loan or cut queued spend before advancing.`, "bank");
  else if(runway !== Infinity && runway <= 2)
    add(95, "\u26A0\uFE0F", `About ${runway} month(s) of runway left`, `Burn is outpacing ${fmt$(Math.round(rev))}/mo of revenue. Either borrow (${fmt$(Math.max(0, debtCapacity()-c.debt.loanBalance))} available), raise a round in My Empire, or trim payroll.`, "bank");

  if(c.pendingEvent)
    add(92, "\u26A1", "An event needs your decision", `"${c.pendingEvent.title}" is waiting. Unresolved events keep compounding.`, "decisions");

  const cap = headcountCap(), room = cap - c.employees.length;
  if(room <= 0 && c.cash > 20000)
    add(70, "\u{1F3E2}", "Office is at capacity", `You're at ${c.employees.length}/${cap} headcount. Upgrade the workspace in Decisions \u2192 Expansion before you can hire again.`, "decisions");

  if(c.employees.length){
    const avgMorale = Math.round(c.employees.reduce((s,e)=>s+e.morale,0)/c.employees.length);
    if(avgMorale < 55) add(72, "\u{1F614}", `Morale is ${avgMorale}/100`, "Low morale raises attrition and cuts output. Try a team event, a benefits tier upgrade, or equity grants \u2014 option holders quit far less.", "hr");
    const atRisk = c.employees.filter(e=>e.morale<35);
    if(atRisk.length) add(68, "\u{1F6AA}", `${atRisk.length} person(s) at flight risk`, atRisk.slice(0,3).map(e=>`${e.name} (${e.role})`).join(", ") + ". A bonus, promotion, or equity grant usually resets them.", "team");
  } else {
    add(80, "\u{1F464}", "You have no employees", "Nothing compounds without a team. Start with the entry rung in your core department.", "hr");
  }

  if(c.clients && c.clients.length){
    const risky = c.clients.filter(cl=>cl.health<40);
    if(risky.length) add(74, "\u{1F91D}", `${risky.length} client(s) about to churn`, risky.slice(0,3).map(r=>r.name).join(", ") + ". A retention offer costs far less than replacing the revenue.", "clients");
  }

  if(c.product && c.product.maturity < 40 && rev > 0)
    add(60, "\u{1F4E6}", `Product maturity is ${c.product.maturity}/100`, "Thin product means high churn. Ship a planned feature or add engineers.", "product");

  // Industry-specific coaching
  const ind = (c.industry||"ai_saas");
  const ops = c.ops || {};
  if(ind==="retail"){
    if(!(ops.stores||[]).length) add(88, "\u{1F3EA}", "You have no stores open", "Retail revenue comes from locations. Open a kiosk in Industry Ops to start selling.", "industry");
    else {
      const dry = (ops.stores||[]).filter(s=>(s.inventory||0) < 5000);
      if(dry.length) add(78, "\u{1F4E6}", `${dry.length} store(s) nearly out of stock`, "Stockouts are lost revenue, not deferred revenue. Restock in Industry Ops.", "industry");
    }
  } else if(ind==="restaurant"){
    if(!(ops.locations||[]).length) add(88, "\u{1F35D}", "No restaurants open yet", "Open a food truck in Industry Ops \u2014 cheapest way to start covers.", "industry");
    else if((ops.quality||0) < 50) add(82, "\u{1F9EA}", `Food quality is ${Math.round(ops.quality)}/100`, "Below 42 you risk a failed health inspection. Hire kitchen staff, run training, or remodel.", "industry");
  } else if(ind==="robotics"){
    if(!(ops.released||[]).length && !ops.rnd) add(88, "\u{1F916}", "No product in R&D or released", "Robotics earns nothing until a model ships. Start the palletizer program in Industry Ops.", "industry");
    else if((ops.backlog||0) > 0 && !(ops.lines||[]).length) add(84, "\u{1F3ED}", `${ops.backlog} unit(s) backlogged with no capacity`, "Orders are stacking up but you can't build them. Add a production cell.", "industry");
  } else if(ind==="finance"){
    const util = ops.deposits ? (ops.loanBook||0)/ops.deposits : 0;
    if(util < 0.4) add(76, "\u{1F3E6}", "Your deposits are sitting idle", `Only ${Math.round(util*100)}% of deposits are lent out. Loosen underwriting or run a lending campaign to earn spread.`, "industry");
    else if(util > 0.8) add(80, "\u26A0\uFE0F", "Loan book is stretched", "You're near the 85% cap on deposits. Run a deposit campaign before writing more loans.", "industry");
  } else {
    if(!deptHas("sales","rep")) add(76, "\u{1F4DE}", "No sales pipeline", "In SaaS, a sales rep is the growth engine. Hire one before spending on anything else.", "hr");
  }

  // Capital & equity
  const fundedKeys = c.funding||[];
  const nextRound = (typeof FUNDING_ROUNDS!=="undefined") ? FUNDING_ROUNDS.find(r=>fundedKeys.indexOf(r.key)<0 && rev>=r.minRev) : null;
  if(nextRound && c.cash < rev*3)
    add(66, "\u{1F4B0}", `You qualify for a ${nextRound.name}`, `${fmt$(nextRound.cash)} for ${nextRound.pct}% dilution. Non-debt cash, no monthly payment.`, "empire");
  if(c.employees.length >= 3 && eq(c).grants.length === 0)
    add(58, "\u{1F4C8}", "Your option pool is untouched", `${(100*eq(c).pool/eq(c).totalShares).toFixed(1)}% is sitting unallocated. Grants vest over 48 months and materially reduce attrition.`, "empire");
  if(!(c.board||[]).length && c.cash > 80000)
    add(52, "\u{1F3DB}\uFE0F", "No board seats filled", "A Finance Chair cuts interest rates 15%; an Angel adds 15% to valuation. Both pay for themselves at your cash level.", "hr");

  // Empire & personal
  const passive = (G.companies||[]).filter(x=>x.passive).length;
  if((G.companies||[]).length === 1 && p.cash > 300000)
    add(55, "\u{1F3D7}\uFE0F", `You have ${fmt$(p.cash)} idle personally`, "That's enough to found a second company in a different industry, or hire a CEO here and go build something else.", "empire");
  if(passive) add(40, "\u{1F9D1}\u200D\u{1F4BC}", `${passive} company(ies) on autopilot`, "Check their valuations in My Empire \u2014 a CEO-run company you ignore can quietly stall.", "empire");
  if((p.wellbeing||0) < 40)
    add(50, "\u2728", `Your wellbeing is ${p.wellbeing||0}/100`, "Burnout drags your happiness and the company's momentum down. The Personal tab has free options (a run, the library, an unplugged weekend) and paid ones.", "personal");
  if(p.cash > 100000 && (G.company.assets ? 0 : 0) === 0 && p.cash > rev*8)
    add(35, "\u{1F4B9}", "Idle personal cash", `${fmt$(p.cash)} earning nothing. Investments compound monthly in the Invest tab.`, "invest");

  if(!out.length) add(20, "\u2705", "Nothing is on fire", "Solid position. Push growth: a new business line, a bigger price tier, or your next funding round.", "decisions");
  return out.sort((a,b)=>b.pri-a.pri);
}
function adviceCard(limit, title){
  const list = jarvisAdvice().slice(0, limit);
  return `<div class="card mb14">
    <h3>\u{1F916} ${title}</h3>
    ${list.map(a=>`<div class="ladder-card"><div class="row"><div>
      <div class="title">${a.icon} ${a.title}</div>
      <div class="desc">${a.text}</div></div>
      <button class="btn secondary small" data-goto="${a.tab}">Go</button>
    </div></div>`).join("")}
  </div>`;
}
function wireAdvice(wrap){
  wrap.querySelectorAll("[data-goto]").forEach(b=> b.onclick = ()=>{
    G.ui.activeTab = b.getAttribute("data-goto");
    renderDock(); renderScreen();
  });
}
function renderDecisions(){
  const wrap = renderDecisionsBase();
  const card = el(adviceCard(3, "F.E.L.I.P.E AI \u2014 top moves this month"));
  const title = wrap.querySelector(".window-title");
  if(title && title.parentNode===wrap && title.nextSibling) wrap.insertBefore(card, title.nextSibling); else wrap.appendChild(card);
  wireAdvice(wrap);
  return wrap;
}
function renderAssistant(){
  const wrap = renderAssistantBase();
  const card = el(adviceCard(6, "What I'd do right now"));
  const title = wrap.querySelector(".window-title");
  if(title && title.parentNode===wrap && title.nextSibling) wrap.insertBefore(card, title.nextSibling); else wrap.insertBefore(card, wrap.firstChild);
  const quick = el(`<div class="flexrow mb8" style="flex-wrap:wrap;gap:6px;">
    ${["What should I do?","How's my runway?","Should I raise money?","Who should I hire next?","How do I grow faster?","Am I overpaying anyone?"].map(q=>`<button class="btn secondary small" data-ask="${q}">${q}</button>`).join("")}
  </div>`);
  const msgs = wrap.querySelector("#assistantMsgs");
  if(msgs && msgs.parentNode) msgs.parentNode.insertBefore(quick, msgs);
  quick.querySelectorAll("[data-ask]").forEach(b=> b.onclick = ()=>{
    const q = b.getAttribute("data-ask");
    G.assistantChat.push({ from:"me", text:q });
    G.assistantChat.push({ from:"them", text: assistantAnswer(q) });
    renderScreen();
  });
  wireAdvice(wrap);
  return wrap;
}
function assistantAnswer(question){
  const t = (question||"").toLowerCase();
  const c = G.company, p = G.personal;
  const rev = monthlyRevenue(c);
  const runway = cashRunway();
  if(/what should i|stuck|advice|help|next move|priorit|recommend|what do i do|what now/.test(t)){
    const top = jarvisAdvice().slice(0,3);
    return `Here's how I'd rank it:<br>` + top.map((a,i)=>`<b>${i+1}. ${a.icon} ${a.title}</b> \u2014 ${a.text}`).join("<br>");
  }
  if(/raise|funding|fundrais|investor|round|capital|money|borrow|loan|credit/.test(t)){
    const room = Math.max(0, debtCapacity() - c.debt.loanBalance);
    const next = (typeof FUNDING_ROUNDS!=="undefined") ? FUNDING_ROUNDS.filter(r=>(c.funding||[]).indexOf(r.key)<0) : [];
    const ready = next.filter(r=>rev>=r.minRev);
    return `Debt: you can borrow up to <b>${fmt$(room)}</b> more (capacity scales with your ${fmt$(Math.round(rev))}/mo revenue and net worth); current loan balance ${fmt$(c.debt.loanBalance)}, credit line ${fmt$(c.debt.locBalance)}/${fmt$(c.debt.locLimit)}.<br>Equity: ${ready.length? `you qualify for <b>${ready[0].name}</b> \u2014 ${fmt$(ready[0].cash)} for ${ready[0].pct}%` : next.length? `next round is ${next[0].name}, needs ${fmt$(next[0].minRev)}/mo revenue` : "all rounds are closed"}.<br>Rule of thumb: debt for short cash gaps, equity for hiring or expansion you can't repay in 24 months.`;
  }
  if(/hire|hiring|who should i/.test(t)){
    const cap = headcountCap();
    const gaps = [];
    if(!deptHas("sales","rep")) gaps.push("a Sales rung \u2014 nothing sells itself");
    if(!deptHas("support","rep") && (c.clients||[]).length>3) gaps.push("Support \u2014 client health has no coverage");
    if((c.product&&c.product.maturity<40)) gaps.push("Product/engineering \u2014 maturity is low");
    if(!deptHas("finance","cfo") && c.debt.loanBalance>0) gaps.push("a CFO \u2014 cuts your interest rates 40%");
    return `Headcount ${c.employees.length}/${cap}. Payroll ${fmt$(c.employees.reduce((s,e)=>s+e.salary,0))}/mo against ${fmt$(Math.round(rev))}/mo revenue.<br>${gaps.length? "Biggest gaps: "+gaps.join("; ")+"." : "Coverage looks balanced \u2014 promote before you add headcount."}`;
  }
  if(/grow|faster|scale|revenue|expand/.test(t)){
    const ind = c.industry||"ai_saas";
    const play = { retail:"open another store format and push the price tier up a notch once demand holds",
      restaurant:"add a location, but only after quality is above 60 \u2014 bad inspections are expensive",
      robotics:"finish the R&D program in flight, then add production capacity to clear backlog",
      finance:"raise deposits first, then lend up to ~80% of them at balanced underwriting",
      ai_saas:"pair a sales rung with a shipped feature \u2014 pipeline plus product beats either alone" }[ind];
    return `At ${fmt$(Math.round(rev))}/mo, your fastest lever in ${industry().name} is to ${play}.<br>Then reinvest: ${c.cash>rev*4? "you're sitting on cash, deploy it" : "fund it with the credit line rather than stalling"}.`;
  }
  if(/overpay|salary|payroll|cost|cut/.test(t)){
    const sorted = [...c.employees].sort((a,b)=>b.salary-a.salary).slice(0,3);
    const weak = c.employees.filter(e=>e.performance<45);
    return `Payroll is ${fmt$(c.employees.reduce((s,e)=>s+e.salary,0))}/mo. Top earners: ${sorted.map(e=>`${e.name} (${fmt$(e.salary)})`).join(", ")||"none"}.<br>${weak.length? `Underperformers to coach or cut: ${weak.map(e=>e.name).join(", ")}.` : "No clear underperformers \u2014 cutting here would cost you output."}`;
  }
  if(/equity|stock|option|cap table|vest|dilut/.test(t)){
    const e = eq(c);
    return `You hold ${(founderPct(c)*100).toFixed(1)}% of ${c.name} (${fmt$(stakeValue(c))} on a ${fmt$(c.valuation||0)} valuation). Option pool left: ${(100*e.pool/e.totalShares).toFixed(2)}%, ${e.grants.length} grant(s) outstanding, ${e.investors.length} investor(s) on the cap table.<br>Grants vest over 48 months and cut attrition \u2014 spend the pool on people you'd hate to lose.`;
  }
  if(/empire|second company|another business|ceo|step away/.test(t)){
    return `You run ${(G.companies||[]).length} company(ies); ${(G.companies||[]).filter(x=>x.passive).length} on autopilot. Personal cash ${fmt$(p.cash)}, total net worth ${fmt$(p.totalNetWorth||p.cash)}.<br>Hiring a CEO keeps a company compounding in the background while you start something in a different industry \u2014 diversification smooths the bad months.`;
  }
  if(/runway|burn|cash last|how long/.test(t)){
    if(runway===Infinity) return `Profitable \u2014 revenue ${fmt$(Math.round(rev))}/mo covers expenses. Cash ${fmt$(c.cash)}, plus ${fmt$(Math.max(0, debtCapacity()-c.debt.loanBalance))} of untapped borrowing capacity.`;
    return `About <b>${runway} month(s)</b> of runway at current burn. Cash ${fmt$(c.cash)}, credit available ${fmt$(c.debt.locLimit-c.debt.locBalance)}, additional borrowing capacity ${fmt$(Math.max(0, debtCapacity()-c.debt.loanBalance))}.`;
  }
  return assistantAnswerBase(question);
}


/* ================= v10 — Life, Ledger & Balance ================= */
function addCatalog(arr, items){ items.forEach(i=>{ if(!arr.some(x=>x.key===i.key)) arr.push(i); }); }

/* --- Houses: 20 total --- */
