function svgIcon(name, cls){
  const d = SVG_PATHS[name] || SVG_PATHS.box;
  return `<svg class="svg-ico ${cls||""}" viewBox="0 0 24 24" aria-hidden="true">${d}</svg>`;
}
function svgArt(name, tier){
  const d = SVG_PATHS[name] || SVG_PATHS.box;
  return `<div class="shop-art art-tier${tier||1}"><svg viewBox="0 0 24 24" aria-hidden="true">${d}</svg></div>`;
}
function artFor(item, kind){
  const price = item.price || 0;
  const tier = price > 5000000 ? 4 : price > 900000 ? 3 : price > 150000 ? 2 : 1;
  let name = "box";
  if(kind==="house"){
    name = price >= 20000000 ? "tower" : price >= 8000000 ? "castle" : price >= 3000000 ? "villa"
      : price >= 900000 ? "estate" : price >= 250000 ? "house" : "apartment";
  } else if(kind==="car"){
    name = price >= 1000000 ? "hypercar" : price >= 120000 ? "sportscar" : price >= 35000 ? "truck" : "car";
  } else if(kind==="toy"){
    if(item.cls==="air") name = price >= 20000000 ? "jet" : price >= 3000000 ? "plane" : "helicopter";
    else if(item.cls==="sea") name = price >= 30000000 ? "ship" : price >= 2000000 ? "yacht" : "boat";
    else {
      const n = (item.name||"").toLowerCase();
      name = /watch|chrono/.test(n) ? "watch" : /art|paint|sculpt/.test(n) ? "art"
        : /guitar|music|vinyl/.test(n) ? "guitar" : /wine|whisk|bourbon|scotch/.test(n) ? "wine" : "gem";
    }
  } else if(kind==="vacation"){
    const n = (item.name||"").toLowerCase();
    name = /ski|alps|mountain|everest|patagonia|peak/.test(n) ? "mountain"
      : /beach|island|maldives|reef|tahiti|caribbean|coast/.test(n) ? "palm" : "globe";
  }
  return svgArt(name, tier);
}

/* ---------- 100% founder ownership at founding ---------- */
function initEquity(){
  return { totalShares:TOTAL_SHARES, founder:TOTAL_SHARES, pool:0, grants:[], investors:[], dividendsPaid:0 };
}
function openOptionPool(pct){
  const e = eq(G.company);
  const shares = Math.round(e.totalShares * (pct/100));
  if(shares > e.founder) return "You don't hold that many shares.";
  e.founder -= shares; e.pool += shares;
  logHistory(`Carved out a ${pct}% employee option pool from your own shares.`);
  return null;
}
function grantEquity(empId, pct, vestMonths){
  const co = G.company, e = co.employees.find(x=>x.id===empId);
  if(!e) return "Employee not found.";
  const E = eq(co);
  const shares = Math.round(E.totalShares * (pct/100));
  if(shares > E.pool + E.founder) return "You don't have that many shares left to give.";
  const fromPool = Math.min(shares, E.pool);
  E.pool -= fromPool;
  E.founder -= (shares - fromPool);
  E.grants.push({ id:uid(), empId, name:e.name, role:e.role, shares, vestMonths:vestMonths||48, vestedMonths:0,
    grantedMonth:co.month, grantedYear:co.year });
  e.morale = clamp(e.morale + Math.min(25, Math.round(pct*12)), 0, 100);
  e.equityShares = (e.equityShares||0) + shares;
  logHistory(`Granted ${e.name} ${pct}% equity (${shares.toLocaleString()} shares, ${vestMonths||48}-month vest)${(shares-fromPool)>0?" \u2014 diluted from your own stake":""}.`);
  return null;
}

/* ---------- Industry progression: start with the AI company, earn the rest ---------- */
const INDUSTRY_UNLOCK = { ai_saas:0, retail:150000, restaurant:300000, robotics:750000, finance:2000000 };
function empireScore(){
  const p = pInit();
  const co = (G.companies||[]).reduce((s,c)=> s + (c.netWorth||0) + (c.cash||0), 0);
  return Math.round((p.netWorth||0) + co);
}
function unlockReq(key){ return INDUSTRY_UNLOCK[key]!==undefined ? INDUSTRY_UNLOCK[key] : 0; }
function syncIndustryUnlocks(){
  if(!G || !G.playerMeta) return [];
  if(!G.playerMeta.unlockedIndustries) G.playerMeta.unlockedIndustries = ["ai_saas"];
  const list = G.playerMeta.unlockedIndustries;
  const score = empireScore();
  const fresh = [];
  INDUSTRY_KEYS.forEach(k=>{
    const owned = (G.companies||[]).some(c=>c.industry===k);
    if(list.indexOf(k)<0 && (owned || score >= unlockReq(k))){ list.push(k); fresh.push(k); }
  });
  return fresh;
}
function industryUnlocked(key){
  if(!G || !G.playerMeta) return unlockReq(key)===0;
  syncIndustryUnlocks();
  return G.playerMeta.unlockedIndustries.indexOf(key) >= 0;
}
function industryLockNote(key){
  return `Unlocks at ${fmt$(unlockReq(key))} total net worth \u2014 you're at ${fmt$(empireScore())}.`;
}

/* ---------- Onboarding: you, your company, your industry — in that order ---------- */
