/* ---------- Dock: label inside the button ---------- */
function renderDock(){
  let dock = document.getElementById("dock");
  if(!dock){
    const main = document.createElement("div");
    main.id = "main";
    main.innerHTML = `<div id="dock"></div><div id="screen"></div>`;
    document.getElementById("app").appendChild(main);
    dock = document.getElementById("dock");
  }
  const active = groupOfTab(G.ui.activeTab);
  dock.innerHTML = DOCK_GROUPS.map(g=>`
    <div class="dock-btn ${active.id===g.id?"active":""}" data-group="${g.id}" title="${g.items.map(i=>dockItem(i).label).join(" \u00b7 ")}">
      <span>${g.icon}</span><span class="dock-in">${g.label.toUpperCase()}</span>
      <span class="dot ${groupNeedsAttention(g)?"show":""}"></span>
    </div>`).join("");
  dock.querySelectorAll("[data-group]").forEach(b=> b.onclick = ()=>{
    const g = DOCK_GROUPS.find(x=>x.id===b.getAttribute("data-group"));
    if(!g) return;
    G.ui.lastTabByGroup = G.ui.lastTabByGroup || {};
    G.ui.activeTab = G.ui.lastTabByGroup[g.id] && g.items.indexOf(G.ui.lastTabByGroup[g.id])>=0
      ? G.ui.lastTabByGroup[g.id] : g.items[0];
    renderDock(); renderScreen();
  });
}

/* ---------- Tier-1 tab bar: biggest line on the screen ---------- */
function subTabBar(){
  const g = groupOfTab(G.ui.activeTab);
  if(g.items.length<2) return null;
  const cur = dockItem(G.ui.activeTab);
  const bar = el(`<div class="tierbar1">
    <div class="muted tier1-crumb">${g.icon} ${g.label} <span style="opacity:.5;">\u203A</span> <b style="color:var(--accent);">${cur.label}</b></div>
    <div class="flexrow" style="flex-wrap:wrap;gap:6px;">
      ${g.items.map(id=>{ const it = dockItem(id); const on = G.ui.activeTab===id; const dot = tabNeedsAttention(id);
        return `<button class="btn ${on?"":"secondary"}" data-subtab="${id}"
          style="${on?"box-shadow:inset 0 -3px 0 rgba(255,255,255,.5);font-weight:700;":""}">${it.icon} ${it.label}${dot?` <span style="color:${on?"#fff":"var(--warn)"};">\u25CF</span>`:""}</button>`; }).join("")}
    </div></div>`);
  bar.querySelectorAll("[data-subtab]").forEach(b=> b.onclick = ()=>{
    G.ui.activeTab = b.getAttribute("data-subtab");
    G.ui.lastTabByGroup = G.ui.lastTabByGroup || {};
    G.ui.lastTabByGroup[groupOfTab(G.ui.activeTab).id] = G.ui.activeTab;
    renderDock(); renderScreen();
  });
  return bar;
}

/* ---------- Activity log ---------- */
DOCK_ITEMS.push({ id:"log", icon:"\u{1F9FE}", label:"Activity Log" });
(function addLogTab(){
  const run = DOCK_GROUPS.find(g=>g.id==="run");
  if(run && run.items.indexOf("log")<0) run.items.push("log");
})();
function renderLog(){
  const c = G.company;
  const p = pInit();
  if(!G.ui.logScope) G.ui.logScope = "company";
  const wrap = el(`<div></div>`);
  const coRows = (c.history||[]).map(h=>({ when:`Y${h.year} M${h.month}`, text:h.text }));
  const perRows = ((p.fulfillHistory||[]).map(f=>({ when:`Y${f.year||1} M${f.month||1}`, text:f.text || f.name })))
    .concat((p.assets && p.assets.vacationHistory || []).map(v=>({ when:`Y${v.year} M${v.month}`, text:`Trip: ${v.name}` })));
  const rows = G.ui.logScope==="personal" ? perRows : coRows;
  wrap.innerHTML = `
    <div class="window-title"><h2>\u{1F9FE} Activity Log</h2><span class="sub">${c.name} \u00b7 Year ${c.year}, Month ${c.month}</span></div>
    <div class="flexrow tierbar2 mb14" style="gap:6px;">
      <button class="btn ${G.ui.logScope==="company"?"":"secondary"} small" data-logscope="company">Company (${coRows.length})</button>
      <button class="btn ${G.ui.logScope==="personal"?"":"secondary"} small" data-logscope="personal">Personal (${perRows.length})</button>
    </div>
    <div class="flatsec">
      <h3>Newest first</h3>
      ${rows.length? rows.slice(0,200).map(r=>`<div class="logrow"><span class="when">${r.when}</span><span>${r.text}</span></div>`).join("")
        : `<div class="muted">Nothing logged yet \u2014 advance a month or make a decision.</div>`}
    </div>`;
  wrap.querySelectorAll("[data-logscope]").forEach(b=> b.onclick = ()=>{ G.ui.logScope = b.getAttribute("data-logscope"); renderScreen(); });
  return wrap;
}
function renderScreen(){
  if(G.ui.activeTab==="log"){
    const screen = document.getElementById("screen");
    screen.innerHTML = "";
    try { screen.appendChild(renderLog()); }
    catch(err){ screen.innerHTML = `<div class="card"><h3 class="bad">Log hit an error</h3><div class="muted">${(err&&err.message)||err}</div></div>`; }
    const bar = subTabBar();
    if(bar) screen.insertBefore(bar, screen.firstChild);
    G.ui.lastTabByGroup = G.ui.lastTabByGroup || {};
    G.ui.lastTabByGroup[groupOfTab(G.ui.activeTab).id] = G.ui.activeTab;
    renderDock();
    return;
  }
  return renderScreenV11();
}

/* ---------- Expenses you can actually explain ---------- */
const EXPENSE_INFO = {
  salaries:    { label:"Payroll",            why:"Salaries for everyone on the team. Changes when you hire, promote, or let someone go.", go:"hr" },
  marketing:   { label:"Marketing",          why:"Only what you chose to spend on campaigns this month. Set it in Decisions.", go:"decisions" },
  tools:       { label:"Software & tools",   why:"$25/mo per person on payroll. Zero while you're solo.", go:"hr" },
  rent:        { label:"Rent & facilities",  why:"Set by your HQ stage. A garage costs nothing.", go:"decisions" },
  debtService: { label:"Debt service",       why:"Payments on loans and the credit line. Borrow or repay in the Bank.", go:"bank" },
  other:       { label:"Admin & misc",       why:"$15/mo per person, plus benefits and any board seats you've filled.", go:"hr" },
};
function expInfo(k){ return EXPENSE_INFO[k] || { label:k, why:"", go:"financials" }; }
function leanMode(){ return !!(G.company.costPolicy && G.company.costPolicy.lean); }
function toggleLean(){
  const c = G.company;
  if(!c.costPolicy) c.costPolicy = { lean:false };
  c.costPolicy.lean = !c.costPolicy.lean;
  logHistory(c.costPolicy.lean
    ? "Switched to lean overhead \u2014 cheaper tools and admin, slightly slower execution."
    : "Turned off lean overhead \u2014 full tooling restored.");
  renderScreen();
}
function renderFinancialsV12(){
  const c = G.company;
  const exp = c.expensesBreakdown;
  const rev = c.revenueBreakdown;
  const totalExp = Object.values(exp).reduce((a,b)=>a+b,0);
  const totalRev = rev.recurring + rev.oneOff;
  const netProfit = totalRev - totalExp;
  const hist = c.financialHistory.slice(-6);
  const maxAbs = Math.max(1, ...hist.map(h=>Math.abs(h.netProfit)));
  const wrap = el(`<div></div>`);
  const lines = Object.entries(exp).filter(([k,v])=>v>0 || ["salaries","rent"].indexOf(k)>=0);
  wrap.innerHTML = `
    <div class="window-title"><h2>\u{1F4CA} Financial Report</h2><span class="sub">Year ${c.year}, Month ${c.month}</span></div>
    <div class="ledger-row">
      <div class="lg"><div class="k">Revenue</div><div class="v good">${fmt$(totalRev)}</div><div class="n">${fmt$(rev.recurring)} recurring \u00b7 ${fmt$(rev.oneOff)} other</div></div>
      <div class="lg"><div class="k">Expenses</div><div class="v ${totalExp>0?"bad":""}">${fmt$(totalExp)}</div><div class="n">${lines.length} line item(s)</div></div>
      <div class="lg"><div class="k">Net profit</div><div class="v ${netProfit>=0?"good":"bad"}">${fmt$(netProfit)}</div><div class="n">${leanMode()?"Lean overhead on":"Standard overhead"}</div></div>
    </div>
    <div class="flatsec">
      <h3>Where the money goes</h3>
      ${totalExp===0? `<div class="muted" style="font-size:12px;">Nothing yet. You have no payroll, no rent, no tools and no debt \u2014 so this month costs you nothing. Expenses appear here the moment you cause them.</div>`:""}
      ${lines.map(([k,v])=>{ const i = expInfo(k);
        return `<div class="exp-line">
          <div><div><b>${i.label}</b> <span class="muted" style="font-size:11px;">${Math.round(100*v/Math.max(1,totalExp))}%</span></div>
            <div class="why">${i.why}</div></div>
          <div style="text-align:right;white-space:nowrap;">
            <div style="font-weight:700;">${fmt$(v)}</div>
            <button class="btn secondary small" data-expgo="${i.go}">Manage</button>
          </div></div>`; }).join("")}
    </div>
    <div class="flatsec">
      <h3>Cost control</h3>
      <div class="flexrow" style="justify-content:space-between;gap:12px;flex-wrap:wrap;">
        <div class="why" style="max-width:56ch;">Lean overhead cuts software and admin spend by 25%. Cheap, but execution slows slightly \u2014 success score takes a small monthly hit.</div>
        <button class="btn ${leanMode()?"":"secondary"} small" id="leanToggle">${leanMode()?"Lean overhead: ON":"Switch to lean overhead"}</button>
      </div>
    </div>
    <div class="flatsec">
      <h3>Net profit \u2014 last 6 months</h3>
      ${hist.length? hist.map(h=>`<div class="barrow"><span class="lbl">Y${h.year} M${h.month}</span><div class="track"><div class="fill" style="width:${50+50*(h.netProfit/maxAbs)}%;background:${h.netProfit>=0?'var(--good)':'var(--bad)'};"></div></div><span>${fmt$(h.netProfit)}</span></div>`).join("")
      : `<span class="muted">No history yet \u2014 advance a month.</span>`}
    </div>`;
  wrap.querySelectorAll("[data-expgo]").forEach(b=> b.onclick = ()=>{ G.ui.activeTab = b.getAttribute("data-expgo"); renderDock(); renderScreen(); });
  const lt = wrap.querySelector("#leanToggle");
  if(lt) lt.onclick = toggleLean;
  return wrap;
}

/* ---------- Market: one SVG style everywhere ---------- */
function v10Card(item, kind, opts){
  const p = pInit();
  opts = opts || {};
  const owned = opts.owned || false;
  const locked = (item.minNetWorth||0) > 0 && (p.netWorth||0) < item.minNetWorth;
  const sub = kind==="house" ? ` \u00b7 ${fmt$(item.mortgage)}/mo` : "";
  return `<div class="shop-card ${locked?'locked-overlay':''}">
    ${locked?`<div class="locked-badge">Needs ${fmt$(item.minNetWorth)} net worth</div>`:""}
    ${artFor(item, kind)}
    <div class="info">
      <div class="name">${item.name} ${owned?'<span class="pill good">Owned</span>':''}</div>
      <div class="feat">${item.feat||""}</div>
      <div class="price">${fmt$(item.price)}${sub}</div>
      ${owned && kind!=="vacation" ? "" : `<button class="btn small" ${locked||opts.disabled?'disabled':''} data-v10buy="${kind}:${item.key}">${opts.label || (kind==="vacation"?"Book Trip":"Buy")}</button>`}
    </div></div>`;
}
const SHOPTAB_ICON = { houses:"house", cars:"car", air:"plane", sea:"yacht", lux:"gem", trips:"globe", owned:"box" };
function renderMarketV12(){
  const wrap = renderMarketV11();
  wrap.querySelectorAll("[data-shoptab]").forEach(b=>{
    const id = b.getAttribute("data-shoptab");
    const txt = b.textContent.replace(/^[^A-Za-z(]+/, "").trim();
    b.innerHTML = `${svgIcon(SHOPTAB_ICON[id]||"box")} ${txt}`;
  });
  const tabRow = wrap.querySelector("[data-shoptab]");
  if(tabRow && tabRow.parentNode) tabRow.parentNode.classList.add("tierbar2");
  const title = wrap.querySelector(".window-title h2");
  if(title) title.innerHTML = `${svgIcon("scale")} Market vs Owned`;
  wrap.querySelectorAll(".ladder-card .title").forEach(t=>{
    const raw = t.innerHTML;
    const stripped = raw.replace(/^(?:[\uD800-\uDBFF][\uDC00-\uDFFF]|[\u2190-\u2BFF\uFE0F\u200D\u26A0-\u27BF])+\s*/, "");
    const name = (t.textContent||"").toLowerCase();
    let ico = "box";
    if(/house|home|villa|penthouse|chalet|estate|loft|studio|townhome|bungalow|ranch|brownstone|vineyard|ch\u00e2teau|chateau|compound|tower|beach/.test(name)) ico = "house";
    else if(/jet|plane|aircraft|cessna|gulfstream|helicopter|citation|learjet/.test(name)) ico = "plane";
    else if(/yacht|boat|catamaran|sail|ship|cruiser/.test(name)) ico = "yacht";
    else if(/watch|chrono/.test(name)) ico = "watch";
    else if(/art|paint|sculpt/.test(name)) ico = "art";
    else if(/car|coupe|sedan|pickup|truck|hatch|roadster|suv|ev\b/.test(name)) ico = "car";
    t.innerHTML = `${svgIcon(ico)} ${stripped}`;
  });
  wrap.querySelectorAll(".card > h3").forEach(h=>{
    const t = h.textContent.replace(/^(?:[\uD800-\uDBFF][\uDC00-\uDFFF]|[\u2190-\u2BFF\uFE0F\u200D\u26A0-\u27BF])+\s*/, "").trim();
    let ico = "box";
    if(/propert|real estate/i.test(t)) ico = "house";
    else if(/garage|vehicle/i.test(t)) ico = "car";
    else if(/collectible|aircraft, boats/i.test(t)) ico = "gem";
    else if(/fleet/i.test(t)) ico = "plane";
    else if(/trip/i.test(t)) ico = "globe";
    h.innerHTML = `${svgIcon(ico)} ${t}`;
  });
  return wrap;
}

/* ---------- Bank overview: lines, not a wall of boxes ---------- */
function renderBank(){
  const wrap = renderBankV11();
  const secRow = wrap.querySelector("[data-banksec]");
  if(secRow && secRow.parentNode) secRow.parentNode.classList.add("tierbar2");
  const accRow = wrap.querySelector("[data-bankacct]");
  if(accRow && accRow.parentNode) accRow.parentNode.classList.add("tierbar2");
  if(G.ui.bankSection==="overview"){
    const grid = wrap.querySelector(".grid.cols-3");
    if(grid){
      const cards = Array.from(grid.querySelectorAll(".card"));
      const row = document.createElement("div");
      row.className = "ledger-row";
      row.innerHTML = cards.map(c=>{
        const k = c.querySelector("h3"); const v = c.querySelector(".big"); const n = c.querySelector(".muted");
        return `<div class="lg"><div class="k">${k?k.textContent:""}</div>
          <div class="v ${v && v.classList.contains("bad")?"bad":""}">${v?v.textContent:""}</div>
          <div class="n">${n?n.innerHTML:""}</div></div>`;
      }).join("");
      grid.replaceWith(row);
    }
    Array.from(wrap.querySelectorAll(".card")).forEach(c=>{
      if(c.querySelector("[data-banksec]") || c.querySelector("[data-bankacct]")) return;
      c.classList.remove("card");
      c.classList.add("flatsec");
    });
  }
  return wrap;
}

/* ---------- Empire: locked industries + hint text below the button ---------- */
function renderEmpire(){
  const wrap = renderEmpireV11();
  const hint = wrap.querySelector("#v10FoundHint");
  if(hint){ hint.className = "muted found-hint"; hint.style.marginLeft = "0"; }
  const grid = wrap.querySelector(".folder-grid");
  if(grid){
    syncIndustryUnlocks();
    grid.querySelectorAll("[data-found]").forEach(t=>{
      const key = t.getAttribute("data-found");
      if(industryUnlocked(key)) return;
      t.classList.add("locked-overlay");
      if(!t.querySelector(".locked-badge")){
        const b = document.createElement("div");
        b.className = "locked-badge";
        b.textContent = `${fmt$(unlockReq(key))} net worth`;
        t.appendChild(b);
      }
      t.onclick = ()=> alert(`${INDUSTRIES[key].label} is still locked.\n\n${industryLockNote(key)}`);
    });
    if(!industryUnlocked(G.ui.foundIndustry||"")){
      const open = INDUSTRY_KEYS.filter(k=>industryUnlocked(k));
      if(open.length) G.ui.foundIndustry = open[0];
    }
  }
  return wrap;
}

/* ---------- Monthly hook: announce unlocks ---------- */
function advanceMonth(){
  const before = (G.playerMeta && G.playerMeta.unlockedIndustries || []).slice();
  const out = advanceMonthV11();
  const fresh = syncIndustryUnlocks().filter(k=>before.indexOf(k)<0);
  if(fresh.length){
    fresh.forEach(k=> logHistory(`New industry unlocked: ${INDUSTRIES[k].label}. You can found one from the Empire tab.`));
    setTimeout(()=>{
      alert(`\u{1F513} Unlocked: ${fresh.map(k=>INDUSTRIES[k].label).join(", ")}\n\nYou can found a company in that industry from the Empire tab \u2014 once you clear the founding requirements.`);
    }, 50);
  }
  return out;
}

/* ---------- Save migration ---------- */
function normalizeGame(g){
  const out = normalizeGameV11(g);
  if(out){
    if(!out.playerMeta) out.playerMeta = { playerName:"Founder" };
    (out.companies||[]).forEach(co=>{
      if(!co.costPolicy) co.costPolicy = { lean:false };
      const e = co.equity;
      if(e && e.pool === 1000000 && (e.grants||[]).length===0 && (e.investors||[]).length===0){
        e.founder += e.pool; e.pool = 0;
      }
    });
    if(!out.playerMeta.unlockedIndustries){
      out.playerMeta.unlockedIndustries = ["ai_saas"];
      (out.companies||[]).forEach(co=>{ if(out.playerMeta.unlockedIndustries.indexOf(co.industry)<0) out.playerMeta.unlockedIndustries.push(co.industry); });
      const score = Math.round(((out.personal&&out.personal.netWorth)||0) + (out.companies||[]).reduce((s,c)=>s+(c.netWorth||0)+(c.cash||0),0));
      INDUSTRY_KEYS.forEach(k=>{ if(out.playerMeta.unlockedIndustries.indexOf(k)<0 && score >= unlockReq(k)) out.playerMeta.unlockedIndustries.push(k); });
    }
  }
  return out;
}


