const PAL = {
  night:"#121722", dusk:"#1d2436", day:"#2a3650", ground:"#222a36", ground2:"#1a202a",
  wall:"#4c5670", wall2:"#5f6a86", brick:"#7d4b43", wood:"#7d5b3a", stone:"#6d727c",
  stucco:"#cbb89b", glass:"#6ea8fe", roof:"#333b4e", roof2:"#262d3d", win:"#f5b95d",
  cool:"#9ad6ff", water:"#27556e", water2:"#356f8d", tree:"#2c6248", tree2:"#3d8a63",
  snow:"#e8eef6", metal:"#98a2b3", chrome:"#c8d0dc", tire:"#15181e", red:"#df564e",
  sun:"#f5d06b", sand:"#c6a878", grass:"#3a6a45", purple:"#b39ddb", black:"#0d1016",
};

function rct(x,y,w,h,f,r){ return `<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${f}"${r?` rx="${r}"`:""}/>`; }
function ply(pts,f){ return `<polygon points="${pts}" fill="${f}"/>`; }
function crc(x,y,r,f){ return `<circle cx="${x}" cy="${y}" r="${r}" fill="${f}"/>`; }
function ell(x,y,rx,ry,f){ return `<ellipse cx="${x}" cy="${y}" rx="${rx}" ry="${ry}" fill="${f}"/>`; }
function ln(x1,y1,x2,y2,s,w){ return `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${s}" stroke-width="${w||1.4}" stroke-linecap="round"/>`; }
function pth(d,f,s,w){ return `<path d="${d}" fill="${f||"none"}"${s?` stroke="${s}" stroke-width="${w||1.5}" stroke-linecap="round" stroke-linejoin="round"`:""}/>`; }

function sky(top){ return rct(0,0,200,120,top||PAL.night); }
function stars(n,seed){
  let out="", s = seed||7;
  for(let i=0;i<(n||18);i++){ s=(s*9301+49297)%233280; const x=(s/233280)*200; s=(s*9301+49297)%233280; const y=(s/233280)*58;
    out += crc(Math.round(x),Math.round(y)+3,(i%4===0)?1.1:0.7,"#cfd8e8"); }
  return out;
}
function moon(x,y,r){ return crc(x||168,y||22,r||9,"#e9eefa") + crc((x||168)+4,(y||22)-3,(r||9)*0.85,PAL.night); }
function sunDisc(x,y,r,f){ return crc(x||162,y||28,r||13,f||PAL.sun); }
function grd(y,f){ return rct(0,y,200,120-y,f||PAL.ground); }
function hill(y,f){ return pth(`M0 ${y+10} Q50 ${y-6} 100 ${y+4} T200 ${y-2} L200 120 L0 120 Z`, f||PAL.ground2); }
function winRow(x,y,cols,dx,w,h,f){ let o=""; for(let i=0;i<cols;i++) o+=rct(x+i*dx,y,w,h,f||PAL.win,1); return o; }
function winGrid(x,y,cols,rows,dx,dy,w,h,f){ let o=""; for(let r=0;r<rows;r++) o+=winRow(x,y+r*dy,cols,dx,w,h,((r+1)%3===0)?PAL.roof2:(f||PAL.win)); return o; }
function gable(x,y,w,h,f){ return ply(`${x-3},${y} ${x+w/2},${y-h} ${x+w+3},${y}`, f||PAL.roof); }
function hipRoof(x,y,w,h,f){ return ply(`${x},${y} ${x+w*0.22},${y-h} ${x+w*0.78},${y-h} ${x+w},${y}`, f||PAL.roof); }
function pine(x,base,s,f){ const S=s||1; return ply(`${x},${base-26*S} ${x-9*S},${base} ${x+9*S},${base}`, f||PAL.tree) + rct(x-1.4*S,base,2.8*S,4*S,"#3a2b20"); }
function tree(x,base,s){ const S=s||1; return rct(x-1.6*S,base-9*S,3.2*S,9*S,"#3d2c20") + crc(x,base-15*S,8.5*S,PAL.tree) + crc(x-6*S,base-11*S,5.5*S,PAL.tree2) + crc(x+6*S,base-12*S,5*S,PAL.tree2); }
function palm(x,base,s,flip){ const S=s||1, d=flip?-1:1;
  return pth(`M${x} ${base} q${2*d*S} ${-14*S} ${5*d*S} ${-24*S}`,null,"#6b5335",2.4*S)
    + pth(`M${x+5*d*S} ${base-24*S} q${-11*S} ${-7*S} ${-19*S} ${-2*S} q9 ${-4*S} ${19*S} ${-1*S}`,PAL.tree2)
    + pth(`M${x+5*d*S} ${base-24*S} q${11*S} ${-8*S} ${19*S} ${-3*S} q-9 ${-3*S} ${-19*S} ${-1*S}`,PAL.tree)
    + pth(`M${x+5*d*S} ${base-24*S} q${-3*S} ${-12*S} ${2*S} ${-18*S} q3 ${8*S} ${2*S} ${18*S}`,PAL.tree2); }
function water(y,f){ return rct(0,y,200,120-y,f||PAL.water) + ln(18,y+8,62,y+8,PAL.water2,2) + ln(96,y+14,150,y+14,PAL.water2,2) + ln(40,y+22,110,y+22,PAL.water2,2) + ln(130,y+28,186,y+28,PAL.water2,2); }
function pool(x,y,w,h){ return rct(x,y,w,h,"#3d87a8",3) + ln(x+4,y+h*0.45,x+w-4,y+h*0.45,"#69b6d6",1.6); }
function peaks(y,f,snowTop){
  let o = ply(`0,${y+12} 34,${y-22} 62,${y+12}`, f||"#2f3848") + ply(`46,${y+12} 88,${y-34} 128,${y+12}`, f||"#374158") + ply(`110,${y+12} 152,${y-26} 196,${y+12}`, f||"#2f3848");
  if(snowTop) o += ply(`80,${y-34} 88,${y-34} 97,${y-22} 90,${y-19} 84,${y-22} 78,${y-20}`,PAL.snow) + ply(`28,${y-22} 34,${y-22} 41,${y-13} 30,${y-11} 25,${y-14}`,PAL.snow);
  return o;
}
function cityline(y){
  const b=[[6,26,16],[26,38,11],[42,20,22],[66,30,14],[100,24,26],[128,34,12],[166,26,20],[188,12,15]];
  let o=""; b.forEach(([x,h,w],i)=>{ o+=rct(x,y-h,w,h,i%2?"#232b3a":"#1d2430"); o+=winGrid(x+2.5,y-h+4,Math.max(1,Math.floor(w/6)),Math.max(1,Math.floor(h/8)),6,8,2.4,3,PAL.win); });
  return o;
}
function fence(x1,x2,y){ let o=ln(x1,y-6,x2,y-6,"#5a4a38",1.6); for(let x=x1;x<=x2;x+=9) o+=ln(x,y-10,x,y,"#5a4a38",1.6); return o; }
function road(y){ return ply(`60,${y} 140,${y} 200,120 0,120`,"#2b313d") + ln(100,y+2,100,118,"#7d8798",2.2) + ln(100,y+2,100,118,"#2b313d",0); }
function scene(inner, cls){ return `<div class="art-scene ${cls||""}"><svg viewBox="0 0 200 120" preserveAspectRatio="none">${inner}</svg></div>`; }
function thumb(inner){ return `<div class="art-thumb"><svg viewBox="0 0 200 120" preserveAspectRatio="none">${inner}</svg></div>`; }

