/* ---------- Vehicles: silhouettes drawn per model ---------- */
function garage(f){ return sky(f||"#1a2030") + rct(0,84,200,36,"#232a36") + ell(100,104,86,12,"#1b212c"); }
function wheel(x,y,r,rim){ return crc(x,y,r,PAL.tire) + crc(x,y,r*0.42,rim||PAL.chrome); }
function showroom(){ return sky("#191f2c") + rct(0,0,200,54,"#1f2634") + winRow(16,14,5,36,26,5,"#2c3a44") + rct(0,84,200,36,"#242b38") + ell(100,102,90,13,"#1c222d"); }
