/* ---------- Art resolver ---------- */
function artInner(item, kind){
  try {
    if(kind==="house" && HOUSE_ART[item.key]) return HOUSE_ART[item.key]();
    if(kind==="car" && CAR_ART[item.key]) return CAR_ART[item.key]();
    if(kind==="toy" && TOY_ART[item.key]) return TOY_ART[item.key]();
    if(kind==="vacation" && TRIP_ART[item.key]) return TRIP_ART[item.key]();
  } catch(e){}
  const price = item.price || 0;
  if(kind==="house") return price>5000000 ? HOUSE_ART.villa() : price>700000 ? HOUSE_ART.suburban() : HOUSE_ART.studio();
  if(kind==="car") return price>500000 ? CAR_ART.supercar() : price>60000 ? CAR_ART.german() : CAR_ART.hatch();
  if(kind==="toy") return item.cls==="air" ? TOY_ART.lightjet() : item.cls==="sea" ? TOY_ART.cabin_cruiser() : TOY_ART.watch();
  return TRIP_ART.worldtour();
}
function artFor(item, kind){ return scene(artInner(item, kind)); }
function artThumb(item, kind){ return thumb(artInner(item, kind)); }
function artKindOf(item){
  if(!item) return "toy";
  if(item.mortgage!==undefined || HOUSE_ART[item.key]) return "house";
  if(CAR_ART[item.key]) return "car";
  if(TRIP_ART[item.key]) return "vacation";
  return "toy";
}

/* ---------- Portfolio thumbnails ---------- */
function catalogIndex(){
  if(window.__catIdx) return window.__catIdx;
  const idx = {};
  HOUSES.forEach(h=> idx[(h.name||"").toLowerCase()] = { item:h, kind:"house" });
  CARS.forEach(c=> idx[(c.name||"").toLowerCase()] = { item:c, kind:"car" });
  TOYS.forEach(t=> idx[(t.name||"").toLowerCase()] = { item:t, kind:"toy" });
  VACATIONS.forEach(v=> idx[(v.name||"").toLowerCase()] = { item:v, kind:"vacation" });
  window.__catIdx = idx;
  return idx;
}
function lookupCatalog(label){
  const idx = catalogIndex();
  const clean = (label||"").replace(/\s+/g," ").trim().toLowerCase();
  if(idx[clean]) return idx[clean];
  const keys = Object.keys(idx);
  const hit = keys.find(k=> clean.indexOf(k)>=0);
  return hit ? idx[hit] : null;
}

/* ---------- Market: illustrated cards + illustrated portfolio rows ---------- */
function renderMarket(){
  const wrap = renderMarketV12();
  wrap.querySelectorAll(".ladder-card").forEach(card=>{
    const t = card.querySelector(".title");
    if(!t) return;
    const found = lookupCatalog(t.textContent||"");
    if(!found) return;
    t.innerHTML = t.innerHTML.replace(/^\s*<svg[\s\S]*?<\/svg>\s*/i, "");
    const row = card.querySelector(".row");
    if(!row || row.querySelector(".art-thumb")) return;
    row.classList.add("with-art");
    const holder = document.createElement("div");
    holder.innerHTML = artThumb(found.item, found.kind);
    row.insertBefore(holder.firstChild, row.firstChild);
  });
  return wrap;
}

/* ---------- Fulfillment: cost up front, payoff underneath, real ideas ---------- */
const INSIGHT_OUTCOMES = [
  { key:"pricing", label:"a pricing insight", apply:(c)=>{ c.priceTier = clamp((c.priceTier||1)+0.05, 0.5, 3); return "You spotted a pricing gap. Price tier nudged up with no churn hit."; } },
  { key:"process", label:"a process fix", apply:(c)=>{ if(c.costPolicy) c.costPolicy.lean = true; return "You redesigned a workflow on a napkin. Lean overhead switched on."; } },
  { key:"product", label:"a product idea", apply:(c)=>{ c.successScore = clamp(c.successScore+5,0,100); return "A product idea clicked. Success score +5."; } },
  { key:"pipeline", label:"a warm introduction", apply:(c)=>{ const boost = Math.max(400, Math.round((c.mrr||0)*0.04)); c.mrr = (c.mrr||0) + boost; return `Someone you met sent business your way. +${fmt$(boost)} MRR.`; } },
  { key:"talent", label:"a hiring lead", apply:(c)=>{ c.employees.forEach(e=> e.morale = clamp(e.morale+6,0,100)); return "You came back energized and it showed. Team morale +6 across the board."; } },
  { key:"savings", label:"a cost discovery", apply:(c)=>{ const cut = Math.round((c.expensesBreakdown.marketing||0)*0.15); c.expensesBreakdown.marketing = Math.max(0,(c.expensesBreakdown.marketing||0)-cut); return cut>0 ? `You found ${fmt$(cut)}/mo of wasted ad spend and killed it.` : "You mapped where money leaks before it starts. Noted for later."; } },
];
function doFulfillment(key){
  const p = pInit();
  const a = FULFILLMENT.find(x=>x.key===key);
  if(!a) return;
  if(p.actsThisMonth.indexOf(key)>=0){ alert(`You already did "${a.name}" this month.`); return; }
  if(p.cash < a.price){ alert(`Not enough personal cash for ${a.name} (${fmt$(a.price)}).`); return; }
  p.cash -= a.price;
  p.happiness = clamp(p.happiness + a.happiness, 0, 100);
  p.wellbeing = clamp(p.wellbeing + a.wellbeing, 0, 100);
  p.actsThisMonth.push(key);
  p.fulfillHistory.push({ name:a.name, month:G.company.month, year:G.company.year });
  p.monthEvents.push(`${a.name}${a.price?` (${fmt$(a.price)})`:" (free)"} \u2014 +${a.happiness} happiness, +${a.wellbeing} wellbeing`);
  if(!p.insights) p.insights = [];
  let msg = "";
  if(a.insight && Math.random() < 0.5){
    const out = pick(INSIGHT_OUTCOMES);
    let detail = "";
    try { detail = out.apply(G.company) || ""; } catch(e){ detail = ""; }
    const line = `\u{1F4A1} ${a.name} sparked ${out.label}: ${detail}`;
    p.insights.push({ name:a.name, outcome:detail, month:G.company.month, year:G.company.year });
    p.monthEvents.push(line);
    logHistory(line);
    msg = `\n\n\u{1F4A1} ${detail}`;
  }
  alert(`${a.name} \u2014 ${a.price?fmt$(a.price):"free"}\n+${a.happiness} happiness \u00b7 +${a.wellbeing} wellbeing${msg}`);
  renderAll();
}
function fulfillCard(a, done){
  return `<div class="fcard ${done?"done":""}">
    <div class="ftop">
      <div class="fname">${a.name}${done?' <span class="pill good">Done</span>':""}</div>
      <div class="fcost ${a.price?"":"free"}">${a.price? fmt$(a.price) : "Free"}</div>
    </div>
    <div class="fgain">+${a.happiness} happiness \u00b7 +${a.wellbeing} wellbeing${a.insight?" \u00b7 \u{1F4A1} can spark a real business idea":""}</div>
    <div class="fdesc">${a.desc}</div>
    <div class="fact"><button class="btn secondary small" data-fulfill="${a.key}" ${done?"disabled":""}>${done?"Done this month":"Do it"}</button></div>
  </div>`;
}

/* ---------- Personal: fulfillment rebuilt, compensation moved to Finance ---------- */
function renderPersonal(){
  const wrap = renderPersonalV12();
  const p = pInit();
  const cards = Array.from(wrap.querySelectorAll(".card"));
  const fulfillCardEl = cards.find(c=> /Fulfillment/i.test((c.querySelector("h3")||{}).textContent||""));
  if(fulfillCardEl){
    const grid = fulfillCardEl.querySelector(".grid");
    if(grid){
      grid.className = "grid cols-2";
      grid.innerHTML = FULFILLMENT.map(a=> fulfillCard(a, p.actsThisMonth.indexOf(a.key)>=0)).join("");
    }
    if(p.insights && p.insights.length){
      const ins = document.createElement("div");
      ins.className = "muted mt8";
      ins.style.fontSize = "11.5px";
      ins.innerHTML = `\u{1F4A1} Ideas this life: ${p.insights.slice(-3).map(i=>i.outcome).join(" \u00b7 ")}`;
      fulfillCardEl.appendChild(ins);
    }
  }
  const compCard = cards.find(c=> /My Compensation/i.test((c.querySelector("h3")||{}).textContent||""));
  if(compCard){
    compCard.innerHTML = `<h3>\u{1F4BC} My Compensation</h3>
      <div class="muted" style="font-size:12.5px;">Your draw and founder bonuses are company money, so they now live with the rest of the company's money.</div>
      <div class="mt8"><button class="btn small" id="goFinComp">\u{1F4CA} Open Finance \u2192 Owner Pay</button>
        <button class="btn secondary small" id="goShop2">Open The Market</button>
        <button class="btn secondary small" id="goBank2">My Bank Accounts</button></div>`;
    const gf = compCard.querySelector("#goFinComp");
    if(gf) gf.onclick = ()=>{ G.ui.activeTab="financials"; renderDock(); renderScreen(); };
    const gs = compCard.querySelector("#goShop2");
    if(gs) gs.onclick = ()=>{ G.ui.activeTab="market"; renderDock(); renderScreen(); };
    const gb = compCard.querySelector("#goBank2");
    if(gb) gb.onclick = ()=>{ G.ui.activeTab="bank"; G.ui.bankAccount="personal"; renderDock(); renderScreen(); };
  }
  wrap.querySelectorAll("[data-fulfill]").forEach(b=> b.onclick=()=> doFulfillment(b.getAttribute("data-fulfill")));
  return wrap;
}

/* ---------- Owner pay lives in Finance ---------- */
function ownerPaySection(){
  const p = pInit();
  const cap = Math.max(3500, Math.round((G.company.mrr||0)*0.6) + 3500);
  const box = el(`<div class="flatsec">
    <h3>\u{1F4BC} Owner Pay</h3>
    <div class="muted mb8" style="font-size:12px;">Your draw and any founder bonus come out of ${G.company.name}'s cash before profit. Cap right now is ${fmt$(cap)}/mo based on revenue.</div>
    <div class="ledger-row">
      <div class="lg"><div class="k">Monthly draw</div><div class="v good">${fmt$(p.salaryDraw)}</div><div class="n">Paid to you every month close</div></div>
      <div class="lg"><div class="k">Annualized</div><div class="v">${fmt$(p.salaryDraw*12)}</div><div class="n">If you hold this rate for a year</div></div>
      <div class="lg"><div class="k">Share of expenses</div><div class="v">${Math.round(100*p.salaryDraw/Math.max(1,Object.values(G.company.expensesBreakdown).reduce((a,b)=>a+b,0)+p.salaryDraw))}%</div><div class="n">Your pay vs. company costs</div></div>
    </div>
    <div class="flexrow mt8" style="align-items:center;gap:8px;">
      <button class="btn secondary small" id="ownerDown">\u2212 $500</button>
      <b style="min-width:92px;text-align:center;display:inline-block;">${fmt$(p.salaryDraw)}/mo</b>
      <button class="btn secondary small" id="ownerUp">+ $500</button>
      <button class="btn small" id="ownerBonus">\u{1F381} Pay Myself a Bonus</button>
    </div>
  </div>`);
  box.querySelector("#ownerUp").onclick = ()=>{ p.salaryDraw = Math.min(cap, p.salaryDraw+500); renderScreen(); };
  box.querySelector("#ownerDown").onclick = ()=>{ p.salaryDraw = Math.max(0, p.salaryDraw-500); renderScreen(); };
  box.querySelector("#ownerBonus").onclick = ()=>{
    const amount = Number(window.prompt("Bonus amount (paid from company cash)?", "5000"));
    if(!amount || amount<=0) return;
    if(!affordOrAlert(amount, "your bonus")) return;
    queueAdd({ id:uid(), label:"Founder bonus to self", cost:amount, run:(report)=>{
      if(G.company.cash<amount){ report.push("Skipped your founder bonus \u2014 insufficient company cash."); return; }
      G.company.cash -= amount; G.personal.cash += amount;
      G.personal.happiness = clamp(G.personal.happiness+6,0,100);
      report.push(`You paid yourself a ${fmt$(amount)} bonus.`);
    }});
    renderScreen();
  };
  return box;
}
function renderFinancials(){
  const wrap = renderFinancialsV12();
  wrap.appendChild(ownerPaySection());
  return wrap;
}

/* ---------- Month close: room to breathe, and a story ---------- */
function mcLine(label, value, why, cls){
  return `<div class="mc-line ${cls||""}"><div class="mc-l">${label}${why?`<span class="mc-why">${why}</span>`:""}</div><div class="mc-n ${cls&&cls.indexOf("good")>=0?"good":""}">${value}</div></div>`;
}
function mcSec(title, rows){
  return `<div class="mc-sec"><div class="mc-t">${title}</div>${rows.join("")}</div>`;
}
function monthStory(r){
  const c = G.company, out = [];
  const margin = r.revenue>0 ? Math.round(100*r.netProfit/r.revenue) : 0;
  const runway = (r.cashDelta<0) ? Math.floor(c.cash/Math.max(1,-r.cashDelta)) : null;
  let p1 = `${c.name} brought in <b>${fmt$(r.revenue)}</b> and spent <b>${fmt$(r.expenses)}</b> keeping the lights on, so the business itself ${r.netProfit>=0?`earned <b class="good">${fmt$(r.netProfit)}</b>`:`lost <b class="bad">${fmt$(Math.abs(r.netProfit))}</b>`} on ${margin}% margin.`;
  if(r.oneOffSpend>0) p1 += ` On top of that you wrote <b>${fmt$(r.oneOffSpend)}</b> of one-time checks, which is why cash moved ${r.cashDelta>=0?"up":"down"} <b class="${r.cashDelta>=0?"good":"bad"}">${fmt$(Math.abs(r.cashDelta))}</b> instead.`;
  out.push(p1);
  let p2 = "";
  if(r.mrrDelta>0) p2 += `Recurring revenue grew ${fmt$(r.mrrDelta)} this month. `;
  else if(r.mrrDelta<0) p2 += `Recurring revenue slipped ${fmt$(Math.abs(r.mrrDelta))} \u2014 worth knowing why before next close. `;
  else p2 += `Recurring revenue held flat. `;
  if(runway!==null) p2 += `At this burn you have roughly <b>${runway} month${runway===1?"":"s"}</b> of cash left. `;
  else p2 += `You're cash-positive, so every month from here buys you options. `;
  if(r.debtTotal>0) p2 += `You're carrying ${fmt$(r.debtTotal)} of debt against ${fmt$(c.cash)} in the bank.`;
  else p2 += `You're carrying no debt.`;
  out.push(p2);
  const big = (r.lines||[]).slice(0,2);
  if(big.length) out.push(`The headline: ${big.join(" ")}`);
  return out.map(p=>`<p>${p}</p>`).join("");
}
function showMonthSummaryModal(){
  const r = G.company.lastReport;
  if(!r) return;
  const p = pInit();
  const overlay = document.getElementById("modalOverlay");
  const box = document.getElementById("modalBox");
  box.style.maxWidth = "760px"; box.style.maxHeight = "84vh"; box.style.overflowY = "auto";
  const tabs = [
    { key:"company", label:"\u{1F3E2} Company" },
    { key:"personal", label:"\u{1F3E1} Personal" },
    { key:"invest", label:"\u{1F4C8} Investments" },
  ];
  box.innerHTML = `
    <span class="close" id="closeModal">&times;</span>
    <h3>Month Closed \u2014 Year ${r.year}, Month ${r.month}</h3>
    <div class="flexrow mb8" style="gap:6px;">${tabs.map((t,i)=>`<button class="btn ${i===0?"":"secondary"} small" data-mtab="${t.key}">${t.label}</button>`).join("")}</div>
    <div id="mtabPanels"></div>
    <div class="mt14"><button class="btn small" id="closeSummaryBtn">Got it</button></div>
  `;
  const panels = box.querySelector("#mtabPanels");
  function renderPanel(key){
    if(key==="company"){
      const oneOffs = (r.lines||[]).filter(l=> /bonus|hire|hired|upgrade|paid|bought|purchase/i.test(l));
      panels.innerHTML = `
        <div class="mc-head" style="border-color:${r.cashDelta>=0?"var(--good)":"var(--bad)"};">
          <div class="mc-k">\u{1F4B0} Total cash change this month</div>
          <div class="mc-v ${r.cashDelta>=0?"good":"bad"}">${r.cashDelta>=0?"+":""}${fmt$(r.cashDelta)}</div>
          <div class="mc-sub">Recurring profit and one-off spend combined \u2014 the real bottom line. Bank balance is now ${fmt$(G.company.cash)}.</div>
        </div>
        ${mcSec("Revenue &amp; profit", [
          mcLine("Revenue", fmt$(r.revenue), "Recurring money in from customers"),
          mcLine("Recurring expenses", `\u2212 ${fmt$(r.expenses)}`, "Payroll, tools, rent, marketing, interest, your draw"),
          mcLine("Net profit", `${r.netProfit>=0?"":"\u2212"}${fmt$(Math.abs(r.netProfit))}`, "What the business earns when nothing unusual happens", "total"),
        ])}
        ${mcSec("One-off spend", [
          mcLine("One-time checks written", `\u2212 ${fmt$(r.oneOffSpend||0)}`, oneOffs.length? oneOffs.slice(0,3).join(" \u00b7 ") : "Bonuses, hires, upgrades, purchases \u2014 none this month", "total"),
        ])}
        ${mcSec("Position", [
          mcLine("MRR change", `${r.mrrDelta>=0?"+":"\u2212"}${fmt$(Math.abs(r.mrrDelta))}`, "Movement in locked-in monthly revenue"),
          mcLine("Total debt", fmt$(r.debtTotal), "Loans plus line of credit drawn"),
          mcLine("Cash on hand", fmt$(G.company.cash), "Company operating account"),
        ])}
        <div class="mc-story"><div class="mc-t">The month in plain English</div>${monthStory(r)}</div>
        ${(r.lines&&r.lines.length)? `<div class="mc-sec"><div class="mc-t">Everything that happened</div>${r.lines.map(l=>`<div class="mc-ev">\u2022 ${l}</div>`).join("")}</div>` : ""}
      `;
    } else if(key==="personal"){
      const draw = Math.min(p.salaryDraw, r.revenue>=0?p.salaryDraw:0);
      panels.innerHTML = `
        <div class="mc-head">
          <div class="mc-k">\u{1F3E1} Your money this month</div>
          <div class="mc-v good">+${fmt$(draw)}</div>
          <div class="mc-sub">Draw paid out of company cash. Personal balance is now ${fmt$(p.cash)}.</div>
        </div>
        ${mcSec("You", [
          mcLine("Happiness", `${Math.round(p.happiness)}/100`, "Fed by what you do outside work"),
          mcLine("Wellbeing", `${Math.round(p.wellbeing)}/100`, "Burn this down and performance follows"),
          mcLine("Personal debt", fmt$(Object.values(p.debt||{}).reduce((a,b)=>a+(b.balance||0),0)), "Mortgages, auto notes, personal loans"),
        ])}
        ${(r.personalEvents&&r.personalEvents.length)? `<div class="mc-sec"><div class="mc-t">Life events</div>${r.personalEvents.map(e=>`<div class="mc-ev">\u2022 ${e}</div>`).join("")}</div>` : `<div class="mc-sec"><div class="mc-t">Life events</div><div class="mc-ev muted">Nothing personal happened this month. That's its own kind of data.</div></div>`}
      `;
    } else {
      panels.innerHTML = `
        <div class="mc-head">
          <div class="mc-k">\u{1F4C8} Portfolio change</div>
          <div class="mc-v ${r.investDelta>=0?"good":"bad"}">${r.investDelta>=0?"+":""}${fmt$(r.investDelta)}</div>
          <div class="mc-sub">Drift across savings, index funds, growth stocks, bonds, and real estate.</div>
        </div>
        ${mcSec("Note", [ mcLine("Money that works while you sleep", "", "Investments move whether or not you touch them. Check the Invest tab to rebalance.") ])}
      `;
    }
  }
  box.querySelectorAll("[data-mtab]").forEach(b=> b.onclick=()=>{
    box.querySelectorAll("[data-mtab]").forEach(x=>x.classList.add("secondary"));
    b.classList.remove("secondary");
    renderPanel(b.getAttribute("data-mtab"));
  });
  renderPanel("company");
  overlay.classList.add("show");
  const close = ()=>{ overlay.classList.remove("show"); box.style.maxWidth=""; };
  box.querySelector("#closeModal").onclick = close;
  box.querySelector("#closeSummaryBtn").onclick = close;
}

/* ---------- Dock: Personal \u2192 My Life \u2192 Market ---------- */
(function reorderLife(){
  try {
    const g = DOCK_GROUPS.find(x=> x.id==="life" || x.key==="life");
    if(g && g.items) g.items = ["personal","life","market"];
  } catch(e){}
})();

/* =================== v14: Depth & Light =================== */
/* Realism pass: every primitive now renders with gradients, shading,
   reflections and cast shadows, and every scene gets atmosphere. */

const SCENE_DEFS = `<defs>
  <linearGradient id="gSky" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0" stop-color="#000" stop-opacity=".45"/>
    <stop offset=".55" stop-color="#000" stop-opacity="0"/>
    <stop offset="1" stop-color="#fff" stop-opacity=".14"/>
  </linearGradient>
  <linearGradient id="gFace" x1="0" y1="0" x2="1" y2="1">
    <stop offset="0" stop-color="#fff" stop-opacity=".16"/>
    <stop offset=".45" stop-color="#fff" stop-opacity=".03"/>
    <stop offset="1" stop-color="#000" stop-opacity=".26"/>
  </linearGradient>
  <linearGradient id="gEdge" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0" stop-color="#fff" stop-opacity=".22"/>
    <stop offset=".18" stop-color="#fff" stop-opacity=".05"/>
    <stop offset=".82" stop-color="#000" stop-opacity=".08"/>
    <stop offset="1" stop-color="#000" stop-opacity=".30"/>
  </linearGradient>
  <radialGradient id="gSphere" cx=".34" cy=".3" r=".8">
    <stop offset="0" stop-color="#fff" stop-opacity=".30"/>
    <stop offset=".55" stop-color="#fff" stop-opacity=".02"/>
    <stop offset="1" stop-color="#000" stop-opacity=".34"/>
  </radialGradient>
  <radialGradient id="gGlow" cx=".5" cy=".5" r=".5">
    <stop offset="0" stop-color="#ffd98a" stop-opacity=".55"/>
    <stop offset="1" stop-color="#ffd98a" stop-opacity="0"/>
  </radialGradient>
  <linearGradient id="gGlass" x1="0" y1="0" x2="1" y2="1">
    <stop offset="0" stop-color="#dff1ff" stop-opacity=".55"/>
    <stop offset=".4" stop-color="#8fc9ff" stop-opacity=".18"/>
    <stop offset="1" stop-color="#0b1320" stop-opacity=".45"/>
  </linearGradient>
  <linearGradient id="gWater" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0" stop-color="#fff" stop-opacity=".24"/>
    <stop offset=".25" stop-color="#fff" stop-opacity=".05"/>
    <stop offset="1" stop-color="#000" stop-opacity=".42"/>
  </linearGradient>
  <linearGradient id="gGround" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0" stop-color="#fff" stop-opacity=".10"/>
    <stop offset="1" stop-color="#000" stop-opacity=".45"/>
  </linearGradient>
  <radialGradient id="gVig" cx=".5" cy=".46" r=".78">
    <stop offset=".55" stop-color="#000" stop-opacity="0"/>
    <stop offset="1" stop-color="#000" stop-opacity=".42"/>
  </radialGradient>
  <linearGradient id="gHaze" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0" stop-color="#9fb6d8" stop-opacity=".18"/>
    <stop offset="1" stop-color="#9fb6d8" stop-opacity="0"/>
  </linearGradient>
  <filter id="fSoft" x="-30%" y="-30%" width="160%" height="160%">
    <feGaussianBlur stdDeviation="2.2"/>
  </filter>
  <filter id="fBloom" x="-60%" y="-60%" width="220%" height="220%">
    <feGaussianBlur stdDeviation="3.4"/>
  </filter>
</defs>`;

/* ---- shaded primitives ---- */
function rct(x,y,w,h,f,r){
  const rr = r?` rx="${r}"`:"";
  let o = `<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${f}"${rr}/>`;
  if(w>=5 && h>=5 && f && f!=="none"){
    o += `<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="url(#gEdge)"${rr}/>`;
  }
  return o;
}
function ply(pts,f,flat){
  let o = `<polygon points="${pts}" fill="${f}"/>`;
  if(!flat && f && f!=="none") o += `<polygon points="${pts}" fill="url(#gFace)"/>`;
  return o;
}
function crc(x,y,r,f,flat){
  let o = `<circle cx="${x}" cy="${y}" r="${r}" fill="${f}"/>`;
  if(!flat && r>=2.2 && f && f!=="none") o += `<circle cx="${x}" cy="${y}" r="${r}" fill="url(#gSphere)"/>`;
  return o;
}
function ell(x,y,rx,ry,f,flat){
  let o = `<ellipse cx="${x}" cy="${y}" rx="${rx}" ry="${ry}" fill="${f}"/>`;
  if(!flat && f && f!=="none") o += `<ellipse cx="${x}" cy="${y}" rx="${rx}" ry="${ry}" fill="url(#gSphere)"/>`;
  return o;
}
function shade(pts){ return `<polygon points="${pts}" fill="#000" opacity=".22"/>`; }
function castShadow(x,y,w,op){ return `<ellipse cx="${x}" cy="${y}" rx="${w}" ry="${Math.max(2,w*0.16)}" fill="#000" opacity="${op||0.34}" filter="url(#fSoft)"/>`; }

/* ---- sky, ground, atmosphere ---- */
function sky(top){
  const c = top||PAL.night;
  return `<rect x="0" y="0" width="200" height="120" fill="${c}"/>`
    + `<rect x="0" y="0" width="200" height="120" fill="url(#gSky)"/>`;
}
function grd(y,f){
  return `<rect x="0" y="${y}" width="200" height="${120-y}" fill="${f||PAL.ground}"/>`
    + `<rect x="0" y="${y}" width="200" height="${120-y}" fill="url(#gGround)"/>`
    + `<rect x="0" y="${y}" width="200" height="1.2" fill="#fff" opacity=".10"/>`;
}
function sunDisc(x,y,r,f){
  const X=x||162, Y=y||28, R=r||13;
  return crc(X,Y,R*2.1,"url(#gGlow)",true) + crc(X,Y,R,f||PAL.sun,true) + crc(X,Y,R,"#fff",true).replace('fill="#fff"','fill="#fff" opacity=".18"');
}
function moon(x,y,r){
  const X=x||168, Y=y||22, R=r||9;
  return crc(X,Y,R*2.4,"url(#gGlow)",true) + crc(X,Y,R,"#e9eefa",true) + crc(X+4,Y-3,R*0.85,PAL.night,true)
    + crc(X-2,Y+2,1.6,"#cfd6e6",true) + crc(X-4,Y-3,1.1,"#cfd6e6",true);
}

/* ---- windows: glass, reflection, spill ---- */
function winRow(x,y,cols,dx,w,h,f){
  let o="";
  const lit = (f||PAL.win);
  const isLit = lit===PAL.win || lit==="#f5b95d";
  for(let i=0;i<cols;i++){
    const X = x+i*dx;
    if(isLit) o += `<rect x="${X-1.4}" y="${y-1.4}" width="${w+2.8}" height="${h+2.8}" fill="${lit}" opacity=".22" filter="url(#fBloom)"/>`;
    o += `<rect x="${X}" y="${y}" width="${w}" height="${h}" fill="${lit}" rx="0.8"/>`;
    o += `<rect x="${X}" y="${y}" width="${w}" height="${h}" fill="url(#gGlass)" rx="0.8"/>`;
    if(w>=5 && h>=5) o += `<polygon points="${X},${y+h} ${X+w*0.55},${y} ${X+w},${y} ${X+w*0.35},${y+h}" fill="#fff" opacity=".14"/>`;
  }
  return o;
}

/* ---- water with depth and a light path ---- */
function water(y,f){
  let o = `<rect x="0" y="${y}" width="200" height="${120-y}" fill="${f||PAL.water}"/>`;
  o += `<rect x="0" y="${y}" width="200" height="${120-y}" fill="url(#gWater)"/>`;
  o += `<rect x="0" y="${y}" width="200" height="1.4" fill="#cfe9f5" opacity=".35"/>`;
  for(let i=0;i<7;i++){
    const yy = y + 4 + i*((120-y-4)/7), len = 26 + (i%3)*22, xx = (i%2? 18 : 96) + (i*13)%60;
    o += `<rect x="${xx}" y="${yy}" width="${len}" height="${1 + i*0.22}" fill="#cfe9f5" opacity="${0.26 - i*0.02}" rx="1"/>`;
  }
  return o;
}

/* ---- vegetation with volume ---- */
function pine(x,base,s,f){
  const S=s||1, col=f||PAL.tree;
  let o = castShadow(x, base+1.5, 9*S, .30);
  o += rct(x-1.5*S, base-6*S, 3*S, 6*S, "#3a2b20");
  for(let i=0;i<3;i++){
    const t = base - (10+i*8)*S, w = (10-i*2.4)*S, h = (11+i*1)*S;
    o += ply(`${x},${t-h} ${x-w},${t} ${x+w},${t}`, col);
    o += `<polygon points="${x},${t-h} ${x+w},${t} ${x+w*0.1},${t}" fill="#000" opacity=".20"/>`;
  }
  return o;
}
function tree(x,base,s){
  const S=s||1;
  return castShadow(x, base+1.5, 9*S, .30)
    + rct(x-1.8*S, base-10*S, 3.6*S, 10*S, "#3d2c20")
    + crc(x-5*S, base-13*S, 6.4*S, PAL.tree)
    + crc(x+5*S, base-14*S, 6*S, PAL.tree)
    + crc(x, base-19*S, 8.4*S, PAL.tree2)
    + crc(x-2*S, base-21*S, 4.4*S, "#4b9c72");
}

/* ---- textures: brick courses, siding, shingles, stone ---- */
function brickWall(x,y,w,h,base){
  let o = rct(x,y,w,h,base||PAL.brick);
  for(let r=0; r*3.4 < h; r++){
    const yy = y + r*3.4;
    o += `<rect x="${x}" y="${yy}" width="${w}" height=".55" fill="#2a1714" opacity=".35"/>`;
    for(let c=(r%2?0:3); c<w; c+=6.4) o += `<rect x="${x+c}" y="${yy}" width=".5" height="3.4" fill="#2a1714" opacity=".28"/>`;
  }
  return o;
}
function siding(x,y,w,h,base){
  let o = rct(x,y,w,h,base||PAL.wall);
  for(let r=0; r*2.6 < h; r++) o += `<rect x="${x}" y="${y+r*2.6}" width="${w}" height=".5" fill="#000" opacity=".16"/>`;
  return o;
}
function shingle(pts, base){
  return ply(pts, base||PAL.roof) + `<polygon points="${pts}" fill="#000" opacity=".12"/>`;
}
function stoneWall(x,y,w,h,base){
  let o = rct(x,y,w,h,base||PAL.stone);
  for(let r=0; r*4.2 < h; r++){
    const yy=y+r*4.2;
    for(let c=(r%2?2:6); c<w; c+=8.5) o += `<rect x="${x+c}" y="${yy+0.6}" width="7" height="3" fill="#fff" opacity=".06" rx="1"/>`;
    o += `<rect x="${x}" y="${yy}" width="${w}" height=".5" fill="#000" opacity=".22"/>`;
  }
  return o;
}
function gable(x,y,w,h,f){ return shingle(`${x-3},${y} ${x+w/2},${y-h} ${x+w+3},${y}`, f||PAL.roof)
  + `<polygon points="${x+w/2},${y-h} ${x+w+3},${y} ${x+w/2},${y}" fill="#000" opacity=".16"/>`; }
function hipRoof(x,y,w,h,f){ return shingle(`${x},${y} ${x+w*0.22},${y-h} ${x+w*0.78},${y-h} ${x+w},${y}`, f||PAL.roof)
  + `<rect x="${x-2}" y="${y-1.4}" width="${w+4}" height="1.8" fill="#000" opacity=".28" rx=".6"/>`; }

/* ---- wheels get rims, tread and contact shadow ---- */
function wheel(x,y,r,tire){
  return castShadow(x, y+r*0.92, r*1.05, .38)
    + crc(x,y,r,tire||PAL.tire,true)
    + crc(x,y,r,"url(#gSphere)",true)
    + crc(x,y,r*0.55,"#aeb7c6",true) + crc(x,y,r*0.55,"url(#gSphere)",true)
    + crc(x,y,r*0.22,"#6c7585",true)
    + `<circle cx="${x}" cy="${y}" r="${r*0.8}" fill="none" stroke="#0a0d12" stroke-width=".8" opacity=".55"/>`;
}

/* ---- scenes: atmosphere, horizon haze, vignette, correct aspect ---- */
function sceneWrap(inner, cls, klass){
  return `<div class="${klass} ${cls||""}"><svg viewBox="0 0 200 120" preserveAspectRatio="xMidYMid slice">`
    + SCENE_DEFS
    + inner
    + `<rect x="0" y="52" width="200" height="34" fill="url(#gHaze)"/>`
    + `<rect x="0" y="0" width="200" height="120" fill="url(#gVig)"/>`
    + `</svg></div>`;
}
function scene(inner, cls){ return sceneWrap(inner, cls, "art-scene"); }
function thumb(inner){ return sceneWrap(inner, "", "art-thumb"); }

