/* ---------------- Bulk hiring: fill to capacity in one click ---------------- */
function v16HireCapacity(deptKey, rungKey){
  const alreadyQueued = G.ui.queue.filter(q=>q.hireDept===deptKey && q.hireRung===rungKey).length;
  const remaining = rungRemaining(deptKey, rungKey);
  const roomLeft = headcountCap() - G.company.employees.length - G.ui.queue.filter(q=>q.hireDept).length;
  let qty = Math.max(0, roomLeft);
  if(remaining!==Infinity) qty = Math.min(qty, Math.max(0, remaining-alreadyQueued));
  return qty;
}
function v16QueueHires(deptKey, rungKey, want){
  const r = LADDERS[deptKey].rungs.find(x=>x.key===rungKey);
  const qty = Math.min(want, v16HireCapacity(deptKey, rungKey));
  if(qty<=0){ alert("No hiring capacity available right now \u2014 promote someone, upgrade the office, or hire the rung below."); return; }
  for(let i=0;i<qty;i++){
    queueAdd({ id:uid(), label:`Hire ${r.label}`, hireDept:deptKey, hireRung:rungKey, run:(report)=>{
      const e = hire(deptKey, rungKey); report.push(`${e.name} joined as ${e.role}.`);
    }});
  }
  renderScreen();
}
function v16InjectBulkHire(){
  document.querySelectorAll("[data-hire]").forEach(btn=>{
    if(btn.getAttribute("data-v16bulk")) return;
    btn.setAttribute("data-v16bulk","1");
    const [deptKey, rungKey] = btn.getAttribute("data-hire").split(":");
    const cap = v16HireCapacity(deptKey, rungKey);
    if(cap<=1) return;
    const opts = [5,10,20,40,100].filter(n=>n<=cap);
    const frag = document.createDocumentFragment();
    opts.forEach(n=>{
      const b = document.createElement("button");
      b.className = "btn secondary small"; b.textContent = `+${n}`;
      b.onclick = ()=> v16QueueHires(deptKey, rungKey, n);
      frag.appendChild(b);
    });
    const maxBtn = document.createElement("button");
    maxBtn.className = "btn small"; maxBtn.textContent = `Fill to capacity (+${cap})`;
    maxBtn.onclick = ()=> v16QueueHires(deptKey, rungKey, cap);
    frag.appendChild(maxBtn);
    if(btn.parentNode) btn.parentNode.insertBefore(frag, btn.nextSibling);
  });
}

/* ---------------- Line staffing panel on Industry Ops ---------------- */
function lineStaffingSection(){
  const def = crewDefForOps();
  const lines = opsLines(G.company);
  if(!def) return null;
  const box = el(`<div class="card mt14"><h3>\u{1F465} Line Staffing</h3>
    <div class="muted mb8" style="font-size:12px;">Every ${def.noun} needs its own crew of ${def.label}s. A fully staffed ${def.noun} runs at about 115% of its rated output; an empty one limps along at 40% on borrowed HQ help. Crew members are real employees on your payroll and count against your headcount cap.</div>
    ${lines.length? lines.map(l=>{
      const req = lineReqCrew(l), have = lineCrew(l).length, need = Math.max(0, req-have);
      return `<div class="ladder-card"><div class="row"><div>
        <div class="title">${l.name} ${lineStaffLabel(l)}</div>
        <div class="desc">Needs ${req} ${def.label}(s) for full rate${have?` \u00b7 ${lineCrew(l).map(e=>e.name).join(", ")}`:" \u00b7 nobody assigned"}</div></div>
        <div class="flexrow">
          <button class="btn secondary small" data-crew="${l.id}:1">+1</button>
          <button class="btn secondary small" data-crew="${l.id}:5">+5</button>
          ${need>0?`<button class="btn small" data-crew="${l.id}:${need}">Staff fully (+${need})</button>`:`<span class="pill good">Fully staffed</span>`}
          ${have>0?`<button class="btn danger small" data-crewcut="${l.id}">Cut 1</button>`:""}
        </div></div></div>`;
    }).join("") : `<div class="muted">No ${def.noun}s open yet.</div>`}
  </div>`);
  box.querySelectorAll("[data-crew]").forEach(b=> b.onclick=()=>{
    const [id, n] = b.getAttribute("data-crew").split(":");
    const l = opsLines(G.company).find(x=>x.id===id); if(!l) return;
    const made = hireLineCrew(l, Number(n));
    if(made) renderScreen();
  });
  box.querySelectorAll("[data-crewcut]").forEach(b=> b.onclick=()=>{
    const id = b.getAttribute("data-crewcut");
    const l = opsLines(G.company).find(x=>x.id===id); if(!l) return;
    const crew = lineCrew(l); if(!crew.length) return;
    const victim = crew[crew.length-1];
    if(!confirm(`Let go of ${victim.name} from ${l.name}?`)) return;
    fireEmployee(victim.id);
    renderAll();
  });
  return box;
}
