const _v16RenderScreen = renderScreen;
renderScreen = function(){
  v16Migrate();
  const out = _v16RenderScreen.apply(this, arguments);
  try { v16InjectBulkHire(); } catch(e){}
  return out;
};


/* ================= v17: Feedback, Scale, Takeovers, Parallel R&D ================= */

/* ---------------- 1. Click feedback: toasts + press states ---------------- */
(function injectV17Css(){
  const css = document.createElement("style");
  css.textContent = `
  #v17Toasts{position:fixed;right:18px;bottom:18px;z-index:99999;display:flex;flex-direction:column;gap:8px;align-items:flex-end;pointer-events:none;}
  .v17-toast{background:var(--panel2,#1b1f27);border:1px solid var(--border,#2c3340);border-left:4px solid var(--good,#39d98a);
    color:var(--text,#e8ecf3);padding:10px 14px;border-radius:8px;font-size:13px;max-width:360px;box-shadow:0 8px 24px rgba(0,0,0,.35);
    animation:v17in .18s ease-out;}
  .v17-toast.bad{border-left-color:var(--bad,#ff6b6b);}
  .v17-toast.warn{border-left-color:var(--warn,#ffc86b);}
  .v17-toast b{color:#fff;}
  @keyframes v17in{from{opacity:0;transform:translateY(8px);}to{opacity:1;transform:none;}}
  button:not([disabled]):active{transform:translateY(1px) scale(.985);filter:brightness(.92);}
  .v17-flash{animation:v17flash .45s ease-out;}
  @keyframes v17flash{0%{box-shadow:0 0 0 0 rgba(57,217,138,.55);}100%{box-shadow:0 0 0 12px rgba(57,217,138,0);}}
  .v17-sel{outline:2px solid var(--good,#39d98a);outline-offset:1px;}
  .v17-role{font-size:11.5px;line-height:1.45;opacity:.85;margin-top:6px;}
  `;
  document.head.appendChild(css);
  const host = document.createElement("div");
  host.id = "v17Toasts";
  document.body.appendChild(host);
  document.addEventListener("click", (ev)=>{
    const b = ev.target && ev.target.closest && ev.target.closest("button");
    if(!b || b.disabled) return;
    b.classList.remove("v17-flash");
    void b.offsetWidth;
    b.classList.add("v17-flash");
    setTimeout(()=>b.classList.remove("v17-flash"), 480);
  }, true);
})();
function toast(msg, kind){
  const host = document.getElementById("v17Toasts");
  if(!host){ return; }
  const t = document.createElement("div");
  t.className = "v17-toast" + (kind? " "+kind : "");
  t.innerHTML = msg;
  host.appendChild(t);
  setTimeout(()=>{ t.style.transition="opacity .25s"; t.style.opacity="0"; setTimeout(()=>t.remove(), 300); }, 4200);
  while(host.children.length > 5) host.firstChild.remove();
}
function queuedSummary(){
  const n = G.ui.queue.reduce((s,q)=>s+(q.hireQty||1),0);
  return `${G.ui.queue.length} action(s) queued \u00b7 ${fmt$(G.ui.queue.reduce((s,q)=>s+(q.cost||0),0))} committed`;
}

/* ---------------- 2. Ladder gates removed, hires batch properly ---------------- */
function rungCapacity(){ return Infinity; }        // hire any level, any time
function rungRemaining(){ return Infinity; }
function hireGateAllows(){ return true; }
function queuedHireCount(){ return G.ui.queue.reduce((s,q)=> s + (q.hireDept ? (q.hireQty||1) : 0), 0); }
function v16HireCapacity(){
  return Math.max(0, headcountCap() - G.company.employees.length - queuedHireCount());
}
function v16QueueHires(deptKey, rungKey, want){
  const r = LADDERS[deptKey].rungs.find(x=>x.key===rungKey);
  const room = v16HireCapacity();
  const qty = Math.min(want, room);
  if(qty<=0){
    toast(`<b>No room to hire.</b> You are at ${G.company.employees.length}/${headcountCap()} headcount including queued hires. Buy more space in Facilities.`, "bad");
    return;
  }
  const salary = Math.round((r.salaryRange[0]+r.salaryRange[1])/2);
  // ONE queue item for the whole batch, so a 200-person hire is not 200 items
  queueAdd({ id:uid(), label:`Hire ${qty} \u00d7 ${r.label}`, hireDept:deptKey, hireRung:rungKey, hireQty:qty,
    payroll: salary*qty,
    run:(report)=>{
      let made = 0;
      for(let i=0;i<qty;i++){
        if(G.company.employees.length >= headcountCap()){ break; }
        hire(deptKey, rungKey); made++;
      }
      report.push(made===qty
        ? `Hired ${made} ${r.label}(s) \u2014 about ${fmt$(salary*made)}/mo added to payroll.`
        : `Hired ${made} of ${qty} ${r.label}(s) \u2014 ran out of headcount capacity at ${headcountCap()}.`);
    }});
  if(qty < want) toast(`<b>Queued ${qty} of ${want} ${r.label}s.</b> That is all the headcount capacity you have left.`, "warn");
  else toast(`<b>Queued ${qty} \u00d7 ${r.label}.</b> ~${fmt$(salary*qty)}/mo payroll. ${queuedSummary()}. They join when you advance the month.`);
  renderScreen();
}

