/* Bonus Center and Marketing: make the selected amount obvious */
function bonusCenterSection(){
  const emps = G.company.employees||[];
  const depts = Object.keys(LADDERS).filter(dk=> emps.some(e=>e.dept===dk));
  const box = el(`<div class="flatsec">
    <h3>\u{1F4B0} Bonus Center</h3>
    <div class="muted mb8" style="font-size:12px;">Pick a per-person amount, then choose who gets it. Everything is confirmed before it is queued, and the queue shows the total.</div>
    ${depts.length? `<div class="flexrow mb8" style="align-items:center;gap:8px;flex-wrap:wrap;">
      <span class="muted" style="font-size:12px;">Per person:</span>
      ${[500,1000,2500,5000,10000,25000].map(v=>`<button class="btn secondary small" data-bonus-amt="${v}">${fmt$(v)}</button>`).join("")}
      <input id="bonusCustom" placeholder="Custom $" style="background:var(--panel2);border:1px solid var(--border);color:var(--text);border-radius:6px;padding:7px 9px;width:110px;" />
    </div>
    <div class="mb8">Selected: <b id="bonusShown">${fmt$(1000)} each</b></div>
    <div class="flexrow" style="gap:6px;flex-wrap:wrap;">
      <button class="btn small" data-bonus-dept="__all">\u{1F389} Everyone (${emps.length})</button>
      ${depts.map(dk=>`<button class="btn secondary small" data-bonus-dept="${dk}">${LADDERS[dk].label} (${emps.filter(e=>e.dept===dk).length})</button>`).join("")}
    </div>`
    : `<div class="muted">Nobody on payroll yet.</div>`}
  </div>`);
  let amt = 1000;
  const shown = box.querySelector("#bonusShown");
  const btns = [...box.querySelectorAll("[data-bonus-amt]")];
  const sync = (activeBtn)=>{
    if(shown) shown.textContent = `${fmt$(amt)} each`;
    btns.forEach(b=>{ b.classList.remove("v17-sel"); b.classList.add("secondary"); });
    if(activeBtn){ activeBtn.classList.add("v17-sel"); activeBtn.classList.remove("secondary"); }
  };
  btns.forEach(b=> b.onclick=()=>{ amt = Number(b.getAttribute("data-bonus-amt")); sync(b); toast(`Bonus amount set to <b>${fmt$(amt)} per person</b>. Now pick who gets it.`); });
  const custom = box.querySelector("#bonusCustom");
  if(custom) custom.oninput = ()=>{ const v = Number((custom.value||"").replace(/[^0-9.]/g,"")); if(v>0){ amt = v; sync(null); } };
  box.querySelectorAll("[data-bonus-dept]").forEach(b=> b.onclick=()=>{
    const dk = b.getAttribute("data-bonus-dept");
    const targets = dk==="__all" ? emps.slice() : emps.filter(e=>e.dept===dk);
    if(!targets.length) return;
    const per = amt, total = per*targets.length;
    const who = dk==="__all" ? "the whole company" : LADDERS[dk].label;
    if(!confirm(`Pay ${fmt$(per)} each to ${targets.length} person(s) in ${who}?\n\nTotal: ${fmt$(total)}`)) return;
    if(!affordOrAlert(total, `bonuses for ${who}`)) return;
    queueAdd({ id:uid(), label:`Bonuses \u2014 ${who}: ${fmt$(per)} \u00d7 ${targets.length}`, cost:total, run:(report)=>{
      if(G.company.cash<total){ report.push(`Skipped ${who} bonuses \u2014 insufficient cash.`); return; }
      G.company.cash -= total;
      targets.forEach(t=>{
        const e = G.company.employees.find(x=>x.id===t.id); if(!e) return;
        e.morale = clamp(e.morale + clamp(6 + per/900, 4, 22), 0, 100);
        e.performance = clamp(e.performance + 2, 0, 100);
      });
      report.push(`Paid ${fmt$(per)} bonuses to ${targets.length} person(s) in ${who} \u2014 ${fmt$(total)} total.`);
    }});
    toast(`<b>Queued: ${fmt$(per)} \u00d7 ${targets.length} = ${fmt$(total)}</b> in bonuses for ${who}. ${queuedSummary()}.`);
    renderScreen();
  });
  sync(btns[1]);
  return box;
}

/* Owner pay: confirm every click, and never double-fire a bonus silently */
const _v17OwnerPaySection = ownerPaySection;
ownerPaySection = function(){
  const box = _v17OwnerPaySection.apply(this, arguments);
  try {
    box.querySelectorAll("[data-owner-step]").forEach(b=>{
      const prev = b.onclick;
      b.onclick = ()=>{ if(prev) prev(); toast(`Monthly draw is now <b>${fmt$(pInit().salaryDraw)}/mo</b>.`); };
    });
    box.querySelectorAll("[data-owner-bonus]").forEach(b=>{
      const amount = Number(b.getAttribute("data-owner-bonus"));
      b.onclick = ()=>{
        const queuedAlready = G.ui.queue.filter(q=>/Founder bonus/.test(q.label)).reduce((s,q)=>s+(q.cost||0),0);
        if(!confirm(`Pay yourself a ${fmt$(amount)} bonus from company cash?${queuedAlready?`\n\nYou already have ${fmt$(queuedAlready)} of founder bonuses queued this month.`:""}`)) return;
        if(!affordOrAlert(amount, "your bonus")) return;
        queueAdd({ id:uid(), label:`Founder bonus to self (${fmt$(amount)})`, cost:amount, run:(report)=>{
          if(G.company.cash<amount){ report.push("Skipped your founder bonus \u2014 insufficient company cash."); return; }
          G.company.cash -= amount; G.personal.cash += amount;
          G.personal.happiness = clamp(G.personal.happiness+6,0,100);
          report.push(`You paid yourself a ${fmt$(amount)} bonus.`);
        }});
        const totalNow = G.ui.queue.filter(q=>/Founder bonus/.test(q.label)).reduce((s,q)=>s+(q.cost||0),0);
        toast(`<b>${fmt$(amount)} bonus queued.</b> Founder bonuses queued this month: ${fmt$(totalNow)}. ${queuedSummary()}.`);
        renderScreen();
      };
    });
  } catch(e){}
  return box;
};

/* Queue panel: show totals and batch sizes clearly */
function renderQueuePanel(commitBtnId){
  const cap = headcountCap();
  const currentHeadcount = G.company.employees.length;
  const queuedHires = queuedHireCount();
  const roomLeft = Math.max(0, cap - currentHeadcount - queuedHires);
  const committed = G.ui.queue.reduce((s,q)=>s+(q.cost||0),0);
  const payroll = G.ui.queue.reduce((s,q)=>s+(q.payroll||0),0);
  const personalMoves = (G.personal.monthEvents||[]);
  return `<div class="card mt14"><h3>This Month's Plan (${G.ui.queue.length})</h3>
    <div class="muted mb8" style="font-size:11.5px;">Headcount: ${currentHeadcount} on team + ${queuedHires} queued / ${cap} cap \u00b7 ${roomLeft} seat(s) open
      ${committed?` \u00b7 <b>${fmt$(committed)}</b> of cash committed`:""}${payroll?` \u00b7 <b>${fmt$(payroll)}/mo</b> of new payroll`:""}.</div>
    <div id="queueList">${G.ui.queue.length? G.ui.queue.map(q=>{
      const icon = q.hireDept ? "\u{1F9D1}\u200D\u{1F4BC}" : /bonus/i.test(q.label) ? "\u{1F4B0}" : /takeover/i.test(q.label) ? "\u2694\uFE0F" : /retention|check-in|upsell/i.test(q.label) ? "\u{1F91D}" : /research/i.test(q.label) ? "\u{1F50D}" : /event|lunch|retreat/i.test(q.label) ? "\u{1F389}" : /facilit|campus|tower|annex|workspace|line/i.test(q.label) ? "\u{1F3E2}" : "\u{1F4CB}";
      return `<span class="qi">${icon} ${q.label}${q.cost?` <span class="muted">(${fmt$(q.cost)})</span>`:""} <span data-qremove="${q.id}" style="cursor:pointer;">&times;</span></span>`;
    }).join("") : `<span class="muted">Nothing queued \u2014 that's fine, some months you just execute.</span>`}</div>
    ${personalMoves.length? `<div class="mt8"><div class="muted" style="font-size:11.5px;">\u{1F3E1} Personal moves already made this month (settled instantly from your personal cash):</div>
      <div class="mt4">${personalMoves.map(e=>`<span class="qi">\u{1F3E1} ${e}</span>`).join("")}</div></div>` : ""}
    <div class="mt14"><button class="btn" id="${commitBtnId}" style="background:var(--good);color:#04241a;">\u2705 Advance Month</button></div>
  </div>`;
}

