const LEADERBOARD_FORM_URL = "https://www.notion.so/6926d539a040465d9f73ae3bfbdb7a01";

/* ---------------- 1. Click feedback on EVERYTHING clickable ---------------- */
(function v18ClickFeedback(){
  const css = document.createElement("style");
  css.textContent = `
  .v18-press{animation:v18press .3s ease-out;}
  @keyframes v18press{0%{transform:scale(.97);filter:brightness(.88);}100%{transform:none;filter:none;}}
  .v18-ring{animation:v18ring .5s ease-out;}
  @keyframes v18ring{0%{box-shadow:0 0 0 0 rgba(57,217,138,.5);}100%{box-shadow:0 0 0 10px rgba(57,217,138,0);}}
  #topbar .stat.big .value{font-size:18px;}
  #topbar #coSwitch{font-size:14px;font-weight:600;padding:7px 10px;max-width:280px;}
  .v18-perso{display:flex;gap:14px;align-items:center;padding:4px 16px;background:#14171d;border-bottom:1px solid var(--border);font-size:12px;overflow-x:auto;}
  .v18-perso b{color:var(--text);}
  .v18-banner{margin:10px 0;padding:10px 12px;border-radius:8px;border:1px solid var(--warn,#ffc86b);background:rgba(255,200,107,.08);font-size:12.5px;display:flex;gap:10px;align-items:center;justify-content:space-between;}
  `;
  document.head.appendChild(css);
  const CLICKY = "button,select,option,a,input[type=checkbox],input[type=radio],.radio-chip,.chip,.pill.clickable,.qi,.shop-card,.ladder-card,.dock-btn,.tab,.tabbtn,.stat.clickable,[data-tab],[data-group],[data-ops-open],[data-ops-price],[data-ops-quality],[data-toggledept],[data-qremove],[role=button],[onclick]";
  document.addEventListener("click", (ev)=>{
    let node = ev.target;
    let hit = null;
    while(node && node !== document.body){
      if(node.matches && node.matches(CLICKY)){ hit = node; break; }
      if(node.onclick){ hit = node; break; }
      node = node.parentElement;
    }
    if(!hit || hit.disabled) return;
    hit.classList.remove("v18-press","v18-ring");
    void hit.offsetWidth;
    hit.classList.add("v18-press","v18-ring");
    setTimeout(()=>hit.classList.remove("v18-press","v18-ring"), 520);
  }, true);
  document.addEventListener("change", (ev)=>{
    const t = ev.target;
    if(t && t.tagName==="SELECT"){ t.classList.add("v18-ring"); setTimeout(()=>t.classList.remove("v18-ring"), 520); }
  }, true);
})();

/* ---------------- 2. Industry-aware money language ---------------- */
function isFinanceCo(co){ return ((co||G.company).industry === "finance"); }
function financeOps(co){ const c = co||G.company; return (c.ops && c.ops.type==="finance") ? c.ops : null; }
function financeMonthly(co){
  const o = financeOps(co); if(!o) return null;
  const uw = (typeof UNDERWRITING!=="undefined" && UNDERWRITING.find(u=>u.key===o.underwriting)) || { rate:0.009, defaults:0.012, label:"Balanced" };
  const interest = Math.round(o.loanBook * uw.rate);
  const depositCost = Math.round(o.deposits * 0.0016);
  const premiums = o.insuranceBook>0 ? Math.round(o.insuranceBook*0.022) : 0;
  const claims = o.insuranceBook>0 ? Math.round(o.insuranceBook*0.014) : 0;
  const expectedCharge = Math.round(o.loanBook * uw.defaults);
  return { uw, interest, depositCost, premiums, claims, expectedCharge,
    net: interest + premiums - depositCost - claims - expectedCharge,
    capacity: Math.round(o.deposits*0.85) };
}

/* ---------------- 3. Topbar: switcher first, industry KPIs, personal line ---------------- */
function personalSnapshot(){
  const p = pInit();
  const rentals = (p.assets.houses||[]).filter(h=>h.rented).reduce((s,h)=>s+Math.round(h.price*0.006),0);
  const income = (p.salaryDraw||0) + rentals + (p.investIncome||0);
  const expenses = Object.values(p.expenses||{}).reduce((a,b)=>a+(b||0),0);
  return { income, expenses, rentals, net: income-expenses, worth: p.netWorth||0, cash: p.cash||0 };
}
function renderTopbar(){
  recomputeMRR();
  const c = G.company;
  const expenses = Object.values(c.expensesBreakdown).reduce((a,b)=>a+b,0);
  const bar = document.createElement("div");
  bar.id = "topbar";
  const debtTotal = c.debt.loanBalance + c.debt.locBalance;
  const cfg = industry();
  const fin = financeMonthly(c);
  const opsRev = c.businessLines.reduce((s,l)=>s+l.monthlyRevenue,0);
  const switcher = G.companies.length>1
    ? `<select id="coSwitch">${G.companies.map((co,i)=>`<option value="${i}" ${i===G.activeCompanyIndex?"selected":""}>${industryOf(co).icon} ${co.name}${co.passive?" (passive)":""}</option>`).join("")}</select>`
    : `<div class="stat big"><div class="label">Company</div><div class="value">${cfg.icon} ${c.name}</div></div>`;
  const coreStats = fin
    ? `<div class="stat" title="Customer deposits fund your loan book. You can lend up to 85% of deposits."><div class="label">Deposits \u24D8</div><div class="value">${fmt$(fin ? financeOps(c).deposits : 0)}</div></div>
       <div class="stat" title="Outstanding loans earning ${(fin.uw.rate*100).toFixed(2)}%/mo interest. Lending capacity ${fmt$(fin.capacity)}."><div class="label">Loan Book \u24D8</div><div class="value good">${fmt$(financeOps(c).loanBook)}</div></div>
       ${financeOps(c).insuranceBook>0? `<div class="stat" title="Premiums earned monthly, before claims."><div class="label">Premiums/mo</div><div class="value good">${fmt$(fin.premiums)}</div></div>
       <div class="stat" title="Expected claims each month. Actual claims are volatile."><div class="label">Claims/mo \u24D8</div><div class="value bad">${fmt$(fin.claims)}</div></div>`:""}
       <div class="stat" title="Interest + premiums minus deposit cost, expected charge-offs and claims."><div class="label">Net Interest/mo \u24D8</div><div class="value ${fin.net<0?"bad":"good"}">${fmt$(fin.net)}</div></div>`
    : `<div class="stat"><div class="label">${opsBasedIndustry()? "Contract Rev" : "MRR"}</div><div class="value good">${fmt$(c.mrr)}</div></div>
       <div class="stat" title="Recurring revenue plus operations and business-line revenue."><div class="label">Revenue/mo \u24D8</div><div class="value good">${fmt$(c.mrr + opsRev)}</div></div>`;
  bar.innerHTML = `
    ${switcher}
    <div class="stat big"><div class="label">Cash</div><div class="value ${c.cash<0?"bad":""}">${fmt$(c.cash)}</div></div>
    ${coreStats}
    <div class="stat" title="Recurring costs as of your last month close."><div class="label">Expenses/mo \u24D8</div><div class="value bad">${fmt$(expenses)}</div></div>
    <div class="stat"><div class="label">Net Worth</div><div class="value ${c.netWorth<0?"bad":""}">${fmt$(c.netWorth)}</div></div>
    <div class="stat" title="Your ownership after equity grants and any secondary sales."><div class="label">Your Stake \u24D8</div><div class="value">${(founderPct(c)*100).toFixed(1)}%</div></div>
    <div class="stat clickable" id="hcStat" style="cursor:pointer;" title="Click to open Facilities and add seats."><div class="label">Employees \u24D8</div><div class="value ${c.employees.length>=headcountCap()?"bad":""}">${c.employees.length}/${headcountCap()}</div></div>
    <div class="stat" title="Weighted score: morale, client health, profit, growth, minus distress."><div class="label">Success \u24D8</div><div class="value ${c.successScore>=60?"good":c.successScore<35?"bad":""}">${c.successScore}</div></div>
    ${debtTotal>0? `<div class="stat"><div class="label">Debt</div><div class="value bad">${fmt$(debtTotal)}</div></div>`:""}
    <div class="grow"></div>
    <div class="datebox">${G.meta.playerName} \u00b7 Year ${c.year} \u00b7 Month ${c.month}<br>${GAME_VERSION}</div>
    <button class="btn" id="advanceBtn">Advance Month \u25B6</button>
  `;
  const app = document.getElementById("app");
  const existing = app.querySelector("#topbar");
  if(existing) existing.remove();
  const oldP = app.querySelector("#v18Personal");
  if(oldP) oldP.remove();
  app.prepend(bar);
  // personal line under the topbar
  const ps = personalSnapshot();
  const prow = document.createElement("div");
  prow.id = "v18Personal";
  prow.className = "v18-perso";
  prow.innerHTML = `<span>\u{1F3E1} <span class="muted">Personal</span></span>
    <span class="muted">Cash</span> <b>${fmt$(ps.cash)}</b>
    <span class="muted">Income/mo</span> <b class="good">${fmt$(ps.income)}</b>${ps.rentals? ` <span class="muted">(incl. ${fmt$(ps.rentals)} rent)</span>`:""}
    <span class="muted">Expenses/mo</span> <b class="bad">${fmt$(ps.expenses)}</b>
    <span class="muted">Net/mo</span> <b class="${ps.net<0?"bad":"good"}">${fmt$(ps.net)}</b>
    <span class="muted">Net worth</span> <b>${fmt$(ps.worth)}</b>
    <span class="grow" style="flex:1;"></span>
    <button class="btn secondary small" id="v18Infuse">\u{1F4B5} Invest personal cash into company</button>`;
  bar.insertAdjacentElement("afterend", prow);
  bar.querySelector("#advanceBtn").onclick = ()=>{ confirmAndAdvance(); };
  const sw = bar.querySelector("#coSwitch");
  if(sw) sw.onchange = ()=>{ switchCompany(Number(sw.value)); };
  const hc = bar.querySelector("#hcStat");
  if(hc) hc.onclick = ()=>{ G.ui.activeTab = "hr"; renderAll(); toast("Facilities & Campus is at the bottom of HR & Hiring \u2014 that is where you add seats."); };
  const inf = prow.querySelector("#v18Infuse");
  if(inf) inf.onclick = ()=> v18Infuse();
}
function v18Infuse(){
  const p = pInit();
  const raw = window.prompt(`Invest personal cash into ${G.company.name}.\n\nPersonal cash available: ${fmt$(p.cash)}\nCompany cash: ${fmt$(G.company.cash)}\n\nHow much do you want to put in?`, "25000");
  if(raw===null) return;
  const amt = Math.round(Number(String(raw).replace(/[^0-9.]/g,"")));
  if(!amt || amt<=0) return;
  if(amt > p.cash){ toast(`<b>Not enough personal cash.</b> You have ${fmt$(p.cash)}.`, "bad"); return; }
  p.cash -= amt;
  G.company.cash += amt;
  p.monthEvents.push(`Invested ${fmt$(amt)} of personal cash into ${G.company.name}`);
  logHistory(`Founder injected ${fmt$(amt)} of personal capital.`);
  toast(`<b>${fmt$(amt)} injected.</b> Company cash is now ${fmt$(G.company.cash)}; your personal cash is ${fmt$(p.cash)}.`);
  renderAll();
}

