function founderActionsForIndustry(){
  return FOUNDER_ACTIONS_BY_INDUSTRY[G.company.industry] || FOUNDER_ACTIONS;
}
function renderFounderBucket(){
  const c = G.company;
  const used = c.founderActionsUsed||0;
  const left = Math.max(0, FOUNDER_ACTION_CAP - used);
  const acts = founderActionsForIndustry();
  const cfg = industry();
  return `<div class="card mb14" style="border:1px solid var(--good);">
    <h3>\u{1F680} Founder Hustle \u2014 ${cfg.icon} ${cfg.label} <span class="muted" style="font-size:12px;font-weight:400;">\u2014 ${left}/${FOUNDER_ACTION_CAP} left this month</span></h3>
    <div class="muted mb8" style="font-size:12.5px;">These are the things a founder in <b>${cfg.label}</b> can personally do with no staff and no budget. They change with the business you're running.</div>
    <div class="flexrow">${acts.map(a=>`<button class="btn secondary small" data-founder="${a.key}" ${left<=0?'disabled':''} title="${a.desc}">${a.label}</button>`).join("")}</div>
    ${G.ui.founderMsg? `<div class="mt8" style="font-size:12.5px;color:var(--good);">${G.ui.founderMsg}</div>` : ""}
  </div>`;
}
const _v18RunFounderAction = runFounderAction;
runFounderAction = function(key){
  const c = G.company;
  if(String(key).indexOf("v18_")!==0) {
    const out = _v18RunFounderAction.apply(this, arguments);
    if(G.ui.founderMsg) toast(G.ui.founderMsg);
    return out;
  }
  if((c.founderActionsUsed||0) >= FOUNDER_ACTION_CAP) return;
  c.founderActionsUsed = (c.founderActionsUsed||0) + 1;
  c.founderActionsLifetime = (c.founderActionsLifetime||0) + 1;
  const o = c.ops || {};
  let msg = "";
  if(key==="v18_demo"){
    const hits = (Math.random()<0.5?1:0) + (Math.random()<0.35?1:0);
    for(let i=0;i<hits;i++){
      const mrrVal = rand(180,520);
      c.clients.push({ id:uid(), name:pick(["Halcyon Data","Brightline Ops","Northwind Analytics","Pulse Retail"]), mrr:mrrVal, health:rand(65,88), sinceMonth:c.month, sinceYear:c.year });
    }
    recomputeMRR();
    msg = hits? `Demo day landed ${hits} new client(s).` : "Good crowd at the demo, no signatures yet.";
  } else if(key==="v18_sidewalk"){
    const gain = rand(2000,6500); c.cash += gain; msg = `You worked the floor all week \u2014 ${fmt$(gain)} in extra sales.`;
  } else if(key==="v18_supplier"){
    (o.stores||[]).forEach(s=>{ if(s.unitCost) s.unitCost = Math.round(s.unitCost*0.93); });
    c.expensesBreakdown.other = Math.round((c.expensesBreakdown.other||0)*0.94);
    msg = "Supplier blinked \u2014 unit costs down about 7%.";
  } else if(key==="v18_popup"){
    const gain = rand(1200,4200); c.cash += gain; msg = `Pop-up weekend brought in ${fmt$(gain)}.`;
  } else if(key==="v18_kitchen"){
    const save = rand(1500,4500); c.cash += save; c.successScore = clamp(c.successScore+1,0,100);
    msg = `You covered shifts yourself \u2014 ${fmt$(save)} of labor saved and the crew noticed.`;
  } else if(key==="v18_tasting"){
    (o.locations||[]).forEach(l=>{ if(l.demand!==undefined) l.demand = Math.min(1.6, (l.demand||1)+0.08); });
    msg = "Tasting night packed the room \u2014 demand is up at every location.";
  } else if(key==="v18_critic"){
    if(Math.random()<0.55){ c.successScore = clamp(c.successScore+8,0,100); (o.locations||[]).forEach(l=>{ if(l.demand!==undefined) l.demand = Math.min(1.8,(l.demand||1)+0.15); });
      msg = "The review was glowing. Reputation and demand jumped."; }
    else { c.successScore = clamp(c.successScore-5,0,100); msg = "The critic was not kind. Reputation took a hit \u2014 fix the weak location."; }
  } else if(key==="v18_catering"){
    const gain = rand(2500,9000); c.cash += gain; msg = `Catering job paid ${fmt$(gain)}.`;
  } else if(key==="v18_prototype"){
    (o.lines||[]).forEach(l=>{ if(l.throughput) l.throughput = Math.round(l.throughput*1.06); });
    msg = "You fixed the jig yourself \u2014 throughput up about 6% on every line.";
  } else if(key==="v18_pilot"){
    if(Math.random()<0.5){ const val = rand(15000,45000); c.cash += val; c.successScore = clamp(c.successScore+3,0,100);
      msg = `Pilot install signed \u2014 ${fmt$(val)} up front and a reference customer.`; }
    else msg = "The plant manager liked it but wants to see the safety cert first.";
  } else if(key==="v18_grant"){
    if(Math.random()<0.4){ const val = rand(40000,120000); c.cash += val; msg = `R&D grant approved \u2014 ${fmt$(val)} of non-dilutive cash.`; }
    else msg = "Grant application submitted. No decision yet.";
  } else if(key==="v18_tradeshow"){
    const gain = rand(0,2)===0? 0 : rand(8000,30000); if(gain){ c.cash += gain; }
    c.successScore = clamp(c.successScore+2,0,100);
    msg = gain? `Trade show generated ${fmt$(gain)} of orders.` : "Trade show filled the pipeline but no orders closed yet.";
  } else if(key==="v18_bigdep"){
    if(o.deposits!==undefined){ const add = rand(250000,900000); o.deposits += add; msg = `Landed a commercial depositor \u2014 ${fmt$(add)} of new deposits, which raises your lending capacity to ${fmt$(Math.round(o.deposits*0.85))}.`; }
    else msg = "No deposit book to grow yet.";
  } else if(key==="v18_loanpitch"){
    if(o.loanBook!==undefined){
      const cap = Math.round(o.deposits*0.85) - o.loanBook;
      const amt = Math.max(0, Math.min(cap, rand(80000,260000)));
      if(amt>0){ o.loanBook += amt; msg = `You underwrote a ${fmt$(amt)} loan personally \u2014 clean file, full spread.`; }
      else msg = "You're already lent out to the 85% deposit limit. Gather deposits first.";
    } else msg = "No loan book yet.";
  } else if(key==="v18_reinsure"){
    if(o.insuranceBook>0){ o.reinsured = true; msg = "Reinsurance in place \u2014 claims volatility is capped from here on."; }
    else msg = "Launch an insurance line first and then reinsurance is worth buying.";
  } else if(key==="v18_regulator"){
    c.successScore = clamp(c.successScore+3,0,100);
    msg = "The examiner left happy. Fewer nasty surprises at the next exam.";
  }
  G.ui.founderMsg = msg;
  if(msg) toast(msg);
  recomputeMRR();
  renderAll();
};

/* ---------------- 5. Finance: how the money actually works + safety valve ---------------- */
function financeExplainerCard(){
  const fin = financeMonthly();
  if(!fin) return null;
  const o = financeOps();
  const p = pInit();
  const box = el(`<div class="card mt14"><h3>\u{1F9EE} How This Bank Makes Money</h3>
    <div class="muted" style="font-size:12.5px;line-height:1.55;">
      There is no MRR in banking. Your monthly income is:<br>
      <b>Loan interest</b> (${fmt$(o.loanBook)} book \u00d7 ${(fin.uw.rate*100).toFixed(2)}%/mo = <b class="good">${fmt$(fin.interest)}</b>)
      ${o.insuranceBook>0? `<br>+ <b>Premiums</b> (${fmt$(o.insuranceBook)} in force \u00d7 2.2%/mo = <b class="good">${fmt$(fin.premiums)}</b>)`:""}
      <br>\u2212 <b>Cost of deposits</b> (${fmt$(o.deposits)} \u00d7 0.16%/mo = <b class="bad">${fmt$(fin.depositCost)}</b>)
      <br>\u2212 <b>Expected charge-offs</b> (${(fin.uw.defaults*100).toFixed(1)}% of the book = <b class="bad">${fmt$(fin.expectedCharge)}</b>, volatile)
      ${o.insuranceBook>0? `<br>\u2212 <b>Claims</b> (about <b class="bad">${fmt$(fin.claims)}</b>/mo, very volatile)`:""}
      <br>= <b class="${fin.net<0?"bad":"good"}">${fmt$(fin.net)}</b> before payroll and overhead.
    </div>
    <div class="mt8" style="font-size:12.5px;">
      <b>Two traps to know.</b> A deposit campaign costs cash today and only pays off once loan officers turn those deposits into loans \u2014 deposits alone are a liability, not income. And you can only lend up to <b>85% of deposits</b> (${fmt$(fin.capacity)} right now), so campaigns are what unlock growth later, not this month.
    </div>
    ${G.company.cash < 0 || fin.net + G.company.cash < 0 ? `<div class="v18-banner mt8"><span>\u26A0\uFE0F Cash is tight. You can put personal money in (${fmt$(p.cash)} available), draw on the line of credit in the Bank tab, or pause campaigns for a month while interest accrues.</span><button class="btn small" data-v18infuse="1">Invest personal cash</button></div>`:""}
  </div>`);
  box.querySelectorAll("[data-v18infuse]").forEach(b=> b.onclick=()=> v18Infuse());
  return box;
}

