function facilitiesBanner(){
  const c = G.company;
  const cap = headcountCap();
  const used = c.employees.length;
  if(used < cap*0.8) return null;
  const box = el(`<div class="v18-banner"><span>\u{1F3D7}\uFE0F You're at <b>${used}/${cap}</b> seats. Build more space to keep hiring \u2014 Annex (+150), Campus (+900), Tower (+3,000), Global Network (+9,000).</span>
    <button class="btn small" data-v18fac="1">Open Facilities</button></div>`);
  box.querySelectorAll("[data-v18fac]").forEach(b=> b.onclick=()=>{ G.ui.activeTab="hr"; renderAll();
    setTimeout(()=>{ const t = [...document.querySelectorAll("h3")].find(h=>h.textContent.indexOf("Facilities")>=0); if(t) t.scrollIntoView({behavior:"smooth", block:"center"}); }, 60);
  });
  return box;
}

/* ---------------- 7. Leaderboard ---------------- */
function v18RunCode(){
  const c = G.company, p = pInit();
  const payload = {
    v: 18,
    player: G.meta.playerName || "Anonymous",
    company: c.name,
    industry: industry().label,
    months: (c.year-1)*12 + c.month,
    networth: Math.round((c.netWorth||0) + (p.netWorth||0)),
    company_value: Math.round(c.valuation||0),
    personal_networth: Math.round(p.netWorth||0),
    revenue: Math.round(c.mrr + c.businessLines.reduce((s,l)=>s+l.monthlyRevenue,0)),
    employees: c.employees.length,
    clients: c.clients.length,
    success: c.successScore,
    companies: G.companies.length,
    stamp: Date.now()
  };
  const json = JSON.stringify(payload);
  const b64 = btoa(unescape(encodeURIComponent(json))).replace(/=+$/,"");
  let sum = 0; for(let i=0;i<b64.length;i++) sum = (sum + b64.charCodeAt(i)*(i+1)) % 9973;
  return `BES1-${b64}-${sum.toString(36).toUpperCase()}`;
}
function renderLeaderboard(){
  const c = G.company, p = pInit();
  const code = v18RunCode();
  const total = Math.round((c.netWorth||0) + (p.netWorth||0));
  const wrap = el(`<div>
    <div class="window-title"><h2>\u{1F3C6} Leaderboard</h2><span class="sub">Submit your empire and see where you land</span></div>
    <div class="card mb14">
      <h3>Your Run Right Now</h3>
      <div class="grid3">
        <div class="card"><h3>Total Net Worth</h3><div class="big good">${fmt$(total)}</div><div class="muted" style="font-size:11px;">Company ${fmt$(c.netWorth||0)} + personal ${fmt$(p.netWorth||0)}</div></div>
        <div class="card"><h3>Revenue/mo</h3><div class="big">${fmt$(c.mrr + c.businessLines.reduce((s,l)=>s+l.monthlyRevenue,0))}</div></div>
        <div class="card"><h3>Months Played</h3><div class="big">${(c.year-1)*12 + c.month}</div></div>
      </div>
      <div class="muted mt8" style="font-size:12px;">Ranked by <b>total net worth</b>. Your name, company, industry, revenue, headcount, months played and success score all travel inside the code \u2014 nothing else leaves your browser.</div>
      <div class="flexrow mt8" style="gap:8px;flex-wrap:wrap;">
        <button class="btn" id="v18Submit">\u{1F3C6} Submit current game to leaderboard</button>
        <button class="btn secondary small" id="v18Copy">\u{1F4CB} Copy run code only</button>
        <a class="btn secondary small" href="${LEADERBOARD_FORM_URL}" target="_blank" rel="noopener" style="text-decoration:none;">\u{1F517} Open submission form</a>
      </div>
      <div class="mt8"><textarea id="v18Code" readonly style="width:100%;height:96px;background:var(--panel2);border:1px solid var(--border);color:var(--muted);border-radius:8px;padding:8px;font-family:monospace;font-size:11px;">${code}</textarea></div>
      <div class="muted mt8" style="font-size:11.5px;">1. Hit submit \u2014 the code is copied and the Notion form opens. 2. Paste into the single box. 3. Submit. Felipe refreshes the board and the top 10 by net worth get posted.</div>
    </div>
  </div>`);
  const copy = async ()=>{
    const ta = wrap.querySelector("#v18Code");
    try { await navigator.clipboard.writeText(ta.value); }
    catch(e){ ta.select(); try{ document.execCommand("copy"); }catch(e2){} }
  };
  wrap.querySelector("#v18Copy").onclick = async ()=>{ await copy(); toast("<b>Run code copied.</b> Paste it into the leaderboard form."); };
  wrap.querySelector("#v18Submit").onclick = async ()=>{
    await copy();
    toast("<b>Run code copied \u2014 opening the form.</b> Paste into the one box and submit.");
    window.open(LEADERBOARD_FORM_URL, "_blank", "noopener");
  };
  return wrap;
}
