/* ---------------- Screen wiring ---------------- */
const _v18RenderScreen = renderScreen;
renderScreen = function(){
  if(G.ui.activeTab === "leaderboard"){
    const host = document.getElementById("screen");
    if(host){
      host.innerHTML = "";
      host.appendChild(renderLeaderboard());
      return;
    }
  }
  const out = _v18RenderScreen.apply(this, arguments);
  try {
    const host = document.getElementById("screen");
    if(host){
      const tab = G.ui.activeTab;
      if(tab==="hr" || tab==="team" || tab==="orgchart"){
        const banner = facilitiesBanner();
        if(banner) host.prepend(banner);
      }
      if(tab==="industry" || tab==="financials" || tab==="bank"){
        const fin = financeExplainerCard();
        if(fin) host.appendChild(fin);
      }
    }
  } catch(e){}
  return out;
};


