/* ---------------- 1. Topbar: slim switcher, no MRR tile, corporate strip ---------------- */
function corporateSnapshot(){
  const c = G.company;
  const expenses = Object.values(c.expensesBreakdown).reduce((a,b)=>a+b,0);
  const opsRev = c.businessLines.reduce((s,l)=>s+l.monthlyRevenue,0);
  return { revenue: c.mrr + opsRev, expenses, net: (c.mrr+opsRev) - expenses, worth: c.netWorth||0, cash: c.cash||0 };
}
function renderTopbar(){
  recomputeMRR();
  const c = G.company;
  const cfg = industry();
  const fin = financeMonthly(c);
  const cs = corporateSnapshot();
  const debtTotal = c.debt.loanBalance + c.debt.locBalance;
  const switcher = G.companies.length>1
    ? `<select id="coSwitch" title="Switch company">${G.companies.map((co,i)=>`<option value="${i}" ${i===G.activeCompanyIndex?"selected":""}>${industryOf(co).icon} ${co.name}${co.passive?" (passive)":""}</option>`).join("")}</select>`
    : `<div class="stat"><div class="label">Company</div><div class="value">${cfg.icon} ${c.name}</div></div>`;
  const bar = document.createElement("div");
  bar.id = "topbar";
  bar.innerHTML = `
    ${switcher}
    <div class="stat"><div class="label">Cash</div><div class="value ${c.cash<0?"bad":""}">${fmt$(c.cash)}</div></div>
    <div class="stat" title="Recurring revenue plus operations and business-line revenue."><div class="label">Revenue/mo \u24D8</div><div class="value good">${fmt$(cs.revenue)}</div></div>
    <div class="stat" title="Recurring costs as of your last month close."><div class="label">Expenses/mo \u24D8</div><div class="value bad">${fmt$(cs.expenses)}</div></div>
    <div class="stat"><div class="label">Net Worth</div><div class="value ${c.netWorth<0?"bad":""}">${fmt$(c.netWorth)}</div></div>
    <div class="stat clickable" id="hcStat" style="cursor:pointer;" title="Click to open Facilities and add seats."><div class="label">Employees \u24D8</div><div class="value ${c.employees.length>=headcountCap()?"bad":""}">${c.employees.length}/${headcountCap()}</div></div>
    <div class="stat" title="Weighted score: morale, client health, profit, growth, minus distress."><div class="label">Success \u24D8</div><div class="value ${c.successScore>=60?"good":c.successScore<35?"bad":""}">${c.successScore}</div></div>
    <div class="grow"></div>
    <div class="datebox">${G.meta.playerName} \u00b7 Year ${c.year} \u00b7 Month ${c.month}<br>${GAME_VERSION}</div>
    <button class="btn" id="advanceBtn">Advance Month \u25B6</button>
  `;
  const app = document.getElementById("app");
  ["#topbar","#v19Corp","#v18Personal"].forEach(sel=>{ const n = app.querySelector(sel); if(n) n.remove(); });
  app.prepend(bar);

  // corporate strip (same delicate size as the personal strip)
  const corp = document.createElement("div");
  corp.id = "v19Corp";
  corp.className = "v19-strip";
  const kpi = fin
    ? `<span class="muted">Deposits</span> <b>${fmt$(financeOps(c).deposits)}</b>
       <span class="muted">Loan book</span> <b class="good">${fmt$(financeOps(c).loanBook)}</b>
       ${financeOps(c).insuranceBook>0? `<span class="muted">Premiums/mo</span> <b class="good">${fmt$(fin.premiums)}</b> <span class="muted">Claims/mo</span> <b class="bad">${fmt$(fin.claims)}</b>`:""}
       <span class="muted">Net interest/mo</span> <b class="${fin.net<0?"bad":"good"}">${fmt$(fin.net)}</b>`
    : `<span class="muted">${opsBasedIndustry()? "Contract rev" : "Recurring rev"}</span> <b class="good">${fmt$(c.mrr)}</b>
       ${c.clients.length? `<span class="muted">Clients</span> <b>${c.clients.length}</b>`:""}`;
  corp.innerHTML = `<span>${cfg.icon} <span class="muted">Company</span></span>
    <span class="muted">Cash</span> <b class="${c.cash<0?"bad":""}">${fmt$(c.cash)}</b>
    <span class="muted">Revenue/mo</span> <b class="good">${fmt$(cs.revenue)}</b>
    <span class="muted">Expenses/mo</span> <b class="bad">${fmt$(cs.expenses)}</b>
    <span class="muted">Net/mo</span> <b class="${cs.net<0?"bad":"good"}">${fmt$(cs.net)}</b>
    <span class="muted">Net worth</span> <b>${fmt$(cs.worth)}</b>
    <span class="muted">Your stake</span> <b>${(founderPct(c)*100).toFixed(1)}%</b>
    ${debtTotal>0? `<span class="muted">Debt</span> <b class="bad">${fmt$(debtTotal)}</b>`:""}
    <span class="sep">|</span> ${kpi}`;
  bar.insertAdjacentElement("afterend", corp);

  const ps = personalSnapshot();
  const prow = document.createElement("div");
  prow.id = "v18Personal";
  prow.className = "v18-perso";
  prow.innerHTML = `<span>\u{1F3E1} <span class="muted">Personal</span></span>
    <span class="muted">Cash</span> <b>${fmt$(ps.cash)}</b>
    <span class="muted">Income/mo</span> <b class="good">${fmt$(ps.income)}</b>${ps.rentals? ` <span class="muted">(incl. ${fmt$(ps.rentals)} rent)</span>`:""}
    <span class="muted">Expenses/mo</span> <b class="bad">${fmt$(ps.expenses)}</b>
    <span class="muted">Net/mo</span> <b class="${ps.net<0?"bad":"good"}">${fmt$(ps.net)}</b>
    <span class="muted">Net worth</span> <b>${fmt$(ps.worth)}</b>
    <span class="grow" style="flex:1;"></span>
    <button class="btn secondary small" id="v18Infuse">\u{1F4B5} Invest personal cash into company</button>`;
  corp.insertAdjacentElement("afterend", prow);

  bar.querySelector("#advanceBtn").onclick = ()=>{ confirmAndAdvance(); };
  const sw = bar.querySelector("#coSwitch");
  if(sw) sw.onchange = ()=>{ switchCompany(Number(sw.value)); };
  const hc = bar.querySelector("#hcStat");
  if(hc) hc.onclick = ()=>{ G.ui.activeTab = "facilities"; renderAll(); };
  const inf = prow.querySelector("#v18Infuse");
  if(inf) inf.onclick = ()=> v18Infuse();
}

/* ---------------- 2. Prettier "This Month's Plan" ---------------- */
function v19QueueIcon(q){
  const l = q.label || "";
  if(q.hireDept) return "\u{1F9D1}\u200D\u{1F4BC}";
  if(/bonus|raise|pay/i.test(l)) return "\u{1F4B0}";
  if(/takeover|acquis/i.test(l)) return "\u2694\uFE0F";
  if(/retention|check-in|upsell|client/i.test(l)) return "\u{1F91D}";
  if(/research|study|survey/i.test(l)) return "\u{1F50D}";
  if(/event|lunch|retreat|party/i.test(l)) return "\u{1F389}";
  if(/facilit|campus|tower|annex|workspace|office/i.test(l)) return "\u{1F3E2}";
  if(/market|ad |ads|campaign/i.test(l)) return "\u{1F4E3}";
  if(/feature|build|ship|product/i.test(l)) return "\u{1F4E6}";
  if(/loan|credit|deposit|insur/i.test(l)) return "\u{1F3E6}";
  if(/store|location|line|kiosk|truck/i.test(l)) return "\u{1F6CD}\uFE0F";
  return "\u{1F4CB}";
}
function v19PrettyLabel(q){
  let l = String(q.label || "").trim();
  l = l.replace(/^item added:?\s*/i, "").replace(/^added:?\s*/i, "");
  if(q.hireQty && q.hireQty > 1 && !/\u00d7|x\s*\d/i.test(l)) l = `${l} \u00d7 ${q.hireQty}`;
  return l.charAt(0).toUpperCase() + l.slice(1);
}
function renderQueuePanel(commitBtnId){
  const cap = headcountCap();
  const currentHeadcount = G.company.employees.length;
  const queuedHires = queuedHireCount();
  const roomLeft = Math.max(0, cap - currentHeadcount - queuedHires);
  const committed = G.ui.queue.reduce((s,q)=>s+(q.cost||0),0);
  const payroll = G.ui.queue.reduce((s,q)=>s+(q.payroll||0),0);
  const personalMoves = (G.personal.monthEvents||[]);
  const rows = G.ui.queue.map(q=>`<div class="v19-qrow">
      <span class="qicon">${v19QueueIcon(q)}</span>
      <span class="qtext">${v19PrettyLabel(q)}</span>
      ${q.cost? `<span class="qcost">${fmt$(q.cost)}</span>`:""}
      ${q.payroll? `<span class="qcost">+${fmt$(q.payroll)}/mo</span>`:""}
      <span class="qx" data-qremove="${q.id}" title="Remove">\u00d7</span>
    </div>`).join("");
  const perRows = personalMoves.map(e=>`<div class="v19-qrow" style="border-style:dashed;">
      <span class="qicon">\u{1F3E1}</span><span class="qtext">${e}</span><span class="qcost">settled</span>
    </div>`).join("");
  return `<div class="card mt14"><h3>\u{1F5D3}\uFE0F This Month's Plan <span class="muted" style="font-weight:400;font-size:12px;">\u2014 ${G.ui.queue.length} item${G.ui.queue.length===1?"":"s"} queued</span></h3>
    <div class="muted mb8" style="font-size:11.5px;">${currentHeadcount} on team + ${queuedHires} queued / ${cap} seats \u00b7 ${roomLeft} open${committed?` \u00b7 <b>${fmt$(committed)}</b> cash committed`:""}${payroll?` \u00b7 <b>${fmt$(payroll)}/mo</b> new payroll`:""}</div>
    <div id="queueList" class="v19-qgrid">${rows || `<span class="muted">Nothing queued \u2014 that's fine, some months you just execute.</span>`}</div>
    ${perRows? `<div class="mt8"><div class="muted mb4" style="font-size:11.5px;">\u{1F3E1} Personal moves already settled this month</div><div class="v19-qgrid">${perRows}</div></div>`:""}
    <div class="mt14"><button class="btn" id="${commitBtnId}" style="background:var(--good);color:#04241a;">\u2705 Advance Month</button></div>
  </div>`;
}

