(function v19MoveTabs(){
  const people = DOCK_GROUPS.find(g=>g.id==="people");
  if(people && people.items.indexOf("facilities")<0) people.items.push("facilities");
  DOCK_GROUPS.forEach(g=>{ const i = g.items.indexOf("leaderboard"); if(i>=0) g.items.splice(i,1); });
  const sys = DOCK_GROUPS.find(g=>g.id==="system");
  if(sys && sys.items.indexOf("leaderboard")<0) sys.items.unshift("leaderboard");
})();

