/* ---- 1. Header: company cash, revenue, expenses, profit ---- */
renderTopbar = function(){
  recomputeMRR();
  const c = G.company, cfg = industry(), cap = headcountCap();
  const cs = (typeof corporateSnapshot==="function") ? corporateSnapshot() : { revenue:c.mrr||0, expenses:0, net:0 };
  const switcher = G.companies.length>1
    ? `<select id="coSwitch" title="Switch company">${G.companies.map((co,i)=>`<option value="${i}" ${i===G.activeCompanyIndex?"selected":""}>${industryOf(co).icon} ${co.name}${co.passive?" (passive)":""}</option>`).join("")}</select>`
    : `<span>${cfg.icon} <b>${c.name}</b></span>`;
  const bar = document.createElement("div");
  bar.id = "topbar";
  bar.innerHTML = `
    ${switcher}
    <span class="v19-lbl">Cash</span> <b class="${c.cash<0?"bad":""}">${fmt$(c.cash)}</b>
    <span class="v19-lbl">Rev</span> <b class="good">${fmt$(cs.revenue)}</b>
    <span class="v19-lbl">Exp</span> <b class="bad">${fmt$(cs.expenses)}</b>
    <span class="v19-lbl">Profit</span> <b class="${cs.net<0?"bad":"good"}">${fmt$(cs.net)}</b>
    <span class="v22-sep">|</span>
    <span class="v19-lbl">Employees</span> <b id="hcStatVal" style="cursor:pointer;" class="${c.employees.length>=cap?"bad":""}" title="Open Facilities">${c.employees.length}/${cap}</b>
    <span class="grow" style="flex:1;"></span>
    <span class="v19-lbl">Year ${c.year} \u00b7 Month ${c.month}</span>
    <button class="btn" id="advanceBtn">Advance Month \u25B6</button>
  `;
  const app = document.getElementById("app");
  ["#topbar","#v19Corp","#v18Personal"].forEach(sel=>{ const n = app.querySelector(sel); if(n) n.remove(); });
  app.prepend(bar);

  const ps = personalSnapshot();
  const prow = document.createElement("div");
  prow.id = "v18Personal";
  prow.className = "v18-perso";
  prow.innerHTML = `<span>\u{1F3E1} <span class="muted">Personal</span></span>
    <span class="muted">Cash</span> <b>${fmt$(ps.cash)}</b>
    <span class="muted">Net/mo</span> <b class="${ps.net<0?"bad":"good"}">${fmt$(ps.net)}</b>
    <span class="muted">Net worth</span> <b>${fmt$(ps.worth)}</b>
    <span class="grow" style="flex:1;"></span>
    <button class="btn secondary small" id="v18Infuse">\u{1F4B5} Invest personal cash into company</button>`;
  bar.insertAdjacentElement("afterend", prow);

  bar.querySelector("#advanceBtn").onclick = ()=>{ confirmAndAdvance(); };
  const sw = bar.querySelector("#coSwitch");
  if(sw) sw.onchange = ()=>{ switchCompany(Number(sw.value)); };
  const hv = bar.querySelector("#hcStatVal");
  if(hv) hv.onclick = ()=>{ G.ui.activeTab = "facilities"; renderAll(); };
  const inf = prow.querySelector("#v18Infuse");
  if(inf) inf.onclick = ()=> v18Infuse();
};

/* ---- 2. Sidebar: HQ absorbs People, renames, reorder ---- */
const V22_PEOPLE_SUBS = ["team","hr","orgchart","board","slack","zoom"];
DOCK_ITEMS.push({ id:"people", icon:"\u{1F9D1}\u200D\u{1F4BC}", label:"People" });
(function v22Labels(){
  const l = DOCK_ITEMS.find(i=>i.id==="log"); if(l) l.label = "Log";
  const h = DOCK_ITEMS.find(i=>i.id==="hq"); if(h) h.label = "HQ";
})();
(function v22Nav(){
  const g = (id, icon, label, items)=>({ id, icon, label, items });
  const next = [
    g("run",    "\u{1F9ED}", "Decide",   ["decisions"]),
    g("hq",     "\u{1F3E2}", "HQ",       ["financials","industry","facilities","product","clients","research","people"]),
    g("bank",   "\u{1F3E6}", "Bank",     ["bank"]),
    g("invest", "\u{1F4B9}", "Invest",   ["invest"]),
    g("log",    "\u{1F9FE}", "Log",      ["log"]),
    g("life",   "\u{1F3E1}", "Personal", ["personal","life","empire","market"]),
    g("jarvis", "\u{1F916}", "F.E.L.I.P.E", ["assistant"]),
    g("miles",  "\u{1F3C5}", "Milestones", ["milestones"]),
    g("board2", "\u{1F3C6}", "Leaderboard", ["leaderboard"]),
    g("system", "\u{1F4BE}", "System",   ["saves"]),
  ];
  DOCK_GROUPS.length = 0;
  next.forEach(x=>DOCK_GROUPS.push(x));
})();

function v22IsPeopleTab(id){ return V22_PEOPLE_SUBS.indexOf(id)>=0; }
groupOfTab = function(tabId){
  if(v22IsPeopleTab(tabId)) return DOCK_GROUPS.find(g=>g.id==="hq") || DOCK_GROUPS[0];
  return DOCK_GROUPS.find(g=>g.items.indexOf(tabId)>=0) || DOCK_GROUPS[0];
};
function v22LastPeopleTab(){
  G.ui.lastPeopleTab = G.ui.lastPeopleTab && v22IsPeopleTab(G.ui.lastPeopleTab) ? G.ui.lastPeopleTab : "team";
  return G.ui.lastPeopleTab;
}

/* ---- 3. Two-level sticky sub-tabs ---- */
subTabBar = function(){
  const g = groupOfTab(G.ui.activeTab);
  if(!g || g.items.length<2) return null;
  const inPeople = v22IsPeopleTab(G.ui.activeTab);
  const activeTop = inPeople ? "people" : G.ui.activeTab;
  const cur = dockItem(activeTop);
  const crumb = inPeople
    ? `${g.icon} ${g.label} \u203A <b style="color:var(--accent);">People</b> \u203A ${dockItem(G.ui.activeTab).label}`
    : `${g.icon} ${g.label} \u203A <b style="color:var(--accent);">${cur.label}</b>`;
  const bar = el(`<div class="v21-subbar">
    <div class="flexrow" style="flex-wrap:wrap;gap:6px;align-items:center;">
      <span class="muted" style="font-size:11.5px;margin-right:4px;">${crumb}</span>
      ${g.items.map(id=>{ const it = dockItem(id);
        return `<button class="btn ${activeTop===id?"":"secondary"} small" data-subtab="${id}">${it.icon} ${it.label}</button>`; }).join("")}
    </div>
    ${inPeople? `<div class="v22-sub2"><span class="lbl">People</span>${V22_PEOPLE_SUBS.map(id=>{ const it = dockItem(id);
        return `<button class="btn ${G.ui.activeTab===id?"":"secondary"} small" data-subtab2="${id}">${it.icon} ${it.label}</button>`; }).join("")}</div>`:""}
  </div>`);
  const go = (id)=>{
    if(id==="people") id = v22LastPeopleTab();
    G.ui.activeTab = id;
    if(v22IsPeopleTab(id)) G.ui.lastPeopleTab = id;
    G.ui.lastTabByGroup = G.ui.lastTabByGroup || {};
    G.ui.lastTabByGroup[groupOfTab(id).id] = id;
    renderDock(); renderScreen();
    const sc = document.getElementById("screen"); if(sc) sc.scrollTop = 0;
  };
  bar.querySelectorAll("[data-subtab]").forEach(b=> b.onclick = ()=> go(b.getAttribute("data-subtab")));
  bar.querySelectorAll("[data-subtab2]").forEach(b=> b.onclick = ()=> go(b.getAttribute("data-subtab2")));
  return bar;
};

/* ---- 4. Route the "people" umbrella tab + drop the HQ-inside-HQ tab ---- */
(function v22Route(){
  const prev = renderScreen;
  renderScreen = function(){
    if(G.ui.activeTab === "people" || G.ui.activeTab === "hq"){
      G.ui.activeTab = (G.ui.activeTab==="hq") ? "financials" : v22LastPeopleTab();
    }
    if(v22IsPeopleTab(G.ui.activeTab)) G.ui.lastPeopleTab = G.ui.activeTab;
    return prev.apply(this, arguments);
  };
  const prevDock = renderDock;
  renderDock = function(){
    const r = prevDock.apply(this, arguments);
    const dock = document.getElementById("dock");
    if(dock){
      dock.querySelectorAll("[data-group]").forEach(b=>{
        b.onclick = ()=>{
          const g = DOCK_GROUPS.find(x=>x.id===b.getAttribute("data-group"));
          if(!g) return;
          G.ui.lastTabByGroup = G.ui.lastTabByGroup || {};
          let target = G.ui.lastTabByGroup[g.id];
          const valid = target && (g.items.indexOf(target)>=0 || (g.id==="hq" && v22IsPeopleTab(target)));
          if(!valid) target = g.items[0];
          if(target==="people") target = v22LastPeopleTab();
          G.ui.activeTab = target;
          renderDock(); renderScreen();
          const sc = document.getElementById("screen"); if(sc) sc.scrollTop = 0;
        };
      });
    }
    return r;
  };
})();

/* ---- 5. Team roster: department head large, everyone else half-height rows ---- */
function v22MiniCard(e){
  return `<div class="v22-mini" data-empcard="${e.id}">
    <span class="av">${e.icon}</span>
    <span><span class="nm">${e.name}</span><br><span class="rl">${e.role}</span></span>
    <span class="sp"></span>
    <span class="mt">${fmt$(e.salary)}/mo \u00b7 P${e.performance} \u00b7 M${e.morale}</span>
    <button class="btn secondary small msg" data-message-emp="${e.id}">\u{1F4AC}</button>
  </div>`;
}
renderTeam = function(){
  const wrap = el(`<div></div>`);
  let html = `<div class="window-title"><h2>\u{1F9D1}\u200D\u{1F4BC} Team</h2><span class="sub">${G.company.employees.length} employee(s) total</span></div>`;
  DEPT_KEYS.forEach(dk=>{
    const ladder = LADDERS[dk];
    const emps = deptEmployees(dk).slice().sort((a,b)=> rungIndex(dk,b.rung) - rungIndex(dk,a.rung));
    const head = emps[0] || null;
    const rest = emps.slice(1);
    const avgPerf = emps.length? Math.round(emps.reduce((s,e)=>s+e.performance,0)/emps.length) : 0;
    const avgMorale = emps.length? Math.round(emps.reduce((s,e)=>s+e.morale,0)/emps.length) : 0;
    html += `<div class="dept-section"><div class="dept-header" data-toggleteam="${dk}">
      <b>${ladder.icon} ${ladder.label}</b><span class="muted">${emps.length} \u00b7 ${head? head.role+" leads" : "no lead"} \u00b7 avg perf ${avgPerf} \u00b7 avg morale ${avgMorale}</span></div>
      <div class="dept-body ${G.ui.openDept==='team_'+dk?'open':''}" id="teambody_${dk}">
        ${emps.length===0? `<div class="muted">No hires yet in this department.</div>` :
          `<div class="v22-headwrap">${empCardHtml(head)}</div>
           ${rest.length? `<div class="v22-minigrid">${rest.map(e=>v22MiniCard(e)).join("")}</div>`:""}
           <div class="mt8"><button class="btn secondary small" data-deptbonus="${dk}">\u{1F4B0} Give Department Bonus Pool</button></div>`}
      </div></div>`;
  });
  wrap.innerHTML = html;
  wrap.querySelectorAll("[data-toggleteam]").forEach(h=> h.onclick=()=>{
    const key = "team_"+h.getAttribute("data-toggleteam");
    G.ui.openDept = (G.ui.openDept===key)? null : key;
    renderScreen();
  });
  wrap.querySelectorAll("[data-empcard]").forEach(c=> c.onclick=(ev)=>{
    if(ev.target && ev.target.closest && ev.target.closest("[data-message-emp]")) return;
    openEmployeeModal(c.getAttribute("data-empcard"));
  });
  wrap.querySelectorAll("[data-message-emp]").forEach(b=> b.onclick=(ev)=>{
    ev.stopPropagation();
    const id = b.getAttribute("data-message-emp");
    G.company.slackThreads[id] = G.company.slackThreads[id] || [];
    G.ui.activeSlackId = id;
    G.ui.activeTab = "slack";
    renderAll();
  });
  wrap.querySelectorAll("[data-deptbonus]").forEach(b=> b.onclick=()=>{
    const dk = b.getAttribute("data-deptbonus");
    const emps = deptEmployees(dk);
    if(emps.length===0) return;
    const amountStr = window.prompt(`Total bonus pool to distribute across ${emps.length} ${LADDERS[dk].label} employee(s)?`, "1000");
    const amount = Number(amountStr);
    if(!amount || amount<=0) return;
    if(!affordOrAlert(amount, "the department bonus pool")) return;
    const weights = emps.map(e=> (rungIndex(dk,e.rung)+1) * (1+tenureMonths(e)/12));
    const totalWeight = weights.reduce((a,b)=>a+b,0);
    queueAdd({ id:uid(), label:`Bonus pool: ${LADDERS[dk].label}`, cost:amount, run:(report)=>{
      if(G.company.cash<amount){ report.push(`Skipped ${LADDERS[dk].label} bonus pool \u2014 insufficient cash.`); return; }
      G.company.cash -= amount;
      emps.forEach((e,i)=>{
        const share = Math.round(amount * (weights[i]/totalWeight));
        e.morale = clamp(e.morale+12,0,100); e.performance = clamp(e.performance+4,0,100);
        report.push(`${e.name} received a ${fmt$(share)} bonus.`);
      });
    }});
    renderScreen();
  });
  return wrap;
};

/* ---- 6. Leaderboard: rank titles + oversized medals ---- */
const V22_RANK_TITLES = [
  "Titan of Industry","Tycoon","Magnate","Mogul","Industrialist",
  "Business Leader","Operator","Builder","Upstart","Contender",
];
function v22RankTitle(i){ return V22_RANK_TITLES[i] || "Contender"; }
renderLeaderboard = function(){
  const c = G.company, p = pInit();
  const code = v19RunCode();
  const total = Math.round((c.netWorth||0) + (p.netWorth||0));
  const board = LB_SEED.slice().concat([{ name:(G.meta.playerName||"You") + " (you, unsubmitted)", company:c.name, industry:`${industry().icon} ${industry().label}`, nw: total, months:(c.year-1)*12+c.month, you:true }])
    .sort((a,b)=>b.nw-a.nw).slice(0,11);
  const yourRank = board.findIndex(r=>r.you) + 1;
  const wrap = el(`<div>
    <div class="window-title"><h2>\u{1F3C6} Leaderboard</h2><span class="sub">Top empires across every player \u00b7 ranked by total net worth</span></div>
    <div class="card mb14">
      <div class="flexrow" style="gap:8px;flex-wrap:wrap;align-items:center;">
        <button class="btn" id="v18Submit">\u{1F3C6} Submit current run to leaderboard</button>
        <button class="btn secondary small" id="v18Copy">\u{1F4CB} Copy run code</button>
        <a class="btn secondary small" href="${LEADERBOARD_FORM_URL}" target="_blank" rel="noopener" style="text-decoration:none;">\u{1F517} Open submission form</a>
        <span class="muted" style="font-size:11.5px;">Your run: <b>${fmt$(total)}</b> net worth${yourRank? ` \u00b7 would rank <b>#${yourRank}</b> \u00b7 <b>${v22RankTitle(yourRank-1)}</b>`:""}</span>
      </div>
      <div class="muted mt8" style="font-size:11.5px;">Submit copies your run code and opens the form \u2014 paste it in the one box and send. Nothing else leaves your browser.</div>
    </div>
    <div class="flatsec mb14">
      <h3>Hall of Titans \u2014 by total net worth</h3>
      ${board.slice(0,10).map((r,i)=>`<div class="v19-lbrow ${r.you?"you":""}">
        <span class="rk">${i<3? `<span class="v22-medal">${i===0?"\u{1F947}":i===1?"\u{1F948}":"\u{1F949}"}</span>` : `<span class="v22-rankno">#${i+1}</span>`}</span>
        <span class="nm"><span class="v22-title">${v22RankTitle(i)}</span><br><b>${r.name}</b> <span class="muted">\u00b7 ${r.company} \u00b7 ${r.industry} \u00b7 ${r.months} mo</span></span>
        <span class="nw ${r.you?"good":""}">${fmt$(r.nw)}</span>
      </div>`).join("")}
      <div class="muted mt8" style="font-size:11px;">Seeded with sample runs until real submissions land. Felipe refreshes the board from the Notion database.</div>
    </div>
    <div class="card">
      <h3>Your Run Code</h3>
      <textarea id="v18Code" readonly style="width:100%;height:84px;background:var(--panel2);border:1px solid var(--border);color:var(--muted);border-radius:8px;padding:8px;font-family:monospace;font-size:11px;">${code}</textarea>
      <div class="muted mt4" style="font-size:11px;">Carries player, company, industry, net worth, revenue, headcount, months played and success score.</div>
    </div>
  </div>`);
  const copy = async ()=>{
    const ta = wrap.querySelector("#v18Code");
    try { await navigator.clipboard.writeText(ta.value); }
    catch(e){ ta.select(); try{ document.execCommand("copy"); }catch(e2){} }
  };
  wrap.querySelector("#v18Copy").onclick = async ()=>{ await copy(); toast("<b>Run code copied.</b> Paste it into the leaderboard form."); };
  wrap.querySelector("#v18Submit").onclick = async ()=>{
    await copy();
    toast("<b>Run code copied \u2014 opening the form.</b> Paste into the one box and submit.");
    window.open(LEADERBOARD_FORM_URL, "_blank", "noopener");
  };
  return wrap;
};

