/* ---- A. Board compensation: adjustable retainers + board bonuses ---- */
function v22BoardPay(){
  if(typeof G === "undefined" || !G || !G.company) return {};
  G.company.boardPay = G.company.boardPay || {};
  return G.company.boardPay;
}
function v22SyncBoardPay(){
  const pay = v22BoardPay();
  BOARD_SEATS.forEach(s=>{
    if(s.baseUpkeep === undefined) s.baseUpkeep = s.upkeep;
    s.upkeep = (pay[s.key] !== undefined) ? pay[s.key] : s.baseUpkeep;
  });
}
try { v22SyncBoardPay(); } catch(e){}
(function v22WrapAdvance(){
  if(typeof advanceMonth !== "function") return;
  const prev = advanceMonth;
  advanceMonth = function(){ try { v22SyncBoardPay(); } catch(e){} return prev.apply(this, arguments); };
})();
function v22BoardPaySection(){
  v22SyncBoardPay();
  const c = G.company, board = c.board || [];
  if(!board.length) return "";
  const rows = board.map(k=>{
    const s = BOARD_SEATS.find(x=>x.key===k);
    if(!s) return "";
    const base = s.baseUpkeep || s.upkeep;
    const cur = s.upkeep;
    const pct = Math.round((cur/base-1)*100);
    return `<div class="v22-payrow">
      <span>${s.icon}</span><span class="nm">${s.name}</span>
      <span class="muted" style="font-size:11px;">base ${fmt$(base)}/mo${pct?` \u00b7 ${pct>0?"+":""}${pct}%`:""}</span>
      <span class="sp"></span>
      <button class="btn secondary small" data-v22paydn="${s.key}">\u2212</button>
      <b>${fmt$(cur)}/mo</b>
      <button class="btn secondary small" data-v22payup="${s.key}">+</button>
      <button class="btn secondary small" data-v22bonus="${s.key}">\u{1F4B0} Bonus</button>
    </div>`;
  }).join("");
  const total = board.reduce((sum,k)=>{ const s = BOARD_SEATS.find(x=>x.key===k); return sum+(s?s.upkeep:0); },0);
  return `<div class="flatsec mb14" id="v22BoardPay">
    <h3>\u{1F4B5} Board compensation</h3>
    <div class="muted mb8" style="font-size:12px;">Raise a director's retainer to buy loyalty and influence: every 25% raise adds +1 success score while it stands. One-off bonuses land immediately and nudge the board your way.</div>
    ${rows}
    <div class="muted" style="font-size:11.5px;">Total board upkeep <b>${fmt$(total)}/mo</b> \u00b7 charged at month close.</div>
  </div>`;
}
function v22WireBoardPay(root){
  if(!root) return;
  const step = (key, dir)=>{
    v22SyncBoardPay();
    const s = BOARD_SEATS.find(x=>x.key===key); if(!s) return;
    const base = s.baseUpkeep || s.upkeep;
    const next = Math.max(Math.round(base*0.5), Math.round(s.upkeep + dir*base*0.25));
    v22BoardPay()[key] = next;
    v22SyncBoardPay();
    G.company.successScore = clamp((G.company.successScore||0) + (dir>0?1:-1), 0, 100);
    toast(`<b>${s.name} retainer ${dir>0?"raised":"cut"}.</b> Now ${fmt$(next)}/mo \u00b7 success ${dir>0?"+1":"-1"}.`, dir>0?"good":"warn");
    logHistory(`${s.name} board retainer set to ${fmt$(next)}/mo.`);
    renderScreen();
  };
  root.querySelectorAll("[data-v22payup]").forEach(b=> b.onclick = ()=> step(b.getAttribute("data-v22payup"), 1));
  root.querySelectorAll("[data-v22paydn]").forEach(b=> b.onclick = ()=> step(b.getAttribute("data-v22paydn"), -1));
  root.querySelectorAll("[data-v22bonus]").forEach(b=> b.onclick = ()=>{
    const key = b.getAttribute("data-v22bonus");
    const s = BOARD_SEATS.find(x=>x.key===key); if(!s) return;
    const def = String(Math.round((s.upkeep||1500)*2));
    const amountStr = window.prompt(`One-off bonus for ${s.name}?`, def);
    const amount = Number(amountStr);
    if(!amount || amount<=0) return;
    if(!affordOrAlert(amount, `a board bonus for ${s.name}`)) return;
    G.company.cash -= amount;
    G.company.successScore = clamp((G.company.successScore||0) + 2, 0, 100);
    toast(`<b>${fmt$(amount)} bonus paid to ${s.name}.</b> Success +2 \u00b7 the board is pleased.`, "good");
    logHistory(`Paid ${fmt$(amount)} board bonus to ${s.name}.`);
    renderAll();
  });
}
(function v22BoardTabPatch(){
  const prev = renderBoardTab;
  renderBoardTab = function(){
    const wrap = prev.apply(this, arguments);
    try {
      const pay = el(`<div>${v22BoardPaySection()}</div>`);
      const seats = wrap.querySelector("#v21BoardSeats");
      if(seats && v22BoardPaySection()) wrap.insertBefore(pay, seats);
      v22WireBoardPay(wrap);
    } catch(e){}
    return wrap;
  };
})();

/* ---- B. C-suite section at the top of Team ---- */
(function v22CsuiteSection(){
  const prev = renderTeam;
  renderTeam = function(){
    const wrap = prev.apply(this, arguments);
    try {
      const execs = (G.company.employees||[]).filter(e=> typeof isCSuite==="function" && isCSuite(e));
      if(execs.length){
        const sec = el(`<div class="flatsec mb14">
          <h3>\u{1F454} C-Suite \u00b7 ${execs.length} executive${execs.length>1?"s":""}</h3>
          <div class="v22-csuite">
            ${execs.map(e=>`<div class="v22-mini" data-empcard="${e.id}">
              <span class="av">${e.icon}</span>
              <span><span class="nm">${e.name}</span><br><span class="rl">${e.role} \u00b7 ${LADDERS[e.dept]?LADDERS[e.dept].label:e.dept}</span></span>
              <span class="sp"></span>
              <span class="mt">${fmt$(e.salary)}/mo \u00b7 P${e.performance}</span>
            </div>`).join("")}
          </div>
        </div>`);
        sec.querySelectorAll("[data-empcard]").forEach(c=> c.onclick = ()=> openEmployeeModal(c.getAttribute("data-empcard")));
        const title = wrap.querySelector(".window-title");
        if(title && title.nextSibling) wrap.insertBefore(sec, title.nextSibling);
        else wrap.appendChild(sec);
      }
    } catch(e){}
    return wrap;
  };
})();

/* ---- C. Adjustable side panel width ---- */
const V22_DOCK_MODES = ["icons","medium","full"];
const V22_NICKS = { run:"Decide", hq:"HQ", bank:"Bank", invest:"Invest", log:"Log", life:"Personal",
  jarvis:"FELIPE", miles:"Miles", board2:"Ranks", system:"Sys" };
function v22DockMode(){
  G.ui.dockMode = V22_DOCK_MODES.indexOf(G.ui.dockMode)>=0 ? G.ui.dockMode : "medium";
  return G.ui.dockMode;
}
(function v22DockWidth(){
  const prev = renderDock;
  renderDock = function(){
    const r = prev.apply(this, arguments);
    const dock = document.getElementById("dock");
    if(!dock) return r;
    const mode = v22DockMode();
    dock.classList.remove("v22-dock-icons","v22-dock-medium","v22-dock-full");
    dock.classList.add("v22-dock-"+mode);
    dock.querySelectorAll("[data-group]").forEach(btn=>{
      const g = DOCK_GROUPS.find(x=>x.id===btn.getAttribute("data-group"));
      const lbl = btn.querySelector(".dock-in");
      if(g && lbl) lbl.textContent = (mode==="full") ? g.label : (V22_NICKS[g.id] || g.label).toUpperCase();
    });
    const ctl = document.createElement("div");
    ctl.className = "v22-dockwidth";
    ctl.innerHTML = `<button class="btn secondary small" id="v22DockToggle" title="Side panel width">${mode==="icons"?"\u00BB":mode==="medium"?"\u00BB":"\u00AB"}</button>`;
    dock.appendChild(ctl);
    const t = ctl.querySelector("#v22DockToggle");
    if(t) t.onclick = ()=>{
      const i = V22_DOCK_MODES.indexOf(v22DockMode());
      G.ui.dockMode = V22_DOCK_MODES[(i+1) % V22_DOCK_MODES.length];
      renderDock();
    };
    return r;
  };
})();


