function v24Co(){ return (typeof G !== "undefined" && G && G.company) ? G.company : null; }
function v24Toast(msg){ try{ if(typeof toast==="function") toast(msg); }catch(e){} }
function v24Payroll(){ const c=v24Co(); return c? c.employees.reduce((s,e)=>s+e.salary,0) : 0; }

/* ---------- 1. Crisis & external-shock events ---------- */
