/* ---------- 5. Competitors that react to you ---------- */
function v24CompetitorReactions(report){
  const c = v24Co(); if(!c || !Array.isArray(c.competitors) || c.competitors.length===0) return;
  const hist = c.financialHistory || [];
  const prevMrr = hist.length>=2 ? hist[hist.length-2].mrr : 0;
  const nowMrr = hist.length>=1 ? hist[hist.length-1].mrr : c.mrr;
  const growth = prevMrr>0 ? (nowMrr - prevMrr)/prevMrr : 0;
  const priceTier = (c.ops && c.ops.priceTier) || c.priceTier || 1;
  const lastTier = c._v24LastTier === undefined ? priceTier : c._v24LastTier;
  c._v24LastTier = priceTier;
  const aggressive = c.competitors.filter(x=> x.threat==="High" || x.marketShare>12);
  if(aggressive.length===0) return;
  const rival = pick(aggressive);

  if(priceTier > lastTier && Math.random() < 0.6){
    c.clients.forEach(cl=> cl.health = clamp(cl.health - rand(3,7), 0, 100));
    rival.marketShare = +(rival.marketShare + randf(0.3,0.9)).toFixed(1);
    report.push(`${rival.name} answered your price increase with a discount campaign — client health slipped and they picked up share.`);
    v24Toast(`${rival.name} undercut your new pricing`);
    return;
  }
  if(growth > 0.12 && Math.random() < 0.55){
    const mode = pick(["poach","copy","raid"]);
    if(mode==="poach" && c.clients.length>2){
      const weakest = c.clients.slice().sort((a,b)=>a.health-b.health)[0];
      c.clients = c.clients.filter(x=>x.id!==weakest.id);
      rival.marketShare = +(rival.marketShare + 0.5).toFixed(1);
      try{ if(typeof recomputeMRR==="function") recomputeMRR(); }catch(e){}
      report.push(`${rival.name} noticed your growth and poached ${weakest.name} (${fmt$(weakest.mrr)}/mo).`);
      v24Toast(`${rival.name} poached ${weakest.name}`);
    } else if(mode==="copy"){
      rival.funding = Math.round((rival.funding||0) * 1.15);
      rival.marketShare = +(rival.marketShare + randf(0.4,1.1)).toFixed(1);
      report.push(`${rival.name} copied your latest positioning and raised a defensive round.`);
    } else if(c.employees.length>3){
      const target = pick(c.employees.filter(e=>e.performance>70) .length ? c.employees.filter(e=>e.performance>70) : c.employees);
      target.morale = clamp(target.morale - 12, 0, 100);
      report.push(`${rival.name} is recruiting your top performers — ${target.name} took the call.`);
    }
  }
}

/* ---------- 6. F.E.L.I.P.E advisory brief ---------- */
function v24Brief(){
  const c = v24Co(); if(!c) return [];
  const out = [];
  const h = c.financialHistory || [];
  const last = h[h.length-1], prev3 = h[h.length-4];
  if(last && prev3 && prev3.mrr>0){
    const g = (last.mrr - prev3.mrr)/prev3.mrr;
    out.push(`${(typeof mrrWord==="function"?mrrWord():"MRR")} is ${g>=0?"up":"down"} ${Math.abs(Math.round(g*100))}% over three months (${fmt$(prev3.mrr)} → ${fmt$(last.mrr)}).${g<0?" I would look at client health before adding headcount.":""}`);
  }
  const payroll = v24Payroll();
  if(c.mrr>0){
    const ratio = payroll/c.mrr;
    if(ratio>0.85) out.push(`Payroll is ${Math.round(ratio*100)}% of ${(typeof mrrWord==="function"?mrrWord():"MRR")}. Above roughly 70% you are buying growth you cannot yet afford.`);
    else if(ratio<0.35 && c.employees.length>3) out.push(`Payroll is only ${Math.round(ratio*100)}% of revenue. You are under-invested in people — there is room to hire into demand.`);
  }
  if(last && last.netProfit<0){
    const runway = last.netProfit<0 ? Math.floor(c.cash/Math.abs(last.netProfit)) : 99;
    out.push(`You burned ${fmt$(Math.abs(last.netProfit))} last month. At that rate you have roughly ${runway} month(s) of runway.`);
  }
  const mkt = c.marketingBudget||0;
  if(mkt===0 && c.mrr>2000) out.push(`Marketing budget is zero. Pipeline will follow it down within two months.`);
  if(c.employees.length){
    const avg = c.employees.reduce((s,e)=>s+e.morale,0)/c.employees.length;
    if(avg<55) out.push(`Average morale is ${Math.round(avg)}. Attrition and performance both track this number — a town hall or review cycle would help.`);
  }
  v24EnsureAccounts();
  const atRisk = (c.clients||[]).filter(cl=>{ const r = v24RenewalRisk(cl); return r.months<=3 && cl.health<60; });
  if(atRisk.length) out.push(`${atRisk.length} account(s) renew within three months with health below 60: ${atRisk.slice(0,3).map(x=>x.name).join(", ")}. Retention offers are cheaper than replacement.`);
  const due = v24ReviewQueue().length;
  if(due>0) out.push(`${due} employee(s) are due for performance review. Zoom → Performance Review lets you authorize in bulk.`);
  const g = v24Goals();
  if(g && !g.business) out.push(`No business goal is set. Milestones & Badges → Goals pays out cash and morale as you hit targets.`);
  if(out.length===0) out.push(`Nothing is on fire. Revenue, morale and cash are all inside normal ranges — this is the month to place a bet.`);
  return out;
}
(function v24AssistantHook(){
  try{
    if(typeof renderAssistant !== "function") return;
    const prev = renderAssistant;
    renderAssistant = function(){
      const wrap = prev.apply(this, arguments);
      try{
        const lines = v24Brief();
        const card = document.createElement("div");
        card.className = "card mb8 v24-brief";
        card.innerHTML = `<h3>\u{1F9E0} F.E.L.I.P.E advisory brief</h3>
          <div class="muted mb8" style="font-size:11px;">Fiscally Erudite Logic Investment Planning Engine \u2014 reading your actual trend data, Y${G.company.year} M${G.company.month}.</div>
          <ul style="margin:0;padding-left:18px;">${lines.map(l=>`<li>${l}</li>`).join("")}</ul>`;
        wrap.insertBefore(card, wrap.firstChild);
      }catch(e){}
      return wrap;
    };
  }catch(e){}
})();

/* ---------- 7. Clients tab: contracts & renewals ---------- */
(function v24ClientsHook(){
  try{
    if(typeof renderClients !== "function") return;
    const prev = renderClients;
    renderClients = function(){
      const wrap = prev.apply(this, arguments);
      try{
        const c = v24Co(); if(!c) return wrap;
        v24EnsureAccounts();
        const rows = (c.clients||[]).map(cl=> ({ cl, r: v24RenewalRisk(cl) })).sort((a,b)=> a.r.months - b.r.months);
        const soon = rows.filter(x=> x.r.months<=3);
        const card = document.createElement("div");
        card.className = "card mb8";
        card.innerHTML = `<h3>\u{1F4C5} Contracts & renewals</h3>
          <div class="muted mb8" style="font-size:11.5px;">Every account is on a term. At renewal, health decides whether they stay, expand, or walk. ${c.churnedAccounts? `${c.churnedAccounts} account(s) lost at renewal so far.`:""}</div>
          ${rows.length? `<table class="v24-rev"><thead><tr><th>Account</th><th>${(typeof mrrWord==="function"?mrrWord():"MRR")}</th><th>Term</th><th>Renews</th><th>Health</th><th>Renewal risk</th><th>Expansion</th></tr></thead><tbody>
            ${rows.slice(0,25).map(({cl,r})=>`<tr>
              <td>${cl.name}</td><td>${fmt$(cl.mrr)}</td><td>${cl.termMonths} mo</td>
              <td>Y${cl.renewYear} M${cl.renewMonth} <span class="muted v24-risk">(${r.months<=0?"now":r.months+" mo"})</span></td>
              <td><span class="pill ${cl.health>60?'good':cl.health>35?'warn':'bad'}">${cl.health}</span></td>
              <td><span class="pill ${r.risk<35?'good':r.risk<60?'warn':'bad'}">${r.risk}%</span></td>
              <td>${cl.expansion}%</td></tr>`).join("")}
          </tbody></table>${rows.length>25?`<div class="muted mt8" style="font-size:11.5px;">Showing the 25 nearest renewals of ${rows.length}.</div>`:""}`
            : `<div class="muted" style="font-size:12px;">No accounts under contract yet.</div>`}
          ${soon.length? `<div class="mt8" style="font-size:12px;"><b>Watchlist:</b> ${soon.map(x=>x.cl.name).join(", ")} renew within three months.</div>`:""}`;
        wrap.insertBefore(card, wrap.children[1] || null);
      }catch(e){}
      return wrap;
    };
  }catch(e){}
})();

/* ---------- 8. Bonus chooser + richer employee / exec modal ---------- */
function v24BonusDialog(id){
  const c = v24Co(); if(!c) return;
  const e = c.employees.find(x=>x.id===id); if(!e) return;
  const box = document.getElementById("modalBox");
  const presets = [500, 1000, 2500, 5000, 10000, Math.round(e.salary), Math.round(e.salary*3)];
  const uniq = [...new Set(presets)].sort((a,b)=>a-b);
  box.innerHTML = `<span class="close" id="closeModal">&times;</span>
    <h3>\u{1F4B0} Bonus for ${e.name}</h3>
    <div class="muted mb8" style="font-size:12px;">${e.role} \u00b7 ${fmt$(e.salary)}/mo \u00b7 morale ${e.morale} \u00b7 performance ${e.performance}</div>
    <div class="v24-amt">${uniq.map(a=>`<button class="btn secondary small" data-v24bamt="${a}">${fmt$(a)}</button>`).join("")}</div>
    <div class="v24-amt"><input id="v24BonusCustom" type="number" placeholder="Custom $" />
      <button class="btn small" id="v24BonusGo">Authorize bonus</button></div>
    <div class="muted" style="font-size:11.5px;">Bonuses queue with your other decisions and land at month close. Morale moves with size; performance gets a lift either way.</div>`;
  const give = (amount)=>{
    if(!amount || amount<=0) return;
    if(typeof affordOrAlert==="function" && !affordOrAlert(amount, `a bonus for ${e.name}`)) return;
    queueAdd({ id:uid(), label:`Bonus: ${e.name} (${fmt$(amount)})`, cost:amount, run:(report)=>{
      if(G.company.cash<amount){ report.push(`Skipped bonus for ${e.name} — insufficient cash.`); return; }
      G.company.cash -= amount;
      e.morale = clamp(e.morale + Math.min(22, Math.round(amount/Math.max(250, e.salary/6))), 0, 100);
      e.performance = clamp(e.performance+5,0,100);
      report.push(`Paid ${e.name} a ${fmt$(amount)} bonus.`);
    }});
    v24Toast(`Queued a ${fmt$(amount)} bonus for ${e.name}`);
    document.getElementById("modalOverlay").classList.remove("show");
    if(typeof renderScreen==="function") renderScreen();
  };
  box.querySelectorAll("[data-v24bamt]").forEach(b=> b.onclick = ()=> give(Number(b.getAttribute("data-v24bamt"))));
  box.querySelector("#v24BonusGo").onclick = ()=> give(Number(box.querySelector("#v24BonusCustom").value));
  box.querySelector("#closeModal").onclick = ()=> document.getElementById("modalOverlay").classList.remove("show");
}
function v24ExecLine(e){
  const c = v24Co();
  const dept = LADDERS[e.dept] ? LADDERS[e.dept].label : e.dept;
  const staff = (typeof deptEmployees==="function") ? deptEmployees(e.dept).length : 0;
  const opts = [
    `${dept} is ${staff} people deep. Give me headcount and I'll give you output.`,
    `Cash is ${fmt$(c.cash)} and payroll is ${fmt$(v24Payroll())}/mo. I'd keep three months of cover before we expand.`,
    `${(typeof mrrWord==="function"?mrrWord():"MRR")} sits at ${fmt$(c.mrr)}. My team can move that if you fund it.`,
    `Morale in ${dept} is my problem. Bonuses help; predictable reviews help more.`,
    `Give me a target headcount and I'll fill the ladder without bothering you again.`,
  ];
  return pick(opts);
}
function v24EnhanceModal(id){
  const c = v24Co(); if(!c) return;
  const e = c.employees.find(x=>x.id===id); if(!e) return;
  const box = document.getElementById("modalBox"); if(!box) return;
  const bonusBtn = box.querySelector("#bonusBtn");
  if(bonusBtn){ bonusBtn.textContent = "Give Bonus"; bonusBtn.onclick = ()=> v24BonusDialog(id); }
  const leader = (typeof isLeader==="function") && isLeader(e);
  const exec = (typeof isCSuite==="function") && isCSuite(e);
  if(!leader && !exec) return;
  const staff = (typeof deptEmployees==="function") ? deptEmployees(e.dept).length : 0;
  const extra = document.createElement("div");
  extra.className = "mt14";
  extra.innerHTML = `
    <div style="border-top:1px solid var(--border);padding-top:10px;">
      <div class="muted" style="font-size:10.5px;letter-spacing:.06em;text-transform:uppercase;margin-bottom:6px;">${exec?"Executive controls":"Leader controls"}</div>
      <div class="v24-row mb8">
        <button class="btn secondary small" id="v24PayDn">Salary −10%</button>
        <span style="font-size:12px;"><b>${fmt$(e.salary)}</b>/mo</span>
        <button class="btn secondary small" id="v24PayUp">Salary +10%</button>
        <button class="btn secondary small" id="v24Speak">Speak with ${e.name.split(" ")[0]}</button>
      </div>
      <div class="v24-row">
        <span style="font-size:12px;">Grow ${LADDERS[e.dept]?LADDERS[e.dept].label:e.dept} from <b>${staff}</b> to</span>
        <input id="v24DelegTo" type="number" min="${staff}" placeholder="${Math.max(staff+5, 25)}" style="width:90px;background:var(--panel);border:1px solid var(--border);color:var(--text);border-radius:6px;padding:6px 8px;font-size:12px;" />
        <button class="btn small" id="v24DelegGo">Delegate</button>
      </div>
      <div class="muted mt8" id="v24Says" style="font-size:11.5px;"></div>
    </div>`;
  box.appendChild(extra);
  const refresh = ()=>{ const ov=document.getElementById("modalOverlay"); ov.classList.remove("show"); if(typeof renderScreen==="function") renderScreen(); };
  box.querySelector("#v24PayUp").onclick = ()=>{ e.salary = Math.round(e.salary*1.1); e.morale = clamp(e.morale+5,0,100);
    if(typeof logHistory==="function") logHistory(`Raised ${e.name}'s salary to ${fmt$(e.salary)}/mo.`); v24Toast(`${e.name}: ${fmt$(e.salary)}/mo`); refresh(); };
  box.querySelector("#v24PayDn").onclick = ()=>{ e.salary = Math.round(e.salary*0.9); e.morale = clamp(e.morale-8,0,100);
    if(typeof logHistory==="function") logHistory(`Cut ${e.name}'s salary to ${fmt$(e.salary)}/mo.`); v24Toast(`${e.name}: ${fmt$(e.salary)}/mo`); refresh(); };
  box.querySelector("#v24Speak").onclick = ()=>{
    const line = v24ExecLine(e);
    box.querySelector("#v24Says").innerHTML = `<b>${e.name}:</b> \u201C${line}\u201D`;
    try{ c.csuiteChannel.push({ from:e.name, text:line, month:c.month, year:c.year }); }catch(err){}
  };
  box.querySelector("#v24DelegGo").onclick = ()=>{
    const target = Number(box.querySelector("#v24DelegTo").value);
    if(!target || target<=staff){ v24Toast("Enter a headcount above the current team size"); return; }
    if(typeof v23StaffTo==="function"){ v23StaffTo(e.dept, target); v24Toast(`${e.name} is staffing ${LADDERS[e.dept]?LADDERS[e.dept].label:e.dept} up to ${target}`); }
    refresh();
  };
}
