/* ---------- 2. Engagement staff in HR ---------- */
(function v25EngagementRung(){
  try{
    if(typeof LADDERS==="undefined" || !LADDERS.hr || !LADDERS.hr.rungs) return;
    if(LADDERS.hr.rungs.some(r=>r.key==="engagement")) return;
    const mk = ()=>({ key:"engagement", label:"Engagement Specialist", salaryRange:[4600,5600], icon:"\u{1F389}",
      desc:"Plans team events. Bigger events need more engagement staff on payroll." });
    LADDERS.hr.rungs.splice(1, 0, mk());
    // Keep the base ladder and every industry role list index-aligned.
    if(typeof BASE_LADDERS!=="undefined" && BASE_LADDERS.hr && BASE_LADDERS.hr.rungs &&
       !BASE_LADDERS.hr.rungs.some(r=>r.key==="engagement")) BASE_LADDERS.hr.rungs.splice(1, 0, mk());
    if(typeof INDUSTRIES!=="undefined"){
      Object.keys(INDUSTRIES).forEach(k=>{
        const roles = INDUSTRIES[k] && INDUSTRIES[k].roles && INDUSTRIES[k].roles.hr;
        if(Array.isArray(roles) && roles[1]!=="Engagement Specialist") roles.splice(1, 0, "Engagement Specialist");
      });
    }
    if(typeof applyIndustryLabels==="function"){ try{ applyIndustryLabels(); }catch(e){} }
  }catch(e){}
})();
function v25EngagementCount(){
  try{
    if(typeof deptEmployees!=="function") return 0;
    return deptEmployees("hr").filter(e=>e.rung==="engagement").length;
  }catch(e){ return 0; }
}

/* ---------- 3. Events catalog ---------- */
const V25_EVENTS = [
  { key:"coffee",   name:"Coffee Cart Morning",   icon:"\u2615", eng:0, per:18,  base:250,   morale:2,  desc:"Barista in the lobby. Cheap, instant goodwill." },
  { key:"lunch",    name:"Team Lunch",            icon:"\u{1F35C}", eng:0, per:34,  base:400,   morale:3,  desc:"Catered lunch for the whole company." },
  { key:"gamenight",name:"Game Night",            icon:"\u{1F3AE}", eng:1, per:26,  base:600,   morale:4,  desc:"Pizza, consoles, and mild competitive chaos." },
  { key:"bowling",  name:"Bowling & Bar Tab",     icon:"\u{1F3B3}", eng:1, per:55,  base:900,   morale:5,  desc:"Lanes, shoes, and questionable technique." },
  { key:"escape",   name:"Escape Room Tournament",icon:"\u{1F513}", eng:2, per:70,  base:1400,  morale:6,  desc:"Teams race the clock. Cross-department bonding." },
  { key:"volunteer",name:"Volunteer Day",         icon:"\u{1F91D}", eng:2, per:45,  base:1800,  morale:7,  desc:"Paid day of service. Great for morale and reputation." },
  { key:"sports",   name:"Stadium Suite Night",   icon:"\u{1F3DF}\uFE0F", eng:3, per:120, base:4000, morale:8,  desc:"Private suite, catered, everyone tells the story for months." },
  { key:"holiday",  name:"Holiday Gala",          icon:"\u{1F389}", eng:3, per:190, base:7000,  morale:10, desc:"Venue, band, open bar, awards." },
  { key:"offsite",  name:"Two-Day Offsite",       icon:"\u{1F3D5}\uFE0F", eng:4, per:420, base:15000, morale:12, desc:"Hotel, workshops, and a bonfire nobody forgets." },
  { key:"ski",      name:"Mountain Ski Weekend",  icon:"\u{1F3BF}", eng:5, per:700, base:28000, morale:14, desc:"Lift passes, lodge, and a hot tub summit." },
  { key:"cruise",   name:"Company Cruise",        icon:"\u{1F6F3}\uFE0F", eng:6, per:1100, base:60000, morale:16, desc:"Four nights at sea. Out of office, genuinely." },
  { key:"yacht",    name:"Private Yacht Charter", icon:"\u{1F6E5}\uFE0F", eng:8, per:1900, base:120000, morale:20, desc:"Chartered yacht, chef, and legendary status." },
];
function v25EventCost(ev){
  const c = v25Co();
  const heads = c && c.employees ? c.employees.length : 0;
  return Math.round(ev.base + ev.per * heads);
}
function v25EventsRun(){
  const c = v25Co();
  if(!c) return [];
  c.eventsRun = c.eventsRun || [];
  return c.eventsRun;
}
function v25EventThisMonth(){
  const c = v25Co();
  if(!c) return false;
  return c.lastEventStamp === (c.year*12 + c.month);
}
function v25RunEvent(key){
  const c = v25Co();
  if(!c) return;
  const ev = V25_EVENTS.find(x=>x.key===key);
  if(!ev) return;
  if(v25EngagementCount() < ev.eng){ v25Toast(`${ev.name} needs ${ev.eng} engagement specialists on payroll.`, "bad"); return; }
  if(v25EventThisMonth()){ v25Toast("You've already run an event this month.", "bad"); return; }
  const cost = v25EventCost(ev);
  if((c.cash||0) < cost){ v25Toast(`Not enough cash for ${ev.name} (${typeof fmt$==="function"?fmt$(cost):cost}).`, "bad"); return; }
  c.cash -= cost;
  let lift = ev.morale;
  try{
    (c.employees||[]).forEach(e=>{ e.morale = (typeof clamp==="function") ? clamp((e.morale||60)+lift, 0, 100) : Math.min(100,(e.morale||60)+lift); });
  }catch(e){}
  c.lastEventStamp = c.year*12 + c.month;
  v25EventsRun().push({ key:ev.key, month:c.month, year:c.year, cost });
  try{ if(typeof logHistory==="function") logHistory(`${ev.icon} ${ev.name} \u2014 ${typeof fmt$==="function"?fmt$(cost):cost}, +${lift} morale company-wide.`); }catch(e){}
  v25Toast(`${ev.name} was a hit. +${lift} morale.`, "good");
  try{ if(typeof renderAll==="function") renderAll(); }catch(e){}
}
function v25EventsCard(){
  const c = v25Co();
  const eng = v25EngagementCount();
  const used = v25EventThisMonth();
  const wrap = document.createElement("div");
  wrap.className = "card";
  const rows = V25_EVENTS.map(ev=>{
    const cost = v25EventCost(ev);
    const locked = eng < ev.eng;
    const money = (typeof fmt$==="function") ? fmt$(cost) : ("$"+cost);
    return `<div class="v25-ev ${locked?"v25-locked":""}">
      <div class="ico">${ev.icon}</div>
      <div>
        <div class="nm">${ev.name}</div>
        <div class="ds">${ev.desc}</div>
        <div class="ds">${ev.eng===0?"No engagement staff required":`Needs ${ev.eng} engagement specialist${ev.eng>1?"s":""} (you have ${eng})`} \u00b7 +${ev.morale} morale</div>
      </div>
      <div class="rt">
        <div style="font-weight:600;font-size:13px;">${money}</div>
        <button class="btn small" data-v25ev="${ev.key}" ${(locked||used)?"disabled":""}>${locked?"Locked":(used?"Done this month":"Run Event")}</button>
      </div>
    </div>`;
  }).join("");
  wrap.innerHTML = `<h3>\u{1F389} TEAM EVENTS</h3>
    <div class="muted" style="font-size:12px;margin-bottom:8px;">Hire Engagement Specialists in HR to unlock bigger events. One event per month; cost scales with headcount.</div>
    ${rows}`;
  wrap.querySelectorAll("[data-v25ev]").forEach(b=> b.onclick = ()=> v25RunEvent(b.getAttribute("data-v25ev")));
  return wrap;
}
