function v26Co(){ try{ return G && G.company ? G.company : null; }catch(e){ return null; } }
function v26Money(n){ try{ return fmt$(Math.round(n||0)); }catch(e){ return "$"+Math.round(n||0); } }

/* ---------- 1. Retail: seasonality, shrinkage, reorder points, real unit economics ---------- */
const V26_SEASON = [0.86,0.82,0.94,0.97,1.02,1.03,0.98,1.05,1.00,1.08,1.24,1.46]; // Jan..Dec
const V26_SEASON_LABEL = ["Post-holiday lull","Slowest month","Spring pickup","Steady","Steady","Summer traffic","Summer dip","Back-to-school","Steady","Early holiday","Black Friday","Holiday peak"];
function v26MonthOfYear(){ const c=v26Co(); return ((c && c.month ? c.month : 1) - 1) % 12; }
function v26SeasonFactor(){ return V26_SEASON[v26MonthOfYear()]; }
function v26SeasonName(){ return V26_SEASON_LABEL[v26MonthOfYear()]; }
function v26StoreInit(s){
  if(s.unitsOnHand===undefined){
    // migrate legacy dollar-denominated inventory into units
    s.unitsOnHand = Math.max(0, Math.floor((s.inventory||0)/19));
  }
  if(s.reorderPoint===undefined) s.reorderPoint = Math.round((s.baseDemand||100)*0.5);
  if(s.reorderQty===undefined) s.reorderQty = Math.round((s.baseDemand||100)*1.5);
  if(s.autoReorder===undefined) s.autoReorder = false;
  if(!Array.isArray(s.inbound)) s.inbound = []; // [{units, arrivesIn, cost}]
  return s;
}
function v26UnitCost(){
  const supply = (typeof rungCount==="function") ? rungCount("operations","rep") : 0;
  const buyers = (typeof rungCount==="function") ? rungCount("product","rep") : 0;
  let c = 19;
  if(supply>0) c *= 0.94;              // supply chain staff negotiate freight
  c *= Math.max(0.82, 1 - 0.01*Math.min(buyers,8)); // buyers negotiate cost of goods
  return c;
}
function v26ShrinkRate(){
  const c = v26Co();
  const ops = (typeof rungCount==="function") ? rungCount("operations","rep") : 0;
  const loss = (typeof deptHas==="function" && deptHas("operations","manager")) ? 0.008 : 0.019;
  return Math.max(0.003, loss - 0.001*Math.min(ops,6));
}
function v26LeadTime(){
  const ops = (typeof rungCount==="function") ? rungCount("operations","rep") : 0;
  if(typeof deptHas==="function" && deptHas("operations","coo")) return 0;
  return ops>=3 ? 0 : 1;
}
function opsResolveRetail(co, report){
  const o = co.ops;
  if(!o || !o.stores || o.stores.length===0){ if(o){ o.lastNet=0; o.lastGross=0; } return 0; }
  o.stores.forEach(v26StoreInit);
  const assoc = rungCount("sales","rep");
  const merch = rungCount("product","rep");
  const price = 42 * o.priceTier;
  const unitCost = v26UnitCost();
  const elasticity = o.priceTier>1.1 ? 0.8 : o.priceTier<0.95 ? 1.18 : 1;
  const season = v26SeasonFactor();
  const shrinkRate = v26ShrinkRate();
  const lead = v26LeadTime();
  let gross=0, cogs=0, rent=0, sold=0, lostUnits=0, stockouts=0, shrinkUnits=0, reorderSpend=0, reorderUnits=0;
  o.stores.forEach(s=>{
    rent += s.rent;
    // receive inbound shipments
    s.inbound = (s.inbound||[]).filter(sh=>{
      sh.arrivesIn -= 1;
      if(sh.arrivesIn<=0){ s.unitsOnHand += sh.units; return false; }
      return true;
    });
    // shrinkage: theft, damage, spoilage
    const shrunk = Math.floor(s.unitsOnHand * shrinkRate * randf(0.6,1.5));
    s.unitsOnHand = Math.max(0, s.unitsOnHand - shrunk);
    shrinkUnits += shrunk;
    const staffed = 1 + 0.045*assoc + 0.03*merch;
    const demand = Math.round(s.baseDemand * staffed * (1+marketingBoost()) * elasticity * season * randf(0.9,1.12) * (0.7 + o.satisfaction/200));
    const units = Math.min(demand, s.unitsOnHand);
    sold += units;
    s.unitsOnHand -= units;
    gross += units*price; cogs += units*unitCost;
    s.lastDemand = demand; s.lastSold = units;
    if(demand > units){ stockouts++; lostUnits += (demand - units); }
    // auto replenishment
    if(s.autoReorder){
      const incoming = (s.inbound||[]).reduce((a,b)=>a+b.units,0);
      if(s.unitsOnHand + incoming <= s.reorderPoint){
        const cost = Math.round(s.reorderQty * unitCost);
        if((co.cash||0) - reorderSpend >= cost){
          reorderSpend += cost; reorderUnits += s.reorderQty;
          if(lead<=0) s.unitsOnHand += s.reorderQty;
          else s.inbound.push({ units:s.reorderQty, arrivesIn:lead, cost });
        }
      }
    }
    s.inventory = Math.round(s.unitsOnHand * unitCost); // keep legacy field meaningful
  });
  if(reorderSpend>0){
    co.cash -= reorderSpend;
    report.push(`\u{1F4E6} Auto-replenishment bought ${reorderUnits.toLocaleString()} units for ${fmt$(reorderSpend)}${v26LeadTime()>0?" (arrives next month)":""}.`);
  }
  if(shrinkUnits>0) report.push(`\u{1F575}\uFE0F Shrinkage: ${shrinkUnits.toLocaleString()} units (${(shrinkRate*100).toFixed(1)}%/mo) written off \u2014 ${fmt$(shrinkUnits*unitCost)} of goods gone.`);
  if(stockouts>0){
    o.satisfaction = clamp(o.satisfaction - 4*stockouts, 0, 100);
    report.push(`\u{1F6CD}\uFE0F ${stockouts} store(s) stocked out \u2014 ${lostUnits.toLocaleString()} units of demand lost (${fmt$(lostUnits*price)} of sales). Satisfaction ${o.satisfaction}.`);
  } else {
    o.satisfaction = clamp(o.satisfaction + 2, 0, 100);
  }
  const net = Math.round(gross - cogs - rent);
  o.lastGross = Math.round(gross); o.lastNet = net;
  o.lastSeason = season; o.lastLost = lostUnits; o.lastShrink = shrinkUnits;
  o.lastMargin = gross>0 ? (gross-cogs)/gross : 0;
  report.push(`\u{1F6CD}\uFE0F ${v26SeasonName()} (${Math.round(season*100)}% traffic): sold ${sold.toLocaleString()} units for ${fmt$(gross)} \u00b7 COGS ${fmt$(cogs)} \u00b7 rent ${fmt$(rent)} \u2192 ${fmt$(net)}.`);
  return net;
}
function v26RetailPanel(){
  const co = v26Co(); if(!co || !co.ops || co.ops.type!=="retail") return null;
  const o = co.ops; o.stores.forEach(v26StoreInit);
  const unitCost = v26UnitCost(), price = 42*o.priceTier, lead = v26LeadTime();
  const onHand = o.stores.reduce((a,s)=>a+s.unitsOnHand,0);
  const inbound = o.stores.reduce((a,s)=>a+(s.inbound||[]).reduce((x,y)=>x+y.units,0),0);
  const wrap = document.createElement("div");
  wrap.className = "card mb14";
  wrap.innerHTML = `<h3>\u{1F4CA} Inventory & Demand Planning</h3>
  <div class="v26-kpi">
    <div class="k"><div class="lbl">Season (${v26SeasonName()})</div><div class="val">${Math.round(v26SeasonFactor()*100)}%</div></div>
    <div class="k"><div class="lbl">Unit economics</div><div class="val">${v26Money(price-unitCost)}</div><div class="lbl">${v26Money(price)} price \u2212 ${v26Money(unitCost)} cost</div></div>
    <div class="k"><div class="lbl">Units on hand</div><div class="val">${onHand.toLocaleString()}</div><div class="lbl">${inbound.toLocaleString()} in transit</div></div>
    <div class="k"><div class="lbl">Shrinkage</div><div class="val">${(v26ShrinkRate()*100).toFixed(1)}%/mo</div><div class="lbl">Last: ${(o.lastShrink||0).toLocaleString()} units</div></div>
    <div class="k"><div class="lbl">Lost sales</div><div class="val ${(o.lastLost||0)>0?"v26-warn":"v26-good"}">${(o.lastLost||0).toLocaleString()}</div><div class="lbl">units last month</div></div>
  </div>
  <div class="muted" style="font-size:12px;">Lead time is <b>${lead===0?"same month":"1 month"}</b> \u2014 3+ supply chain associates or a COO removes the delay. Supply chain staff and buyers cut unit cost; an Ops Manager cuts shrinkage.</div>
  ${o.stores.map(s=>{
    const cover = s.lastDemand ? (s.unitsOnHand/Math.max(1,s.lastDemand)).toFixed(1) : "\u2014";
    return `<div class="ladder-card" style="margin-top:8px;"><div class="title">\u{1F3EC} ${s.name}</div>
      <div class="desc">${s.unitsOnHand.toLocaleString()} units on hand \u00b7 ${cover} months of cover \u00b7 last month sold ${(s.lastSold||0).toLocaleString()} of ${(s.lastDemand||0).toLocaleString()} demanded${(s.inbound||[]).length?` \u00b7 <span class="v26-chip">${(s.inbound||[]).reduce((a,b)=>a+b.units,0)} in transit</span>`:""}</div>
      <div class="v26-row">
        <label>Reorder at <input type="number" min="0" value="${s.reorderPoint}" data-v26rp="${s.id}"> units</label>
        <label>Order qty <input type="number" min="1" value="${s.reorderQty}" data-v26rq="${s.id}"> units</label>
        <button class="btn ${s.autoReorder?"":"secondary"} small" data-v26auto="${s.id}">${s.autoReorder?"\u2713 Auto-reorder on":"Auto-reorder off"}</button>
        <button class="btn secondary small" data-v26buy="${s.id}:${s.reorderQty}">Buy ${s.reorderQty} units (${v26Money(s.reorderQty*unitCost)})</button>
      </div></div>`;
  }).join("")}`;
  wrap.querySelectorAll("[data-v26rp]").forEach(i=> i.onchange = ()=>{
    const s = o.stores.find(x=>x.id===i.getAttribute("data-v26rp")); if(s) s.reorderPoint = Math.max(0, Math.round(Number(i.value)||0));
  });
  wrap.querySelectorAll("[data-v26rq]").forEach(i=> i.onchange = ()=>{
    const s = o.stores.find(x=>x.id===i.getAttribute("data-v26rq")); if(s) s.reorderQty = Math.max(1, Math.round(Number(i.value)||1));
    renderScreen();
  });
  wrap.querySelectorAll("[data-v26auto]").forEach(b=> b.onclick = ()=>{
    const s = o.stores.find(x=>x.id===b.getAttribute("data-v26auto")); if(!s) return;
    s.autoReorder = !s.autoReorder; renderScreen();
  });
  wrap.querySelectorAll("[data-v26buy]").forEach(b=> b.onclick = ()=>{
    const p = b.getAttribute("data-v26buy").split(":");
    const s = o.stores.find(x=>x.id===p[0]); if(!s) return;
    const units = Math.max(1, Number(p[1])||1);
    const cost = Math.round(units * v26UnitCost());
    if(typeof opsSpend==="function" ? !opsSpend(cost, `Purchase order for ${s.name}`) : (co.cash<cost)){ return; }
    if(typeof opsSpend!=="function") co.cash -= cost;
    const lead2 = v26LeadTime();
    if(lead2<=0) s.unitsOnHand += units; else s.inbound.push({ units, arrivesIn:lead2, cost });
    s.inventory = Math.round(s.unitsOnHand * v26UnitCost());
    if(typeof toast==="function") toast(`Ordered ${units} units for ${s.name}${lead2>0?" \u2014 arrives next month":""}.`, "good");
    renderAll();
  });
  return wrap;
}
(function v26IndustryPanel(){
  try{
    if(typeof renderIndustryOps !== "function") return;
    const prev = renderIndustryOps;
    renderIndustryOps = function(){
      const wrap = prev.apply(this, arguments);
      try{ const p = v26RetailPanel(); if(p && wrap && wrap.appendChild) wrap.appendChild(p); }catch(e){}
      return wrap;
    };
  }catch(e){}
})();

/* ---------- 2. Event fatigue ---------- */
function v26EventFatigue(key){
  try{
    const c = v26Co(); if(!c) return 1;
    const now = (c.year||1)*12 + (c.month||1);
    const runs = (c.eventsRun||[]).filter(r=>r.key===key).map(r=>r.year*12 + r.month);
    const last = runs.length ? Math.max.apply(null, runs) : null;
    if(last===null) return 1;
    const gap = now - last;
    if(gap >= 12) return 1;
    if(gap >= 6) return 0.75;
    if(gap >= 3) return 0.5;
    return 0.3;
  }catch(e){ return 1; }
}
(function v26PatchEvents(){
  try{
    if(typeof v25RunEvent !== "function") return;
    v25RunEvent = function(key){
      const c = v26Co(); if(!c) return;
      const ev = V25_EVENTS.find(x=>x.key===key); if(!ev) return;
      if(v25EngagementCount() < ev.eng){ v25Toast(`${ev.name} needs ${ev.eng} engagement specialists on payroll.`, "bad"); return; }
      if(v25EventThisMonth()){ v25Toast("You've already run an event this month.", "bad"); return; }
      const cost = v25EventCost(ev);
      if((c.cash||0) < cost){ v25Toast(`Not enough cash for ${ev.name} (${v26Money(cost)}).`, "bad"); return; }
      const fatigue = v26EventFatigue(key);
      const lift = Math.max(1, Math.round(ev.morale * fatigue));
      c.cash -= cost;
      (c.employees||[]).forEach(e=>{ e.morale = clamp((e.morale||60)+lift, 0, 100); });
      c.lastEventStamp = c.year*12 + c.month;
      (c.eventsRun = c.eventsRun || []).push({ key:ev.key, month:c.month, year:c.year, cost });
      try{ logHistory(`${ev.icon} ${ev.name} \u2014 ${fmt$(cost)}, +${lift} morale${fatigue<1?" (repeat event, reduced impact)":""}.`); }catch(e){}
      v25Toast(fatigue<1 ? `${ev.name} again? +${lift} morale \u2014 the team has seen this one recently.` : `${ev.name} was a hit. +${lift} morale.`, fatigue<0.6?"warn":"good");
      try{ renderAll(); }catch(e){}
    };
    if(typeof v25EventsCard === "function"){
      const prevCard = v25EventsCard;
      v25EventsCard = function(){
        const card = prevCard.apply(this, arguments);
        try{
          card.querySelectorAll("[data-v25ev]").forEach(b=>{
            const key = b.getAttribute("data-v25ev");
            const f = v26EventFatigue(key);
            if(f<1 && !b.disabled){
              b.textContent = `Run (${Math.round(f*100)}% impact)`;
              b.title = "The team has done this recently \u2014 morale payoff is reduced. Mix it up.";
            }
          });
          const note = document.createElement("div");
          note.className = "muted";
          note.style.cssText = "font-size:11.5px;margin-top:6px;";
          note.textContent = "Event fatigue: repeating an event within 3 / 6 / 12 months pays 30% / 50% / 75% of the morale bump. Variety wins.";
          card.appendChild(note);
        }catch(e){}
        return card;
      };
    }
  }catch(e){}
})();

/* ---------- 3. Engagement specialists: passive retention + recruiting ---------- */
function v26EngagementPerks(){
  const n = (typeof v25EngagementCount==="function") ? v25EngagementCount() : 0;
  return {
    count: n,
    morale: Math.min(4, Math.floor(n/2)),            // passive monthly morale
    quitCut: Math.min(0.6, 0.12*n),                   // fraction of attrition events prevented
    hireBoost: Math.min(12, 2*n)                      // starting performance for new hires
  };
}
(function v26HireBoost(){
  try{
    if(typeof hire !== "function") return;
    const prev = hire;
    hire = function(){
      const emp = prev.apply(this, arguments);
      try{
        const p = v26EngagementPerks();
        if(emp && p.hireBoost>0){
          emp.performance = clamp((emp.performance||70) + p.hireBoost, 0, 100);
          emp.morale = clamp((emp.morale||70) + Math.round(p.hireBoost/2), 0, 100);
        }
      }catch(e){}
      return emp;
    };
  }catch(e){}
})();
(function v26RetentionShield(){
  try{
    if(typeof fireEmployee !== "function") return;
    const prev = fireEmployee;
    fireEmployee = function(id){
      try{
        if(window.__v26VoluntaryExit){
          const p = v26EngagementPerks();
          if(p.quitCut>0 && Math.random() < p.quitCut){
            const emp = (v26Co().employees||[]).find(x=>x.id===id);
            if(emp){
              emp.morale = clamp((emp.morale||50)+18, 0, 100);
              try{ logHistory(`${emp.name} was about to walk \u2014 the engagement team talked them into staying.`); }catch(e){}
              return;
            }
          }
        }
      }catch(e){}
      return prev.apply(this, arguments);
    };
  }catch(e){}
})();
(function v26MonthlyEngagement(){
  try{
    if(typeof advanceMonth !== "function") return;
    const prev = advanceMonth;
    advanceMonth = function(){
      window.__v26VoluntaryExit = true;
      let out;
      try{ out = prev.apply(this, arguments); }
      finally{ window.__v26VoluntaryExit = false; }
      try{
        const p = v26EngagementPerks();
        if(p.morale>0){
          (v26Co().employees||[]).forEach(e=>{ e.morale = clamp((e.morale||60)+p.morale, 0, 100); });
        }
      }catch(e){}
      return out;
    };
  }catch(e){}
})();

/* ---------- 4. One executive per seat, hard cap on batches ---------- */
function v26IsCsuite(rung){
  try{ return (typeof CSUITE_RUNGS!=="undefined") && CSUITE_RUNGS.indexOf(rung)>=0; }catch(e){ return false; }
}
function v26SeatTaken(dept, rung){
  try{
    const c = v26Co(); if(!c) return false;
    const have = (c.employees||[]).filter(e=>e.dept===dept && e.rung===rung).length;
    const queued = ((G.ui&&G.ui.queue)||[]).filter(q=>q.hireDept===dept && q.hireRung===rung)
      .reduce((a,q)=>a+(q.hireQty||1),0);
    return (have + queued) >= 1;
  }catch(e){ return false; }
}
(function v26CsuiteCap(){
  try{
    if(typeof v16QueueHires === "function"){
      const prev = v16QueueHires;
      v16QueueHires = function(deptKey, rungKey, want){
        if(v26IsCsuite(rungKey)){
          if(v26SeatTaken(deptKey, rungKey)){
            if(typeof toast==="function") toast("<b>That executive seat is filled.</b> One officer per function \u2014 let them go first.", "warn");
            return;
          }
          want = 1;
        }
        return prev.call(this, deptKey, rungKey, want);
      };
    }
    if(typeof queueAdd === "function"){
      const prevAdd = queueAdd;
      queueAdd = function(item){
        try{
          if(item && item.hireRung && v26IsCsuite(item.hireRung)){
            if(v26SeatTaken(item.hireDept, item.hireRung)){
              if(typeof toast==="function") toast("<b>One officer per function.</b> That seat is already filled or queued.", "warn");
              return;
            }
            item.hireQty = 1;
            item.label = item.label ? item.label.replace(/^Hire \d+ \u00d7 /, "Hire 1 \u00d7 ") : item.label;
          }
        }catch(e){}
        return prevAdd.apply(this, arguments);
      };
    }
    if(typeof hire === "function"){
      const prevHire = hire;
      hire = function(deptKey, rungKey){
        if(v26IsCsuite(rungKey)){
          const c = v26Co();
          const have = c ? (c.employees||[]).filter(e=>e.dept===deptKey && e.rung===rungKey).length : 0;
          if(have >= 1) return null; // silently refuse duplicates from legacy batch loops
        }
        return prevHire.apply(this, arguments);
      };
    }
  }catch(e){}
})();

/* ---------- 5. Fire executives straight from the C-suite screen ---------- */
function v26FireExec(id){
  const c = v26Co(); if(!c) return;
  const e = (c.employees||[]).find(x=>x.id===id); if(!e) return;
  const sev = Math.round((e.salary||0) * 3);
  const overlay = document.getElementById("modalOverlay"), box = document.getElementById("modalBox");
  const run = ()=>{
    if((c.cash||0) < sev){ if(typeof toast==="function") toast(`You need ${v26Money(sev)} for the severance package.`, "bad"); return; }
    c.cash -= sev;
    try{ fireEmployee(e.id); }catch(err){}
    try{ c.successScore = clamp((c.successScore||55)-2, 0, 100); }catch(err){}
    (c.employees||[]).forEach(x=>{ if(typeof isLeader==="function" && isLeader(x)) x.morale = clamp((x.morale||60)-4,0,100); });
    try{ logHistory(`Removed ${e.name} as ${e.role}. Severance ${fmt$(sev)}.`); }catch(err){}
    if(typeof toast==="function") toast(`${e.name} is out as ${e.role}. Severance ${v26Money(sev)} paid.`, "warn");
    try{ renderAll(); }catch(err){}
  };
  if(!overlay || !box){ if(confirm(`Remove ${e.name} as ${e.role}? Severance ${v26Money(sev)}.`)) run(); return; }
  box.innerHTML = `<span class="close" id="v26FireX">&times;</span>
    <h3>\u{1F6AA} Remove ${e.name}?</h3>
    <div class="muted mb8" style="font-size:12.5px;">${e.role} \u00b7 ${v26Money(e.salary)}/mo \u00b7 P${e.performance} \u00b7 M${e.morale}</div>
    <div class="muted" style="font-size:12.5px;">Executive exits are expensive and visible: <b>${v26Money(sev)}</b> severance (3 months), \u22122 success score, and a morale hit across your remaining leadership. The seat reopens immediately.</div>
    <div style="display:flex;gap:8px;margin-top:14px;justify-content:flex-end;">
      <button class="btn secondary" id="v26FireNo">Keep them</button>
      <button class="btn danger" id="v26FireYes">Pay ${v26Money(sev)} & remove</button>
    </div>`;
  overlay.classList.add("show"); overlay.style.removeProperty("display");
  const close = ()=>{ overlay.classList.remove("show"); overlay.style.display = "none"; };
  box.querySelector("#v26FireX").onclick = close;
  box.querySelector("#v26FireNo").onclick = close;
  box.querySelector("#v26FireYes").onclick = ()=>{ close(); run(); };
}
(function v26CsuiteFireButtons(){
  try{
    if(typeof v23RenderCsuite !== "function") return;
    const prev = v23RenderCsuite;
    v23RenderCsuite = function(){
      const wrap = prev.apply(this, arguments);
      try{
        wrap.querySelectorAll("[data-v23execopen]").forEach(openBtn=>{
          const id = openBtn.getAttribute("data-v23execopen");
          const b = document.createElement("button");
          b.className = "btn danger small";
          b.textContent = "Let go";
          b.onclick = ()=> v26FireExec(id);
          openBtn.parentNode.insertBefore(b, openBtn.nextSibling);
        });
      }catch(e){}
      return wrap;
    };
  }catch(e){}
})();

