/* ================= v28 — Storage-Proof Saves & Save Codes =================
   The Notion mobile app renders this file in a sandboxed iframe where
   localStorage is often partitioned or blocked outright. When that happens the
   game cannot read OR write saves, so the load list is legitimately empty.
   v28 adds: (1) an in-memory storage fallback so a session still works,
   (2) portable save codes that carry a whole run as text, and (3) clear
   messaging so the player knows which mode they are in. */

const V28_MEM = {};
let V28_STORAGE_OK = null;
function v28StorageOk(){
  if(V28_STORAGE_OK !== null) return V28_STORAGE_OK;
  try{
    localStorage.setItem("__v28probe", "1");
    V28_STORAGE_OK = localStorage.getItem("__v28probe") === "1";
    localStorage.removeItem("__v28probe");
  }catch(e){ V28_STORAGE_OK = false; }
  return V28_STORAGE_OK;
}
function v28Get(k){
  if(v28StorageOk()){ try{ const v = localStorage.getItem(k); if(v !== null) return v; }catch(e){} }
  return Object.prototype.hasOwnProperty.call(V28_MEM, k) ? V28_MEM[k] : null;
}
function v28Set(k, v){
  V28_MEM[k] = v;
  if(v28StorageOk()){ try{ localStorage.setItem(k, v); }catch(e){} }
}
function v28Del(k){
  delete V28_MEM[k];
  try{ localStorage.removeItem(k); }catch(e){}
}

/* ---------- Persistence rebuilt on the resilient layer ---------- */
(function v28Persistence(){
  try{
    saveToSlot = function(state, slotKey, label){
      try{
        v28Set(slotKey, JSON.stringify(state));
        let idx = JSON.parse(v28Get(LS_SLOTS_INDEX) || "[]");
        idx = idx.filter(s=>s.key !== slotKey);
        idx.push({ key:slotKey, label: label || (state.meta && state.meta.name) || "Saved game",
          savedAt: Date.now(), month: state.company.month, year: state.company.year, cash: state.company.cash });
        v28Set(LS_SLOTS_INDEX, JSON.stringify(idx));
      }catch(e){}
    };
    listSlots = function(){
      try{ return JSON.parse(v28Get(LS_SLOTS_INDEX) || "[]").sort((a,b)=>b.savedAt - a.savedAt); }
      catch(e){ return []; }
    };
    loadSlot = function(key){
      try{ const raw = v28Get(key); return raw ? JSON.parse(raw) : null; }catch(e){ return null; }
    };
    deleteSlot = function(key){
      try{
        v28Del(key);
        let idx = JSON.parse(v28Get(LS_SLOTS_INDEX) || "[]");
        idx = idx.filter(s=>s.key !== key);
        v28Set(LS_SLOTS_INDEX, JSON.stringify(idx));
      }catch(e){}
    };
  }catch(e){}
})();

/* ---------- Portable save codes ---------- */
const V28_CODE_PREFIX = "NAVSAVE1";
function v28B64FromBytes(bytes){
  let bin = "";
  const chunk = 0x8000;
  for(let i=0;i<bytes.length;i+=chunk) bin += String.fromCharCode.apply(null, bytes.subarray(i, i+chunk));
  return btoa(bin);
}
function v28BytesFromB64(b64){
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for(let i=0;i<bin.length;i++) out[i] = bin.charCodeAt(i);
  return out;
}
async function v28ExportCode(state){
  const json = JSON.stringify(state || G);
  let bytes = new TextEncoder().encode(json);
  let tag = "R";
  if(typeof CompressionStream !== "undefined"){
    try{
      const stream = new Blob([bytes]).stream().pipeThrough(new CompressionStream("gzip"));
      bytes = new Uint8Array(await new Response(stream).arrayBuffer());
      tag = "Z";
    }catch(e){ bytes = new TextEncoder().encode(json); tag = "R"; }
  }
  return V28_CODE_PREFIX + tag + "-" + v28B64FromBytes(bytes);
}
async function v28ImportCode(code){
  let s = String(code || "").replace(/\s+/g, "");
  const i = s.indexOf(V28_CODE_PREFIX);
  if(i < 0) throw new Error("That doesn't look like a NAVigating Business save code.");
  s = s.slice(i);
  const tag = s.charAt(V28_CODE_PREFIX.length);
  const dash = s.indexOf("-");
  if(dash < 0) throw new Error("Save code is incomplete.");
  let bytes = v28BytesFromB64(s.slice(dash + 1));
  if(tag === "Z"){
    if(typeof DecompressionStream === "undefined") throw new Error("This browser can't unpack compressed save codes.");
    const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream("gzip"));
    bytes = new Uint8Array(await new Response(stream).arrayBuffer());
  }
  const state = JSON.parse(new TextDecoder().decode(bytes));
  const hasCo = !!state && ((Array.isArray(state.companies) && state.companies.length) || state.company);
  if(!hasCo) throw new Error("Save code parsed but contained no company.");
  return state;
}
async function v28CopyText(text){
  try{ await navigator.clipboard.writeText(text); return true; }
  catch(e){
    try{
      const ta = document.createElement("textarea");
      ta.value = text;
      ta.style.cssText = "position:fixed;left:-9999px;top:0;";
      document.body.appendChild(ta);
      ta.select();
      const ok = document.execCommand("copy");
      ta.remove();
      return ok;
    }catch(e2){ return false; }
  }
}
async function v28ApplyCode(code){
  const state = await v28ImportCode(code);
  G = normalizeGame(state);
  if(!G || !G.company) throw new Error("Save code loaded but the company data was unreadable.");
  if(typeof applyIndustryLabels === "function") applyIndustryLabels();
  try{ saveToSlot(G, (typeof LS_PREFIX==="string"?LS_PREFIX:"besim2_") + "slot_imported", "\u{1F4E5} Imported \u2014 " + (G.company.name || "Company")); }catch(e){}
  const ob = document.getElementById("onboard");
  if(ob) ob.style.display = "none";
  renderAll();
}

