/* ---------- Start screen: paste a save code + storage warning ---------- */
(function v28Onboard(){
  try{
    if(typeof renderOnboard !== "function") return;
    const prev = renderOnboard;
    renderOnboard = function(){
      prev.apply(this, arguments);
      try{
        const ob = document.getElementById("onboard");
        const card = ob && ob.querySelector(".ob-card");
        if(!card || card.querySelector(".v28-obcode")) return;

        const box = document.createElement("div");
        box.className = "v28-obcode";
        box.innerHTML = `
          <div class="v28-hd">\u{1F511} Have a save code?</div>
          <button class="v28-toggle" data-v28open="1">Paste a save code to restore a run</button>
          <div id="v28ObPanel" style="display:none;margin-top:8px;">
            <textarea class="v28-code" id="v28ObCode" placeholder="NAVSAVE1Z-..."></textarea>
            <button class="btn small" id="v28ObLoad" style="margin-top:8px;width:100%;">Restore this run</button>
            <div class="muted" style="font-size:11px;margin-top:6px;">Save codes work across devices and every future version \u2014 no browser storage needed.</div>
          </div>`;

        const resume = card.querySelector(".v27-resume");
        const sub = card.querySelector("p.sub");
        if(resume && resume.parentNode) resume.parentNode.insertBefore(box, resume.nextSibling);
        else if(sub && sub.parentNode) sub.parentNode.insertBefore(box, sub.nextSibling);
        else card.insertBefore(box, card.firstChild);

        box.querySelector("[data-v28open]").onclick = ()=>{
          const p = document.getElementById("v28ObPanel");
          if(p) p.style.display = p.style.display === "none" ? "block" : "none";
        };
        box.querySelector("#v28ObLoad").onclick = async ()=>{
          const ta = document.getElementById("v28ObCode");
          try{ await v28ApplyCode(ta.value); if(typeof toast==="function") toast("Run restored from save code.","good"); }
          catch(e){ alert("Couldn't read that save code.\n\n" + (e && e.message ? e.message : e)); }
        };

        if(!v28StorageOk()){
          const warn = document.createElement("div");
          warn.className = "v28-warn";
          warn.innerHTML = `<b>\u26A0\uFE0F This app can't save to browser storage.</b><br>
            You're likely in the Notion mobile app, which blocks storage inside embeds. Your run will work
            for this session but won't be remembered after you close it. Use <b>Save Games \u2192 Copy save code</b>
            and paste that code back in here to continue later or on another device.`;
          box.parentNode.insertBefore(warn, box);
        }
      }catch(e){}
    };
  }catch(e){}
})();

/* ---------- Save Games screen: export/import codes ---------- */
(function v28SavesScreen(){
  try{
    if(typeof renderSaves !== "function") return;
    const prev = renderSaves;
    renderSaves = function(){
      const wrap = prev.apply(this, arguments);
      try{
        if(!wrap || wrap.querySelector(".v28-codecard")) return wrap;

        if(!v28StorageOk()){
          const warn = document.createElement("div");
          warn.className = "v28-warn";
          warn.innerHTML = `<b>\u26A0\uFE0F Browser storage is blocked here.</b><br>
            Slots below live in memory only for this session \u2014 closing the app loses them.
            Copy a <b>save code</b> below and keep it somewhere safe (a Notion page works well).`;
          wrap.insertBefore(warn, wrap.children[1] || null);
        }

        const card = document.createElement("div");
        card.className = "card mt14 v28-codecard";
        card.innerHTML = `
          <h3>\u{1F511} Save codes \u2014 portable, storage-free</h3>
          <div class="muted" style="font-size:11.5px;margin-bottom:8px;">
            A save code is your entire run as text. It survives app restarts, device changes and every future version.
          </div>
          <textarea class="v28-code" id="v28OutCode" readonly placeholder="Tap Generate to build your code"></textarea>
          <div class="flexrow" style="margin-top:8px;gap:8px;">
            <button class="btn small" id="v28Gen">Generate</button>
            <button class="btn secondary small" id="v28Copy">Copy save code</button>
          </div>
          <div style="border-top:1px solid var(--border);margin-top:12px;padding-top:10px;">
            <h3>Restore from a code</h3>
            <textarea class="v28-code" id="v28InCode" placeholder="NAVSAVE1Z-..."></textarea>
            <button class="btn small" id="v28Import" style="margin-top:8px;">Restore this run</button>
          </div>`;
        wrap.appendChild(card);

        const outEl = ()=>card.querySelector("#v28OutCode");
        const gen = async ()=>{
          const code = await v28ExportCode(G);
          outEl().value = code;
          return code;
        };
        card.querySelector("#v28Gen").onclick = async ()=>{
          try{ const c = await gen(); if(typeof toast==="function") toast(`Save code ready \u2014 ${c.length.toLocaleString()} characters.`,"good"); }
          catch(e){ if(typeof toast==="function") toast("Couldn't build a save code.","bad"); }
        };
        card.querySelector("#v28Copy").onclick = async ()=>{
          try{
            const code = outEl().value || await gen();
            const ok = await v28CopyText(code);
            if(typeof toast==="function") toast(ok ? "Save code copied. Paste it somewhere safe." : "Copy blocked \u2014 select the text and copy manually.", ok?"good":"warn");
          }catch(e){}
        };
        card.querySelector("#v28Import").onclick = async ()=>{
          try{
            await v28ApplyCode(card.querySelector("#v28InCode").value);
            if(typeof toast==="function") toast("Run restored from save code.","good");
          }catch(e){ alert("Couldn't read that save code.\n\n" + (e && e.message ? e.message : e)); }
        };
      }catch(e){}
      return wrap;
    };
  }catch(e){}
})();

