const V29_MONTHS = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
function v29Co(){ try{ return (G && G.company) ? G.company : null; }catch(e){ return null; } }
function v29Money(n){ try{ return fmt$(Math.round(n||0)); }catch(e){ return "$" + Math.round(n||0); } }
function v29Short(n){
  const v = Math.round(n||0), a = Math.abs(v), sg = v<0 ? "-" : "";
  if(a >= 1e9) return sg + "$" + (a/1e9).toFixed(a>=1e10?0:1) + "B";
  if(a >= 1e6) return sg + "$" + (a/1e6).toFixed(a>=1e7?0:1) + "M";
  if(a >= 1e4) return sg + "$" + Math.round(a/1e3) + "K";
  return v29Money(v);
}
function v29Ui(){ if(!G.ui) G.ui = {}; if(!G.ui.v29) G.ui.v29 = { scope:"company", hist:[] }; if(!G.ui.v29.hist) G.ui.v29.hist = []; return G.ui.v29; }
function v29Snap(){
  const c = v29Co(); if(!c) return null;
  const cs = (typeof corporateSnapshot==="function") ? corporateSnapshot() : { revenue:c.mrr||0, expenses:0, net:0, worth:c.netWorth||0, cash:c.cash||0 };
  const ps = (typeof personalSnapshot==="function") ? personalSnapshot() : { cash:0, net:0, worth:0, expenses:0 };
  return {
    stamp: (c.year||1)*100 + (c.month||1),
    cash: c.cash||0, rev: cs.revenue||0, exp: cs.expenses||0, net: cs.net||0,
    heads: (c.employees||[]).length, worth: cs.worth||0,
    pcash: ps.cash||0, pnet: ps.net||0, pworth: ps.worth||0, pexp: ps.expenses||0
  };
}
function v29Track(){
  try{
    const u = v29Ui(), s = v29Snap();
    if(!s) return;
    const last = u.hist[u.hist.length-1];
    if(last && last.stamp === s.stamp) u.hist[u.hist.length-1] = s;
    else u.hist.push(s);
    if(u.hist.length > 25) u.hist = u.hist.slice(-25);
  }catch(e){}
}
function v29Prev(){
  const u = v29Ui();
  const s = v29Snap();
  if(!s) return null;
  for(let i = u.hist.length - 1; i >= 0; i--) if(u.hist[i].stamp !== s.stamp) return u.hist[i];
  return null;
}
function v29Delta(cur, prev, opts){
  const o = opts || {};
  if(prev === undefined || prev === null) return `<div class="dl flat">\u00b7</div>`;
  const d = (cur||0) - (prev||0);
  if(Math.abs(d) < (o.eps || 0.5)) return `<div class="dl flat">no change</div>`;
  const good = o.invert ? d < 0 : d > 0;
  const arrow = d > 0 ? "\u25B2" : "\u25BC";
  const txt = o.raw ? Math.abs(d).toLocaleString() : v29Short(Math.abs(d)).replace("-","");
  return `<div class="dl ${good?"good":"bad"}">${arrow} ${txt}</div>`;
}
function v29Spark(key){
  try{
    const u = v29Ui();
    const pts = u.hist.slice(-10).map(h=>h[key]||0);
    if(pts.length < 3) return "";
    const min = Math.min.apply(null, pts), max = Math.max.apply(null, pts);
    const span = (max - min) || 1;
    return `<div class="v29-spark">${pts.map((p,i)=>{
      const h = Math.max(1, Math.round(((p - min)/span)*13));
      return `<i class="${i===pts.length-1?"last":""}" style="height:${h}px;"></i>`;
    }).join("")}</div>`;
  }catch(e){ return ""; }
}
function v29Runway(){
  const c = v29Co(); if(!c) return null;
  const cs = (typeof corporateSnapshot==="function") ? corporateSnapshot() : null;
  const net = cs ? cs.net : 0;
  if(net >= 0) return { months: Infinity, pct: 100, cls:"" };
  const months = (c.cash||0) / Math.abs(net);
  return { months, pct: Math.max(2, Math.min(100, Math.round((months/18)*100))), cls: months < 3 ? "bad" : months < 7 ? "warn" : "" };
}

/* ---------- The cockpit header ---------- */
function v29Tile(o){
  return `<div class="v29-t ${o.tab||o.onclick?"click":""}" ${o.tab?`data-v29tab="${o.tab}"`:""} title="${o.title||""}">
    <div class="lb">${o.label}</div>
    <div class="vl ${o.cls||""}">${o.value}</div>
    ${o.delta||""}${o.spark||""}</div>`;
}
function v29RenderHeader(){
  const c = v29Co(); if(!c) return;
  try{ if(typeof recomputeMRR==="function") recomputeMRR(); }catch(e){}
  v29Track();
  const u = v29Ui();
  const scope = u.scope === "personal" ? "personal" : "company";
  const cfg = (typeof industry==="function") ? industry() : { icon:"\u{1F4BC}" };
  const cs = (typeof corporateSnapshot==="function") ? corporateSnapshot() : { revenue:0, expenses:0, net:0, worth:0 };
  const ps = (typeof personalSnapshot==="function") ? personalSnapshot() : { cash:0, net:0, worth:0, expenses:0 };
  const cap = (typeof headcountCap==="function") ? headcountCap() : 0;
  const prev = v29Prev();
  const multi = G.companies && G.companies.length > 1;
  const rw = v29Runway();

  const tiles = scope === "company" ? [
    v29Tile({ label:"Cash", value:v29Short(c.cash), cls:c.cash<0?"bad":"", tab:"financials",
      delta:v29Delta(c.cash, prev&&prev.cash), spark:v29Spark("cash"), title:"Company cash \u2014 open Financials" }),
    v29Tile({ label:"Revenue / mo", value:v29Short(cs.revenue), cls:"good", tab:"financials",
      delta:v29Delta(cs.revenue, prev&&prev.rev), spark:v29Spark("rev") }),
    v29Tile({ label:"Profit / mo", value:v29Short(cs.net), cls:cs.net<0?"bad":"good", tab:"financials",
      delta:v29Delta(cs.net, prev&&prev.net), spark:v29Spark("net") }),
    v29Tile({ label:"Team", value:`${(c.employees||[]).length}<span style="font-size:11px;color:var(--muted);">/${cap}</span>`,
      cls:(c.employees||[]).length>=cap?"bad":"", tab:"facilities",
      delta:v29Delta((c.employees||[]).length, prev&&prev.heads, { raw:true, eps:0.5 }), title:"Headcount vs capacity \u2014 open Facilities" })
  ] : [
    v29Tile({ label:"Personal cash", value:v29Short(ps.cash), tab:"personal",
      delta:v29Delta(ps.cash, prev&&prev.pcash), spark:v29Spark("pcash") }),
    v29Tile({ label:"Net / mo", value:v29Short(ps.net), cls:ps.net<0?"bad":"good", tab:"personal",
      delta:v29Delta(ps.net, prev&&prev.pnet), spark:v29Spark("pnet") }),
    v29Tile({ label:"Lifestyle burn", value:v29Short(ps.expenses), cls:"bad", tab:"life",
      delta:v29Delta(ps.expenses, prev&&prev.pexp, { invert:true }) }),
    v29Tile({ label:"Net worth", value:v29Short(ps.worth + (cs.worth||0)), cls:"good", tab:"empire",
      delta:v29Delta(ps.worth, prev&&prev.pworth), spark:v29Spark("pworth"),
      title:"Company + personal net worth" })
  ];

  const head = document.createElement("div");
  head.id = "v29head";
  head.innerHTML = `
    <div class="v29-r1">
      <div class="v29-co" id="v29Co" title="${multi?"Switch company":"Your company"}">
        <span class="ic">${cfg.icon}</span>
        <span style="min-width:0;">
          <div class="nm">${c.name}</div>
          <div class="cv">${(cfg.label||"Business")} \u00b7 ${v29Short(cs.worth||c.netWorth||0)} value</div>
        </span>
        ${multi?`<span class="caret">\u25BC</span>`:""}
      </div>
      <div class="v29-scope" id="v29Scope">
        <button data-v29scope="company" class="${scope==="company"?"on":""}">Company</button>
        <button data-v29scope="personal" class="${scope==="personal"?"on":""}">Personal</button>
      </div>
      <span class="v29-grow"></span>
      <div class="v29-clock">
        <div class="mo">${V29_MONTHS[((c.month||1)-1)%12]} \u00b7 M${c.month}</div>
        <div class="yr">Year ${c.year}</div>
      </div>
      <button class="btn" id="v29Adv">Advance \u25B6</button>
    </div>
    <div class="v29-tiles">${tiles.join("")}</div>
    ${scope==="company" && rw && rw.months !== Infinity ? `
      <div class="v29-runway ${rw.cls}"><i style="width:${rw.pct}%"></i></div>
      <div class="v29-note"><span class="pill">\u26FD ${rw.months<1?"under a month":rw.months.toFixed(1)+" months"} of runway at this burn</span></div>` : ""}
    ${scope==="personal" ? `<div class="v29-note">
        <span class="pill click" id="v29Infuse">\u{1F4B5} Invest personal cash into company</span>
        <span class="pill click" data-v29tab="life">\u{1F3E1} Lifestyle</span>
      </div>` : ""}
  `;

  const app = document.getElementById("app");
  if(!app) return;
  ["#v29head","#topbar","#v19Corp","#v18Personal"].forEach(sel=>{ const n = app.querySelector(sel); if(n) n.remove(); });
  app.prepend(head);

  const advBtn = head.querySelector("#v29Adv");
  if(advBtn) advBtn.onclick = ()=>{ if(typeof confirmAndAdvance==="function") confirmAndAdvance(); else { advanceMonth(); renderAll(); } };
  head.querySelectorAll("[data-v29scope]").forEach(b=> b.onclick = ()=>{
    v29Ui().scope = b.getAttribute("data-v29scope");
    v29RenderHeader();
  });
  head.querySelectorAll("[data-v29tab]").forEach(t=> t.onclick = ()=>{
    G.ui.activeTab = t.getAttribute("data-v29tab");
    renderAll();
  });
  const inf = head.querySelector("#v29Infuse");
  if(inf) inf.onclick = ()=>{ try{ v18Infuse(); }catch(e){} };

  const coBtn = head.querySelector("#v29Co");
  if(coBtn) coBtn.onclick = ()=>{
    if(!multi){ G.ui.activeTab = "financials"; renderAll(); return; }
    const open = head.querySelector(".v29-copop");
    if(open){ open.remove(); return; }
    const pop = document.createElement("div");
    pop.className = "v29-copop";
    pop.innerHTML = G.companies.map((co,i)=>{
      const ic = (typeof industryOf==="function") ? industryOf(co).icon : "\u{1F4BC}";
      return `<div class="row ${i===G.activeCompanyIndex?"on":""}" data-v29co="${i}">
        <span>${ic}</span><span class="sp"><b>${co.name}</b>${co.passive?` <span class="mt">passive</span>`:""}</span>
        <span class="mt">${v29Short(co.cash||0)}</span></div>`;
    }).join("");
    head.appendChild(pop);
    pop.querySelectorAll("[data-v29co]").forEach(r=> r.onclick = (ev)=>{
      ev.stopPropagation();
      const i = Number(r.getAttribute("data-v29co"));
      pop.remove();
      if(typeof switchCompany==="function") switchCompany(i);
    });
  };
}
(function v29MountHeader(){
  try{
    renderTopbar = function(){ try{ v29RenderHeader(); }catch(e){} };
  }catch(e){}
})();

/* ---------- Exit interviews: track every departure with a reason ---------- */
function v29Departures(){
  const c = v29Co(); if(!c) return [];
  if(!Array.isArray(c.departures)) c.departures = [];
  return c.departures;
}
function v29Reason(emp){
  if(window.V29_EXIT_REASON) return window.V29_EXIT_REASON;
  const m = emp.morale === undefined ? 70 : emp.morale;
  const p = emp.performance === undefined ? 70 : emp.performance;
  if(m < 30) return "Burned out \u2014 morale collapsed";
  if(m < 50) return "Unhappy \u2014 left for a better culture";
  if(p < 45) return "Performance managed out";
  if(p > 80) return "Poached \u2014 took a bigger offer";
  return "Moved on \u2014 routine turnover";
}
(function v29TrackExits(){
  try{
    if(typeof fireEmployee !== "function") return;
    const prev = fireEmployee;
    fireEmployee = function(id){
      let rec = null;
      try{
        const c = v29Co();
        const emp = c && (c.employees||[]).find(x=>x.id===id);
        if(emp) rec = {
          name: emp.name, role: emp.role, dept: emp.dept, rung: emp.rung,
          salary: emp.salary||0, morale: emp.morale, performance: emp.performance,
          month: c.month, year: c.year, reason: v29Reason(emp)
        };
      }catch(e){}
      const r = prev.apply(this, arguments);
      try{ if(rec){ const list = v29Departures(); list.unshift(rec); if(list.length > 80) list.length = 80; } }catch(e){}
      return r;
    };
  }catch(e){}
})();
(function v29ExecFireReason(){
  try{
    if(typeof v26FireExec !== "function") return;
    const prev = v26FireExec;
    v26FireExec = function(){
      window.V29_EXIT_REASON = "Dismissed by you \u2014 executive change";
      try{ return prev.apply(this, arguments); }
      finally{ setTimeout(()=>{ window.V29_EXIT_REASON = null; }, 4000); }
    };
  }catch(e){}
})();
function v29ExitCard(){
  const c = v29Co(); if(!c) return "";
  const all = v29Departures();
  if(!all.length) return `<div class="card mt14"><h3>\u{1F6AA} Exit interviews</h3>
    <div class="muted" style="font-size:11.5px;">Nobody has left yet. This card will show who left, why, and which department is bleeding people.</div></div>`;
  const stamp = (x)=>(x.year||1)*12 + (x.month||1);
  const now = stamp(c);
  const yr = all.filter(d=>now - stamp(d) < 12);
  const byDept = {};
  yr.forEach(d=>{ const k = d.dept || "other"; byDept[k] = (byDept[k]||0) + 1; });
  const worst = Object.keys(byDept).sort((a,b)=>byDept[b]-byDept[a]);
  const reasons = {};
  yr.forEach(d=>{ reasons[d.reason] = (reasons[d.reason]||0) + 1; });
  const topReasons = Object.keys(reasons).sort((a,b)=>reasons[b]-reasons[a]).slice(0,3);
  const cost = yr.reduce((a,d)=>a + Math.round((d.salary||0)/12 * 1.5), 0);
  return `<div class="card mt14">
    <h3>\u{1F6AA} Exit interviews \u2014 last 12 months</h3>
    <div class="muted" style="font-size:11.5px;margin-bottom:8px;">
      ${yr.length} departure(s) \u00b7 est. replacement cost ${v29Money(cost)}
      ${worst.length? ` \u00b7 worst hit: <b>${worst[0]}</b> (${byDept[worst[0]]})` : ""}
    </div>
    <div style="margin-bottom:8px;">${topReasons.map(r=>`<span class="v29-chip">${r} \u00d7${reasons[r]}</span>`).join("")}</div>
    ${all.slice(0,8).map(d=>`<div class="v29-xi">
      <span class="ic">\u{1F6AB}</span>
      <span><div class="nm">${d.name}</div><div class="mt">${d.role} \u00b7 ${d.dept||""}</div></span>
      <span class="rt">${d.reason}<br>Y${d.year} M${d.month}</span>
    </div>`).join("")}
    ${all.length>8? `<div class="muted" style="font-size:11px;">+${all.length-8} earlier departure(s) on file.</div>`:""}
  </div>`;
}
(function v29HrExit(){
  try{
    if(typeof renderHR !== "function") return;
    const prev = renderHR;
    renderHR = function(){
      const wrap = prev.apply(this, arguments);
      try{
        if(wrap && wrap.insertAdjacentHTML && !wrap.querySelector(".v29-xi")) wrap.insertAdjacentHTML("beforeend", v29ExitCard());
      }catch(e){}
      return wrap;
    };
  }catch(e){}
})();
(function v29MonthlyExits(){
  try{
    if(typeof advanceMonth !== "function") return;
    const prev = advanceMonth;
    advanceMonth = function(){
      const before = v29Departures().length;
      const r = prev.apply(this, arguments);
      try{
        const list = v29Departures();
        const fresh = list.length - before;
        if(fresh > 0){
          const names = list.slice(0, fresh);
          const depts = {};
          names.forEach(d=>{ const k = d.dept||"other"; depts[k] = (depts[k]||0)+1; });
          const worst = Object.keys(depts).sort((a,b)=>depts[b]-depts[a])[0];
          if(typeof logHistory==="function")
            logHistory(`\u{1F6AA} Exit report: ${fresh} departure(s)${worst?` \u2014 ${worst} hit hardest`:""}. Reasons: ${names.map(n=>n.reason).slice(0,3).join("; ")}. See People \u2192 HR.`);
        }
      }catch(e){}
      return r;
    };
  }catch(e){}
})();

/* ---------- Retail clearance markdowns ---------- */
function v29ClearanceReady(){
  const c = v29Co();
  if(!c || !c.ops || c.ops.type !== "retail") return { ok:false, why:"Not a retail business." };
  const last = c.ops.lastClearance || 0;
  const now = (c.year||1)*12 + (c.month||1);
  if(now - last < 3) return { ok:false, why:`Clearance cools down for ${3 - (now-last)} more month(s).` };
  const units = (c.ops.stores||[]).reduce((a,s)=>a + (s.unitsOnHand||0), 0);
  if(units < 20) return { ok:false, why:"Not enough inventory on hand to clear." };
  return { ok:true, units };
}
function v29RunClearance(){
  try{
    const c = v29Co();
    const rd = v29ClearanceReady();
    if(!rd.ok){ if(typeof toast==="function") toast(rd.why, "warn"); return; }
    const o = c.ops;
    const price = 42 * (o.priceTier||1) * 0.6;
    let sold = 0, gross = 0;
    (o.stores||[]).forEach(s=>{
      const move = Math.floor((s.unitsOnHand||0) * randf(0.45, 0.7));
      s.unitsOnHand = Math.max(0, (s.unitsOnHand||0) - move);
      if(typeof v26UnitCost === "function") s.inventory = Math.round(s.unitsOnHand * v26UnitCost());
      sold += move;
      gross += move * price;
    });
    gross = Math.round(gross);
    c.cash += gross;
    o.lastClearance = (c.year||1)*12 + (c.month||1);
    o.satisfaction = clamp((o.satisfaction||70) + 3, 0, 100);
    if(typeof logHistory === "function")
      logHistory(`\u{1F3F7}\uFE0F Clearance markdown: moved ${sold.toLocaleString()} units at 40% off for ${v29Money(gross)}. Shelves cleared, shoppers happy (+3 satisfaction).`);
    if(typeof toast === "function") toast(`<b>Clearance run.</b> ${sold.toLocaleString()} units moved for ${v29Money(gross)}.`, "good");
    renderAll();
  }catch(e){}
}
(function v29ClearanceUi(){
  try{
    if(typeof renderIndustryOps !== "function") return;
    const prev = renderIndustryOps;
    renderIndustryOps = function(){
      const wrap = prev.apply(this, arguments);
      try{
        const c = v29Co();
        if(!wrap || !c || !c.ops || c.ops.type !== "retail") return wrap;
        if(wrap.querySelector("#v29Clear")) return wrap;
        const rd = v29ClearanceReady();
        const onHand = (c.ops.stores||[]).reduce((a,s)=>a + (s.unitsOnHand||0), 0);
        const card = document.createElement("div");
        card.className = "card mt14";
        card.innerHTML = `
          <h3>\u{1F3F7}\uFE0F Clearance markdown</h3>
          <div class="muted" style="font-size:11.5px;margin-bottom:8px;">
            Dump 45\u201370% of on-hand stock at <b>40% off</b> for immediate cash instead of paying rent on it and
            losing it to shrinkage. Shoppers love a sale (+3 satisfaction). Once every 3 months.
          </div>
          <div class="muted" style="font-size:11.5px;margin-bottom:8px;">On hand: <b>${onHand.toLocaleString()}</b> units \u00b7 clearance price ${v29Money(42*(c.ops.priceTier||1)*0.6)}/unit</div>
          <button class="btn ${rd.ok?"":"secondary"} small" id="v29Clear" ${rd.ok?"":"disabled"}>${rd.ok?"Run clearance event":rd.why}</button>`;
        wrap.appendChild(card);
        const b = card.querySelector("#v29Clear");
        if(b && rd.ok) b.onclick = ()=> v29RunClearance();
      }catch(e){}
      return wrap;
    };
  }catch(e){}
})();

try{ v29Track(); }catch(e){}


