/* ---------- 8-tile cockpit: first four full size, extras at quarter width ---------- */
(function v31RelaxClamp(){
  try{
    v30Ui = function(){
      const u = v29Ui();
      if(!u.tiles) u.tiles = { company:V30_DEFAULTS.company.slice(), personal:V30_DEFAULTS.personal.slice() };
      ["company","personal"].forEach(s=>{
        if(!Array.isArray(u.tiles[s]) || !u.tiles[s].length) u.tiles[s] = V30_DEFAULTS[s].slice();
        u.tiles[s] = u.tiles[s].filter(k=>V30_METRICS[k]).slice(0,8);
        while(u.tiles[s].length < 4){
          const fill = V30_DEFAULTS[s].find(k=>u.tiles[s].indexOf(k)<0);
          if(!fill) break;
          u.tiles[s].push(fill);
        }
      });
      if(u.sparks === undefined) u.sparks = true;
      return u;
    };
  }catch(e){}
})();
function v31Ui(){ return v30Ui(); }
(function v31HeaderTiles(){
  try{
    const prev = v29RenderHeader;
    v29RenderHeader = function(){
      prev.apply(this, arguments);
      try{
        const head = document.getElementById("v29head");
        const c = v30Co(); if(!head || !c) return;
        const u = v31Ui();
        const scope = u.scope === "personal" ? "personal" : "company";
        const picks = u.tiles[scope] || [];
        const host = head.querySelector(".v29-tiles");
        const old = head.querySelector(".v30-tiles2");
        if(old) old.remove();
        if(!host || picks.length <= 4) return;
        const cs = (typeof corporateSnapshot==="function") ? corporateSnapshot() : { revenue:0, expenses:0, net:0, worth:0 };
        const ps = (typeof personalSnapshot==="function") ? personalSnapshot() : { cash:0, net:0, worth:0, expenses:0, income:0 };
        const prevSnap = v29Prev();
        host.innerHTML = picks.slice(0,4).map(k=> v30TileHtml(k, c, cs, ps, prevSnap)).join("");
        host.querySelectorAll("[data-v29tab]").forEach(t=> t.onclick = ()=>{ G.ui.activeTab = t.getAttribute("data-v29tab"); renderAll(); });
        const row2 = document.createElement("div");
        row2.className = "v30-tiles2";
        const sparkWas = u.sparks;
        u.sparks = false;
        row2.innerHTML = picks.slice(4,8).map(k=> v30TileHtml(k, c, cs, ps, prevSnap)).join("");
        u.sparks = sparkWas;
        row2.querySelectorAll("[data-v29tab]").forEach(t=> t.onclick = ()=>{ G.ui.activeTab = t.getAttribute("data-v29tab"); renderAll(); });
        host.parentNode.insertBefore(row2, host.nextSibling);
      }catch(e){}
    };
  }catch(e){}
})();
(function v31Picker(){
  try{
    v30OpenPicker = function(head, scope){
      const old = head.querySelector(".v30-pick");
      if(old){ old.remove(); return; }
      const u = v31Ui();
      const picked = (u.tiles[scope]||[]).slice();
      const opts = Object.keys(V30_METRICS).filter(k=> V30_METRICS[k].scope === scope);
      const pop = document.createElement("div");
      pop.className = "v30-pick";
      const draw = ()=>{
        pop.innerHTML = `<h4>${scope} tiles \u2014 pick 4 to 8</h4>
          <div class="cnt" style="margin-bottom:6px;">The first four stay full size. Anything past four drops into a quarter-width strip underneath, same height.</div>
          ${opts.map(k=>{ const i = picked.indexOf(k); return `<div class="opt ${i>=0?"on":""}" data-v30m="${k}">
            <span>${i>=0?"\u2713":"\u00b7"}</span><span style="flex:1;">${V30_METRICS[k].label}</span>
            ${i>=0?`<span class="muted" style="font-size:10px;">${i<4?"#"+(i+1):"small "+(i-3)}</span>`:""}</div>`; }).join("")}
          <div class="foot">
            <span class="muted">${picked.length}/8 selected</span>
            <span>
              <button class="btn secondary small" data-v30spark>${u.sparks?"Hide":"Show"} sparklines</button>
              <button class="btn secondary small" data-v30reset>Reset</button>
              <button class="btn small" data-v30save>Save</button>
            </span>
          </div>`;
        pop.querySelectorAll("[data-v30m]").forEach(o=> o.onclick = (ev)=>{
          ev.stopPropagation();
          const k = o.getAttribute("data-v30m");
          const i = picked.indexOf(k);
          if(i>=0){
            if(picked.length <= 4){ v30Toast("Four tiles is the minimum.", "warn"); return; }
            picked.splice(i,1);
          } else if(picked.length >= 8){ v30Toast("Eight tiles max \u2014 deselect one first.", "warn"); return; }
          else picked.push(k);
          draw();
        });
        pop.querySelector("[data-v30reset]").onclick = (ev)=>{ ev.stopPropagation(); picked.length = 0; V30_DEFAULTS[scope].forEach(k=>picked.push(k)); draw(); };
        pop.querySelector("[data-v30spark]").onclick = (ev)=>{ ev.stopPropagation(); u.sparks = !u.sparks; draw(); v29RenderHeader(); };
        pop.querySelector("[data-v30save]").onclick = (ev)=>{
          ev.stopPropagation();
          if(picked.length < 4 || picked.length > 8){ v30Toast("Pick between four and eight metrics.", "warn"); return; }
          u.tiles[scope] = picked.slice();
          const p2 = head.querySelector(".v30-pick"); if(p2) p2.remove();
          v29RenderHeader();
          v30Toast(`<b>Header updated \u2014 ${picked.length} tiles.</b>${picked.length>4?` ${picked.length-4} in the small strip.`:""}`, "good");
        };
      };
      draw();
      head.appendChild(pop);
    };
  }catch(e){}
})();

