/* ---------- A1. Header: one row, equal tiles, reorderable, alert strip ---------- */
function v32Alerts(){
  const out = [];
  try{
    const c = v30Co(); if(!c) return out;
    const cs = corporateSnapshot(), p = pInit();
    const runway = (typeof v29Runway==="function") ? v29Runway() : Infinity;
    if(isFinite(runway) && runway <= 6) out.push({ k:"runway", cls: runway<=3?"bad":"warn", icon:"\u23F3", text:`${runway}mo runway`, tab:"financials" });
    if(c.cash < 0) out.push({ k:"cash", cls:"bad", icon:"\u{1F6A8}", text:`Cash ${fmt$(c.cash)}`, tab:"bank" });
    const accts = (c.clients||[]);
    const atRisk = accts.filter(a=> (a.health||100) < 45).length;
    if(atRisk) out.push({ k:"churn", cls: atRisk>2?"bad":"warn", icon:"\u26A0\uFE0F", text:`${atRisk} churn risk`, tab:"clients" });
    const renewing = accts.filter(a=> (a.renewIn!==undefined ? a.renewIn<=1 : false)).length;
    if(renewing) out.push({ k:"renew", cls:"warn", icon:"\u{1F504}", text:`${renewing} renewing`, tab:"clients" });
    const lowMorale = (c.employees||[]).filter(e=> (e.morale||100) < 40).length;
    if(lowMorale) out.push({ k:"morale", cls: lowMorale>3?"bad":"warn", icon:"\u{1F614}", text:`${lowMorale} unhappy`, tab:"team" });
    const openSeats = (typeof headcountCap==="function" ? headcountCap() : 0) - (c.employees||[]).length;
    if(openSeats <= 0) out.push({ k:"seats", cls:"warn", icon:"\u{1FA91}", text:"No open seats", tab:"facilities" });
    const q = (G.ui.queue||[]).length;
    if(q) out.push({ k:"queue", cls:"good", icon:"\u{1F4CB}", text:`${q} queued`, tab:"decisions" });
    const debt = (c.debt? (c.debt.loanBalance||0)+(c.debt.locBalance||0) : 0);
    if(debt > Math.max(50000, cs.revenue*6)) out.push({ k:"debt", cls:"warn", icon:"\u{1F4B3}", text:`Debt ${fmt$(debt)}`, tab:"bank" });
    if((p.wellbeing||100) < 40) out.push({ k:"well", cls:"warn", icon:"\u{1FAAB}", text:"Burning out", tab:"life" });
  }catch(e){}
  return out.slice(0,6);
}
