(function v32Picker(){
  try{
    v30OpenPicker = function(head, scope){
      const old = head.querySelector(".v30-pick");
      if(old){ old.remove(); return; }
      const u = v30Ui();
      const picked = (u.tiles[scope]||[]).slice();
      const opts = Object.keys(V30_METRICS).filter(k=> V30_METRICS[k].scope === scope);
      const pop = document.createElement("div");
      pop.className = "v30-pick";
      const apply = ()=>{ u.tiles[scope] = picked.slice(); v29RenderHeader(); };
      const draw = ()=>{
        pop.innerHTML = `<h4>${scope} tiles \u2014 pick 4 to 8, drag-free reorder</h4>
          <div class="cnt" style="margin-bottom:6px;">All tiles share one row at equal size. Use \u2191\u2193 to set the order. Alerts live in the strip underneath.</div>
          ${picked.map((k,i)=>`<div class="opt on" data-v32row="${k}">
              <span>${i+1}</span><span style="flex:1;">${V30_METRICS[k].label}</span>
              <span class="ord">
                <button data-v32up="${k}" ${i===0?"disabled":""}>\u2191</button>
                <button data-v32down="${k}" ${i===picked.length-1?"disabled":""}>\u2193</button>
                <button data-v32rm="${k}">\u2715</button>
              </span></div>`).join("")}
          <div class="cnt" style="margin:6px 0 3px;">Add a metric</div>
          ${opts.filter(k=>picked.indexOf(k)<0).map(k=>`<div class="opt" data-v30m="${k}"><span>\u00b7</span><span style="flex:1;">${V30_METRICS[k].label}</span></div>`).join("")}
          <div class="foot">
            <span class="muted">${picked.length}/8 selected</span>
            <span>
              <button class="btn secondary small" data-v30spark>${u.sparks?"Hide":"Show"} sparklines</button>
              <button class="btn secondary small" data-v30reset>Reset</button>
              <button class="btn small" data-v30save>Save</button>
            </span>
          </div>`;
        const move = (k, d)=>{ const i = picked.indexOf(k); const j = i+d; if(i<0||j<0||j>=picked.length) return; picked.splice(j,0,picked.splice(i,1)[0]); draw(); apply(); };
        pop.querySelectorAll("[data-v32up]").forEach(b=> b.onclick = (ev)=>{ ev.stopPropagation(); move(b.getAttribute("data-v32up"), -1); });
        pop.querySelectorAll("[data-v32down]").forEach(b=> b.onclick = (ev)=>{ ev.stopPropagation(); move(b.getAttribute("data-v32down"), 1); });
        pop.querySelectorAll("[data-v32rm]").forEach(b=> b.onclick = (ev)=>{
          ev.stopPropagation();
          if(picked.length <= 4){ v30Toast("Four tiles is the minimum.", "warn"); return; }
          picked.splice(picked.indexOf(b.getAttribute("data-v32rm")),1); draw(); apply();
        });
        pop.querySelectorAll("[data-v30m]").forEach(o=> o.onclick = (ev)=>{
          ev.stopPropagation();
          if(picked.length >= 8){ v30Toast("Eight tiles max \u2014 remove one first.", "warn"); return; }
          picked.push(o.getAttribute("data-v30m")); draw(); apply();
        });
        pop.querySelector("[data-v30reset]").onclick = (ev)=>{ ev.stopPropagation(); picked.length=0; V30_DEFAULTS[scope].forEach(k=>picked.push(k)); draw(); apply(); };
        pop.querySelector("[data-v30spark]").onclick = (ev)=>{ ev.stopPropagation(); u.sparks = !u.sparks; draw(); v29RenderHeader(); };
        pop.querySelector("[data-v30save]").onclick = (ev)=>{
          ev.stopPropagation(); apply();
          const p2 = head.querySelector(".v30-pick"); if(p2) p2.remove();
          v30Toast(`<b>Header saved \u2014 ${picked.length} tiles.</b>`, "good");
        };
      };
      draw();
      head.appendChild(pop);
    };
  }catch(e){}
})();

