function v32ExecBonus(empId){
  const e = (G.company.employees||[]).find(x=>x.id===empId);
  if(!e){ v30Toast("That executive is no longer on payroll.", "warn"); return; }
  const sal = e.salary||0;
  const presets = [
    { amount: Math.round(sal*0.5), note:"half month" },
    { amount: sal, note:"one month" },
    { amount: sal*3, note:"quarterly" },
    { amount: sal*6, note:"half year" },
    { amount: sal*12, note:"full year" }
  ].filter(x=>x.amount>0);
  v30AmountDialog({
    title:`\u{1F381} Bonus \u2014 ${e.role} ${e.name}`,
    subtitle:`Executive retention bonus. Morale +18, performance +6, and it cuts poaching risk.`,
    presets, suggested: presets[1] ? presets[1].amount : 10000,
    hint:(amt)=>`${fmt$(amt)} \u00b7 ${(sal? (amt/sal).toFixed(1) : "0")}\u00d7 monthly salary \u00b7 company cash ${fmt$(G.company.cash)}`,
    onPick:(amount)=>{
      if(typeof affordOrAlert==="function" && !affordOrAlert(amount, "an executive bonus")) return;
      queueAdd({ id:uid(), label:`Exec bonus: ${e.name} (${fmt$(amount)})`, cost:amount, run:(report)=>{
        if(G.company.cash < amount){ report.push(`Skipped ${e.name}'s bonus \u2014 not enough cash.`); return; }
        G.company.cash -= amount;
        e.morale = clamp((e.morale||0)+18,0,100);
        e.performance = clamp((e.performance||0)+6,0,100);
        e.lastBonusMonth = G.company.month;
        G.company.bonusLifetime = (G.company.bonusLifetime||0) + amount;
        report.push(`${e.role} ${e.name} received a ${fmt$(amount)} executive bonus.`);
      }});
      v30Toast(`<b>Queued.</b> ${e.name} gets ${fmt$(amount)} at month close.`, "good");
    }
  });
}
