/* ---------- B1. VP layer and divisions under the C-suite ---------- */
const V32_DIVISIONS = {
  sales:      ["Enterprise", "Mid-Market", "SMB", "Partnerships"],
  marketing:  ["Brand", "Demand Gen", "Product Marketing", "Communications"],
  engineering:["Platform", "Product Eng", "Infrastructure", "Quality"],
  product:    ["Core Product", "Growth", "Design", "Research"],
  support:    ["Tier 1", "Escalations", "Onboarding", "Knowledge"],
  hr:         ["Talent", "People Ops", "Engagement", "Learning"],
  finance:    ["Accounting", "FP&A", "Treasury", "Procurement"],
  ops:        ["Logistics", "Facilities", "Vendor Management", "Planning"],
  legal:      ["Commercial", "Compliance", "Privacy", "Litigation"]
};
function v32DivisionsFor(dk){
  return V32_DIVISIONS[dk] || ["Division A", "Division B", "Division C"];
}
(function v32VpRung(){
  try{
    if(typeof LADDERS === "undefined") return;
    const mk = (dk)=>({
      key:"vp",
      label:"VP, " + ((LADDERS[dk] && LADDERS[dk].label) || dk),
      salaryRange:[15000, 22000],
      icon:"\u{1F454}",
      desc:"Runs a division inside the department. Below the C-suite, above directors."
    });
    const insertVp = (ladder, dk)=>{
      if(!ladder || !Array.isArray(ladder.rungs)) return;
      if(ladder.rungs.some(r=>r && r.key==="vp")) return;
      let topIdx = ladder.rungs.length - 1;
      for(let i=ladder.rungs.length-1;i>=0;i--){
        const k = (ladder.rungs[i] && ladder.rungs[i].key) || "";
        if(/csuite|chief|cxo|exec/i.test(k)){ topIdx = i; break; }
      }
      ladder.rungs.splice(Math.max(0, topIdx), 0, mk(dk));
    };
    Object.keys(LADDERS).forEach(dk=> insertVp(LADDERS[dk], dk));
    if(typeof BASE_LADDERS !== "undefined") Object.keys(BASE_LADDERS).forEach(dk=> insertVp(BASE_LADDERS[dk], dk));
    if(typeof INDUSTRIES !== "undefined"){
      Object.keys(INDUSTRIES).forEach(ik=>{
        const roles = INDUSTRIES[ik] && INDUSTRIES[ik].roles;
        if(!roles) return;
        Object.keys(roles).forEach(dk=>{
          const arr = roles[dk];
          if(!Array.isArray(arr)) return;
          const lad = LADDERS[dk];
          if(!lad || !Array.isArray(lad.rungs)) return;
          const vpIdx = lad.rungs.findIndex(r=>r && r.key==="vp");
          if(vpIdx < 0) return;
          if(arr.length === lad.rungs.length) return;
          const label = "VP, " + ((lad && lad.label) || dk);
          arr.splice(Math.min(vpIdx, arr.length), 0, label);
        });
      });
    }
  }catch(e){}
})();
(function v32DivisionAssign(){
  try{
    if(typeof hire !== "function") return;
    const prev = hire;
    hire = function(dept, rung){
      const before = ((G.company||{}).employees||[]).length;
      const r = prev.apply(this, arguments);
      try{
        const emps = G.company.employees||[];
        for(let i=before;i<emps.length;i++){
          const e = emps[i];
          if(e && !e.division){
            const divs = v32DivisionsFor(e.dept||dept);
            const counts = divs.map(d=> emps.filter(x=>x.dept===(e.dept||dept) && x.division===d).length);
            const min = Math.min.apply(null, counts);
            e.division = divs[counts.indexOf(min)] || divs[0];
          }
        }
      }catch(err){}
      return r;
    };
  }catch(e){}
})();

/* ---------- B2. Succession: promote from within when an exec seat opens ---------- */
function v32Rungs(dept){
  try{ return ((LADDERS[dept]||{}).rungs)||[]; }catch(e){ return []; }
}
function v32SuccessionCandidates(dept){
  try{
    const emps = (G.company.employees||[]).filter(e=> e.dept===dept);
    const rungs = v32Rungs(dept);
    const idx = (r)=> rungs.findIndex(x=>x.key===r);
    return emps
      .filter(e=> e.rung==="vp" || idx(e.rung) >= Math.max(0, rungs.length-3))
      .sort((a,b)=> ((b.performance||0)+(b.morale||0)) - ((a.performance||0)+(a.morale||0)))
      .slice(0,3);
  }catch(e){ return []; }
}
function v32OfferSuccession(dept, seatRung){
  try{
    const cands = v32SuccessionCandidates(dept);
    if(!cands.length) return false;
    const box = document.getElementById("modalBox");
    const overlay = document.getElementById("modalOverlay");
    if(!box || !overlay) return false;
    const label = (LADDERS[dept] && LADDERS[dept].label) || dept;
    box.innerHTML = `<span class="close" id="v32SucClose">&times;</span>
      <h3>\u2B06\uFE0F Succession \u2014 ${label}</h3>
      <div class="muted" style="font-size:11.5px;">The seat is open. Promoting from within is cheaper than an external search and keeps institutional knowledge \u2014 but an internal promote starts with lower experience.</div>
      <div class="mt8">${cands.map(e=>{
        const newSal = Math.round((e.salary||0) * 1.55);
        return `<div class="flexrow" style="justify-content:space-between;gap:8px;padding:6px 0;border-bottom:1px solid rgba(255,255,255,.07);">
          <span>${e.icon||"\u{1F464}"} <b>${e.name}</b><br><span class="muted" style="font-size:11px;">${e.role} \u00b7 perf ${Math.round(e.performance||0)} \u00b7 morale ${Math.round(e.morale||0)} \u00b7 ${fmt$(e.salary||0)}/mo \u2192 ${fmt$(newSal)}/mo</span></span>
          <button class="btn small" data-v32promote="${e.id}">Promote</button>
        </div>`; }).join("")}</div>
      <div class="flexrow mt8" style="justify-content:flex-end;"><button class="btn secondary small" id="v32SucSkip">Search externally instead</button></div>`;
    overlay.classList.add("show");
    const close = ()=> overlay.classList.remove("show");
    box.querySelector("#v32SucClose").onclick = close;
    box.querySelector("#v32SucSkip").onclick = close;
    box.querySelectorAll("[data-v32promote]").forEach(b=> b.onclick = ()=>{
      const e = (G.company.employees||[]).find(x=>x.id===b.getAttribute("data-v32promote"));
      if(!e){ close(); return; }
      e.rung = seatRung;
      const rd = v32Rungs(dept).find(r=>r.key===seatRung);
      if(rd) e.role = rd.label || e.role;
      e.salary = Math.round((e.salary||0) * 1.55);
      e.morale = clamp((e.morale||0)+20, 0, 100);
      e.performance = clamp((e.performance||0)-8, 0, 100);
      e.promotedFromWithin = true;
      G.company.promotionsLifetime = (G.company.promotionsLifetime||0) + 1;
      try{ logHistory(`${e.name} was promoted into the ${label} executive seat.`); }catch(err){}
      close();
      try{ renderAll(); }catch(err){}
      v30Toast(`<b>${e.name} promoted.</b> Internal hire \u2014 morale up, experience needs time.`, "good");
    });
    return true;
  }catch(e){ return false; }
}
(function v32SuccessionHook(){
  try{
    if(typeof fireEmployee !== "function") return;
    const prev = fireEmployee;
    fireEmployee = function(id){
      let dept = null, rung = null, wasExec = false;
      try{
        const e = ((G.company||{}).employees||[]).find(x=>x.id===id);
        if(e){ dept = e.dept; rung = e.rung; wasExec = (typeof isCSuite==="function" && isCSuite(e)); }
      }catch(err){}
      const r = prev.apply(this, arguments);
      try{ if(wasExec && dept && rung) setTimeout(()=>{ v32OfferSuccession(dept, rung); }, 60); }catch(err){}
      return r;
    };
  }catch(e){}
})();

/* ---------- B3. Retention score, exit interviews and rival poaching ---------- */
function v32Retention(){
  const c = G.company;
  if(c.retentionScore === undefined) c.retentionScore = 72;
  return c.retentionScore;
}
function v32RecomputeRetention(){
  try{
    const c = G.company;
    const emps = c.employees||[];
    if(!emps.length){ c.retentionScore = 72; return 72; }
    const morale = emps.reduce((s,e)=>s+(e.morale||0),0)/emps.length;
    const deps = (c.departures||[]).slice(-12);
    const payReasons = deps.filter(d=> /pay|comp|salary|offer/i.test(d.reason||"")).length;
    const mgmtReasons = deps.filter(d=> /manager|leadership|burn/i.test(d.reason||"")).length;
    let score = morale * 0.75 + 25;
    score -= deps.length * 2.5;
    score -= payReasons * 2;
    score -= mgmtReasons * 3;
    const recentBonus = emps.filter(e=> e.lastBonusMonth!==undefined).length / emps.length;
    score += recentBonus * 8;
    c.retentionScore = Math.round(clamp(score, 0, 100));
    return c.retentionScore;
  }catch(e){ return 70; }
}
const V32_RIVAL_NAMES = ["Northwind Labs","Aperture Group","Halcyon Systems","Brightline Co.","Meridian Works","Ironwood Partners"];
function v32Poach(report){
  try{
    const c = G.company;
    const emps = c.employees||[];
    if(emps.length < 4) return;
    const score = v32RecomputeRetention();
    const risk = clamp((100 - score) / 260, 0, 0.42);
    if(Math.random() > risk) return;
    const target = emps.slice().sort((a,b)=> ((b.performance||0) - (b.morale||0)) - ((a.performance||0) - (a.morale||0)))[0];
    if(!target) return;
    const rival = pick(V32_RIVAL_NAMES);
    c.poached = c.poached || [];
    c.poached.push({ name:target.name, role:target.role, dept:target.dept, rival, month:c.month, year:c.year });
    if(c.poached.length > 40) c.poached = c.poached.slice(-40);
    c.departures = c.departures || [];
    c.departures.push({ name:target.name, role:target.role, dept:target.dept, reason:`Poached by ${rival} \u2014 better offer`, month:c.month, year:c.year });
    fireEmployee(target.id);
    report.push(`\u{1F6AA} ${target.name} (${target.role}) left for ${rival}.`);
  }catch(e){}
}
function v32RivalRosterCard(){
  const c = G.company;
  const list = (c.poached||[]).slice(-10).reverse();
  const score = v32Retention();
  const cls = score>=80?"good":score>=60?"":"bad";
  return `<div class="card mt14"><h3>\u{1F6E1}\uFE0F Retention & rival rosters</h3>
    <div class="flexrow mb8" style="gap:8px;align-items:center;flex-wrap:wrap;">
      <span class="pill ${cls}">Retention score ${score}</span>
      <span class="muted" style="font-size:11.5px;">Built from morale, exit interview reasons and recent bonuses. Low scores invite recruiters.</span>
    </div>
    ${list.length? list.map(p=>`<div class="logrow"><span class="when">Y${p.year} M${p.month}</span><span>${p.name} \u2014 ${p.role} \u2192 <b>${p.rival}</b></span></div>`).join("")
      : `<div class="muted" style="font-size:12px;">Nobody has been poached. Keep it that way.</div>`}
  </div>`;
}

/* ---------- B4. Supplier volume contracts ---------- */
const V32_SUPPLY_TIERS = [
  { tier:1, name:"Spot buying",        discount:0,    minUnits:0,    term:0,  note:"No commitment, list price." },
  { tier:2, name:"Volume tier I",      discount:0.06, minUnits:400,  term:6,  note:"6-month term, 400 units/mo minimum." },
  { tier:3, name:"Volume tier II",     discount:0.12, minUnits:1200, term:12, note:"12-month term, 1,200 units/mo minimum." },
  { tier:4, name:"Strategic partner",  discount:0.20, minUnits:3000, term:18, note:"18-month term, 3,000 units/mo minimum." },
  { tier:5, name:"Exclusive offtake",  discount:0.28, minUnits:8000, term:24, note:"24-month term, 8,000 units/mo minimum." }
];
function v32Supply(){
  const c = G.company;
  if(!c.supplyContract) c.supplyContract = { tier:1, monthsLeft:0, committed:0, shortfalls:0 };
  return c.supplyContract;
}
function v32SupplyDiscount(){
  try{
    const s = v32Supply();
    const def = V32_SUPPLY_TIERS.find(t=>t.tier===s.tier) || V32_SUPPLY_TIERS[0];
    return (s.monthsLeft>0 || s.tier===1) ? def.discount : 0;
  }catch(e){ return 0; }
}
function v32SignSupply(tier){
  const def = V32_SUPPLY_TIERS.find(t=>t.tier===tier);
  if(!def) return;
  const s = v32Supply();
  if(s.monthsLeft > 0 && s.tier !== 1){
    const breakFee = Math.round(s.committed * 18 * (s.monthsLeft/12));
    if(!window.confirm(`Breaking your current contract early costs about ${fmt$(breakFee)}. Continue?`)) return;
    G.company.cash -= breakFee;
  }
  s.tier = def.tier;
  s.monthsLeft = def.term;
  s.committed = def.minUnits;
  try{ logHistory(`Signed a supply contract: ${def.name} (${Math.round(def.discount*100)}% off, ${def.minUnits} units/mo for ${def.term} months).`); }catch(e){}
  v30Toast(`<b>${def.name} signed.</b> ${Math.round(def.discount*100)}% off unit cost. Minimum ${def.minUnits} units/mo.`, "good");
  try{ renderAll(); }catch(e){}
}
function v32SupplyMonthly(report){
  try{
    const c = G.company;
    const s = v32Supply();
    if(s.tier === 1 || s.monthsLeft <= 0) return;
    const o = c.ops || {};
    const bought = o.lastPurchasedUnits || o.purchasedThisMonth || 0;
    if(bought < s.committed){
      const short = s.committed - bought;
      const penalty = Math.round(short * (o.unitCost || 22) * 0.45);
      c.cash -= penalty;
      s.shortfalls = (s.shortfalls||0) + 1;
      c.supplyPenalties = (c.supplyPenalties||0) + 1;
      report.push(`\u{1F4E6} Supply shortfall: bought ${bought} of ${s.committed} committed units \u2014 ${fmt$(penalty)} penalty.`);
    }
    s.monthsLeft -= 1;
    if(s.monthsLeft <= 0){
      report.push(`Supply contract expired. Back to spot pricing until you sign a new one.`);
      s.tier = 1; s.committed = 0;
    }
  }catch(e){}
}
function v32SupplyCard(){
  const s = v32Supply();
  const cur = V32_SUPPLY_TIERS.find(t=>t.tier===s.tier) || V32_SUPPLY_TIERS[0];
  return `<div class="card mt14"><h3>\u{1F4E6} Supplier contracts</h3>
    <div class="muted mb8" style="font-size:11.5px;">Bigger commitments cut unit cost, but you owe the minimum whether demand shows up or not. Downturns punish over-ordering.</div>
    <div class="flexrow mb8" style="gap:8px;flex-wrap:wrap;">
      <span class="pill ${s.tier>1?"good":""}">${cur.name}</span>
      <span class="pill">${Math.round(cur.discount*100)}% off units</span>
      ${s.monthsLeft>0? `<span class="pill">${s.monthsLeft} months left</span>`:""}
      ${s.shortfalls? `<span class="pill bad">${s.shortfalls} shortfall(s)</span>`:""}
    </div>
    ${V32_SUPPLY_TIERS.map(t=>`<div class="flexrow" style="justify-content:space-between;gap:8px;padding:5px 0;border-bottom:1px solid rgba(255,255,255,.06);">
      <span><b>${t.name}</b> <span class="muted" style="font-size:11px;">${t.note}</span></span>
      <button class="btn ${t.tier===s.tier?"secondary":""} small" data-v32supply="${t.tier}" ${t.tier===s.tier?"disabled":""}>${t.tier===s.tier?"Current":"Sign"}</button>
    </div>`).join("")}
  </div>`;
}
(function v32SupplyRouter(){
  try{
    document.addEventListener("click",(ev)=>{
      const t = ev.target && ev.target.closest && ev.target.closest("[data-v32supply]");
      if(!t || t.disabled) return;
      ev.preventDefault(); ev.stopPropagation();
      v32SignSupply(Number(t.getAttribute("data-v32supply")));
    }, true);
  }catch(e){}
})();
(function v32SupplyDiscountHook(){
  try{
    if(typeof v26UnitCost !== "function") return;
    const prev = v26UnitCost;
    v26UnitCost = function(){
      const base = prev.apply(this, arguments);
      try{ return Math.max(1, Math.round(base * (1 - v32SupplyDiscount()))); }catch(e){ return base; }
    };
  }catch(e){}
})();

/* ---------- B5. Accounts by segment, batch check-ins ---------- */
const V32_SEGMENTS = [
  { key:"strategic", label:"Strategic", min:25000 },
  { key:"large",     label:"Large",     min:9000 },
  { key:"midmarket", label:"Mid-Market",min:3000 },
  { key:"smb",       label:"SMB",       min:0 }
];
function v32Segment(cl){
  const mrr = cl.mrr || cl.monthlyValue || cl.value || 0;
  return (V32_SEGMENTS.find(s=> mrr >= s.min) || V32_SEGMENTS[V32_SEGMENTS.length-1]).key;
}
function v32SegmentRollup(){
  const c = G.company;
  const out = {};
  V32_SEGMENTS.forEach(s=> out[s.key] = { count:0, mrr:0, health:0, risk:0 });
  (c.clients||[]).forEach(cl=>{
    const b = out[v32Segment(cl)];
    b.count++;
    b.mrr += (cl.mrr || cl.monthlyValue || cl.value || 0);
    b.health += (cl.health || 70);
    if((cl.health||70) < 45) b.risk++;
  });
  Object.keys(out).forEach(k=>{ const b = out[k]; b.health = b.count ? Math.round(b.health/b.count) : 0; });
  return out;
}
function v32BatchCheckin(segKey){
  const c = G.company;
  const targets = (c.clients||[]).filter(cl=> segKey === "all" || v32Segment(cl) === segKey);
  if(!targets.length){ v30Toast("No accounts in that segment.", "warn"); return; }
  const cost = Math.round(targets.length * 180);
  const label = segKey === "all" ? "all accounts" : (V32_SEGMENTS.find(s=>s.key===segKey)||{}).label;
  if(typeof affordOrAlert==="function" && !affordOrAlert(cost, "a batch check-in")) return;
  queueAdd({ id:uid(), label:`Batch check-in: ${label} (${targets.length})`, cost, run:(report)=>{
    if(G.company.cash < cost){ report.push("Skipped the batch check-in \u2014 not enough cash."); return; }
    G.company.cash -= cost;
    let improved = 0;
    targets.forEach(cl=>{
      const before = cl.health || 70;
      cl.health = clamp(before + (before < 55 ? 12 : 6), 0, 100);
      cl.lastCheckin = { month:G.company.month, year:G.company.year };
      if(cl.health > before) improved++;
    });
    report.push(`\u{1F4DE} Batch check-in with ${targets.length} ${label} \u2014 health improved on ${improved}.`);
  }});
  v30Toast(`<b>Queued.</b> Batch check-in with ${targets.length} accounts for ${fmt$(cost)}.`, "good");
}
function v32ClientsSummary(){
  const roll = v32SegmentRollup();
  const total = Object.keys(roll).reduce((a,k)=>a+roll[k].count,0);
  const totalMrr = Object.keys(roll).reduce((a,k)=>a+roll[k].mrr,0);
  return `<div class="card"><h3>\u{1F4CA} Book of business \u2014 ${total} accounts \u00b7 ${fmt$(Math.round(totalMrr))}/mo</h3>
    <div class="muted mb8" style="font-size:11.5px;">Managed by segment. Individual names still exist underneath \u2014 you just do not have to babysit them one at a time.</div>
    <div class="v32-seg">
      ${V32_SEGMENTS.map(s=>{ const b = roll[s.key];
        return `<div class="v32-segcard">
          <div class="n">${s.label}</div>
          <div class="v">${b.count}</div>
          <div class="s">${fmt$(Math.round(b.mrr))}/mo \u00b7 health ${b.health}${b.risk?` \u00b7 <span class="bad">${b.risk} at risk</span>`:""}</div>
          <button class="btn secondary small" style="margin-top:6px;width:100%;" data-v32checkin="${s.key}" ${b.count?"":"disabled"}>Batch check-in</button>
        </div>`; }).join("")}
    </div>
    <button class="btn small" data-v32checkin="all">\u{1F4DE} Check in with every account</button>
  </div>`;
}
(function v32ClientsRouter(){
  try{
    document.addEventListener("click",(ev)=>{
      const t = ev.target && ev.target.closest && ev.target.closest("[data-v32checkin]");
      if(!t || t.disabled) return;
      ev.preventDefault(); ev.stopPropagation();
      v32BatchCheckin(t.getAttribute("data-v32checkin"));
    }, true);
  }catch(e){}
})();
(function v32ClientsHook(){
  try{
    if(typeof renderClients !== "function") return;
    const prev = renderClients;
    renderClients = function(){
      const wrap = prev.apply(this, arguments);
      try{
        const box = document.createElement("div");
        box.innerHTML = v32ClientsSummary();
        const title = wrap.querySelector(".window-title");
        if(title && title.nextSibling) wrap.insertBefore(box, title.nextSibling);
        else wrap.insertBefore(box, wrap.firstChild);
        const cards = [...wrap.querySelectorAll(".card")].filter(cc=>{
          const h = cc.querySelector("h3");
          return h && /Account|Client/i.test(h.textContent) && !/Book of business/.test(h.textContent);
        });
        cards.forEach(cc=>{
          if(cc.dataset.v32fold) return;
          cc.dataset.v32fold = "1";
          const det = document.createElement("details");
          det.className = "v32-logmonth";
          const sum = document.createElement("summary");
          sum.textContent = "\u{1F4C7} Individual account detail";
          det.appendChild(sum);
          cc.parentNode.insertBefore(det, cc);
          det.appendChild(cc);
        });
        const rr = document.createElement("div");
        rr.innerHTML = v32RivalRosterCard();
        wrap.appendChild(rr);
      }catch(e){}
      return wrap;
    };
  }catch(e){}
})();

/* ---------- B6. Activity log: grouped, filtered, capped ---------- */
(function v32Log(){
  try{
    if(typeof renderLog !== "function") return;
    renderLog = function(){
      const c = G.company;
      const p = pInit();
      if(!G.ui.logScope) G.ui.logScope = "company";
      if(!G.ui.v32logFilter) G.ui.v32logFilter = "all";
      const wrap = el(`<div></div>`);
      const classify = (text)=>{
        const t = String(text||"");
        if(/hired|joined|promoted|left|resigned|poached|fired|bonus|morale/i.test(t)) return "people";
        if(/client|account|renewal|churn|contract|deal/i.test(t)) return "clients";
        if(/cash|loan|paid|revenue|expense|profit|invest|raise|funding|penalt/i.test(t)) return "money";
        return "other";
      };
      const coRows = (c.history||[]).map(h=>({ y:h.year, m:h.month, when:`Y${h.year} M${h.month}`, text:h.text, kind:classify(h.text) }));
      const perRows = ((p.fulfillHistory||[]).map(f=>({ y:f.year||1, m:f.month||1, when:`Y${f.year||1} M${f.month||1}`, text:f.text||f.name, kind:"life" })))
        .concat(((p.assets && p.assets.vacationHistory) || []).map(v=>({ y:v.year, m:v.month, when:`Y${v.year} M${v.month}`, text:`Trip: ${v.name}`, kind:"life" })));
      let rows = G.ui.logScope==="personal" ? perRows : coRows;
      const counts = { all: rows.length };
      ["people","clients","money","other","life"].forEach(k=> counts[k] = rows.filter(r=>r.kind===k).length);
      if(G.ui.v32logFilter !== "all") rows = rows.filter(r=> r.kind === G.ui.v32logFilter);
      rows = (G.ui.logScope==="personal" ? rows.slice().reverse() : rows.slice()).slice(0, 600);
      const groups = [];
      rows.forEach(r=>{
        const key = `Y${r.y} M${r.m}`;
        let g = groups.find(x=>x.key===key);
        if(!g){ g = { key, rows:[] }; groups.push(g); }
        g.rows.push(r);
      });
      const filters = G.ui.logScope==="personal" ? ["all","life"] : ["all","people","clients","money","other"];
      wrap.innerHTML = `
        <div class="window-title"><h2>\u{1F9FE} Activity Log</h2><span class="sub">${c.name} \u00b7 Year ${c.year}, Month ${c.month}</span></div>
        <div class="flexrow mb8" style="gap:6px;">
          <button class="btn ${G.ui.logScope==="company"?"":"secondary"} small" data-logscope="company">Company (${coRows.length})</button>
          <button class="btn ${G.ui.logScope==="personal"?"":"secondary"} small" data-logscope="personal">Personal (${perRows.length})</button>
        </div>
        <div class="flexrow mb14" style="gap:6px;flex-wrap:wrap;">
          ${filters.map(f=>`<button class="btn ${G.ui.v32logFilter===f?"":"secondary"} small" data-v32logf="${f}">${f==='all'?'Everything':f[0].toUpperCase()+f.slice(1)} (${counts[f]||0})</button>`).join("")}
        </div>
        ${groups.length? groups.map((g,i)=>`<details class="v32-logmonth" ${i<2?"open":""}>
            <summary>${g.key} \u00b7 ${g.rows.length} entr${g.rows.length===1?"y":"ies"}</summary>
            <div class="body">${g.rows.map(r=>`<div class="logrow"><span class="when">${r.when}</span><span>${r.text}</span></div>`).join("")}</div>
          </details>`).join("")
          : `<div class="muted">Nothing logged yet \u2014 advance a month or make a decision.</div>`}
        ${(c.history||[]).length>600? `<div class="muted mt8" style="font-size:11px;">Showing the most recent 600 of ${(c.history||[]).length} entries.</div>`:""}`;
      wrap.querySelectorAll("[data-logscope]").forEach(b=> b.onclick = ()=>{ G.ui.logScope = b.getAttribute("data-logscope"); G.ui.v32logFilter = "all"; renderScreen(); });
      wrap.querySelectorAll("[data-v32logf]").forEach(b=> b.onclick = ()=>{ G.ui.v32logFilter = b.getAttribute("data-v32logf"); renderScreen(); });
      return wrap;
    };
  }catch(e){}
})();
(function v32LogCap(){
  try{
    if(typeof logHistory !== "function") return;
    const prev = logHistory;
    logHistory = function(){
      const r = prev.apply(this, arguments);
      try{
        const c = G.company;
        if(c && Array.isArray(c.history) && c.history.length > 1500) c.history = c.history.slice(-1200);
      }catch(e){}
      return r;
    };
  }catch(e){}
})();


/* ================= v32 — Part C: sponsorships, foundation, goals, month close ================= */

/* ---------- C1. Sponsorships: little league to the world stage ---------- */
const V32_SPONSORSHIPS = [
  { key:"littleleague", tier:1, name:"Little league team", cost:2500,      monthly:400,      brand:2,  reach:"Neighborhood", note:"Your logo on 11 tiny jerseys." },
  { key:"highschool",   tier:1, name:"High school stadium board", cost:12000, monthly:1200,   brand:4,  reach:"Town",        note:"Friday night lights." },
  { key:"charity5k",    tier:1, name:"Charity 5K title sponsor", cost:25000, monthly:0,       brand:5,  reach:"City",        note:"Pairs well with the foundation." },
  { key:"minorleague",  tier:2, name:"Minor league club",  cost:150000,     monthly:12000,    brand:10, reach:"Region",      note:"Outfield wall and a mascot handshake." },
  { key:"college",      tier:2, name:"College athletics deal", cost:400000, monthly:30000,    brand:14, reach:"State",       note:"Alumni notice these things." },
  { key:"esports",      tier:3, name:"Esports franchise",  cost:1200000,    monthly:85000,    brand:20, reach:"National",    note:"Cheap reach with a young audience." },
  { key:"prokit",       tier:3, name:"Pro club shirt sponsor", cost:4000000, monthly:260000,  brand:26, reach:"National",    note:"Front-of-shirt placement." },
  { key:"stadium",      tier:4, name:"Stadium naming rights", cost:20000000, monthly:900000,  brand:36, reach:"Continental", note:"Your name on the skyline for a decade." },
  { key:"olympics",     tier:5, name:"Olympic partner",    cost:80000000,   monthly:3000000,  brand:48, reach:"Global",      note:"Rings, rights, and a lot of lawyers." },
  { key:"worldcup",     tier:5, name:"World Cup partner",  cost:150000000,  monthly:5500000,  brand:60, reach:"Global",      note:"The largest audience money can buy." }
];
const V32_TEAMS = [
  { key:"minorbaseball", name:"Minor league baseball club", cost:35000000,   monthly:900000,   income:1100000,  note:"Cheap entry into ownership." },
  { key:"soccer2",       name:"Second-division soccer club", cost:120000000, monthly:3200000,  income:3600000,  note:"Promotion upside, relegation downside." },
  { key:"hoops",         name:"Pro basketball franchise",  cost:400000000,   monthly:9000000,  income:11000000, note:"Fast-appreciating asset class." },
  { key:"football",      name:"Major football franchise",  cost:1000000000,  monthly:22000000, income:29000000, note:"The billion-dollar trophy." },
  { key:"f1",            name:"Formula racing team",       cost:1500000000,  monthly:38000000, income:41000000, note:"Global exposure, brutal cost base." }
];
function v32Spons(){
  const c = G.company;
  c.sponsorships = c.sponsorships || [];
  return c.sponsorships;
}
function v32BrandLift(){
  try{ return v32Spons().reduce((s,x)=> s + (x.brand||0), 0); }catch(e){ return 0; }
}
function v32BuySponsorship(key){
  const def = V32_SPONSORSHIPS.find(s=>s.key===key);
  if(!def) return;
  const list = v32Spons();
  if(list.some(s=>s.key===key)){ v30Toast("You already sponsor that.", "warn"); return; }
  if(typeof affordOrAlert==="function" && !affordOrAlert(def.cost, def.name)) return;
  G.company.cash -= def.cost;
  list.push({ key:def.key, name:def.name, tier:def.tier, monthly:def.monthly, brand:def.brand, since:{ month:G.company.month, year:G.company.year } });
  try{ logHistory(`Signed a sponsorship: ${def.name} (${fmt$(def.cost)}).`); }catch(e){}
  v30Toast(`<b>${def.name} signed.</b> Brand lift +${def.brand}, ${fmt$(def.monthly)}/mo carry.`, "good");
  try{ renderAll(); }catch(e){}
}
function v32DropSponsorship(key){
  const list = v32Spons();
  const i = list.findIndex(s=>s.key===key);
  if(i<0) return;
  const s = list[i];
  list.splice(i,1);
  try{ logHistory(`Ended the ${s.name} sponsorship.`); }catch(e){}
  v30Toast(`Ended ${s.name}.`, "warn");
  try{ renderAll(); }catch(e){}
}
function v32BuyTeam(key){
  const def = V32_TEAMS.find(t=>t.key===key);
  if(!def) return;
  const p = pInit();
  p.assets.teams = p.assets.teams || [];
  if(p.assets.teams.some(t=>t.key===key)){ v30Toast("You already own that club.", "warn"); return; }
  if((p.cash||0) < def.cost){ v30Toast(`You need ${fmt$(def.cost)} in personal cash. You have ${fmt$(p.cash||0)}.`, "bad"); return; }
  p.cash -= def.cost;
  p.assets.teams.push({ key:def.key, name:def.name, price:def.cost, monthly:def.monthly, income:def.income, bought:{ month:G.company.month, year:G.company.year }, value:def.cost });
  try{ logHistory(`Personally acquired ${def.name} for ${fmt$(def.cost)}.`); }catch(e){}
  v30Toast(`<b>You own ${def.name}.</b> Net ${fmt$(def.income-def.monthly)}/mo, and the company gets a brand halo.`, "good");
  try{ renderAll(); }catch(e){}
}
function v32SponsorshipScreen(){
  const c = G.company, p = pInit();
  const list = v32Spons();
  const teams = (p.assets.teams||[]);
  const carry = list.reduce((s,x)=> s+(x.monthly||0), 0);
  const teamNet = teams.reduce((s,t)=> s + ((t.income||0)-(t.monthly||0)), 0);
  const wrap = el(`<div></div>`);
  wrap.innerHTML = `
    <div class="window-title"><h2>\u{1F3DF}\uFE0F Sponsorships & Teams</h2><span class="sub">Brand lift +${v32BrandLift()} \u00b7 ${fmt$(carry)}/mo carry \u00b7 ${teams.length} club${teams.length===1?"":"s"} owned</span></div>
    <div class="card"><h3>How this works</h3>
      <div class="muted" style="font-size:11.5px;">Brand lift raises inbound lead flow and slows churn. Team ownership is a personal purchase \u2014 it pays out to you, not the company, but the halo still helps recruiting.</div>
    </div>
    <h3 class="mt14">Company sponsorships \u00b7 company cash ${fmt$(c.cash)}</h3>
    <div class="v32-spon">
      ${V32_SPONSORSHIPS.map(s=>{
        const owned = list.some(x=>x.key===s.key);
        const afford = c.cash >= s.cost;
        return `<div class="v32-sponcard" style="${owned?"border-color:rgba(34,197,94,.4);":""}">
          <div class="tier">Tier ${s.tier} \u00b7 ${s.reach}</div>
          <h4>${s.name}</h4>
          <div class="muted" style="font-size:11.5px;">${s.note}</div>
          <div class="mt8" style="font-size:11.5px;">${fmt$(s.cost)} up front \u00b7 ${fmt$(s.monthly)}/mo \u00b7 brand +${s.brand}</div>
          <button class="btn ${owned?"secondary":""} small" style="margin-top:8px;width:100%;" ${owned?`data-v32spondrop="${s.key}"`:`data-v32spon="${s.key}"`} ${(!owned&&!afford)?"disabled":""}>${owned?"End sponsorship":(afford?"Sign":"Cannot afford")}</button>
        </div>`;
      }).join("")}
    </div>
    <h3 class="mt14">Buy a team \u00b7 personal cash ${fmt$(p.cash||0)}</h3>
    <div class="v32-spon">
      ${V32_TEAMS.map(t=>{
        const owned = teams.some(x=>x.key===t.key);
        const afford = (p.cash||0) >= t.cost;
        return `<div class="v32-sponcard" style="${owned?"border-color:rgba(34,197,94,.4);":""}">
          <div class="tier">Ownership</div>
          <h4>${t.name}</h4>
          <div class="muted" style="font-size:11.5px;">${t.note}</div>
          <div class="mt8" style="font-size:11.5px;">${fmt$(t.cost)} \u00b7 ${fmt$(t.income)}/mo in \u00b7 ${fmt$(t.monthly)}/mo out</div>
          <button class="btn ${owned?"secondary":""} small" style="margin-top:8px;width:100%;" data-v32team="${t.key}" ${(owned||!afford)?"disabled":""}>${owned?"Owned":(afford?"Buy club":"Cannot afford")}</button>
        </div>`;
      }).join("")}
    </div>
    ${teams.length? `<div class="card mt14"><h3>Your clubs</h3>${teams.map(t=>`<div class="flexrow" style="justify-content:space-between;padding:5px 0;border-bottom:1px solid rgba(255,255,255,.06);"><span><b>${t.name}</b> <span class="muted" style="font-size:11px;">bought Y${t.bought.year} M${t.bought.month}</span></span><span class="pill ${((t.income||0)-(t.monthly||0))>=0?"good":"bad"}">${fmt$((t.income||0)-(t.monthly||0))}/mo</span></div>`).join("")}<div class="muted mt8" style="font-size:11px;">Net monthly from clubs: ${fmt$(teamNet)}.</div></div>`:""}`;
  wrap.querySelectorAll("[data-v32spon]").forEach(b=> b.onclick = ()=> v32BuySponsorship(b.getAttribute("data-v32spon")));
  wrap.querySelectorAll("[data-v32spondrop]").forEach(b=> b.onclick = ()=> v32DropSponsorship(b.getAttribute("data-v32spondrop")));
  wrap.querySelectorAll("[data-v32team]").forEach(b=> b.onclick = ()=> v32BuyTeam(b.getAttribute("data-v32team")));
  return wrap;
}
(function v32WireSponsorshipTab(){
  try{
    if(typeof DOCK_ITEMS !== "undefined" && !DOCK_ITEMS.some(d=>d.id==="sponsor")){
      DOCK_ITEMS.push({ id:"sponsor", label:"Sponsorships", icon:"\u{1F3DF}\uFE0F", group:"personal" });
    }
    const prev = renderScreen;
    renderScreen = function(){
      if(G.ui.activeTab === "sponsor"){
        try{
          const host = document.getElementById("screen");
          if(host){ host.innerHTML = ""; host.appendChild(v32SponsorshipScreen()); return; }
        }catch(e){}
      }
      return prev.apply(this, arguments);
    };
  }catch(e){}
})();

/* ---------- C2. Foundation that scales with the empire ---------- */
function v32CharityTiers(){
  const c = G.company;
  const cash = Math.max(0, c.cash||0);
  const steps = [1000, 5000, 25000, 100000, 500000, 2500000, 10000000, 50000000];
  const affordable = steps.filter(v=> v <= Math.max(5000, cash));
  const out = affordable.slice(-5);
  return out.length ? out : [1000];
}
function v32CharityPanel(){
  const c = G.company;
  const ch = c.charity || (c.charity = { totalContributed:0, endowment:0, reputation:0 });
  const tiers = v32CharityTiers();
  const endow = ch.endowment || 0;
  return `<div class="card mt14"><h3>\u{1F3DB}\uFE0F Foundation at scale</h3>
    <div class="muted mb8" style="font-size:11.5px;">Contribution sizes now scale with company cash, up to $50M a click. An endowment compounds and pays out grants automatically, so giving keeps working after you stop clicking.</div>
    <div class="flexrow mb8" style="gap:8px;flex-wrap:wrap;">
      <span class="pill">Lifetime ${fmt$(ch.totalContributed||0)}</span>
      <span class="pill ${endow?"good":""}">Endowment ${fmt$(endow)}</span>
      <span class="pill">Auto-grants ${fmt$(Math.round(endow*0.05/12))}/mo</span>
    </div>
    <div class="muted" style="font-size:11px;margin-bottom:4px;">One-time contribution</div>
    <div class="flexrow mb8" style="gap:6px;flex-wrap:wrap;">
      ${tiers.map(t=>`<button class="btn secondary small" data-v32give="${t}">${fmt$(t)}</button>`).join("")}
      <button class="btn secondary small" data-v32give="custom">Custom\u2026</button>
    </div>
    <div class="muted" style="font-size:11px;margin-bottom:4px;">Endow the foundation (principal stays invested)</div>
    <div class="flexrow" style="gap:6px;flex-wrap:wrap;">
      ${tiers.slice(-3).map(t=>`<button class="btn small" data-v32endow="${t}">Endow ${fmt$(t)}</button>`).join("")}
      <button class="btn small" data-v32endow="custom">Custom endowment\u2026</button>
    </div>
  </div>`;
}
function v32Give(amount, endow){
  const c = G.company;
  if(typeof affordOrAlert==="function" && !affordOrAlert(amount, endow?"an endowment":"a contribution")) return;
  c.cash -= amount;
  c.charity = c.charity || { totalContributed:0, endowment:0, reputation:0 };
  c.charity.totalContributed = (c.charity.totalContributed||0) + amount;
  if(endow) c.charity.endowment = (c.charity.endowment||0) + amount;
  c.charity.reputation = clamp((c.charity.reputation||0) + Math.log10(Math.max(10, amount)), 0, 100);
  try{ logHistory(`${endow?"Endowed":"Contributed"} ${fmt$(amount)} through the foundation.`); }catch(e){}
  v30Toast(`<b>${fmt$(amount)} ${endow?"endowed":"contributed"}.</b> Reputation is climbing.`, "good");
  try{ renderAll(); }catch(e){}
}
(function v32CharityRouter(){
  try{
    document.addEventListener("click",(ev)=>{
      const g = ev.target && ev.target.closest && ev.target.closest("[data-v32give],[data-v32endow]");
      if(!g) return;
      ev.preventDefault(); ev.stopPropagation();
      const endow = g.hasAttribute("data-v32endow");
      const raw = g.getAttribute(endow?"data-v32endow":"data-v32give");
      if(raw === "custom"){
        const tiers = v32CharityTiers();
        v30AmountDialog({
          title: endow ? "\u{1F3DB}\uFE0F Endow the foundation" : "\u{1F54A}\uFE0F Foundation contribution",
          subtitle: endow ? "Principal stays invested and pays out about 5% a year in grants, forever." : "A one-time gift.",
          presets: tiers.map(t=>({ amount:t, note:"" })),
          suggested: tiers[tiers.length-1] || 1000,
          hint:(amt)=>`${fmt$(amt)} \u00b7 company cash ${fmt$(G.company.cash)}`,
          onPick:(amt)=> v32Give(amt, endow)
        });
      } else {
        v32Give(Number(raw), endow);
      }
    }, true);
  }catch(e){}
})();
(function v32CharityMount(){
  try{
    const prev = renderScreen;
    renderScreen = function(){
      const out = prev.apply(this, arguments);
      try{
        const host = document.getElementById("screen");
        if(!host || host.querySelector("[data-v32charity]")) return out;
        const hit = [...host.querySelectorAll("h2,h3")].some(h=>/GonCorp|Foundation|Giving|Charity|Philanthrop/i.test(h.textContent));
        if(hit){
          const box = document.createElement("div");
          box.setAttribute("data-v32charity","1");
          box.innerHTML = v32CharityPanel();
          host.appendChild(box);
        }
      }catch(e){}
      return out;
    };
  }catch(e){}
})();

/* ---------- C3. Goal ladders cap at Tier 10 = Mastered ---------- */
(function v32GoalCap(){
  try{
    if(typeof v30GoalTier === "function"){
      const prev = v30GoalTier;
      v30GoalTier = function(){
        const t = prev.apply(this, arguments);
        return (typeof t === "number") ? Math.min(10, t) : t;
      };
    }
    if(typeof v30PromoteGoals === "function"){
      const prevProm = v30PromoteGoals;
      v30PromoteGoals = function(){
        const r = prevProm.apply(this, arguments);
        try{
          const c = G.company;
          c.goalMastered = c.goalMastered || [];
          const tiers = (c.goals && c.goals.tiers) || {};
          Object.keys(tiers).forEach(k=>{
            if(tiers[k] >= 10){
              tiers[k] = 10;
              if(c.goalMastered.indexOf(k) < 0){
                c.goalMastered.push(k);
                try{ logHistory(`Goal ladder "${k}" reached Tier 10 \u2014 Mastered.`); }catch(e){}
                try{ v30Toast(`<b>Mastered.</b> Tier 10 is the cap \u2014 permanent perk unlocked.`, "good"); }catch(e){}
              }
            }
          });
        }catch(e){}
        return r;
      };
    }
  }catch(e){}
})();

/* ---------- C4. Trophies ride along with the leaderboard run code ---------- */
function v32TrophySummary(){
  try{
    const c = G.company;
    const tr = (c.goalTrophies||[]);
    const names = tr.slice(-12).map(t=> (typeof t === "string" ? t : (t.name||t.key||"trophy")));
    return `Trophies: ${tr.length} \u00b7 Badges: ${(c.badges||[]).length} \u00b7 Mastered ladders: ${(c.goalMastered||[]).length}${names.length? " \u00b7 Case: "+names.join(", ") : ""}`;
  }catch(e){ return "Trophies: 0"; }
}
(function v32ExportTrophies(){
  try{
    if(typeof v28ExportCode !== "function") return;
    const prev = v28ExportCode;
    v28ExportCode = function(){
      try{
        const c = G.company;
        if(c){
          c.trophySnapshot = {
            trophies: (c.goalTrophies||[]).slice(),
            badges: (c.badges||[]).slice(),
            mastered: (c.goalMastered||[]).slice(),
            retention: c.retentionScore || 0,
            sponsorships: (c.sponsorships||[]).map(s=>s.name),
            summary: v32TrophySummary()
          };
        }
      }catch(e){}
      return prev.apply(this, arguments);
    };
  }catch(e){}
})();

/* ---------- C5. Engagement menu grows with the specialists you hire ---------- */
const V32_ENGAGEMENT_EXTRA = [
  { min:2, key:"v32_mentorship", name:"Mentorship program", cost:6000,  morale:9,  note:"Pairs juniors with senior staff." },
  { min:3, key:"v32_offsite",    name:"Department offsite", cost:24000, morale:16, note:"One department, two days, real bonding." },
  { min:4, key:"v32_sabbatical", name:"Sabbatical policy",  cost:40000, morale:20, note:"Expensive, but retention jumps." },
  { min:5, key:"v32_erg",        name:"Employee resource groups", cost:15000, morale:12, note:"Company-wide belonging programs." },
  { min:6, key:"v32_retreat",    name:"Company-wide retreat", cost:120000, morale:28, note:"Everyone, somewhere warm. Unforgettable." }
];
function v32EngagementCount(){
  try{ return (typeof v25EngagementCount === "function") ? (v25EngagementCount()||0) : 0; }catch(e){ return 0; }
}
function v32EngagementUnlocked(){
  const n = v32EngagementCount();
  return V32_ENGAGEMENT_EXTRA.filter(x=> n >= x.min);
}
function v32RunEngagement(key){
  const def = V32_ENGAGEMENT_EXTRA.find(x=>x.key===key);
  if(!def) return;
  if(typeof affordOrAlert==="function" && !affordOrAlert(def.cost, def.name)) return;
  queueAdd({ id:uid(), label:`Engagement: ${def.name}`, cost:def.cost, run:(report)=>{
    if(G.company.cash < def.cost){ report.push(`Skipped ${def.name} \u2014 not enough cash.`); return; }
    G.company.cash -= def.cost;
    (G.company.employees||[]).forEach(e=> e.morale = clamp((e.morale||0)+def.morale, 0, 100));
    G.company.eventsHeld = (G.company.eventsHeld||0) + 1;
    G.company.retentionScore = clamp((G.company.retentionScore||70) + Math.round(def.morale/3), 0, 100);
    report.push(`\u{1F389} ${def.name} ran company-wide \u2014 morale +${def.morale}.`);
  }});
  v30Toast(`<b>Queued.</b> ${def.name} for ${fmt$(def.cost)}.`, "good");
}
function v32EngagementCard(){
  const n = v32EngagementCount();
  const open = v32EngagementUnlocked();
  const next = V32_ENGAGEMENT_EXTRA.find(x=> n < x.min);
  return `<div class="card mt14"><h3>\u{1F389} Advanced engagement programs</h3>
    <div class="muted mb8" style="font-size:11.5px;">${n} engagement specialist${n===1?"":"s"} on staff. Hiring more under People unlocks bigger programs.</div>
    ${open.length? open.map(x=>`<div class="flexrow" style="justify-content:space-between;gap:8px;padding:6px 0;border-bottom:1px solid rgba(255,255,255,.06);">
        <span><b>${x.name}</b><br><span class="muted" style="font-size:11px;">${x.note} \u00b7 ${fmt$(x.cost)} \u00b7 morale +${x.morale}</span></span>
        <button class="btn small" data-v32engage="${x.key}">Run</button>
      </div>`).join("") : `<div class="muted" style="font-size:12px;">Hire engagement specialists under People to unlock these.</div>`}
    ${next? `<div class="muted mt8" style="font-size:11px;">Next unlock at ${next.min} specialists: ${next.name}.</div>`:""}
  </div>`;
}
(function v32EngagementRouter(){
  try{
    document.addEventListener("click",(ev)=>{
      const t = ev.target && ev.target.closest && ev.target.closest("[data-v32engage]");
      if(!t) return;
      ev.preventDefault(); ev.stopPropagation();
      v32RunEngagement(t.getAttribute("data-v32engage"));
    }, true);
  }catch(e){}
})();
(function v32EngagementMount(){
  try{
    const prev = renderScreen;
    renderScreen = function(){
      const out = prev.apply(this, arguments);
      try{
        const host = document.getElementById("screen");
        if(!host || host.querySelector("[data-v32engagebox]")) return out;
        if(G.ui.activeTab==="people" || G.ui.activeTab==="hr"){
          const box = document.createElement("div");
          box.setAttribute("data-v32engagebox","1");
          box.innerHTML = v32EngagementCard();
          host.appendChild(box);
        }
      }catch(e){}
      return out;
    };
  }catch(e){}
})();

