/* ---------- C7. Month close: upkeep, poaching, supply, sponsorships, clubs ---------- */
(function v32MonthClose(){
  try{
    const prev = advanceMonth;
    advanceMonth = function(){
      const r = prev.apply(this, arguments);
      try{
        const c = G.company, p = pInit();
        const report = [];
        const carry = v32Spons().reduce((s,x)=> s+(x.monthly||0), 0);
        if(carry){ c.cash -= carry; report.push(`\u{1F3DF}\uFE0F Sponsorship carry: ${fmt$(carry)}.`); }
        const lift = v32BrandLift();
        if(lift){
          c.mrr = Math.round((c.mrr||0) * (1 + Math.min(0.02, lift/3000)));
          (c.clients||[]).forEach(cl=> cl.health = clamp((cl.health||70) + Math.min(2, lift/40), 0, 100));
        }
        const teams = (p.assets.teams||[]);
        if(teams.length){
          const net = teams.reduce((s,t)=> s + ((t.income||0)-(t.monthly||0)), 0);
          p.cash = (p.cash||0) + net;
          teams.forEach(t=> t.value = Math.round((t.value||t.price||0) * 1.006));
          report.push(`\u{1F3C6} Club ownership net: ${fmt$(net)}.`);
        }
        const endow = (c.charity && c.charity.endowment) || 0;
        if(endow){
          const grant = Math.round(endow * 0.05/12);
          c.charity.totalContributed = (c.charity.totalContributed||0) + grant;
          c.charity.endowment = Math.round(endow * 1.0045);
          report.push(`\u{1F54A}\uFE0F Foundation auto-granted ${fmt$(grant)} from the endowment.`);
        }
        const up = v32ApplyUpkeep();
        if(up.total){ p.cash = (p.cash||0) - up.total; report.push(`\u{1F3E1} Lifestyle upkeep: ${fmt$(up.total)} (homes ${fmt$(up.houses)}, cars ${fmt$(up.cars)}, toys ${fmt$(up.toys)}).`); }
        v32SupplyMonthly(report);
        v32RecomputeRetention();
        v32Poach(report);
        try{
          const cs = corporateSnapshot();
          if((cs.profit||0) > 0) c.profitStreak = (c.profitStreak||0) + 1; else c.profitStreak = 0;
        }catch(e){}
        G.ui.v32deleg = {};
        report.forEach(t=>{ try{ logHistory(t); }catch(e){} });
        try{ if(typeof checkBadges === "function") checkBadges(); }catch(e){}
      }catch(e){}
      return r;
    };
  }catch(e){}
})();

/* ---------- C8. Save-compatibility for every new field ---------- */
(function v32Normalize(){
  try{
    if(typeof normalizeGame !== "function") return;
    const prev = normalizeGame;
    normalizeGame = function(state){
      const s = prev.apply(this, arguments) || state;
      try{
        const cos = (s && s.companies) ? Object.keys(s.companies).map(k=>s.companies[k]) : [];
        cos.forEach(c=>{
          if(!c) return;
          c.sponsorships = c.sponsorships || [];
          c.poached = c.poached || [];
          c.departures = c.departures || [];
          c.goalMastered = c.goalMastered || [];
          c.supplyContract = c.supplyContract || { tier:1, monthsLeft:0, committed:0, shortfalls:0 };
          if(c.retentionScore === undefined) c.retentionScore = 72;
          if(c.bonusLifetime === undefined) c.bonusLifetime = 0;
          if(c.promotionsLifetime === undefined) c.promotionsLifetime = 0;
          if(c.profitStreak === undefined) c.profitStreak = 0;
          if(c.eventsHeld === undefined) c.eventsHeld = 0;
          c.charity = c.charity || { totalContributed:0, endowment:0, reputation:0 };
          if(c.charity.endowment === undefined) c.charity.endowment = 0;
          if(c.personal && c.personal.assets && !c.personal.assets.teams) c.personal.assets.teams = [];
        });
        if(s && s.personal && s.personal.assets && !s.personal.assets.teams) s.personal.assets.teams = [];
      }catch(e){}
      return s;
    };
  }catch(e){}
})();




/* ================= v33 — Part A: the rival economy ================= */

(function v33Css(){
  try{
    const s = document.createElement("style");
    s.textContent = `
    .v33-riv{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:10px;}
    .v33-rivcard{border:1px solid rgba(255,255,255,.09);border-radius:12px;padding:12px;}
    .v33-rivcard h4{margin:0 0 2px;font-size:13.5px;}
    .v33-rivcard .tag{font-size:10px;text-transform:uppercase;letter-spacing:.5px;opacity:.65;}
    .v33-bar{height:8px;border-radius:999px;background:rgba(255,255,255,.08);overflow:hidden;margin-top:6px;}
    .v33-bar > span{display:block;height:100%;border-radius:999px;}
    .v33-share{display:flex;height:22px;border-radius:6px;overflow:hidden;border:1px solid rgba(255,255,255,.1);}
    .v33-share > div{display:flex;align-items:center;justify-content:center;font-size:10px;font-weight:700;color:#0b0f17;white-space:nowrap;overflow:hidden;}
    .v33-feed .row{font-size:11.5px;padding:4px 0;border-bottom:1px solid rgba(255,255,255,.06);}
    .v33-deal{border:1px solid rgba(255,255,255,.12);border-radius:10px;padding:10px;margin-top:8px;}
    `;
    document.head.appendChild(s);
  }catch(e){}
})();

const V33_RIVAL_DEFS = [
  { key:"northwind", name:"Northwind Labs",     color:"#60a5fa", persona:"engineering-led", product:62, price:1.05, aggression:0.45, cash:2200000, revenue:52000, note:"Ships fast, sells badly. Product quality climbs every quarter." },
  { key:"aperture",  name:"Aperture Group",     color:"#f59e0b", persona:"sales-led",       product:48, price:0.92, aggression:0.72, cash:4800000, revenue:86000, note:"Outsells everyone. Will undercut you to win a logo." },
  { key:"halcyon",   name:"Halcyon Systems",    color:"#a78bfa", persona:"enterprise",      product:71, price:1.35, aggression:0.38, cash:9500000, revenue:180000, note:"Premium incumbent. Slow, expensive, trusted by big logos." },
  { key:"brightline",name:"Brightline Co.",     color:"#34d399", persona:"discounter",      product:35, price:0.68, aggression:0.60, cash:900000,  revenue:28000, note:"Cheap and cheerful. Eats the low end of the market." }
];

function v33State(){
  const c = G.company;
  if(!c.v33){
    c.v33 = {
      product: 50,
      price: 1,
      rivals: V33_RIVAL_DEFS.map(r=>({ key:r.key, name:r.name, product:r.product, price:r.price, cash:r.cash, revenue:r.revenue, aggression:r.aggression, alive:true, acquiredBy:null })),
      feed: [],
      deal: null,
      offers: [],
      acquiredByRival: null,
      exited: null,
      lastDealMonth: 0
    };
  }
  if(!Array.isArray(c.v33.rivals) || !c.v33.rivals.length){
    c.v33.rivals = V33_RIVAL_DEFS.map(r=>({ key:r.key, name:r.name, product:r.product, price:r.price, cash:r.cash, revenue:r.revenue, aggression:r.aggression, alive:true, acquiredBy:null }));
  }
  return c.v33;
}
function v33Def(key){ return V33_RIVAL_DEFS.find(r=>r.key===key) || V33_RIVAL_DEFS[0]; }
function v33LiveRivals(){ return v33State().rivals.filter(r=>r.alive); }
function v33PlayerRevenue(){ try{ return Math.max(0, G.company.mrr||0); }catch(e){ return 0; } }
function v33Product(){
  const st = v33State();
  return Math.round(clamp(st.product, 1, 100));
}
function v33Shares(){
  const st = v33State();
  const rows = [{ key:"you", name:(G.company.name||"You"), color:"#22c55e", revenue:v33PlayerRevenue(), you:true }]
    .concat(v33LiveRivals().map(r=>({ key:r.key, name:r.name, color:v33Def(r.key).color, revenue:Math.max(0,r.revenue), you:false })));
  const total = rows.reduce((s,r)=>s+r.revenue,0) || 1;
  rows.forEach(r=> r.share = r.revenue/total);
  return rows.sort((a,b)=> b.share - a.share);
}
function v33MyShare(){
  const row = v33Shares().find(r=>r.you);
  return row ? row.share : 0;
}
function v33Feed(text){
  const st = v33State();
  st.feed.unshift({ text, month:G.company.month, year:G.company.year });
  if(st.feed.length > 80) st.feed.length = 80;
}

/* ---------- Player levers ---------- */
function v33ShipImprovement(){
  const c = G.company;
  const cost = Math.max(25000, Math.round((c.mrr||0) * 0.6));
  if(typeof affordOrAlert==="function" && !affordOrAlert(cost, "a product push")) return;
  queueAdd({ id:uid(), label:`Product push (+quality)`, cost, run:(report)=>{
    if(G.company.cash < cost){ report.push("Skipped the product push \u2014 not enough cash."); return; }
    G.company.cash -= cost;
    const st = v33State();
    const eng = (G.company.employees||[]).filter(e=>e.dept==="engineering"||e.dept==="product").length;
    const gain = clamp(3 + eng*0.35, 2, 12);
    st.product = clamp(st.product + gain, 1, 100);
    report.push(`\u{1F527} Product push shipped \u2014 quality now ${Math.round(st.product)}.`);
  }});
  v30Toast(`<b>Queued.</b> Product push for ${fmt$(cost)}.`, "good");
}
function v33SetPrice(mult){
  const st = v33State();
  const old = st.price;
  st.price = clamp(mult, 0.6, 1.6);
  try{
    const c = G.company;
    if(old > 0) c.mrr = Math.round((c.mrr||0) * (st.price/old));
  }catch(e){}
  v33Feed(`You repriced to ${Math.round(st.price*100)}% of market rate.`);
  v30Toast(`<b>Pricing set to ${Math.round(st.price*100)}%.</b> Cheaper wins volume, dearer wins margin.`, "good");
  try{ renderAll(); }catch(e){}
}

/* ---------- Head-to-head deals ---------- */
function v33DealScore(product, price, relationship){
  return (product * 1.0) + ((1.6 - price) * 45) + (relationship * 0.5);
}
function v33SpawnDeal(report){
  const st = v33State();
  const c = G.company;
  if(st.deal) return;
  if((c.month + c.year*12) - st.lastDealMonth < 2) return;
  const rivals = v33LiveRivals();
  if(!rivals.length) return;
  if(Math.random() > 0.55) return;
  const rival = pick(rivals);
  const size = pick(["Mid-Market","Large","Strategic"]);
  const mrr = size==="Strategic" ? 25000 + Math.round(Math.random()*40000)
            : size==="Large" ? 9000 + Math.round(Math.random()*12000)
            : 3000 + Math.round(Math.random()*5000);
  st.deal = { rival:rival.key, rivalName:rival.name, size, mrr, month:c.month, year:c.year, bid:null };
  st.lastDealMonth = c.month + c.year*12;
  report.push(`\u{1F3AF} A ${size} prospect worth ${fmt$(mrr)}/mo is evaluating you against ${rival.name}.`);
}
function v33BidDeal(mode){
  const st = v33State();
  const d = st.deal;
  if(!d){ v30Toast("No open deal right now.", "warn"); return; }
  const c = G.company;
  const rival = st.rivals.find(r=>r.key===d.rival) || st.rivals[0];
  const costs = { standard:0, discount:Math.round(d.mrr*0.8), allin:Math.round(d.mrr*2.2) };
  const cost = costs[mode] || 0;
  if(cost && typeof affordOrAlert==="function" && !affordOrAlert(cost, "this pursuit")) return;
  if(cost) c.cash -= cost;
  const salesTeam = (c.employees||[]).filter(e=>e.dept==="sales").length;
  const relationship = clamp(30 + salesTeam*4 + (c.retentionScore||70)*0.15, 0, 100);
  const priceMult = mode==="discount" ? v33State().price*0.85 : mode==="allin" ? v33State().price*0.92 : v33State().price;
  let mine = v33DealScore(v33Product(), priceMult, relationship);
  if(mode==="allin") mine += 18;
  const theirs = v33DealScore(rival.product, rival.price, 45 + rival.aggression*35) + (Math.random()*16 - 8);
  const won = mine >= theirs;
  if(won){
    c.mrr = (c.mrr||0) + d.mrr;
    try{ v30EnsureAccounts && v30EnsureAccounts(); }catch(e){}
    try{
      c.clients = c.clients || [];
      c.clients.push({ id:uid(), name:`${d.size} account \u2014 won from ${d.rivalName}`, mrr:d.mrr, health:78, wonFrom:d.rivalName });
    }catch(e){}
    rival.revenue = Math.max(0, rival.revenue - Math.round(d.mrr*0.35));
    v33Feed(`You beat ${d.rivalName} for a ${d.size} account worth ${fmt$(d.mrr)}/mo.`);
    v30Toast(`<b>Won.</b> ${fmt$(d.mrr)}/mo taken from ${d.rivalName}.`, "good");
    try{ logHistory(`Won a competitive ${d.size} deal against ${d.rivalName} (${fmt$(d.mrr)}/mo).`); }catch(e){}
  } else {
    rival.revenue += d.mrr;
    v33Feed(`${d.rivalName} beat you to a ${d.size} account worth ${fmt$(d.mrr)}/mo.`);
    v30Toast(`<b>Lost.</b> ${d.rivalName} took the ${d.size} account.`, "bad");
    try{ logHistory(`Lost a competitive ${d.size} deal to ${d.rivalName}.`); }catch(e){}
  }
  st.deal = null;
  try{ renderAll(); }catch(e){}
}

/* ---------- Rival turns ---------- */
function v33RivalTurn(report){
  const st = v33State();
  const c = G.company;
  const myShare = v33MyShare();
  st.rivals.filter(r=>r.alive).forEach(r=>{
    const def = v33Def(r.key);
    // organic growth, scaled by their own product quality and the market
    const growth = 0.01 + (r.product/100)*0.035 + (Math.random()*0.02 - 0.008);
    r.revenue = Math.max(1000, Math.round(r.revenue * (1 + growth)));
    r.cash += Math.round(r.revenue * 0.22);
    // they invest in product
    if(Math.random() < 0.35){
      r.product = clamp(r.product + (def.persona==="engineering-led" ? 2.2 : 1.1), 1, 100);
    }
    // aggressive moves, more likely when you are winning
    const pressure = r.aggression + myShare*0.5;
    if(Math.random() < pressure*0.28){
      const move = pick(["price","feature","account","talent","campaign"]);
      if(move==="price" && r.price > 0.62){
        r.price = Math.max(0.62, +(r.price - 0.05).toFixed(2));
        v33Feed(`${r.name} cut prices to ${Math.round(r.price*100)}% of market rate.`);
        report.push(`\u2694\uFE0F ${r.name} cut prices \u2014 your churn risk rises until you answer.`);
        (c.clients||[]).forEach(cl=>{ if(Math.random()<0.25) cl.health = clamp((cl.health||70)-6,0,100); });
      } else if(move==="feature"){
        r.product = clamp(r.product + 4, 1, 100);
        v33Feed(`${r.name} shipped a headline feature (quality ${Math.round(r.product)}).`);
        report.push(`\u{1F6A2} ${r.name} shipped a feature that makes your product look dated.`);
      } else if(move==="account" && (c.clients||[]).length){
        const victim = pick(c.clients);
        if(victim && (victim.health||70) < 62){
          const lost = victim.mrr || victim.monthlyValue || victim.value || 0;
          c.clients = c.clients.filter(x=>x!==victim);
          c.mrr = Math.max(0, (c.mrr||0) - lost);
          r.revenue += lost;
          v33Feed(`${r.name} poached your account "${victim.name}" (${fmt$(lost)}/mo).`);
          report.push(`\u{1F6A8} ${r.name} took the ${victim.name} account \u2014 ${fmt$(lost)}/mo gone.`);
        } else {
          v33Feed(`${r.name} pitched your customers and came away empty.`);
        }
      } else if(move==="talent"){
        c.retentionScore = clamp((c.retentionScore||72) - 6, 0, 100);
        v33Feed(`${r.name} opened a recruiting push aimed at your team.`);
        report.push(`\u{1F3AF} ${r.name} is recruiting against you \u2014 retention down.`);
      } else {
        v33Feed(`${r.name} launched a market campaign.`);
        r.revenue = Math.round(r.revenue * 1.03);
      }
    }
  });
  // rivals consolidate
  const live = v33LiveRivals();
  if(live.length > 2 && Math.random() < 0.035){
    const sorted = live.slice().sort((a,b)=> b.cash - a.cash);
    const buyer = sorted[0], target = sorted[sorted.length-1];
    if(buyer && target && buyer.key !== target.key && buyer.cash > target.revenue*24){
      buyer.cash -= Math.round(target.revenue*24);
      buyer.revenue += target.revenue;
      buyer.product = Math.round((buyer.product + target.product)/2 + 3);
      target.alive = false; target.acquiredBy = buyer.name;
      v33Feed(`${buyer.name} acquired ${target.name}.`);
      report.push(`\u{1F3E6} ${buyer.name} acquired ${target.name}. The market just got tougher.`);
    }
  }
}

/* ---------- Acquisition offers and the exit ---------- */
function v33CheckOffers(report){
  const st = v33State();
  const c = G.company;
  const mine = v33PlayerRevenue();
  if(mine <= 0) return;
  const suitors = v33LiveRivals().filter(r=> r.cash > mine*30 && r.revenue > mine*0.6);
  if(suitors.length && Math.random() < 0.08 && !st.offers.length){
    const buyer = pick(suitors);
    const multiple = 22 + Math.round(Math.random()*18);
    const price = Math.round(mine * multiple);
    st.offers = [{ buyer:buyer.name, key:buyer.key, price, multiple, month:c.month, year:c.year }];
    report.push(`\u{1F4BC} ${buyer.name} made an offer to acquire you for ${fmt$(price)} (${multiple}\u00d7 MRR). See the Rivals tab.`);
    v33Feed(`${buyer.name} offered ${fmt$(price)} to acquire the company.`);
  }
}
function v33AcceptOffer(){
  const st = v33State();
  const o = st.offers[0];
  if(!o) return;
  if(!window.confirm(`Sell ${G.company.name} to ${o.buyer} for ${fmt$(o.price)}? This ends the run as an exit.`)) return;
  const p = pInit();
  p.cash = (p.cash||0) + o.price;
  st.exited = { buyer:o.buyer, price:o.price, month:G.company.month, year:G.company.year };
  st.offers = [];
  try{ logHistory(`Exited: sold the company to ${o.buyer} for ${fmt$(o.price)}.`); }catch(e){}
  v30Toast(`<b>Exit complete.</b> ${o.buyer} acquired you for ${fmt$(o.price)}. Proceeds are in personal cash.`, "good");
  try{ renderAll(); }catch(e){}
}
function v33DeclineOffer(){
  const st = v33State();
  const o = st.offers[0];
  if(!o) return;
  st.offers = [];
  v33Feed(`You declined ${o.buyer}'s ${fmt$(o.price)} offer.`);
  const r = st.rivals.find(x=>x.key===o.key);
  if(r) r.aggression = clamp(r.aggression + 0.12, 0, 1);
  v30Toast(`<b>Declined.</b> ${o.buyer} did not take it well.`, "warn");
  try{ renderAll(); }catch(e){}
}
function v33CheckDistress(report){
  const st = v33State();
  const c = G.company;
  if(st.acquiredByRival || st.exited) return;
  const broke = (c.cash||0) < 0;
  if(!broke) { c.v33distress = 0; return; }
  c.v33distress = (c.v33distress||0) + 1;
  if(c.v33distress === 1){
    report.push(`\u26A0\uFE0F You are cash negative. Rivals are circling \u2014 fix it within two months or you will be bought for scrap.`);
    return;
  }
  if(c.v33distress >= 3){
    const buyer = v33LiveRivals().sort((a,b)=>b.cash-a.cash)[0];
    if(buyer){
      const price = Math.max(0, Math.round(v33PlayerRevenue()*6));
      st.acquiredByRival = { buyer:buyer.name, price, month:c.month, year:c.year };
      const p = pInit();
      p.cash = (p.cash||0) + price;
      buyer.revenue += v33PlayerRevenue();
      report.push(`\u{1F3F4} ${buyer.name} acquired your distressed company for ${fmt$(price)}. That is the end of this run.`);
      try{ logHistory(`Acquired in distress by ${buyer.name} for ${fmt$(price)}.`); }catch(e){}
    }
  }
}

/* ---------- Rivals screen ---------- */
function v33RivalsScreen(){
  const st = v33State();
  const c = G.company;
  const shares = v33Shares();
  const wrap = el(`<div></div>`);
  const bar = shares.map(r=>`<div style="width:${Math.max(3, r.share*100)}%;background:${r.color};">${r.share>=0.09? Math.round(r.share*100)+"%" : ""}</div>`).join("");
  const d = st.deal;
  const offer = st.offers[0];
  wrap.innerHTML = `
    <div class="window-title"><h2>\u2694\uFE0F Market & Rivals</h2><span class="sub">Your share ${Math.round(v33MyShare()*100)}% \u00b7 product quality ${v33Product()} \u00b7 pricing ${Math.round(st.price*100)}%</span></div>

    ${st.exited? `<div class="card"><h3>\u{1F3C1} You exited</h3><div class="muted">Sold to ${st.exited.buyer} for ${fmt$(st.exited.price)} in Y${st.exited.year} M${st.exited.month}. Proceeds sit in personal cash.</div></div>`:""}
    ${st.acquiredByRival? `<div class="card"><h3>\u{1F3F4} Acquired in distress</h3><div class="muted">${st.acquiredByRival.buyer} bought the company for ${fmt$(st.acquiredByRival.price)}. Load an earlier save or start fresh.</div></div>`:""}

    <div class="card"><h3>Market share</h3>
      <div class="v33-share">${bar}</div>
      <div class="flexrow mt8" style="gap:10px;flex-wrap:wrap;font-size:11px;">
        ${shares.map(r=>`<span><span style="display:inline-block;width:9px;height:9px;border-radius:2px;background:${r.color};margin-right:4px;"></span>${r.name} \u00b7 ${fmt$(Math.round(r.revenue))}/mo</span>`).join("")}
      </div>
      <div class="muted mt8" style="font-size:11.5px;">Revenue is a finite pool. Every point of share you gain comes off somebody's board.</div>
    </div>

    ${offer? `<div class="card mt14"><h3>\u{1F4BC} Acquisition offer</h3>
      <div style="font-size:12.5px;">${offer.buyer} offers <b>${fmt$(offer.price)}</b> (${offer.multiple}\u00d7 MRR) for the whole company.</div>
      <div class="muted" style="font-size:11.5px;margin-top:4px;">Accepting ends the run as an exit and pays into personal cash. Declining makes them more aggressive.</div>
      <div class="flexrow mt8" style="gap:8px;"><button class="btn small" data-v33accept>Accept the offer</button><button class="btn secondary small" data-v33decline>Decline</button></div>
    </div>`:""}

    ${d? `<div class="card mt14"><h3>\u{1F3AF} Open competitive deal</h3>
      <div style="font-size:12.5px;">A <b>${d.size}</b> prospect worth <b>${fmt$(d.mrr)}/mo</b> is choosing between you and <b>${d.rivalName}</b>.</div>
      <div class="v33-deal">
        <div class="flexrow" style="gap:8px;flex-wrap:wrap;">
          <button class="btn secondary small" data-v33bid="standard">Bid at list price (free)</button>
          <button class="btn secondary small" data-v33bid="discount">Discount to win (${fmt$(Math.round(d.mrr*0.8))})</button>
          <button class="btn small" data-v33bid="allin">Full-court press (${fmt$(Math.round(d.mrr*2.2))})</button>
        </div>
        <div class="muted mt8" style="font-size:11px;">Outcome weighs product quality, price and your sales relationships against theirs.</div>
      </div>
    </div>`:""}

    <div class="card mt14"><h3>Your levers</h3>
      <div class="flexrow" style="gap:8px;flex-wrap:wrap;">
        <button class="btn small" data-v33ship>\u{1F527} Product push (+quality)</button>
        <button class="btn secondary small" data-v33price="0.85">Cut price to 85%</button>
        <button class="btn secondary small" data-v33price="1">Price at market</button>
        <button class="btn secondary small" data-v33price="1.25">Premium at 125%</button>
      </div>
      <div class="muted mt8" style="font-size:11.5px;">Cutting price moves MRR immediately and wins deals; premium pricing protects margin but hands volume to Brightline.</div>
    </div>

    <h3 class="mt14">The competition</h3>
    <div class="v33-riv">
      ${st.rivals.map(r=>{
        const def = v33Def(r.key);
        if(!r.alive) return `<div class="v33-rivcard" style="opacity:.45;"><div class="tag">Acquired</div><h4>${r.name}</h4><div class="muted" style="font-size:11.5px;">Absorbed by ${r.acquiredBy}.</div></div>`;
        return `<div class="v33-rivcard">
          <div class="tag">${def.persona}</div>
          <h4 style="color:${def.color};">${r.name}</h4>
          <div class="muted" style="font-size:11.5px;">${def.note}</div>
          <div style="font-size:11.5px;margin-top:6px;">Revenue ${fmt$(Math.round(r.revenue))}/mo \u00b7 war chest ${fmt$(Math.round(r.cash))}</div>
          <div style="font-size:11px;margin-top:4px;">Product ${Math.round(r.product)} vs your ${v33Product()}</div>
          <div class="v33-bar"><span style="width:${Math.round(r.product)}%;background:${def.color};"></span></div>
          <div style="font-size:11px;margin-top:5px;">Pricing ${Math.round(r.price*100)}% \u00b7 aggression ${Math.round(r.aggression*100)}%</div>
        </div>`;
      }).join("")}
    </div>

    <div class="card mt14"><h3>Competitive feed</h3>
      <div class="v33-feed">${(st.feed||[]).slice(0,18).map(f=>`<div class="row"><span class="muted" style="margin-right:6px;">Y${f.year} M${f.month}</span>${f.text}</div>`).join("") || `<div class="muted" style="font-size:12px;">Quiet so far. That will not last.</div>`}</div>
    </div>`;
  wrap.querySelectorAll("[data-v33bid]").forEach(b=> b.onclick = ()=> v33BidDeal(b.getAttribute("data-v33bid")));
  wrap.querySelectorAll("[data-v33price]").forEach(b=> b.onclick = ()=> v33SetPrice(Number(b.getAttribute("data-v33price"))));
  const ship = wrap.querySelector("[data-v33ship]"); if(ship) ship.onclick = ()=> v33ShipImprovement();
  const acc = wrap.querySelector("[data-v33accept]"); if(acc) acc.onclick = ()=> v33AcceptOffer();
  const dec = wrap.querySelector("[data-v33decline]"); if(dec) dec.onclick = ()=> v33DeclineOffer();
  return wrap;
}
(function v33WireTab(){
  try{
    if(typeof DOCK_ITEMS !== "undefined" && !DOCK_ITEMS.some(d=>d.id==="rivals")){
      DOCK_ITEMS.push({ id:"rivals", label:"Market & Rivals", icon:"\u2694\uFE0F", group:"company" });
    }
    const prev = renderScreen;
    renderScreen = function(){
      if(G.ui.activeTab === "rivals"){
        try{
          const host = document.getElementById("screen");
          if(host){ host.innerHTML = ""; host.appendChild(v33RivalsScreen()); return; }
        }catch(e){}
      }
      return prev.apply(this, arguments);
    };
  }catch(e){}
})();

/* ---------- Share pressure on your own numbers ---------- */
function v33SharePressure(report){
  const st = v33State();
  const c = G.company;
  const myProduct = v33Product();
  const live = v33LiveRivals();
  if(!live.length) return;
  const bestProduct = Math.max.apply(null, live.map(r=>r.product));
  const cheapest = Math.min.apply(null, live.map(r=>r.price));
  let drag = 0;
  if(bestProduct > myProduct + 10) drag += 0.012;
  if(cheapest < st.price - 0.15) drag += 0.010;
  if(drag > 0){
    const lost = Math.round((c.mrr||0) * drag);
    if(lost > 0){
      c.mrr = Math.max(0, (c.mrr||0) - lost);
      report.push(`\u{1F4C9} Competitive pressure cost you ${fmt$(lost)}/mo (better product or cheaper pricing out there).`);
    }
  } else if(myProduct > bestProduct + 8){
    const gain = Math.round((c.mrr||0) * 0.008);
    if(gain > 0){
      c.mrr = (c.mrr||0) + gain;
      report.push(`\u{1F4C8} You have the best product on the market \u2014 ${fmt$(gain)}/mo of share came to you.`);
    }
  }
  // slow product decay: standing still is falling behind
  st.product = clamp(st.product - 0.35, 1, 100);
}

/* ---------- Month close hook ---------- */
(function v33MonthClose(){
  try{
    const prev = advanceMonth;
    advanceMonth = function(){
      const r = prev.apply(this, arguments);
      try{
        const st = v33State();
        if(st.exited || st.acquiredByRival) return r;
        const report = [];
        v33RivalTurn(report);
        v33SharePressure(report);
        v33SpawnDeal(report);
        v33CheckOffers(report);
        v33CheckDistress(report);
        report.forEach(t=>{ try{ logHistory(t); }catch(e){} });
      }catch(e){}
      return r;
    };
  }catch(e){}
})();

/* ---------- Alerts and save compatibility ---------- */
(function v33Alerts(){
  try{
    if(typeof v32Alerts !== "function") return;
    const prev = v32Alerts;
    v32Alerts = function(){
      const out = prev.apply(this, arguments) || [];
      try{
        const st = v33State();
        if(st.deal) out.unshift({ k:"deal", cls:"good", icon:"\u{1F3AF}", text:`Deal vs ${st.deal.rivalName}`, tab:"rivals" });
        if(st.offers && st.offers.length) out.unshift({ k:"offer", cls:"warn", icon:"\u{1F4BC}", text:"Buyout offer", tab:"rivals" });
        const share = v33MyShare();
        if(share > 0 && share < 0.12) out.push({ k:"share", cls:"warn", icon:"\u2694\uFE0F", text:`${Math.round(share*100)}% share`, tab:"rivals" });
      }catch(e){}
      return out.slice(0,6);
    };
  }catch(e){}
})();
(function v33Normalize(){
  try{
    if(typeof normalizeGame !== "function") return;
    const prev = normalizeGame;
    normalizeGame = function(state){
      const s = prev.apply(this, arguments) || state;
      try{
        const cos = (s && s.companies) ? Object.keys(s.companies).map(k=>s.companies[k]) : [];
        cos.forEach(c=>{
          if(!c) return;
          if(!c.v33){
            c.v33 = {
              product:50, price:1,
              rivals: V33_RIVAL_DEFS.map(r=>({ key:r.key, name:r.name, product:r.product, price:r.price, cash:r.cash, revenue:r.revenue, aggression:r.aggression, alive:true, acquiredBy:null })),
              feed:[], deal:null, offers:[], acquiredByRival:null, exited:null, lastDealMonth:0
            };
          }
          if(!Array.isArray(c.v33.feed)) c.v33.feed = [];
          if(!Array.isArray(c.v33.offers)) c.v33.offers = [];
          if(c.v33.product === undefined) c.v33.product = 50;
          if(c.v33.price === undefined) c.v33.price = 1;
        });
      }catch(e){}
      return s;
    };
  }catch(e){}
})();


