/* ---------------- Division P&L ---------------- */
function v33DivState(){
  const c = G.company;
  if(!c.v33div) c.v33div = { budgets:{}, history:[] };
  if(!c.v33div.budgets) c.v33div.budgets = {};
  return c.v33div;
}
function v33DivKey(dept, div){ return dept + "::" + div; }
function v33DivEmployees(dept, div){
  return (G.company.employees||[]).filter(e=> e.dept===dept && (e.division||"") === div);
}
function v33DivCost(dept, div){
  return v33DivEmployees(dept, div).reduce((s,e)=> s + (e.salary||0), 0);
}
function v33DivVp(dept, div){
  return v33DivEmployees(dept, div).find(e=> e.rung==="vp")
      || (G.company.employees||[]).find(e=> e.dept===dept && e.rung==="vp");
}
/* Revenue attribution: revenue-facing divisions carry MRR weighted by headcount
   and performance; support functions are cost centres. */
const V33_REVENUE_DEPTS = ["sales","marketing","product"];
function v33DivRevenue(dept, div){
  const c = G.company;
  if(V33_REVENUE_DEPTS.indexOf(dept) < 0) return 0;
  const staff = v33DivEmployees(dept, div);
  if(!staff.length) return 0;
  const allRevStaff = (c.employees||[]).filter(e=> V33_REVENUE_DEPTS.indexOf(e.dept) >= 0);
  const totalWeight = allRevStaff.reduce((s,e)=> s + (1 + ((e.performance||70)-70)/100), 0) || 1;
  const myWeight = staff.reduce((s,e)=> s + (1 + ((e.performance||70)-70)/100), 0);
  return Math.round((c.mrr||0) * (myWeight/totalWeight));
}
function v33DivRows(){
  const c = G.company;
  const rows = [];
  const depts = Object.keys((typeof V32_DIVISIONS!=="undefined" && V32_DIVISIONS) || {});
  depts.forEach(dept=>{
    (V32_DIVISIONS[dept]||[]).forEach(div=>{
      const staff = v33DivEmployees(dept, div);
      if(!staff.length) return;
      const cost = v33DivCost(dept, div);
      const rev = v33DivRevenue(dept, div);
      const budget = v33DivState().budgets[v33DivKey(dept,div)] || 0;
      rows.push({
        dept, div, staff:staff.length, cost, rev,
        margin: rev - cost,
        budget,
        over: budget > 0 && cost > budget,
        vp: v33DivVp(dept, div) || null,
        revenueCentre: V33_REVENUE_DEPTS.indexOf(dept) >= 0
      });
    });
  });
  return rows.sort((a,b)=> b.margin - a.margin);
}
function v33SetBudget(dept, div){
  const key = v33DivKey(dept, div);
  const cur = v33DivState().budgets[key] || v33DivCost(dept, div);
  const base = Math.max(5000, Math.round(v33DivCost(dept, div) || 20000));
  v30AmountDialog({
    title:`Budget \u2014 ${div}`,
    subtitle:`Monthly payroll cap for this division. Current spend ${fmt$(v33DivCost(dept,div))}.`,
    presets:[
      { label:"Freeze at today", value:base },
      { label:"+10%", value:Math.round(base*1.1) },
      { label:"+25%", value:Math.round(base*1.25) },
      { label:"+50%", value:Math.round(base*1.5) },
      { label:"Cut 20%", value:Math.round(base*0.8) }
    ],
    suggested: cur,
    hint:"Divisions that run over budget flag their VP for review.",
    onPick:(amt)=>{
      v33DivState().budgets[key] = Math.max(0, Math.round(amt));
      v30Toast(`<b>Budget set.</b> ${div} capped at ${fmt$(Math.round(amt))}/mo.`, "good");
      try{ renderAll(); }catch(e){}
    }
  });
}
function v33FireVp(dept, div){
  const vp = v33DivVp(dept, div);
  if(!vp){ v30Toast("No VP in that division.", "warn"); return; }
  if(!window.confirm(`Remove ${vp.name} as VP of ${div}? Severance applies and the team takes a morale hit.`)) return;
  try{ fireEmployee(vp.id); }catch(e){}
  try{ logHistory(`Removed ${vp.name} (VP, ${div}) on division performance.`); }catch(e){}
  try{ renderAll(); }catch(e){}
}
function v33DivisionCard(){
  const rows = v33DivRows();
  const box = el(`<div class="card mt14" data-v33divbox></div>`);
  if(!rows.length){
    box.innerHTML = `<h3>\u{1F4CA} Division P&L</h3><div class="muted" style="font-size:12px;">Hire into a department to open its divisions. VPs get measured on the numbers below.</div>`;
    return box;
  }
  const totalRev = rows.reduce((s,r)=>s+r.rev,0);
  const totalCost = rows.reduce((s,r)=>s+r.cost,0);
  box.innerHTML = `
    <h3>\u{1F4CA} Division P&L</h3>
    <div class="muted" style="font-size:11.5px;margin-bottom:8px;">Attributed revenue ${fmt$(totalRev)}/mo \u00b7 payroll ${fmt$(totalCost)}/mo \u00b7 net ${fmt$(totalRev-totalCost)}/mo. Revenue is attributed to sales, marketing and product by headcount and performance; everything else is a cost centre.</div>
    <div class="v33-div">
      ${rows.map(r=>`
        <div class="v33-divcard">
          <div class="flexrow" style="justify-content:space-between;align-items:flex-start;">
            <h4>${r.div}</h4>
            <span class="v33-flag ${r.over? "v33-over":"v33-ok"}">${r.over? "Over budget":"On budget"}</span>
          </div>
          <div class="muted" style="font-size:10.5px;text-transform:uppercase;letter-spacing:.4px;">${r.dept} \u00b7 ${r.staff} people</div>
          <div class="v33-kv"><span class="muted">VP</span><span>${r.vp? r.vp.name : "\u2014 vacant"}</span></div>
          ${r.revenueCentre? `<div class="v33-kv"><span class="muted">Revenue</span><span>${fmt$(r.rev)}/mo</span></div>`:""}
          <div class="v33-kv"><span class="muted">Payroll</span><span>${fmt$(r.cost)}/mo</span></div>
          <div class="v33-kv"><span class="muted">${r.revenueCentre? "Margin":"Net cost"}</span><span style="color:${r.margin>=0? "#22c55e":"#ef4444"};font-weight:700;">${fmt$(r.margin)}/mo</span></div>
          <div class="v33-kv"><span class="muted">Budget</span><span>${r.budget? fmt$(r.budget)+"/mo" : "none set"}</span></div>
          <div class="flexrow mt8" style="gap:6px;">
            <button class="btn secondary small" data-v33budget="${r.dept}|${r.div}">Set budget</button>
            ${r.vp? `<button class="btn secondary small" data-v33firevp="${r.dept}|${r.div}">Replace VP</button>`:""}
          </div>
        </div>`).join("")}
    </div>`;
  box.querySelectorAll("[data-v33budget]").forEach(b=>{
    const [dept, div] = b.getAttribute("data-v33budget").split("|");
    b.onclick = ()=> v33SetBudget(dept, div);
  });
  box.querySelectorAll("[data-v33firevp]").forEach(b=>{
    const [dept, div] = b.getAttribute("data-v33firevp").split("|");
    b.onclick = ()=> v33FireVp(dept, div);
  });
  return box;
}

/* ---------------- Annual comp review ---------------- */
function v33CompState(){
  const c = G.company;
  if(!c.v33comp) c.v33comp = { lastYear:0, open:false, draft:{} };
  return c.v33comp;
}
function v33DeptsWithStaff(){
  const seen = {};
  (G.company.employees||[]).forEach(e=>{ if(e.dept) seen[e.dept] = (seen[e.dept]||0)+1; });
  return Object.keys(seen).map(d=>({ dept:d, n:seen[d] }));
}
function v33DeptPayroll(dept){
  return (G.company.employees||[]).filter(e=>e.dept===dept).reduce((s,e)=>s+(e.salary||0),0);
}
function v33MarketGap(dept){
  // how far behind the market your pay is, driven by rival aggression
  try{
    const st = v33State();
    const heat = v33LiveRivals().reduce((s,r)=>s+r.aggression,0) / Math.max(1, v33LiveRivals().length);
    return Math.round(3 + heat*7);
  }catch(e){ return 5; }
}
function v33OpenCompReview(){
  const cs = v33CompState();
  cs.open = true;
  const depts = v33DeptsWithStaff();
  if(!depts.length){ v30Toast("No staff to review yet.", "warn"); cs.open = false; return; }
  const box = document.getElementById("modalBox");
  const overlay = document.getElementById("modalOverlay");
  if(!box || !overlay) return;
  box.innerHTML = `
    <h3>\u{1F4B0} Annual compensation review \u2014 Year ${G.company.year}</h3>
    <div class="muted" style="font-size:12px;">Set a raise percentage per department. Market is running about <b>${v33MarketGap()}%</b> this year \u2014 pay below it and rivals will make offers your people take.</div>
    <div class="v33-comp">
      ${depts.map(d=>`
        <div class="v33-comprow">
          <span style="flex:1;text-transform:capitalize;">${d.dept} <span class="muted">\u00b7 ${d.n} people \u00b7 ${fmt$(v33DeptPayroll(d.dept))}/mo</span></span>
          <input type="number" min="0" max="30" value="${v33MarketGap()}" data-v33raise="${d.dept}" /> <span class="muted">%</span>
        </div>`).join("")}
    </div>
    <div class="muted" style="font-size:11px;margin-top:6px;" data-v33comptotal></div>
    <div class="flexrow mt14" style="gap:8px;justify-content:flex-end;">
      <button class="btn secondary small" data-v33compskip>Skip this year</button>
      <button class="btn small" data-v33compapply>Approve raises</button>
    </div>`;
  overlay.classList.add("show");
  const recalc = ()=>{
    let add = 0;
    box.querySelectorAll("[data-v33raise]").forEach(inp=>{
      const dept = inp.getAttribute("data-v33raise");
      add += v33DeptPayroll(dept) * (Number(inp.value||0)/100);
    });
    const t = box.querySelector("[data-v33comptotal]");
    if(t) t.textContent = `Adds ${fmt$(Math.round(add))}/mo to payroll (${fmt$(Math.round(add*12))}/yr).`;
  };
  box.querySelectorAll("[data-v33raise]").forEach(inp=> inp.oninput = recalc);
  recalc();
  const close = ()=>{ overlay.classList.remove("show"); v33CompState().open = false; };
  const skip = box.querySelector("[data-v33compskip]");
  if(skip) skip.onclick = ()=>{
    const c = G.company;
    c.retentionScore = clamp((c.retentionScore||72) - 12, 0, 100);
    (c.employees||[]).forEach(e=>{ e.morale = clamp((e.morale||70) - 8, 0, 100); });
    try{ logHistory("Skipped the annual comp review. Morale and retention took the hit."); }catch(e){}
    v30Toast("<b>Skipped.</b> Word travels. Retention dropped.", "bad");
    close(); try{ renderAll(); }catch(e){}
  };
  const apply = box.querySelector("[data-v33compapply]");
  if(apply) apply.onclick = ()=>{
    const c = G.company;
    const market = v33MarketGap();
    let added = 0, happy = 0, sour = 0;
    box.querySelectorAll("[data-v33raise]").forEach(inp=>{
      const dept = inp.getAttribute("data-v33raise");
      const pct = clamp(Number(inp.value||0), 0, 30);
      (c.employees||[]).filter(e=>e.dept===dept).forEach(e=>{
        const bump = Math.round((e.salary||0) * (pct/100));
        e.salary = (e.salary||0) + bump;
        added += bump;
        if(pct >= market){ e.morale = clamp((e.morale||70) + 9, 0, 100); happy++; }
        else { e.morale = clamp((e.morale||70) - (market-pct), 0, 100); sour++; }
      });
    });
    c.retentionScore = clamp((c.retentionScore||72) + (happy > sour ? 10 : -6), 0, 100);
    try{ logHistory(`Annual comp review: ${fmt$(added)}/mo of raises approved across the company.`); }catch(e){}
    v30Toast(`<b>Raises approved.</b> ${fmt$(added)}/mo added to payroll.`, "good");
    close(); try{ renderAll(); }catch(e){}
  };
}
(function v33CompTrigger(){
  try{
    const prev = advanceMonth;
    advanceMonth = function(){
      const r = prev.apply(this, arguments);
      try{
        const c = G.company;
        const cs = v33CompState();
        if(c.month === 1 && c.year > cs.lastYear && (c.employees||[]).length >= 3){
          cs.lastYear = c.year;
          setTimeout(()=>{ try{ v33OpenCompReview(); }catch(e){} }, 500);
        }
      }catch(e){}
      return r;
    };
  }catch(e){}
})();

