/* ================= v34 ================= */
/* ============ v34 — Nameless client book ============
   Individual client names are gone from the game entirely.
   The book is four segments: Enterprise, Large, Mid-Market, Small.
   Client relations are whole-book or per-segment batch actions only. */

(function v34Css(){
  try{
    const s = document.createElement("style");
    s.textContent = `
    .v34-seg{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:10px;}
    .v34-card{border:1px solid rgba(255,255,255,.1);border-radius:12px;padding:12px;}
    .v34-card .lbl{font-size:10.5px;text-transform:uppercase;letter-spacing:.6px;opacity:.65;}
    .v34-card .cnt{font-size:24px;font-weight:800;line-height:1.1;margin-top:2px;}
    .v34-card .mrr{font-size:13px;font-weight:700;margin-top:2px;}
    .v34-card .sub{font-size:11px;opacity:.7;margin-top:3px;}
    .v34-card .risk{color:#ef4444;font-weight:700;}
    .v34-tot{display:flex;gap:18px;flex-wrap:wrap;font-size:12px;margin-bottom:10px;}
    .v34-tot b{font-size:15px;display:block;}
    .v34-acts{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px;}
    `;
    document.head.appendChild(s);
  }catch(e){}
})();

const V34_SEGMENTS = [
  { key:"enterprise", label:"Enterprise",  min:25000, blurb:"Largest contracts, slowest to move" },
  { key:"large",      label:"Large",       min:9000,  blurb:"Big, but not household names" },
  { key:"midmarket",  label:"Mid-Market",  min:3000,  blurb:"The volume engine" },
  { key:"small",      label:"Small",       min:0,     blurb:"High churn, low touch" }
];
function v34Seg(cl){
  const mrr = (cl && (cl.mrr || cl.monthlyValue || cl.value)) || 0;
  return (V34_SEGMENTS.find(s=> mrr >= s.min) || V34_SEGMENTS[V34_SEGMENTS.length-1]).key;
}
function v34SegLabel(key){ const s = V34_SEGMENTS.find(x=>x.key===key); return s? s.label : "Small"; }

/* ---------- Name eradication ---------- */
const V34_SCRUBBED = [];
function v34Anon(cl){
  if(!cl) return cl;
  const seg = v34SegLabel(v34Seg(cl));
  const old = cl.name;
  if(old && typeof old === "string" && old.indexOf(" account") < 0){
    if(V34_SCRUBBED.indexOf(old) < 0 && old.length > 2) V34_SCRUBBED.push(old);
    if(V34_SCRUBBED.length > 400) V34_SCRUBBED.splice(0, 200);
  }
  cl.name = seg + " account";
  cl.segment = v34Seg(cl);
  return cl;
}
function v34AnonAll(){
  try{ (G.company.clients||[]).forEach(v34Anon); }catch(e){}
}
/* every creation path funnels through Array#push on c.clients */
function v34GuardClients(){
  try{
    const c = G.company;
    if(!c || !Array.isArray(c.clients)) return;
    if(c.clients.__v34) { v34AnonAll(); return; }
    Object.defineProperty(c.clients, "__v34", { value:true, enumerable:false, writable:true });
    Object.defineProperty(c.clients, "push", {
      value: function(){
        const args = [].slice.call(arguments).map(a=> (a && typeof a === "object") ? v34Anon(a) : a);
        return Array.prototype.push.apply(this, args);
      },
      enumerable:false, writable:true, configurable:true
    });
    v34AnonAll();
  }catch(e){}
}
/* scrub any legacy name that already made it into a log line */
(function v34ScrubLog(){
  try{
    if(typeof logHistory !== "function") return;
    const prev = logHistory;
    logHistory = function(text){
      let t = text;
      try{
        if(typeof t === "string" && V34_SCRUBBED.length){
          V34_SCRUBBED.forEach(n=>{
            if(n && t.indexOf(n) >= 0) t = t.split(n).join("a client");
          });
        }
      }catch(e){}
      return prev.call(this, t);
    };
  }catch(e){}
})();

/* ---------- Rollup ---------- */
function v34Rollup(){
  const out = {};
  V34_SEGMENTS.forEach(s=> out[s.key] = { count:0, mrr:0, health:0, risk:0, newThisYear:0 });
  try{
    (G.company.clients||[]).forEach(cl=>{
      const b = out[v34Seg(cl)];
      b.count++;
      b.mrr += (cl.mrr || cl.monthlyValue || cl.value || 0);
      b.health += (cl.health || 70);
      if((cl.health||70) < 45) b.risk++;
      if(cl.sinceYear === G.company.year) b.newThisYear++;
    });
  }catch(e){}
  Object.keys(out).forEach(k=>{ const b = out[k]; b.health = b.count ? Math.round(b.health/b.count) : 0; });
  return out;
}

/* ---------- Whole-book and batch actions ---------- */
function v34Targets(segKey){
  return (G.company.clients||[]).filter(cl=> segKey==="all" || v34Seg(cl)===segKey);
}
function v34Label(segKey){ return segKey==="all" ? "the whole book" : v34SegLabel(segKey); }
function v34Checkin(segKey){
  const targets = v34Targets(segKey);
  if(!targets.length){ v30Toast("No accounts in that segment.", "warn"); return; }
  const cost = targets.length * 180;
  if(typeof affordOrAlert==="function" && !affordOrAlert(cost, "a batch check-in")) return;
  queueAdd({ id:uid(), label:`Check-ins: ${v34Label(segKey)} (${targets.length})`, cost, run:(report)=>{
    if(G.company.cash < cost){ report.push("Skipped the check-ins \u2014 not enough cash."); return; }
    G.company.cash -= cost;
    let improved = 0;
    targets.forEach(cl=>{
      const before = cl.health || 70;
      cl.health = clamp(before + (before < 55 ? 12 : 6), 0, 100);
      cl.lastCheckin = { month:G.company.month, year:G.company.year };
      if(cl.health > before) improved++;
    });
    report.push(`\u{1F4DE} Checked in across ${targets.length} ${v34Label(segKey)} accounts \u2014 health improved on ${improved}.`);
  }});
  v30Toast(`<b>Queued.</b> Check-ins across ${targets.length} accounts for ${fmt$(cost)}.`, "good");
}
function v34Retention(segKey){
  const targets = v34Targets(segKey).filter(cl=> (cl.health||70) < 70);
  if(!targets.length){ v30Toast("Nothing at risk in that segment.", "warn"); return; }
  const cost = targets.length * 450;
  if(typeof affordOrAlert==="function" && !affordOrAlert(cost, "a retention campaign")) return;
  queueAdd({ id:uid(), label:`Retention campaign: ${v34Label(segKey)} (${targets.length})`, cost, run:(report)=>{
    if(G.company.cash < cost){ report.push("Skipped the retention campaign \u2014 not enough cash."); return; }
    G.company.cash -= cost;
    targets.forEach(cl=>{ cl.health = clamp((cl.health||70) + 22, 0, 100); });
    report.push(`\u{1F6E1}\uFE0F Retention campaign steadied ${targets.length} at-risk ${v34Label(segKey)} accounts.`);
  }});
  v30Toast(`<b>Queued.</b> Retention campaign for ${fmt$(cost)}.`, "good");
}
function v34Upsell(segKey){
  const targets = v34Targets(segKey).filter(cl=> (cl.health||70) >= 65);
  if(!targets.length){ v30Toast("No healthy accounts to upsell there.", "warn"); return; }
  const cost = targets.length * 320;
  if(typeof affordOrAlert==="function" && !affordOrAlert(cost, "an upsell campaign")) return;
  queueAdd({ id:uid(), label:`Upsell campaign: ${v34Label(segKey)} (${targets.length})`, cost, run:(report)=>{
    if(G.company.cash < cost){ report.push("Skipped the upsell campaign \u2014 not enough cash."); return; }
    G.company.cash -= cost;
    let won = 0, added = 0;
    targets.forEach(cl=>{
      if(Math.random() < 0.28){
        const bump = Math.round((cl.mrr||0) * 0.12);
        cl.mrr = (cl.mrr||0) + bump;
        G.company.mrr = (G.company.mrr||0) + bump;
        added += bump; won++;
      }
    });
    report.push(won? `\u{1F4C8} Upsell campaign closed ${won} expansions \u2014 ${fmt$(added)}/mo added.`
                   : `\u{1F4C9} The upsell campaign across ${targets.length} accounts landed nothing this month.`);
  }});
  v30Toast(`<b>Queued.</b> Upsell campaign for ${fmt$(cost)}.`, "good");
}
function v34QBR(){
  const targets = v34Targets("enterprise").concat(v34Targets("large"));
  if(!targets.length){ v30Toast("No Enterprise or Large accounts yet.", "warn"); return; }
  const cost = targets.length * 1200;
  if(typeof affordOrAlert==="function" && !affordOrAlert(cost, "quarterly business reviews")) return;
  queueAdd({ id:uid(), label:`QBRs: Enterprise + Large (${targets.length})`, cost, run:(report)=>{
    if(G.company.cash < cost){ report.push("Skipped the QBRs \u2014 not enough cash."); return; }
    G.company.cash -= cost;
    targets.forEach(cl=>{
      cl.health = clamp((cl.health||70) + 15, 0, 100);
      cl.lastQbr = { month:G.company.month, year:G.company.year };
    });
    try{ G.company.retentionScore = clamp((G.company.retentionScore||72) + 3, 0, 100); }catch(e){}
    report.push(`\u{1F4CA} Ran QBRs across ${targets.length} top accounts \u2014 health and standing up.`);
  }});
  v30Toast(`<b>Queued.</b> QBRs for ${fmt$(cost)}.`, "good");
}

/* ---------- The screen ---------- */
function v34RenderClients(){
  v34GuardClients();
  const c = G.company;
  const roll = v34Rollup();
  const total = Object.keys(roll).reduce((a,k)=>a+roll[k].count,0);
  const totalMrr = Object.keys(roll).reduce((a,k)=>a+roll[k].mrr,0);
  const totalRisk = Object.keys(roll).reduce((a,k)=>a+roll[k].risk,0);
  const avgHealth = total ? Math.round((c.clients||[]).reduce((s,x)=>s+(x.health||70),0)/total) : 0;
  const wrap = el(`<div></div>`);

  const segCards = V34_SEGMENTS.map(s=>{
    const b = roll[s.key];
    return `<div class="v34-card">
      <div class="lbl">${s.label}</div>
      <div class="cnt">${b.count}</div>
      <div class="mrr">${fmt$(Math.round(b.mrr))}/mo</div>
      <div class="sub">Avg health ${b.count? b.health : "\u2014"}${b.risk? ` \u00b7 <span class="risk">${b.risk} at risk</span>` : ""}</div>
      <div class="sub">${s.blurb}</div>
      <div class="v34-acts">
        <button class="btn secondary small" data-v34act="checkin|${s.key}" ${b.count?"":"disabled"}>Check in</button>
        <button class="btn secondary small" data-v34act="retention|${s.key}" ${b.count?"":"disabled"}>Retain</button>
      </div>
    </div>`;
  }).join("");

  wrap.innerHTML = `
    <div class="window-title"><h2>\u{1F91D} Clients</h2><span class="sub">${total} accounts \u00b7 ${fmt$(Math.round(totalMrr))}/mo</span></div>

    <div class="card">
      <div class="v34-tot">
        <span><b>${total}</b><span class="muted">accounts</span></span>
        <span><b>${fmt$(Math.round(totalMrr))}</b><span class="muted">book MRR</span></span>
        <span><b>${fmt$(total? Math.round(totalMrr/total) : 0)}</b><span class="muted">avg account</span></span>
        <span><b>${avgHealth || "\u2014"}</b><span class="muted">avg health</span></span>
        <span><b style="color:${totalRisk? "#ef4444":"inherit"};">${totalRisk}</b><span class="muted">at risk</span></span>
      </div>
      <div class="v34-seg">${segCards}</div>
      ${total? "" : `<div class="muted mt8" style="font-size:12px;">No accounts yet \u2014 hire sales and marketing to start winning business.</div>`}
    </div>

    <div class="card mt14">
      <h3>\u{1F4DE} Client relations</h3>
      <div class="muted" style="font-size:11.5px;">Run the book, not the names. Every action applies across a segment or the entire book.</div>
      <div class="v34-acts">
        <button class="btn small" data-v34act="checkin|all" ${total?"":"disabled"}>Check in with the whole book</button>
        <button class="btn secondary small" data-v34act="retention|all" ${total?"":"disabled"}>Retention campaign \u2014 everything at risk</button>
        <button class="btn secondary small" data-v34act="upsell|all" ${total?"":"disabled"}>Upsell campaign \u2014 healthy accounts</button>
        <button class="btn secondary small" data-v34act="qbr|all" ${(roll.enterprise.count+roll.large.count)?"":"disabled"}>QBRs \u2014 Enterprise + Large</button>
      </div>
      <div class="muted mt8" style="font-size:11px;">Check-in $180/account \u00b7 retention $450/at-risk account \u00b7 upsell $320/healthy account \u00b7 QBR $1,200/top account.</div>
    </div>`;

  wrap.querySelectorAll("[data-v34act]").forEach(b=>{
    b.onclick = ()=>{
      const [kind, seg] = b.getAttribute("data-v34act").split("|");
      if(kind==="checkin") v34Checkin(seg);
      else if(kind==="retention") v34Retention(seg);
      else if(kind==="upsell") v34Upsell(seg);
      else if(kind==="qbr") v34QBR();
    };
  });
  return wrap;
}

/* take ownership of the screen after every earlier wrapper has installed */
(function v34TakeOverClients(){
  try{ renderClients = v34RenderClients; }catch(e){}
})();

/* ---------- Keep names out on every turn and every load ---------- */
(function v34MonthHook(){
  try{
    const prev = advanceMonth;
    advanceMonth = function(){
      const r = prev.apply(this, arguments);
      try{ v34GuardClients(); }catch(e){}
      return r;
    };
  }catch(e){}
})();
(function v34RenderHook(){
  try{
    const prev = renderAll;
    renderAll = function(){
      try{ v34GuardClients(); }catch(e){}
      return prev.apply(this, arguments);
    };
  }catch(e){}
})();
(function v34Normalize(){
  try{
    if(typeof normalizeGame !== "function") return;
    const prev = normalizeGame;
    normalizeGame = function(state){
      const s = prev.apply(this, arguments) || state;
      try{
        const cos = (s && s.companies) ? Object.keys(s.companies).map(k=>s.companies[k]) : [];
        cos.forEach(co=>{
          if(!co || !Array.isArray(co.clients)) return;
          co.clients.forEach(cl=>{
            if(!cl) return;
            const mrr = cl.mrr || cl.monthlyValue || cl.value || 0;
            const seg = (V34_SEGMENTS.find(x=> mrr >= x.min) || V34_SEGMENTS[V34_SEGMENTS.length-1]);
            cl.segment = seg.key;
            cl.name = seg.label + " account";
          });
        });
      }catch(e){}
      return s;
    };
  }catch(e){}
})();


/* ================= v34.1 ================= */
/* ============ v34.1 — Storage diet ============
   The activity log was 45% of every save, duplicated across every slot.
   Trim what gets written, show the player what storage costs, and fail
   gracefully instead of silently when localStorage fills up. */

const V341_CAPS = {
  history: 120,      // in-memory activity log
  historySaved: 90,  // what actually gets written to a slot
  feed: 30,          // v33 rival feed
  departures: 40,
  chat: 25
};
const V341_BUDGET = 5 * 1024 * 1024; // browsers cap localStorage near 5MB per origin

/* ---------- keep the in-memory log lean ---------- */
(function v341LogCap(){
  try{
    if(typeof logHistory !== "function") return;
    const prev = logHistory;
    logHistory = function(){
      const r = prev.apply(this, arguments);
      try{
        const h = G.company.history;
        if(h && h.length > V341_CAPS.history) h.length = V341_CAPS.history;
      }catch(e){}
      return r;
    };
  }catch(e){}
})();

/* ---------- trim the payload on the way to disk ---------- */
function v341TrimCompany(co){
  if(!co) return;
  try{
    if(Array.isArray(co.history) && co.history.length > V341_CAPS.historySaved) co.history.length = V341_CAPS.historySaved;
    if(co.v33 && Array.isArray(co.v33.feed) && co.v33.feed.length > V341_CAPS.feed) co.v33.feed.length = V341_CAPS.feed;
    if(Array.isArray(co.departures) && co.departures.length > V341_CAPS.departures) co.departures = co.departures.slice(-V341_CAPS.departures);
    if(co.v33div && co.v33div.history && Array.isArray(co.v33div.history) && co.v33div.history.length > 40) co.v33div.history = co.v33div.history.slice(-40);
  }catch(e){}
}
function v341TrimState(state){
  try{
    if(Array.isArray(state.assistantChat) && state.assistantChat.length > V341_CAPS.chat) state.assistantChat = state.assistantChat.slice(-V341_CAPS.chat);
    const cos = state.companies || {};
    Object.keys(cos).forEach(k=> v341TrimCompany(cos[k]));
  }catch(e){}
  return state;
}

/* ---------- storage accounting ---------- */
function v341Usage(){
  let total = 0; const rows = [];
  try{
    for(let i=0;i<localStorage.length;i++){
      const key = localStorage.key(i);
      const val = localStorage.getItem(key) || "";
      const bytes = (key.length + val.length) * 2; // UTF-16 in practice
      total += bytes;
      if(key.indexOf(LS_PREFIX) === 0) rows.push({ key, bytes });
    }
  }catch(e){}
  rows.sort((a,b)=>b.bytes-a.bytes);
  return { total, rows, pct: Math.min(100, Math.round(total * 100 / V341_BUDGET)) };
}
function v341Kb(bytes){
  if(bytes >= 1024*1024) return (bytes/1024/1024).toFixed(2) + " MB";
  return Math.max(1, Math.round(bytes/1024)) + " KB";
}

/* ---------- safe save: trim, then handle a full disk honestly ---------- */
(function v341SafeSave(){
  try{
    if(typeof saveToSlot !== "function") return;
    const prev = saveToSlot;
    saveToSlot = function(state, slotKey, label){
      try{ v341TrimState(state); }catch(e){}
      try{
        return prev.call(this, state, slotKey, label);
      }catch(err){
        try{
          // quota exceeded — drop the autosave and retry once
          localStorage.removeItem(LS_PREFIX + "autosave");
          return prev.call(this, state, slotKey, label);
        }catch(err2){
          try{ v30Toast("<b>Save failed.</b> Browser storage is full \u2014 delete an old slot and try again.", "bad"); }catch(e){}
          return null;
        }
      }
    };
  }catch(e){}
})();

/* ---------- one-time cleanup of already-bloated slots ---------- */
function v341CompactAll(){
  let before = v341Usage().total, touched = 0;
  try{
    const keys = [];
    for(let i=0;i<localStorage.length;i++){
      const k = localStorage.key(i);
      if(k && k.indexOf(LS_PREFIX) === 0 && k !== LS_SLOTS_INDEX) keys.push(k);
    }
    keys.forEach(k=>{
      try{
        const raw = localStorage.getItem(k);
        if(!raw || raw.charAt(0) !== "{") return;
        const parsed = JSON.parse(raw);
        if(!parsed || !parsed.companies) return;
        v341TrimState(parsed);
        localStorage.setItem(k, JSON.stringify(parsed));
        touched++;
      }catch(e){}
    });
  }catch(e){}
  const after = v341Usage().total;
  const saved = Math.max(0, before - after);
  try{
    v30Toast(touched
      ? `<b>Compacted ${touched} save${touched===1?"":"s"}.</b> Recovered ${v341Kb(saved)}.`
      : "Nothing to compact.", "good");
  }catch(e){}
  try{ renderScreen(); }catch(e){}
  return { touched, saved };
}

/* ---------- storage card on the Saves screen ---------- */
function v341StorageCard(){
  const u = v341Usage();
  const tone = u.pct > 80 ? "#ef4444" : u.pct > 55 ? "#f59e0b" : "#22c55e";
  return `<div class="card mb8" data-v341storage>
    <h3>\u{1F4BE} Storage</h3>
    <div class="muted" style="font-size:11.5px;">Saves live in your browser, which allows roughly 5 MB in total across every slot.</div>
    <div style="margin:8px 0 6px;height:8px;border-radius:6px;background:rgba(255,255,255,.08);overflow:hidden;">
      <div style="height:100%;width:${Math.max(2,u.pct)}%;background:${tone};"></div>
    </div>
    <div style="font-size:12px;"><b>${v341Kb(u.total)}</b> used \u00b7 ${u.pct}% of the browser budget \u00b7 ${u.rows.length} stored item${u.rows.length===1?"":"s"}</div>
    ${u.rows.length ? `<div class="muted" style="font-size:11px;margin-top:6px;">Largest: ${u.rows.slice(0,3).map(r=>`${r.key.replace(LS_PREFIX,"")} ${v341Kb(r.bytes)}`).join(" \u00b7 ")}</div>` : ""}
    <button class="btn secondary small" style="margin-top:8px;" data-v341compact>\u{1F9F9} Compact all saves</button>
  </div>`;
}
(function v341SavesHook(){
  try{
    if(typeof renderSaves !== "function") return;
    const prev = renderSaves;
    renderSaves = function(){
      const wrap = prev.apply(this, arguments);
      try{
        const box = document.createElement("div");
        box.innerHTML = v341StorageCard();
        const node = box.firstElementChild;
        const title = wrap.querySelector(".window-title");
        if(title && title.nextSibling) wrap.insertBefore(node, title.nextSibling);
        else wrap.appendChild(node);
        const btn = node.querySelector("[data-v341compact]");
        if(btn) btn.onclick = ()=> v341CompactAll();
      }catch(e){}
      return wrap;
    };
  }catch(e){}
})();

/* ---------- trim legacy saves as they load ---------- */
(function v341NormalizeHook(){
  try{
    if(typeof normalizeGame !== "function") return;
    const prev = normalizeGame;
    normalizeGame = function(state){
      const s = prev.apply(this, arguments) || state;
      try{ v341TrimState(s); }catch(e){}
      return s;
    };
  }catch(e){}
})();

