function v35Co(){ return (typeof G!=="undefined" && G && G.company) ? G.company : null; }
function v35Toast(m,k){ try{ if(typeof toast==="function") toast(m,k); }catch(e){} }
function v35Rand(a,b){ return a + Math.floor(Math.random()*(b-a+1)); }

/* ---------- 1. Scale tiers: events grow with the company ---------- */
function v35Tier(){
  const c = v35Co(); if(!c) return 1;
  const hc = (c.employees||[]).length, val = c.valuation||0;
  if(hc >= 400 || val >= 25000000) return 4;
  if(hc >= 120 || val >= 6000000) return 3;
  if(hc >= 25  || val >= 750000) return 2;
  return 1;
}
function v35Scale(base){
  const t = v35Tier();
  const mult = [0,1,3.5,11,30][t] || 1;
  const c = v35Co();
  const floor = c ? Math.max(1, Math.round((c.mrr||0)*0.04)) : 1;
  return Math.max(Math.round(base*mult), floor);
}

/* ---------- 2. Employee storage compression ---------- */
function v35RoleFor(dept, rung){
  try{
    const L = LADDERS[dept]; if(!L) return rung;
    const r = (L.rungs||[]).find(x=>x.key===rung);
    return r ? r.label : rung;
  }catch(e){ return rung; }
}
function v35Idx(arr, val){
  if(val===undefined || val===null) return -1;
  let i = arr.indexOf(val);
  if(i<0){ arr.push(val); i = arr.length-1; }
  return i;
}
function v35PackEmployees(co){
  const emps = co.employees;
  if(!Array.isArray(emps) || !emps.length) return;
  const depts=[], rungs=[], divs=[], icons=[];
  const rows = emps.map(e=>{
    const row = {
      i: e.id, n: e.name,
      d: v35Idx(depts, e.dept), r: v35Idx(rungs, e.rung),
      s: e.salary, hm: e.hiredMonth, hy: e.hiredYear
    };
    if(e.performance !== 100) row.p = e.performance;
    if(e.morale !== 100) row.m = e.morale;
    if(e.division) row.v = v35Idx(divs, e.division);
    if(e.lineId) row.l = e.lineId;
    const derivedRole = v35RoleFor(e.dept, e.rung);
    if(e.role && e.role !== derivedRole) row.o = e.role;
    if(e.icon) row.c = v35Idx(icons, e.icon);
    Object.keys(e).forEach(k=>{
      if(["id","name","dept","rung","salary","hiredMonth","hiredYear","performance","morale","division","lineId","role","icon"].indexOf(k)<0){
        row.x = row.x || {}; row.x[k] = e[k];
      }
    });
    return row;
  });
  co.__v35e = { depts, rungs, divs, icons, rows };
  delete co.employees;
}
function v35UnpackEmployees(co){
  const pk = co && co.__v35e;
  if(!pk || !Array.isArray(pk.rows)) return;
  co.employees = pk.rows.map(row=>{
    const dept = pk.depts[row.d], rung = pk.rungs[row.r];
    const e = {
      id: row.i, name: row.n, dept: dept, rung: rung,
      role: row.o || v35RoleFor(dept, rung),
      icon: (row.c>=0 && pk.icons[row.c]) || "\u{1F464}",
      salary: row.s,
      performance: (row.p===undefined ? 100 : row.p),
      morale: (row.m===undefined ? 100 : row.m),
      hiredMonth: row.hm, hiredYear: row.hy,
      division: (row.v>=0 ? pk.divs[row.v] : undefined),
      lineId: (row.l===undefined ? null : row.l)
    };
    if(row.x) Object.keys(row.x).forEach(k=> e[k] = row.x[k]);
    return e;
  });
  delete co.__v35e;
}

/* ---------- 3. Activity log compression (counters + tiering) ---------- */
const V35_VERBATIM_MONTHS = 3;
function v35AbsMonth(y,m){ return (y||1)*12 + (m||1); }
function v35PackHistory(co){
  const h = co.history;
  if(!Array.isArray(h) || h.length < 12) return;
  const nowAbs = v35AbsMonth(co.year, co.month);
  const recent = [], older = [];
  h.forEach(en=>{
    const abs = v35AbsMonth(en.year, en.month);
    if(nowAbs - abs <= V35_VERBATIM_MONTHS) recent.push(en); else older.push(en);
  });
  const byPeriod = {};
  older.forEach(en=>{
    const age = nowAbs - v35AbsMonth(en.year, en.month);
    const key = age <= 12 ? ("m" + en.year + "-" + en.month) : ("y" + en.year);
    (byPeriod[key] = byPeriod[key] || []).push(en);
  });
  const digests = Object.keys(byPeriod).map(key=>{
    const items = byPeriod[key];
    const isYear = key.charAt(0)==="y";
    const counts = {};
    items.forEach(en=>{
      const t = String(en.text||"");
      const head = t.split(/[.—-]/)[0].trim().slice(0,46) || "Activity";
      counts[head] = (counts[head]||0) + (en.n||1);
    });
    const top = Object.keys(counts).map(k=>[k,counts[k]]).sort((a,b)=>b[1]-a[1]).slice(0, isYear?4:5);
    const first = items[items.length-1] || items[0];
    const label = isYear ? ("Year "+first.year) : ("Y"+first.year+" M"+first.month);
    const text = label + " summary: " + top.map(t=> t[0] + (t[1]>1 ? " \u00d7"+t[1] : "")).join("; ") +
      (items.length > top.length ? " (+"+(items.length-top.length)+" more)" : "");
    return { text: text, month: first.month, year: first.year, digest: true };
  });
  co.history = recent.concat(digests).slice(0, 140);
}

/* Collapse repeat entries within the same month into a counter. */
(function v35LogCollapse(){
  if(typeof logHistory !== "function") return;
  const prev = logHistory;
  logHistory = function(text){
    const c = v35Co();
    if(c && Array.isArray(c.history) && text){
      const head = String(text).split(/[.\u2014-]/)[0].trim();
      const recent = c.history.slice(0, 6);
      for(let i=0;i<recent.length;i++){
        const en = recent[i];
        if(!en || en.digest) continue;
        if(en.month===c.month && en.year===c.year){
          const enHead = String(en.text||"").split(/[.\u2014-]/)[0].trim();
          if(enHead && enHead === head){
            en.n = (en.n||1) + 1;
            en.text = enHead + " \u00d7" + en.n;
            return;
          }
        }
      }
    }
    return prev.apply(this, arguments);
  };
})();

/* ---------- 4. Compressed save path ---------- */
function v35CompressState(state){
  let clone;
  try{ clone = JSON.parse(JSON.stringify(state)); }catch(e){ return state; }
  const cos = clone.companies || (clone.company ? [clone.company] : []);
  (clone.companies || []).forEach(co=>{ v35PackHistory(co); v35PackEmployees(co); });
  if(clone.company && !clone.companies){ v35PackHistory(clone.company); v35PackEmployees(clone.company); }
  if(clone.company && clone.companies){
    const idx = (state.companies||[]).indexOf(state.company);
    if(idx>=0) clone.company = clone.companies[idx];
  }
  clone.__v35 = 1;
  return clone;
}
function v35ExpandState(state){
  if(!state) return state;
  (state.companies||[]).forEach(co=> v35UnpackEmployees(co));
  if(state.company) v35UnpackEmployees(state.company);
  return state;
}
(function v35SaveHook(){
  if(typeof saveToSlot !== "function") return;
  const prev = saveToSlot;
  saveToSlot = function(state, key, label){
    let payload = state;
    try{ payload = v35CompressState(state); }catch(e){ payload = state; }
    return prev.call(this, payload, key, label);
  };
})();
(function v35NormalizeHook(){
  if(typeof normalizeGame !== "function") return;
  const prev = normalizeGame;
  normalizeGame = function(state){
    try{ v35ExpandState(state); }catch(e){}
    return prev.apply(this, arguments);
  };
})();

/* ---------- 5. Zoom: categories, suggestions, Q&A ---------- */
function v35HardMonth(){
  const c = v35Co(); if(!c) return false;
  const fh = c.financialHistory || [];
  const last = fh[fh.length-1];
  if(last && last.netProfit < 0) return true;
  const emps = c.employees||[];
  if(emps.length && (emps.reduce((s,e)=>s+e.morale,0)/emps.length) < 55) return true;
  if((c.churnedThisMonth||0) > 0) return true;
  return false;
}
function v35Complaints(){
  const c = v35Co(); if(!c) return [];
  const emps = c.employees||[];
  const out = [];
  const lowPay = emps.filter(e=> e.morale < 62);
  if(lowPay.length) out.push({
    key:"pay", icon:"\u{1F4B8}", title:"Compensation", count: lowPay.length,
    detail:"People below 62 morale are the ones most likely to name pay first.",
    suggestion:"Give this group a 6% adjustment",
    cost: Math.round(lowPay.reduce((s,e)=>s+e.salary,0)*0.06),
    run:()=>{ lowPay.forEach(e=>{ e.salary = Math.round(e.salary*1.06); e.morale = clamp(e.morale+11,0,100); });
      return lowPay.length+" people got a 6% adjustment."; }
  });
  const ratio = emps.length ? (c.clients||[]).length / emps.length : 0;
  if(ratio > 6) out.push({
    key:"load", icon:"\u{1F4DA}", title:"Workload", count: Math.round(ratio),
    detail:"Accounts per head is "+Math.round(ratio)+":1. Above 6 the team feels it.",
    suggestion:"Approve overtime relief this month",
    cost: v35Scale(400),
    run:()=>{ emps.forEach(e=> e.morale = clamp(e.morale+7,0,100)); return "Overtime relief approved company-wide."; }
  });
  const noLead = (typeof DEPT_KEYS!=="undefined" ? DEPT_KEYS : []).filter(dk=>{
    const staff = emps.filter(e=>e.dept===dk);
    return staff.length >= 3 && !staff.some(e=> typeof isLeader==="function" && isLeader(e));
  });
  if(noLead.length) out.push({
    key:"mgmt", icon:"\u{1F9ED}", title:"Management gaps", count: noLead.length,
    detail: noLead.map(d=> (LADDERS[d]?LADDERS[d].label:d)).join(", ")+" have staff but nobody leading them.",
    suggestion:"Name interim leads from within",
    cost: 0,
    run:()=>{ let n=0; noLead.forEach(d=>{ const staff=emps.filter(e=>e.dept===d).sort((a,b)=>b.performance-a.performance)[0];
        if(staff){ staff.morale = clamp(staff.morale+10,0,100); staff.performance = clamp(staff.performance+4,0,100); n++; } });
      return n+" interim lead(s) named."; }
  });
  const prod = c.product || {};
  if((prod.maturity||0) < 55) out.push({
    key:"tools", icon:"\u{1F6E0}\uFE0F", title:"Tools & product gaps", count: Math.round(55-(prod.maturity||0)),
    detail:"Maturity sits at "+(prod.maturity||0)+"/100; the team is apologising for the product.",
    suggestion:"Fund a tooling sprint",
    cost: v35Scale(900),
    run:()=>{ if(c.product) c.product.maturity = clamp((c.product.maturity||0)+4,0,100);
      emps.forEach(e=> e.performance = clamp(e.performance+3,0,100)); return "Tooling sprint funded \u2014 maturity +4."; }
  });
  const stalled = emps.filter(e=> e.performance >= 78 && (typeof isLeader!=="function" || !isLeader(e)));
  if(stalled.length >= 3) out.push({
    key:"growth", icon:"\u{1F4C8}", title:"Career growth", count: stalled.length,
    detail: stalled.length+" high performers have no visible next step.",
    suggestion:"Publish a promotion track",
    cost: v35Scale(300),
    run:()=>{ stalled.forEach(e=> e.morale = clamp(e.morale+9,0,100));
      return "Promotion track published \u2014 "+stalled.length+" high performers responded."; }
  });
  return out;
}
function v35Questions(){
  const c = v35Co(); if(!c) return [];
  const emps = c.employees||[];
  if(!emps.length) return [];
  const qs = [];
  const speaker = (filterFn)=>{ const pool = emps.filter(filterFn||(()=>true)); return pool.length? pick(pool) : pick(emps); };
  const cash = c.cash||0, mrr = c.mrr||0;
  const s1 = speaker(e=>e.dept==="sales");
  qs.push({ id:"runway", who: s1, q:"Are we financially okay? People are asking.",
    ans: cash > mrr*3 ? "We have "+fmt$(cash)+" in the bank against "+fmt$(mrr)+" MRR. We're fine."
                      : "Cash is "+fmt$(cash)+". It's tighter than I'd like, and I won't pretend otherwise.",
    options:[
      { label:"Answer straight", run:()=>{ emps.forEach(e=> e.morale=clamp(e.morale+4,0,100)); return "You answered honestly \u2014 morale +4 company-wide."; } },
      { label:"Deflect", run:()=>{ emps.forEach(e=> e.morale=clamp(e.morale-3,0,100)); return "You dodged it \u2014 people noticed. Morale -3."; } }
    ]});
  const s2 = speaker(e=> e.morale < 70);
  qs.push({ id:"headcount", who: s2, q:"Are we hiring, or are we stretched like this all year?",
    ans: "Headcount is "+emps.length+" against "+(c.clients||[]).length+" accounts.",
    options:[
      { label:"Commit to hiring", run:()=>{ emps.forEach(e=> e.morale=clamp(e.morale+6,0,100)); return "You committed to hiring \u2014 morale +6."; } },
      { label:"Say no for now", run:()=>{ emps.forEach(e=> e.morale=clamp(e.morale-2,0,100)); return "You were candid about the hiring freeze. Morale -2."; } }
    ]});
  const s3 = speaker(e=> e.performance >= 75);
  qs.push({ id:"direction", who: s3, q:"What are we actually betting on next year?",
    ans: "Product maturity "+((c.product&&c.product.maturity)||0)+"/100, success score "+(c.successScore||0)+"/100.",
    options:[
      { label:"Lay out the plan", run:()=>{ emps.forEach(e=> e.performance=clamp(e.performance+3,0,100));
          c.successScore = clamp((c.successScore||0)+1,0,100); return "You laid out the plan \u2014 performance +3, success +1."; } },
      { label:"Keep it vague", run:()=>{ emps.forEach(e=> e.morale=clamp(e.morale-2,0,100)); return "Vague answer \u2014 morale -2."; } }
    ]});
  return qs.slice(0,3);
}
function v35DeptRollup(before){
  const c = v35Co(); if(!c) return "";
  const emps = c.employees||[];
  const keys = (typeof DEPT_KEYS!=="undefined"?DEPT_KEYS:[]).filter(dk=> emps.some(e=>e.dept===dk));
  const rows = keys.map(dk=>{
    const staff = emps.filter(e=>e.dept===dk);
    const b = before[dk] || { p:0, m:0 };
    const p = Math.round(staff.reduce((s,e)=>s+e.performance,0)/staff.length);
    const m = Math.round(staff.reduce((s,e)=>s+e.morale,0)/staff.length);
    const d = (v,o)=> v===o ? "\u2014" : (v>o?"+":"")+(v-o);
    return `<tr><td>${LADDERS[dk]?LADDERS[dk].icon+" "+LADDERS[dk].label:dk}</td><td class="n">${staff.length}</td>
      <td class="n">${p} <span class="muted">(${d(p,b.p)})</span></td>
      <td class="n">${m} <span class="muted">(${d(m,b.m)})</span></td></tr>`;
  }).join("");
  return `<table class="v35-rollup"><tr><th>Department</th><th class="n">People</th><th class="n">Perf</th><th class="n">Morale</th></tr>${rows}</table>`;
}
function v35RenderZoom(){
  const c = G.company;
  const emps = c.employees||[];
  const wrap = el(`<div></div>`);
  const hard = v35HardMonth();
  const topics = (typeof TOWN_HALL_TOPICS!=="undefined"?TOWN_HALL_TOPICS:[]).filter(t=> t.key!=="complaints" && (t.key!=="struggle" || hard));
  wrap.innerHTML = `
    <div class="window-title"><h2>\u{1F3A5} Zoom \u2014 Team Sync</h2><span class="sub">${emps.length} participant(s)${c.zoomUsedThisMonth?" \u00b7 already synced":""}</span></div>
    <div class="radio-row">${(typeof ZOOM_APPROACHES!=="undefined"?ZOOM_APPROACHES:[]).map(a=>`<button class="btn secondary small" data-v35zoom="${a.key}" ${c.zoomUsedThisMonth?"disabled":""}>${a.label}</button>`).join("")}</div>
    <div class="muted mb8" style="font-size:11.5px;">Results report by department, not person by person.</div>
    <div id="v35synced" class="mt8"></div>
    <div class="card mt14"><h3>\u{1F5E3}\uFE0F Open floor</h3>
      <div class="muted mb8" style="font-size:11.5px;">Themes raised by the team this month, each with something you can actually do.</div>
      <div id="v35cats"></div>
    </div>
    <div class="card mt14"><h3>\u2753 Q&amp;A</h3><div id="v35qa"></div></div>
    <div class="card mt14"><h3>\u{1F3DB}\uFE0F Company Town Hall</h3>
      <div class="muted mb8" style="font-size:11.5px;">All-hands announcement. Posts to #general and moves Success Score.${hard?"":" \u00b7 <i>\u201cHard month\u201d is unavailable \u2014 the numbers were fine.</i>"}</div>
      <div class="flexrow">${topics.map(t=>`<button class="btn secondary small" data-v35th="${t.key}" ${c.townHallUsedThisMonth?"disabled":""}>${t.label}</button>`).join("")}</div>
    </div>`;

  function drawCats(){
    const box = wrap.querySelector("#v35cats");
    const cats = v35Complaints();
    if(!cats.length){ box.innerHTML = `<div class="muted" style="font-size:12px;">Nothing material raised this month \u2014 pay, workload, leadership and tooling all look healthy.</div>`; return; }
    box.innerHTML = `<div class="v35-cat">${cats.map(ct=>`<div class="c">
      <div class="hd">${ct.icon} ${ct.title} <span class="muted" style="font-weight:600;">\u00b7 ${ct.count}</span></div>
      <div class="ct">${ct.detail}</div>
      <div class="sg">\u{1F4A1} ${ct.suggestion}${ct.cost?" \u2014 "+fmt$(ct.cost):" \u2014 free"}</div>
      <button class="btn secondary small" data-v35fix="${ct.key}">Do it</button>
    </div>`).join("")}</div>`;
    box.querySelectorAll("[data-v35fix]").forEach(b=> b.onclick = ()=>{
      const ct = v35Complaints().find(x=>x.key===b.getAttribute("data-v35fix")); if(!ct) return;
      if(ct.cost && !affordOrAlert(ct.cost, ct.suggestion.toLowerCase())) return;
      if(ct.cost) G.company.cash -= ct.cost;
      const msg = ct.run();
      logHistory(msg);
      v35Toast("<b>"+ct.title+".</b> "+msg, "good");
      renderAll();
    });
  }
  function drawQa(){
    const box = wrap.querySelector("#v35qa");
    const qs = v35Questions();
    if(!qs.length){ box.innerHTML = `<div class="muted" style="font-size:12px;">No team yet \u2014 hire someone and they'll bring questions.</div>`; return; }
    box.innerHTML = qs.map(q=>`<div class="v35-qa">
      <div class="q">\u201c${q.q}\u201d</div>
      <div class="who">${q.who? q.who.name+" \u00b7 "+q.who.role : "Anonymous"}</div>
      <div class="muted mb8" style="font-size:11.5px;">${q.ans}</div>
      <div class="flexrow">${q.options.map((o,i)=>`<button class="btn secondary small" data-v35q="${q.id}" data-v35qi="${i}">${o.label}</button>`).join("")}</div>
    </div>`).join("");
    box.querySelectorAll("[data-v35q]").forEach(b=> b.onclick = ()=>{
      if(G.company.v35qaDone && G.company.v35qaDone.indexOf(b.getAttribute("data-v35q"))>=0){ v35Toast("Already answered this month.","warn"); return; }
      const q = qs.find(x=>x.id===b.getAttribute("data-v35q")); if(!q) return;
      const msg = q.options[Number(b.getAttribute("data-v35qi"))].run();
      G.company.v35qaDone = (G.company.v35qaDone||[]).concat([q.id]);
      logHistory(msg);
      v35Toast("<b>Q&amp;A.</b> "+msg, "good");
      renderAll();
    });
  }
  drawCats(); drawQa();

  wrap.querySelectorAll("[data-v35zoom]").forEach(b=> b.onclick = ()=>{
    const key = b.getAttribute("data-v35zoom");
    const c2 = G.company;
    const box = wrap.querySelector("#v35synced");
    if(!(c2.employees||[]).length){ box.innerHTML = `<div class="feed-item muted">No team members yet \u2014 it's just you on this call.</div>`; return; }
    const before = {};
    (typeof DEPT_KEYS!=="undefined"?DEPT_KEYS:[]).forEach(dk=>{
      const staff = c2.employees.filter(e=>e.dept===dk); if(!staff.length) return;
      before[dk] = { p: Math.round(staff.reduce((s,e)=>s+e.performance,0)/staff.length),
                     m: Math.round(staff.reduce((s,e)=>s+e.morale,0)/staff.length) };
    });
    c2.employees.forEach(emp=>{
      if(key==="rally"){ emp.performance=clamp(emp.performance+5,0,100); emp.morale=clamp(emp.morale+5,0,100); }
      else if(key==="push"){ emp.performance=clamp(emp.performance+10,0,100); emp.morale=clamp(emp.morale-8,0,100); }
      else if(key==="address"){ emp.morale = clamp(emp.morale + (Math.random()<0.5?8:-3),0,100); }
    });
    box.innerHTML = `<div class="card"><h3>Sync results by department</h3>${v35DeptRollup(before)}</div>`;
    c2.zoomUsedThisMonth = true;
    logHistory("Held a team sync ("+key+").");
    wrap.querySelectorAll("[data-v35zoom]").forEach(x=> x.setAttribute("disabled","true"));
  });
  wrap.querySelectorAll("[data-v35th]").forEach(b=> b.onclick = ()=>{
    if(G.company.townHallUsedThisMonth) return;
    const topic = TOWN_HALL_TOPICS.find(t=>t.key===b.getAttribute("data-v35th")); if(!topic) return;
    if(topic.cost && !affordOrAlert(topic.cost, "the company bonus announcement")) return;
    queueAdd({ id:uid(), label:`Town hall: ${topic.label}`, cost:topic.cost||0, run:(report)=>{
      if(topic.cost && G.company.cash<topic.cost){ report.push("Skipped town hall bonus \u2014 insufficient cash."); return; }
      if(topic.cost) G.company.cash -= topic.cost;
      G.company.employees.forEach(e=> e.morale = clamp(e.morale+topic.moraleAll,0,100));
      G.company.successScore = clamp(G.company.successScore+topic.successAll,0,100);
      G.company.companyChannel.push({ from:"Town Hall", text: topic.line, month:G.company.month, year:G.company.year });
      G.company.townHallCount = (G.company.townHallCount||0)+1;
      report.push(`Held a town hall: ${topic.label}.`);
    }});
    G.company.townHallUsedThisMonth = true;
    renderScreen();
  });
  return wrap;
}

/* ---------- 6. Slack: fewer posts, grouped by month, reactive ---------- */
const V35_CHAN_CAP = 26;
function v35TrimChannels(co){
  ["companyChannel","leadershipChannel","csuiteChannel"].forEach(k=>{
    let ch = co[k]; if(!Array.isArray(ch)) return;
    const seen = [];
    ch = ch.filter(m=>{
      const sig = (m.from||"")+"|"+(m.text||"")+"|"+m.month+"|"+m.year;
      if(seen.indexOf(sig)>=0) return false;
      seen.push(sig); return true;
    });
    co[k] = ch.slice(-V35_CHAN_CAP);
  });
}
function v35ReactivePosts(co){
  const posts = [];
  const fh = co.financialHistory||[];
  const last = fh[fh.length-1], prev2 = fh[fh.length-2];
  if(last && prev2){
    if(last.netProfit>0 && prev2.netProfit<=0) posts.push({from:"Finance", text:"We're back in the black \u2014 "+fmt$(last.netProfit)+" net this month."});
    else if(last.netProfit<0 && prev2.netProfit>=0) posts.push({from:"Finance", text:"Heads up: we ran "+fmt$(Math.abs(last.netProfit))+" negative this month."});
  }
  const emps = co.employees||[];
  if(emps.length){
    const avgM = Math.round(emps.reduce((s,e)=>s+e.morale,0)/emps.length);
    if(avgM < 50) posts.push({from:"HR", text:"Morale is averaging "+avgM+"/100. Worth addressing on the next all-hands."});
  }
  if((co.hiredThisMonth||0) > 0) posts.push({from:"HR", text:"Welcome to the "+co.hiredThisMonth+" new teammate(s) starting this month! \u{1F389}"});
  return posts.slice(0,2);
}
(function v35MonthHook(){
  if(typeof advanceMonth !== "function") return;
  const prev = advanceMonth;
  advanceMonth = function(){
    const r = prev.apply(this, arguments);
    try{
      const co = v35Co();
      if(co){
        co.v35qaDone = [];
        v35ReactivePosts(co).forEach(p=> co.companyChannel.push({from:p.from, text:p.text, month:co.month, year:co.year}));
        v35TrimChannels(co);
      }
    }catch(e){}
    return r;
  };
})();
function v35GroupMessages(list){
  if(!list || !list.length) return `<div class="muted" style="padding:12px;font-size:12px;">Quiet in here. Chatter shows up as things change.</div>`;
  const out = [];
  let lastKey = null;
  list.forEach(m=>{
    const key = "Y"+(m.year||1)+" M"+(m.month||1);
    if(key!==lastKey){ out.push(`<div class="v35-mhead">${key}</div>`); lastKey = key; }
    out.push(`<div class="msg them">${m.from?m.from+": ":""}${m.text}</div>`);
  });
  return out.join("");
}
(function v35SlackHook(){
  if(typeof renderSlack !== "function") return;
  const prev = renderSlack;
  renderSlack = function(){
    const wrap = prev.apply(this, arguments);
    try{
      const co = v35Co(); if(!co) return wrap;
      v35TrimChannels(co);
      const box = wrap.querySelector("#slackMsgs");
      const id = G.ui.activeSlackId;
      const map = { general:"companyChannel", leadership:"leadershipChannel", csuite:"csuiteChannel" };
      if(box && map[id]) box.innerHTML = v35GroupMessages(co[map[id]]||[]);
      if(box) box.scrollTop = box.scrollHeight;
    }catch(e){}
    return wrap;
  };
})();

/* ---------- 7. More random events, incl. employee run-ins ---------- */
function v35RunIns(){
  const c = v35Co(); if(!c) return [];
  const emps = c.employees||[];
  if(!emps.length) return [];
  const evs = [];
  const mk = (id,title,weight,text,choices)=> ({ id:id, title:title, weight:weight, text:text,
    pick:()=> pick(G.company.employees), choices:choices,
    consequence:(e,report)=>{ e.morale = clamp(e.morale-8,0,100); report.push("You never got back to "+e.name+"."); } });

  evs.push(mk("v35_elevator","Hallway run-in",4,
    (e)=>`${e.name} catches you between meetings: \u201cGot two minutes? I've had an idea I can't shake.\u201d`,
    [{ label:"Hear it out", run:(e,report)=>{ e.morale=clamp(e.morale+9,0,100);
        if(Math.random()<0.45){ const mrr=v35Scale(120); G.company.baseMrr=(G.company.baseMrr||0)+mrr;
          report.push(e.name+"'s idea turned into "+fmt$(mrr)+" of new MRR."); }
        else report.push("You heard "+e.name+" out \u2014 nothing actionable, but they felt heard."); } },
     { label:"Ask for it in writing", run:(e,report)=>{ e.morale=clamp(e.morale-3,0,100); report.push("You asked "+e.name+" to write it up."); } }]));

  evs.push(mk("v35_credit","Credit dispute",3,
    (e)=>`${e.name} says someone else presented their work as their own.`,
    [{ label:"Set the record straight publicly", run:(e,report)=>{ e.morale=clamp(e.morale+14,0,100);
        G.company.employees.forEach(x=> x.morale=clamp(x.morale+2,0,100)); report.push("You publicly credited "+e.name+"."); } },
     { label:"Handle it quietly", run:(e,report)=>{ e.morale=clamp(e.morale+5,0,100); report.push("You handled "+e.name+"'s credit dispute privately."); } }]));

  evs.push(mk("v35_family","Personal emergency",3,
    (e)=>`${e.name} needs time off at short notice for a family emergency.`,
    [{ label:"Cover it, fully paid", run:(e,report)=>{ const cost=v35Scale(250);
        if(G.company.cash>=cost){ G.company.cash-=cost; }
        e.morale=clamp(e.morale+20,0,100);
        G.company.employees.forEach(x=> x.morale=clamp(x.morale+3,0,100));
        report.push("You covered "+e.name+"'s leave \u2014 the whole team noticed."); } },
     { label:"Unpaid leave only", run:(e,report)=>{ e.morale=clamp(e.morale-14,0,100); report.push(e.name+" took unpaid leave."); } }]));

  evs.push(mk("v35_side","Side project",2,
    (e)=>`${e.name} is freelancing on the side. It's not competing, but it's eating their evenings.`,
    [{ label:"Allow it openly", run:(e,report)=>{ e.morale=clamp(e.morale+10,0,100); e.performance=clamp(e.performance-3,0,100);
        report.push("You gave "+e.name+" the okay."); } },
     { label:"Ask them to stop", run:(e,report)=>{ e.morale=clamp(e.morale-9,0,100); e.performance=clamp(e.performance+4,0,100);
        report.push("You asked "+e.name+" to wind the side work down."); } }]));

  evs.push(mk("v35_conflict","Two people, one problem",3,
    (e)=>`${e.name} and a teammate aren't speaking. It's starting to show in the work.`,
    [{ label:"Mediate personally", run:(e,report)=>{ e.morale=clamp(e.morale+12,0,100);
        G.company.employees.forEach(x=> x.performance=clamp(x.performance+1,0,100)); report.push("You mediated "+e.name+"'s conflict."); } },
     { label:"Let their manager own it", run:(e,report)=>{ if(Math.random()<0.5){ e.morale=clamp(e.morale+4,0,100); report.push("Their manager sorted it."); }
        else { e.morale=clamp(e.morale-10,0,100); report.push("It festered \u2014 "+e.name+" is unhappy."); } } }]));

  evs.push(mk("v35_mentor","Mentorship ask",2,
    (e)=>`${e.name} asks you directly to mentor them for the next level.`,
    [{ label:"Commit an hour a week", run:(e,report)=>{ e.morale=clamp(e.morale+13,0,100); e.performance=clamp(e.performance+7,0,100);
        report.push("You took "+e.name+" on as a mentee."); } },
     { label:"Pair them with a lead", run:(e,report)=>{ e.morale=clamp(e.morale+5,0,100); e.performance=clamp(e.performance+3,0,100);
        report.push("You paired "+e.name+" with a lead."); } }]));

  evs.push(mk("v35_offer","Outside offer, told honestly",3,
    (e)=>`${e.name} tells you about an outside offer before accepting it \u2014 that's a courtesy.`,
    [{ label:"Beat it (+18% salary)", run:(e,report)=>{ e.salary=Math.round(e.salary*1.18); e.morale=clamp(e.morale+18,0,100);
        report.push("You beat the outside offer for "+e.name+" \u2014 now "+fmt$(e.salary)+"/mo."); } },
     { label:"Wish them well", run:(e,report)=>{ report.push(e.name+" left on good terms."); try{ fireEmployee(e.id); }catch(err){} } }]));

  if(v35Tier() >= 2) evs.push(mk("v35_whistle","Someone raises a flag",3,
    (e)=>`${e.name} quietly reports a process being ignored in another team.`,
    [{ label:"Investigate properly", run:(e,report)=>{ const cost=v35Scale(500);
        if(G.company.cash>=cost) G.company.cash-=cost;
        e.morale=clamp(e.morale+15,0,100); G.company.successScore=clamp((G.company.successScore||0)+2,0,100);
        report.push("You investigated "+e.name+"'s report \u2014 success score up."); } },
     { label:"Note it and move on", run:(e,report)=>{ e.morale=clamp(e.morale-12,0,100);
        G.company.successScore=clamp((G.company.successScore||0)-3,0,100); report.push("You let it slide. It cost you credibility."); } }]));

  if(v35Tier() >= 3) evs.push(mk("v35_press_leak","An employee talked to the press",2,
    (e)=>`${e.name} spoke to a reporter about life inside the company. It wasn't hostile \u2014 but it wasn't cleared.`,
    [{ label:"Coach, don't punish", run:(e,report)=>{ e.morale=clamp(e.morale+8,0,100);
        G.company.employees.forEach(x=> x.morale=clamp(x.morale+2,0,100)); report.push("You coached "+e.name+" instead of punishing them."); } },
     { label:"Formal warning", run:(e,report)=>{ e.morale=clamp(e.morale-16,0,100);
        G.company.employees.forEach(x=> x.morale=clamp(x.morale-2,0,100)); report.push("You issued "+e.name+" a formal warning."); } }]));

  if(v35Tier() >= 3) evs.push(mk("v35_union","Organising conversation",2,
    (e)=>`${e.name} tells you people have been discussing organising. They came to you first.`,
    [{ label:"Listen and fix the cause", run:(e,report)=>{ const cost=v35Scale(1200);
        if(G.company.cash>=cost) G.company.cash-=cost;
        G.company.employees.forEach(x=> x.morale=clamp(x.morale+9,0,100));
        report.push("You addressed the underlying issues \u2014 morale up company-wide."); } },
     { label:"Stay out of it", run:(e,report)=>{ G.company.employees.forEach(x=> x.morale=clamp(x.morale-4,0,100));
        report.push("You stayed out of it."); } }]));

  return evs;
}
function v35CompanyEvents(){
  const t = v35Tier();
  const evs = [];
  evs.push({ id:"v35_audit", title:"Surprise audit", weight:2,
    text:()=>`A routine compliance audit has been scheduled with two weeks' notice.`,
    pick:()=>({id:"company"}),
    choices:[
      { label:`Hire help (${fmt$(v35Scale(700))})`, run:(s,report)=>{ const cost=v35Scale(700);
          if(G.company.cash<cost){ report.push("Couldn't afford audit support."); return; }
          G.company.cash-=cost; G.company.successScore=clamp((G.company.successScore||0)+1,0,100);
          report.push("The audit passed cleanly."); } },
      { label:"Handle it internally", run:(s,report)=>{ if(Math.random()<0.55){ report.push("You passed the audit on your own."); }
          else { G.company.successScore=clamp((G.company.successScore||0)-4,0,100); report.push("The audit turned up gaps."); } } }
    ],
    consequence:(s,report)=>{ G.company.successScore=clamp((G.company.successScore||0)-6,0,100); report.push("You ignored the audit. That was expensive."); } });

  if(t>=2) evs.push({ id:"v35_key_dep", title:"Vendor price hike", weight:3,
    text:()=>`A vendor you depend on raised prices ${v35Rand(12,30)}% with 30 days' notice.`,
    pick:()=>({id:"company"}),
    choices:[
      { label:"Absorb it", run:(s,report)=>{ const cost=v35Scale(450); G.company.cash-=Math.min(G.company.cash,cost);
          report.push("You absorbed the vendor increase ("+fmt$(cost)+")."); } },
      { label:"Switch vendors", run:(s,report)=>{ G.company.employees.forEach(e=> e.performance=clamp(e.performance-4,0,100));
          report.push("You switched vendors \u2014 messy transition, lower run-rate."); } }
    ],
    consequence:(s,report)=>{ const cost=v35Scale(700); G.company.cash-=Math.min(G.company.cash,cost); report.push("The vendor increase hit anyway."); } });

  if(t>=3) evs.push({ id:"v35_dataleak", title:"Security incident", weight:3,
    text:()=>`A misconfigured system exposed limited customer data. Nobody's reported harm yet.`,
    pick:()=>({id:"company"}),
    choices:[
      { label:`Disclose immediately (${fmt$(v35Scale(1500))})`, run:(s,report)=>{ const cost=v35Scale(1500);
          G.company.cash-=Math.min(G.company.cash,cost);
          G.company.successScore=clamp((G.company.successScore||0)+2,0,100);
          (G.company.clients||[]).forEach(c=> c.health=clamp(c.health-5,0,100));
          report.push("You disclosed fast. Short-term pain, long-term trust."); } },
      { label:"Fix quietly", run:(s,report)=>{ if(Math.random()<0.6){ report.push("You fixed it quietly and nobody noticed."); }
          else { G.company.successScore=clamp((G.company.successScore||0)-12,0,100);
            (G.company.clients||[]).forEach(c=> c.health=clamp(c.health-18,0,100));
            report.push("The quiet fix leaked. It was much worse than disclosing."); } } }
    ],
    consequence:(s,report)=>{ G.company.successScore=clamp((G.company.successScore||0)-15,0,100); report.push("The incident went unmanaged."); } });

  if(t>=4) evs.push({ id:"v35_regulator", title:"Regulatory inquiry", weight:3,
    text:()=>`At your size, a regulator has questions about how you operate.`,
    pick:()=>({id:"company"}),
    choices:[
      { label:`Full cooperation (${fmt$(v35Scale(3000))})`, run:(s,report)=>{ const cost=v35Scale(3000);
          G.company.cash-=Math.min(G.company.cash,cost); G.company.successScore=clamp((G.company.successScore||0)+3,0,100);
          report.push("You cooperated fully and closed the inquiry."); } },
      { label:"Minimum compliance", run:(s,report)=>{ if(Math.random()<0.5){ report.push("The inquiry fizzled."); }
          else { const fine=v35Scale(6000); G.company.cash-=Math.min(G.company.cash,fine);
            report.push("You were fined "+fmt$(fine)+"."); } } }
    ],
    consequence:(s,report)=>{ const fine=v35Scale(9000); G.company.cash-=Math.min(G.company.cash,fine); report.push("Ignoring the regulator cost you "+fmt$(fine)+"."); } });

  return evs;
}
(function v35EventPoolHook(){
  if(typeof randomEventPool !== "function") return;
  const prev = randomEventPool;
  randomEventPool = function(){
    let pool = [];
    try{ pool = prev.apply(this, arguments) || []; }catch(e){ pool = []; }
    try{ pool = pool.concat(v35RunIns()).concat(v35CompanyEvents()); }catch(e){}
    return pool;
  };
})();
(function v35EventRateHook(){
  if(typeof maybeTriggerEvent !== "function") return;
  maybeTriggerEvent = function(){
    const c = v35Co(); if(!c || c.pendingEvent) return;
    const pool = randomEventPool();
    if(!pool.length) return;
    const sinceLast = (c.month||0) - (c.v35LastEventMonth||-99);
    const chance = sinceLast >= 2 ? 0.97 : 0.82;
    if(Math.random() > chance) return;
    const weighted = [];
    pool.forEach(ev=>{ const w = Math.max(1, ev.weight||1); for(let i=0;i<w;i++) weighted.push(ev); });
    const ev = pick(weighted);
    const subject = ev.pick ? ev.pick() : null;
    c.v35LastEventMonth = c.month;
    if(ev.autoRun){ const report=[]; ev.autoRun(report); logHistory(report.join(" ")); return; }
    if(!subject) return;
    c.pendingEvent = { defId: ev.id, title: ev.title, text: ev.text(subject), subjectId: subject.id,
      choices: ev.choices.map((ch,i)=>({ idx:i, label:ch.label })) };
    c._eventDef = ev;
    try{ deliverEventToSlack(ev); }catch(e){}
  };
})();

/* ---------- 8. C-Suite square cards ---------- */
function v35RenderCsuite(){
  const c = G.company;
  const execs = (c.employees||[]).filter(e=> typeof isCSuite==="function" && isCSuite(e));
  const payroll = execs.reduce((s,e)=>s+e.salary,0);
  const vacancies = (typeof CSUITE_RUNGS!=="undefined"?CSUITE_RUNGS:[]).filter(rk=> !execs.some(e=>e.rung===rk));
  const wrap = el(`<div></div>`);
  const bar = (v,color)=>`<div class="v35-bar"><i style="width:${clamp(v,0,100)}%;background:${color};"></i></div>`;
  wrap.innerHTML = `
    <div class="window-title"><h2>\u{1F454} C-Suite</h2><span class="sub">${execs.length} officer(s) \u00b7 ${fmt$(payroll)}/mo</span></div>
    <div class="ledger-row">
      <div class="lg"><div class="k">Officers</div><div class="v">${execs.length}</div><div class="n">of ${(typeof CSUITE_RUNGS!=="undefined"?CSUITE_RUNGS.length:0)} seats</div></div>
      <div class="lg"><div class="k">Exec payroll</div><div class="v ${payroll?"bad":""}">${fmt$(payroll)}</div><div class="n">per month</div></div>
      <div class="lg"><div class="k">Avg performance</div><div class="v">${execs.length?Math.round(execs.reduce((s,e)=>s+e.performance,0)/execs.length):"\u2014"}</div><div class="n">Leadership quality</div></div>
      <div class="lg"><div class="k">Avg morale</div><div class="v">${execs.length?Math.round(execs.reduce((s,e)=>s+e.morale,0)/execs.length):"\u2014"}</div><div class="n">Pay and bonuses move this</div></div>
    </div>
    <div class="flatsec mb14"><h3>\u{1F4B5} Officers</h3>
      <div class="muted mb8" style="font-size:12px;">Each 10% raise buys morale and a point of success score; cuts do the reverse.</div>
      ${execs.length? `<div class="v35-sq">${execs.map(e=>`<div class="v35-card">
          <div class="ic">${e.icon||"\u{1F464}"}</div>
          <div class="nm">${e.name}</div>
          <div class="rl">${e.role}<br>${LADDERS[e.dept]?LADDERS[e.dept].label:e.dept}</div>
          <div class="pay">${fmt$(e.salary)}<span class="muted" style="font-size:10px;">/mo</span></div>
          <div style="width:100%;">${bar(e.performance,"var(--good,#4caf50)")}<div class="mini" style="justify-content:space-between;"><span>Perf</span><span>${e.performance}</span></div></div>
          <div style="width:100%;">${bar(e.morale,"var(--accent,#5b8def)")}<div class="mini" style="justify-content:space-between;"><span>Morale</span><span>${e.morale}</span></div></div>
          <div class="sp"></div>
          <div class="acts">
            <button class="btn secondary small" data-v35paydn="${e.id}">\u2212</button>
            <button class="btn secondary small" data-v35payup="${e.id}">+</button>
            <button class="btn secondary small" data-v35bonus="${e.id}">\u{1F4B0}</button>
            <button class="btn secondary small" data-v35open="${e.id}">File</button>
          </div>
        </div>`).join("")}</div>`
        : `<div class="muted">No officers yet \u2014 promote a director or hire from HR &amp; Hiring.</div>`}
    </div>
    <div class="flatsec"><h3>\u{1FA91} Open seats</h3>
      ${vacancies.length? `<div class="v35-sq">${vacancies.map(rk=>`<div class="v35-card vac">
          <div class="ic">\u{1FA91}</div>
          <div class="nm">${typeof v23RungLabel==="function"?v23RungLabel(rk):rk.toUpperCase()}</div>
          <div class="rl">${typeof v23RungDept==="function" && v23RungDept(rk) && LADDERS[v23RungDept(rk)] ? LADDERS[v23RungDept(rk)].icon+" "+LADDERS[v23RungDept(rk)].label : "Vacant"}</div>
          <div class="sp"></div>
          <div class="acts"><button class="btn secondary small" data-v35gohr="1">Hire</button></div>
        </div>`).join("")}</div>` : `<div class="muted">Every C-suite seat is filled. \u{1F3AF}</div>`}
    </div>`;
  const bump = (id, dir)=>{
    const e = G.company.employees.find(x=>x.id===id); if(!e) return;
    const next = Math.max(1000, Math.round(e.salary*(dir>0?1.10:0.90)));
    e.salary = next;
    e.morale = clamp(e.morale + (dir>0?6:-9), 0, 100);
    G.company.successScore = clamp((G.company.successScore||0)+(dir>0?1:-1),0,100);
    v35Toast(`<b>${e.name}'s salary ${dir>0?"raised":"cut"} to ${fmt$(next)}/mo.</b>`, dir>0?"good":"warn");
    logHistory(`${e.role} ${e.name} salary set to ${fmt$(next)}/mo.`);
    renderScreen();
  };
  wrap.querySelectorAll("[data-v35payup]").forEach(b=> b.onclick=()=> bump(b.getAttribute("data-v35payup"),1));
  wrap.querySelectorAll("[data-v35paydn]").forEach(b=> b.onclick=()=> bump(b.getAttribute("data-v35paydn"),-1));
  wrap.querySelectorAll("[data-v35bonus]").forEach(b=> b.onclick=()=>{
    const e = G.company.employees.find(x=>x.id===b.getAttribute("data-v35bonus")); if(!e) return;
    const amount = Number(window.prompt(`One-off bonus for ${e.name} (${e.role})?`, String(Math.round(e.salary))));
    if(!amount || amount<=0) return;
    if(!affordOrAlert(amount, `a bonus for ${e.name}`)) return;
    G.company.cash -= amount;
    e.morale = clamp(e.morale+12,0,100); e.performance = clamp(e.performance+3,0,100);
    G.company.successScore = clamp((G.company.successScore||0)+1,0,100);
    v35Toast(`<b>${fmt$(amount)} bonus paid to ${e.name}.</b>`, "good");
    logHistory(`Paid ${fmt$(amount)} bonus to ${e.role} ${e.name}.`);
    renderAll();
  });
  wrap.querySelectorAll("[data-v35open]").forEach(b=> b.onclick=()=>{ try{ openEmployeeModal(b.getAttribute("data-v35open")); }catch(e){} });
  wrap.querySelectorAll("[data-v35gohr]").forEach(b=> b.onclick=()=>{
    G.ui.activeTab="hr"; G.ui.lastPeopleTab="hr"; renderDock(); renderScreen();
  });
  return wrap;
}

/* ---------- 9. Take over the overridden screens last ---------- */
(function v35TakeOver(){
  try{ renderZoom = v35RenderZoom; }catch(e){}
  try{ if(typeof v23RenderCsuite==="function") v23RenderCsuite = v35RenderCsuite; }catch(e){}
})();


/* ================= v35b — answered feedback ================= */

/* ---- 1. Double the segment thresholds ---- */
(function v35DoubleSegments(){
  try{
    if(typeof V34_SEGMENTS === "undefined" || !Array.isArray(V34_SEGMENTS)) return;
    V34_SEGMENTS.forEach(s=>{ if(typeof s.min === "number" && s.min > 0) s.min = s.min * 2; });
  }catch(e){}
})();

/* ---- 2. At-risk accounts raise a header alert ---- */
function v35AtRisk(){
  const c = (typeof G!=="undefined" && G && G.company) ? G.company : null;
  if(!c) return { n:0, mrr:0 };
  const risky = (c.clients||[]).filter(cl=> (cl.health||100) < 55);
  return { n: risky.length, mrr: risky.reduce((s,cl)=> s + (cl.mrr||0), 0) };
}
function v35RenderRiskAlert(){
  try{
    const head = document.querySelector("#v29head");
    if(!head) return;
    const old = head.querySelector("[data-v35risk]");
    if(old) old.remove();
    const r = v35AtRisk();
    if(!r.n) return;
    const bar = document.createElement("div");
    bar.setAttribute("data-v35risk","1");
    bar.style.cssText = "margin-top:8px;display:flex;align-items:center;gap:8px;flex-wrap:wrap;"+
      "background:rgba(220,80,60,.14);border:1px solid rgba(220,80,60,.5);border-radius:9px;"+
      "padding:7px 11px;font-size:12px;cursor:pointer;";
    bar.innerHTML = `<b>\u26A0\uFE0F ${r.n} account${r.n>1?"s":""} at risk</b>` +
      `<span class="muted">${fmt$(r.mrr)}/mo of MRR below 55 health</span>` +
      `<span style="margin-left:auto;font-weight:700;">Open the book \u2192</span>`;
    bar.onclick = ()=>{ G.ui.activeTab = "clients"; try{ renderDock(); }catch(e){} renderScreen(); };
    head.appendChild(bar);
  }catch(e){}
}
(function v35HeaderHook(){
  if(typeof v29RenderHeader !== "function") return;
  const prev = v29RenderHeader;
  v29RenderHeader = function(){
    const out = prev.apply(this, arguments);
    v35RenderRiskAlert();
    return out;
  };
})();

/* ---- 3. Competitive intelligence spend ---- */
function v35IntelState(){
  const c = G.company;
  if(!c.v35intel) c.v35intel = {};
  return c.v35intel;
}
function v35IntelCost(){
  const c = G.company;
  return Math.max(750, Math.round((c.mrr||0) * 0.35));
}
function v35IntelActive(key){
  const c = G.company;
  const st = v35IntelState()[key];
  if(!st) return false;
  return (c.year*12 + c.month) <= st;
}
function v35BuyIntel(key){
  const c = G.company;
  const cost = v35IntelCost();
  if(typeof affordOrAlert==="function" && !affordOrAlert(cost, "competitive intelligence")) return;
  c.cash -= cost;
  v35IntelState()[key] = c.year*12 + c.month + 2;
  logHistory("Bought competitive intelligence on a rival for " + fmt$(cost) + ".");
  if(typeof toast==="function") toast("<b>Intel acquired.</b> Rival pricing and roadmap visible for 3 months.", "good");
  renderScreen();
}
function v35IntelCard(){
  const c = G.company;
  if(typeof v33LiveRivals !== "function") return null;
  let rivals = [];
  try{ rivals = v33LiveRivals() || []; }catch(e){ return null; }
  if(!rivals.length) return null;
  const cost = v35IntelCost();
  const box = el(`<div class="card mt14"></div>`);
  box.innerHTML = `<h3>\u{1F575}\uFE0F Competitive intelligence</h3>
    <div class="muted mb8" style="font-size:11.5px;">Pay to see a rival's pricing and roadmap for three months. Intel makes their next bid readable before you commit.</div>
    <div class="v35-cat">${rivals.map(r=>{
      const key = r.key || r.name;
      const active = v35IntelActive(key);
      return `<div class="c">
        <div class="hd">${r.name||key}</div>
        <div class="ct">Share ${Math.round((r.share||0)*100)}%${r.product?" \u00b7 "+r.product:""}</div>
        ${active ? `<div class="sg">\u{1F513} Price <b>${fmt$(r.price||0)}</b> \u00b7 Roadmap: <b>${r.roadmap || (r.aggression>0.6?"aggressive expansion":"steady hold")}</b><br>
            <span class="muted">Bid guidance: undercut by ~${Math.max(3,Math.round((r.aggression||0.5)*12))}% to win.</span></div>`
          : `<div class="sg muted">Pricing and roadmap hidden.</div>
             <button class="btn secondary small" data-v35intel="${key}">Buy intel \u2014 ${fmt$(cost)}</button>`}
      </div>`;
    }).join("")}</div>`;
  box.querySelectorAll("[data-v35intel]").forEach(b=> b.onclick = ()=> v35BuyIntel(b.getAttribute("data-v35intel")));
  return box;
}
(function v35RivalsHook(){
  if(typeof v33RivalsScreen !== "function") return;
  const prev = v33RivalsScreen;
  v33RivalsScreen = function(){
    const wrap = prev.apply(this, arguments);
    try{ const card = v35IntelCard(); if(card && wrap && wrap.appendChild) wrap.appendChild(card); }catch(e){}
    return wrap;
  };
})();

/* ---- 4. Board intervention after a year under 5% share ---- */
function v35CheckBoard(){
  const c = G.company;
  if(typeof v33MyShare !== "function") return;
  let share = 0;
  try{ share = v33MyShare() || 0; }catch(e){ return; }
  const pct = share > 1 ? share : share * 100;
  if(pct < 5) c.v35lowShare = (c.v35lowShare||0) + 1;
  else c.v35lowShare = 0;
  if(c.v35lowShare >= 12 && !c.pendingEvent && !c.v35boardActed){
    c.v35boardActed = true;
    c.v35lowShare = 0;
    c.pendingEvent = {
      defId: "v35_board", title: "Board intervention",
      text: "Twelve straight months under 5% market share. The board has lost patience and is forcing a decision.",
      subjectId: "company",
      choices: [
        { idx:0, label:"Accept the forced pivot" },
        { idx:1, label:"Fight the board" }
      ]
    };
    try{ logHistory("The board called an emergency session over market share."); }catch(e){}
  }
}
function v35BoardEvent(){
  return {
    id: "v35_board", title: "Board intervention", weight: 1,
    text: ()=> "Twelve straight months under 5% market share. The board has lost patience.",
    pick: ()=> ({ id:"company" }),
    choices: [
      { label:"Accept the forced pivot", run:(s, report)=>{
          const c = G.company;
          if(c.product) c.product.maturity = clamp((c.product.maturity||0) + 12, 0, 100);
          const cost = Math.round((c.cash||0) * 0.15);
          c.cash -= cost;
          c.successScore = clamp((c.successScore||0) + 4, 0, 100);
          (c.employees||[]).forEach(e=> e.morale = clamp(e.morale - 6, 0, 100));
          report.push("The board forced a pivot \u2014 " + fmt$(cost) + " spent, product maturity +12, the team is rattled.");
        } },
      { label:"Fight the board", run:(s, report)=>{
          const c = G.company;
          if(Math.random() < 0.4){
            c.successScore = clamp((c.successScore||0) + 6, 0, 100);
            report.push("You faced the board down and kept control of strategy.");
          } else {
            c.successScore = clamp((c.successScore||0) - 10, 0, 100);
            const execs = (c.employees||[]).filter(e=> typeof isCSuite==="function" && isCSuite(e));
            if(execs.length){ const gone = pick(execs); try{ fireEmployee(gone.id); }catch(e){} 
              report.push("You lost the fight \u2014 the board removed " + gone.name + "."); }
            else report.push("You lost the fight \u2014 the board cut your authority.");
          }
        } }
    ],
    consequence:(s, report)=>{ G.company.successScore = clamp((G.company.successScore||0) - 8, 0, 100);
      report.push("You ignored the board. They noticed."); }
  };
}

/* ---- 5. The responsible officer fires an over-budget VP ---- */
function v35OfficerFor(dept){
  const c = G.company;
  return (c.employees||[]).find(e=> e.dept===dept && typeof isCSuite==="function" && isCSuite(e)) || null;
}
function v35CheckBudgets(){
  const c = G.company;
  if(typeof v33DivRows !== "function") return;
  let rows = [];
  try{ rows = v33DivRows() || []; }catch(e){ return; }
  if(!c.v35over) c.v35over = {};
  rows.forEach(r=>{
    const key = r.dept + "|" + r.div;
    if(r.over) c.v35over[key] = (c.v35over[key]||0) + 1;
    else c.v35over[key] = 0;
    if(c.v35over[key] >= 3 && r.vp){
      const officer = v35OfficerFor(r.dept);
      if(officer){
        const vpName = r.vp.name;
        try{ v33FireVp(r.dept, r.div); }catch(e){ try{ fireEmployee(r.vp.id); }catch(err){} }
        c.v35over[key] = 0;
        try{ logHistory(officer.role + " " + officer.name + " removed " + vpName + " after three months over budget in " + r.div + "."); }catch(e){}
        try{ c.csuiteChannel.push({ from: officer.name, text: "I've made a change in " + r.div + ". Three months over budget is enough.", month:c.month, year:c.year }); }catch(e){}
        if(typeof toast==="function") toast("<b>"+officer.name+" removed "+vpName+".</b> Three months over budget in "+r.div+".", "warn");
      } else {
        if(c.v35over[key] === 3){
          try{ logHistory(r.div + " has been over budget three months, but there's no officer over " + r.dept + " to act on it."); }catch(e){}
        }
      }
    }
  });
}

/* ---- wire the monthly checks and the board event into the pool ---- */
(function v35BMonthHook(){
  if(typeof advanceMonth !== "function") return;
  const prev = advanceMonth;
  advanceMonth = function(){
    const r = prev.apply(this, arguments);
    try{ v35CheckBudgets(); }catch(e){}
    try{ v35CheckBoard(); }catch(e){}
    try{ v35RenderRiskAlert(); }catch(e){}
    return r;
  };
})();
(function v35BPoolHook(){
  if(typeof randomEventPool !== "function") return;
  const prev = randomEventPool;
  randomEventPool = function(){
    let pool = [];
    try{ pool = prev.apply(this, arguments) || []; }catch(e){ pool = []; }
    try{ pool = pool.concat([v35BoardEvent()]); }catch(e){}
    return pool;
  };
})();


/* ================= v35c — load path must always expand ================= */
(function v35LoadHook(){
  if(typeof loadSlot !== "function") return;
  const prev = loadSlot;
  loadSlot = function(){
    const st = prev.apply(this, arguments);
    try{ v35ExpandState(st); }catch(e){}
    return st;
  };
})();
(function v35ImportHook(){
  if(typeof v28ApplyCode !== "function") return;
  const prev = v28ApplyCode;
  v28ApplyCode = function(state){
    try{ v35ExpandState(state); }catch(e){}
    return prev.apply(this, arguments);
  };
})();
/* Belt and braces: expand on any state that reaches normalizeGame or the boot loader. */
(function v35BootExpand(){
  try{
    if(typeof G !== "undefined" && G) v35ExpandState(G);
  }catch(e){}
})();


